INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (15, N'BP_OUT', N'BP', N'a10', N'ПьезНапорВх', N'Пьез. напор на выходе байпаса', N'Пьезометрический напор на выходе байпаса', N'"Пьезометрический напор на выходе байпаса"- цифровое поле, значение которого есть вычисленный  пьезометрический напор в узле,  являющимся выходом байпаса.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (16, N'BP_OUT', N'BP', N'a11', N'ДиамДиаф', N'Диаметр диафрагмы', N'Диаметр диафрагмы на внешнем теплопроводе сети', N'"Диаметр  диафрагмы установленной  на внешнем  теплопроводе сети" - цифровое поле, значение  которого определяется рассчитанным  значением диаметра  диафрагмы,   которую  необходимо   установить  на    внешнем трубопроводе  сети  для  обеспечения  заданных  для байпасного участка условий дросселирования  при потокораспределении  в сети, полученном в результате  расчета  гидравлического   режима.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (17, N'BP_OUT', N'BP', N'a12', N'НасимНап', N'Гасимый напор на диафрагме', N'Гасимый напор на диафрагме', N'"Гасимый напор  на диафрагме" -  цифровое поле, значение  которого определяется падением напора на диафрагме, который необходимо погасить для     обеспечения     заданных     условий     дросселирования   при потокораспределении   в   сети   полученном   в   результате   расчета гидравлического режима.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (18, N'BP_OUT', N'BP', N'a13', N'РасчРасхДиаф', N'Расчетный расход через диафрагму', N'Расчетный расход через диафрагму', N'"Расчетный  расход  через  диафрагму"  - цифровое поле, значение которого  определяется  потокораспределением   в  сети  полученном   в результате  расчета  гидравлического  режима.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (19, N'BP_OUT', N'BP', N'a14', N'МестоУстан', N'Место установки байпасного участка', N'Место установки байпасного участка', N'"Место установки байпасного  участка" - символьное поле,  значение которого произвольно  определяется пользователем  во входном  описании байпасного участка и однозначно идентифицирует место его установки.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (20, N'BP_OUT', N'BP', N'a15', N'ВнутДиамУчаст', N'Внутренний диаметр байпасного участка', N'Внутренний диаметр байпасного участка', N'"Внутренний диаметр байпасного участка" - числовое поле,  значение которого определяет внутренний диаметр труб, проложенных на  байпасном участке теплопровода. Рекомендуется заполнять  значение  внутреннего диаметра с помощью  функции  поля.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (21, N'BP_OUT', N'BP', N'a16', N'ДлинаТруб', N'Длина трубопровода байпасного участка', N'Длина трубопровода байпасного участка', N'"Длина трубопровода байпасного участка" - цифровое поле, значение которого   определяется   строительной   длиной   байпасного   участка теплопровода.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (22, N'BP_OUT', N'BP', N'a17', N'ПотериНапора', N'Потери напора на байпасном участке', N'Потери напора на байпасном участке', N'"Потери  напора на  байпасном участке"  - цифровое  поле, значение которого  определяется  падением  напора, обусловленным гидравлическим сопротивлением  байпасного  участка  (длина,  диаметр,  сумма  местных сопротивлений ...).', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (23, N'BP_OUT', N'BP', N'a18', N'СумГасНапор', N'Суммарный гасимый напор', N'Суммарный гасимый напор', N'"Суммарный  гасимый  напор"  -  цифровое  поле, значение которого определяется  суммой  падений   напора,  обусловленных  гидравлическим сопротивлением  байпасного  участка  и  гасимого  напора на диафрагме.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (24, N'BP_OUT', N'BP', N'a4', N'ГеодОтмВерхаТрубВх', N'Геод.отметка верха трубы узла на входе', N'Геодезическая  отметка верха трубы узла на входе', N' "Геодезическая  отметка верха трубы узла на входе"  -  цифровое  поле,  значение которого   определяется    значением   геодезической отметки верха трубы в месте  расположения узла на  входе байпаса  и используется при расчете гидравлического режима сети.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (25, N'BP_OUT', N'BP', N'a5', N'ПьезНапВх', N'Пьез.напор на входе байпаса', N'Пьезометрический напор на входе байпаса', N'"Пьезометрический напор на входе байпаса" - цифровое поле, значение которого - это вычисленный  пьезометрический напор в узле,  являющимся входом байпаса.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (26, N'BP_OUT', N'BP', N'a9', N'ГеодОтмВерхаТрубВых', N'Геод.отметка верха трубы узла на выходе', N'Геодезическая  отметка верха трубы узла на выходе', N'"Геодезическая  отметка верха трубы "  -  цифровое  поле,  значение которого   определяется    значением   геодезической отметки верха трубы в месте  расположения узла на  выходе байпаса  и используется при расчете гидравлического режима расчетной схемы.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (27, N'BP_OUT', N'BP', N'kod_p', N'КодРасчСхУзлаПрисоед', N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда байпас входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (28, N'BP_OUT', N'BP', N'kod1', N'КодРасчСхВхУзла', N'Код расчетной схемы узла на входе байпаса', N'Код расчетной схемы узла на входе байпаса', N'"Код  расчетной схемы  узла на  входе байпаса"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на входе байпаса.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (29, N'BP_OUT', N'BP', N'kod2', N'КодРасчСхВыхУзла', N'Код расчетной схемы узла на выходе байпаса', N'Код расчетной схемы узла на выходе байпаса', N'"Код  расчетной схемы  узла на  входе байпаса''  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на выходе байпаса.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (30, N'BP_OUT', N'BP', N'nomer', N'№', N'№', N'Порядковый номер экземпляра', N'Порядковый номер экземпляра данного класса. Недопустимая  для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (31, N'BP_OUT', N'BP', N'pr_p', N'ПризТрубУзлаПрис', N'Признак теплопровода узла просоединения', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подача» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда байпас входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (32, N'BP_OUT', N'BP', N'pr1', N'ПризТрубВхУзла', N'Признак трубопровода узла на входе байпаса', N'Признак трубопровода узла на входе байпаса', N'"Признак  теплопровода узла  на входе  байпаса" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  начального  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  трубопроводам  на  расчетной схеме.  Если в поле "Общий", то это означает, что узел принадлежит  и подающему и обратному трубопроводам.  Наличие пробела в полях "Признак трубопровода" для начального и конечного узлов свидетельствует о том , что участок "общий", т.е. его характеристики одинаковы для подающего и обратного трубопроводов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (33, N'BP_OUT', N'BP', N'pr2', N'ПризТрубВыхУзла', N'Признак трубопровода узла на выходе байпаса', N'Признак трубопровода узла на выходе байпаса', N'"Признак  теплопровода узла  на выходе  байпаса" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  конечного  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  трубопроводам  на  расчетной схеме. Если в поле "Общий", то это означает, что узел принадлежит  и подающему и обратному трубопроводам.  Наличие пробела в полях "Признак трубопровода" для начального и конечного узлов свидетельствует о том , что участок "общий", т.е. его характеристики одинаковы для подающего и обратного трубопроводов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (34, N'BP_OUT', N'BP', N'sopr', N'ГидрСопр', N'Гидравлическое сопротивление', N'Полное гидравлическоке сопротивление', N'Полное гидравлическоке сопротивление дроссельных  диафрагм   байпасного  участка сети.   Характеристики  дроссельных диафрагм  обусловленны потокораспределением  полученным в  результате расчета гидравлического режима сети и заданным во  входных  документах алгоритмом дросселирования.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (35, N'BP_OUT', N'BP', N'sos', N'Состояние', N'Состояние', N'Состояние', N'"Состояние байпаса" - символьное поле, значение которого  однозначно определяет состояние, в котором находится байпас.  Если в поле установлено значение - "Активен", то это  соответствуует включенному состоянию байпаса, т.е. поток может  проходить через байпас, дросселироваться до нужного уровня и на  этой основе рассчитывается дроссельная диафрагма. Если в поле  установлено значение - "Закрыт", то байпас отключен, расход через него  физически прерывается. Если в поле установлено значение - "Неактивен",  то байпас находится в неактивном состоянии, т.е. разрыв потока  не происходит, дросселирование и расчет дроссельной диафрагмы  не выполняются, т.е. байпас представляет собой участок  теплопровода с сопротивлением обусловленным геометрическими  характеристиками уложенной на участке трубы. Если в поле  установлено значение - "Установлен", то байпас находится в неактивном  состоянии, т.е. разрыв потока не происходит, дросселирование и  расчет дроссельной диафрагмы не выполняются, но байпас  представляет собой участок трубопровода с сопротивлением,  обусловленным геометрическими характеристиками уложенной на  участке трубы и сопротивлением расcчитанной ранее и  установленной на байпасе дроссельной диафрагмы.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (36, N'BP_OUT', N'BP', N'uzel_p', N'НаимУзлаПрис', N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда байпас входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (37, N'BP_OUT', N'BP', N'uzel1', N'НаимВхУзла', N'Наименование узла на входе байпаса', N'Наименование узла на входе байпаса', N'"Наименование узла  на входе байпаса"  - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно определяет узел на  расчетной  схеме.   Это  наименование  используется  для  указания заданного   направления    потока   сетевой    воды   через    байпас.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (38, N'BP_OUT', N'BP', N'uzel2', N'НаимВыхУзла', N'Наименование узла на выходе байпаса', N'Наименование узла на выходе байпаса', N'"Наименование узла  на выходе байпаса"  - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно определяет узел на  расчетной  схеме.   Это  наименование  используется  для  указания заданного   направления    потока   сетевой    воды   через    байпас.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (39, N'DR_OUT', N'BP', N'nomer', N'1.№', N'1.№', N'Порядковый номер экземпляра', N'Порядковый номер экземпляра данного класса. Недопустимая  для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (40, N'DR_OUT', N'DR', N'b10', N'11.НомерЭлУстан', N'11.Номер элеватора установленный', N'Номер элеватора установленный', N'"Номер элеватора установленный"  - числовое поле,  значение которого отражает основной типоразмерный параметр установленного и действующего в системе отопления элеватора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (41, N'DR_OUT', N'DR', N'b11', N'12.НомерЭлВыбр', N'12.Номер элеватора выбранный', N'Номер элеватора выбранный', N'"Номер  элеватора  выбранный"  -  числовое  поле,  значение которого отражает выбранный средствами  системы номер элеватора  по результатам расчета диаметра горловины элеватора.  Расчет горловины выполняется по формуле                Dг=8,5*(Gр^2*(1+U)^2/Hс)^(1/4), мм, где   Gр - расчетный расход сетевой воды на отопление,т/ч;  U  - расчетный коэффициент смешения;  Hc - потери напора в гидравлическом тракте системы отопления при  расчетном расходе смешанной воды, м.вод.ст.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (42, N'DR_OUT', N'DR', N'b12', N'13.DвнДиафВх', N'13.Внутр.диаметр головной дросс. диафр. для ТПП или отопления', N'Внутренний диаметр головной дросс. диафр. для ТПП или отопления', N'"Внутренний  диаметр  головной  дроссельной  диафрагмы  для  ИТП или отопления"  -  числовое  поле,  значение  которого отражает результаты расчета внутреннего диаметра головной диафрагмы для ИТП (если  остаток располагаемого напора, не  погашенного соплом элеватора,  соизмерим по величине с  аналогичными остатками,  не погашенными  первыми ступенями дросселирования в  системах вентиляции  и закрытой  ГВС.) или  системы отопления (если  остаток располагаемого  напора для  системы отопления значительно  отличается  от  остатков  напора  после  первой   ступени дросселирования в  системах вентиляции  и закрытой  ГВС). Формулы  для расчета внутренних диаметров  диафрагм приведены при  описании входной информации объекта "Диафрагма".', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (43, N'DR_OUT', N'DR', N'b13', N'14.ГасНапДиафВх', N'14.Гасимый напор на головной диаф.для ИТП', N'Гасимый напор на головной диафрагме для ИТП', N'"Гасимый  напор  на  головной  диафрагме  для  ТПП" - числовое поле, значение  которого  отражает  результаты  расчета  гасимого  напора на упомянутой  диафрагме  в  соответствии  с  принципом  двухступенчатого дросселирования располагаемого напора теплового пункта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (44, N'DR_OUT', N'DR', N'b14', N'15.РасхДиафВх', N'15.Расч.расход через головную диафр.для ИТП', N'Расчетный расход через головную диафрагму для ИТП', N'"Расчетный  расход  через  головную  диафрагму  для ИТП " - числовое поле,  значение  которого  отражает  расчетный  расход  теплоносителя, полученный   в   процессе   суммирования   всех   расчетных   нагрузок теплопотребляющих систем теплового пункта.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (45, N'DR_OUT', N'DR', N'b15', N'16.DвнДиафТеплСист', N'16.Внутр. диам. голов. дросс. диафр. для вент. и ГВС или отопл. и ГВС', N'Внутр. диам. голов. дросс. диафр. для вент. и ГВС или отопл. и ГВС', N'"Внутренний диаметр головной дроссельной диафрагмы для вентиляции  и ГВС  или  для  отопления  и  ГВС  " - числовое поле, значение которого отражает результаты  расчета внутреннего  диаметра головной  диафрагмы общей  для  систем  вентиляции  и  закрытой  ГВС  или  для отопления и закрытой  ГВС,  если  они   имеют  соизмеримые  по  величине   остатки располагаемого   напора,   не   погашенные   их   первыми    ступенями дросселирования.   Формулы для  расчета внутренних  диаметров диафрагм приведены  при  описании  входной  информации объекта "Диафрагма".', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (46, N'DR_OUT', N'DR', N'b16', N'17.ГасНапДиафТеплСист', N'17.Гасим. напор на голов. диафр. для вент. и ГВС или отопл. и ГВС', N'Гасим. напор на голов. диафр. для вент. и ГВС или отопл. и ГВС', N'"Гасимый напор на  головной диафрагме для  вентиляции и ГВС  или для отопления  и  ГВС"   -  числовое  поле, значение  которого   отражает результаты  расчета  гасимого  напора, на  упомянутой  диафрагме   в соответствии    с    принципом    двухступенчатого     дросселирования располагаемого   напора   теплового   пункта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (47, N'DR_OUT', N'DR', N'b17', N'18.РасхДиафТеплСист', N'18.Расч. расход через голов. диафр. для вент. и ГВС или отопл.и ГВС', N'Расчет. расход через голов. диафр. для вент. и ГВС или отопл.и ГВС', N'"Расчетный расход через головную диафрагму для вентиляции и ГВС  или для  отопления  и  ГВС"  -  числовое  поле, значение  которого отражает расчетный  расход  теплоносителя, полученный  в  процессе  суммирования заданных расчетных  нагрузок  теплового  пункта  на  вентиляцию  и  ГВС  или на отопление и  ГВС.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (48, N'DR_OUT', N'DR', N'b18', N'19.DвнДиафПодп', N'19.Внутр. диам. подпорной дросс. диафр. на выходе ИТП', N'Внутр. диам. подпорной дросс. диафр. на выходе ИТП', N'"Внутренний диаметр подпорной дроссельной диафрагмы на выходе ИТП" - числовое  поле,   значение  которого   отражает  результаты    расчета внутреннего диаметра подпорной диафрагмы, общей для всех  подключенных теплопотребляющих  систем  теплового  пункта.', NULL, N'мм')
