INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (59, N'DR_OUT', N'DR', N'b29', N'30.РасхДиафВент', N'30.Расч.расход через диафрагму на входе системы вентиляции', N'Расчетный расход через диафрагму на входе системы вентиляции', N'"Расчетный расход  через диафрагму  на входе  системы вентиляции"  - числовое   поле,значение    которого   отражает    расчетный    расход теплоносителя на систему  вентиляции, указанный во входной информации расчета дроссельных органов теплового пункта.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (60, N'DR_OUT', N'DR', N'b3', N'4.НаимПотреб', N'4.Содержательное наименование потребителя', N'Содержательное наименование потребителя', N'"Содержательное  наименование  потребителя"  -  символическое   имя, определяющее полное  содержательное наименование  потребителя в  такой форме, как  оно определено  и используется  в разнообразных  учетных и отчетных  документах,  а  также   расчетных  схемах,  используемых   в теплосети.  Например, "КГБ корпус 4", "ЦТП на Гоголя 12".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (61, N'DR_OUT', N'DR', N'b30', N'31.DвнДиафГВзакр', N'31.Внутр.диам. дросс. диафр. на входе подогр.закр.ГВС', N'Внутренний диам. дросс. диафр. на входе подогр. закрытой ГВС', N'"Внутренний  диаметр  дроссельной  диафрагмы  на входе подогревателя закрытой ГВС" - числовое  поле, значение которого отражает  результаты расчета  внутреннего  диаметра  диафрагмы,  устанавливаемой в качестве первой ступени дросселирования  на входе подогревателя  второй ступени закрытой ГВС.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (62, N'DR_OUT', N'DR', N'b31', N'32.ГасНапДиафГВзакр', N'32.Гасимый напор на диафр. на входе подогр.закр.ГВС', N'Гасимый напор на диафр. на входе подогр. закрытой ГВС', N'"Гасимый напор на диафрагме  на входе подогревателя закрытой  ГВС" - числовое поле,значение которого  отражает результаты расчета  гасимого напора    на   упомянутой   диафрагме   в   соответствии  с  принципом двухступенчатого  дросселирования   располагаемого  напора   теплового пункта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (63, N'DR_OUT', N'DR', N'b32', N'33.РасхДиафГВзакр', N'33.Расч.расход через диафр. на входе подогр.закр.ГВС', N'Расчетный расход через диафр. на входе подогр. закрытой ГВС', N'"Расчетный  расход  через  диафрагму  на входе подогревателей закрытой ГВС"  -  числовое  поле,значение  которого  отражает  расчетный расход теплоносителя  на  закрытую  систему  ГВС,  в случае паралельной или смешанной  схем  присоединения   подогревателей.   В   случае  ГВС   с последовательной   схемой   присоединения   подогревателей  упомянутый расчетный расход принимается равным сумме расходов на отопление и  ГВС для отопительного графика и расходу на отопление в случае  повышенного температурного графика.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (64, N'DR_OUT', N'DR', N'b33', N'34.DвнДиафГВпод', N'34.Внутр. диам. дросс. диафр. на входе в под.труб.откр.ГВ', N'Внутр. диам. дросс. диафр. на входе в под. труб-вод откр.', N' "Внутренний  диаметр  дроссельной  диафрагмы  на  входе  в  подающий трубопровод открытой ГВС" - числовое поле, значение которого  отражает результаты расчета внутреннего  диаметра диафрагмы, устанавливаемой  в качестве  первой   ступени  дросселирования   на  входе   в   подоющий трубопровод открытой ГВС, если  последний подключен либо к  подающему, либо  к  обратному  трубопроводам  распределительной  сети  в пределах теплового  пункта.  При  этом   вариант  совместного  водоразбора   из подающего и обратного  трубопроводов теплового пункта  при дроссельной фиксации  нагрузки   ГВС  не   допускается.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (65, N'DR_OUT', N'DR', N'b34', N'35.ГасНапДиафГВпод', N'35.Гасимый напор на диафр. на входе в под. труб-вод откр.', N'Гасимый напор на диафр. на входе в под. труб-вод откр.', N'"Гасимый напор на диафрагме на входе в подающий трубопровод открытой ГВС" -  числовое поле,  значение которого  отражает результаты расчета гасимого напора,  на упомянутой  диафрагме в  соответствии с принципом двухступенчатого  дросселирования   располагаемого  напора   теплового пункта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (66, N'DR_OUT', N'DR', N'b35', N'36.РасхДиафГВпод', N'36.Расч.расход через диафр. на входе в под.труб.откр.ГВ', N'Расчетный расход через диафр. на входе в под. труб-вод откр.', N'"Расчетный расход  через диафрагму  на входе  в подающий трубопровод открытой ГВС"  - числовое  поле, значение  которого отражает расчетный расход  теплоносителя  из  подающего  трубопровода теплового пункта на открытую систему ГВС, указанный  во входной информации расчета дроссельных органов теплового пункта.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (67, N'DR_OUT', N'DR', N'b36', N'37.DвнДиафЦирк', N'37.Внутр. диам. подпорно-цирк. дросс. диафр.в откр.ГВ', N'Внутр. диам. подпорно-циркуляционной дросс. диафр. в откр.', N'"Внутренний диаметр подпорно-циркуляционной дроссельной диафрагмы  в открытой ГВС" - числовое  поле, значение которого отражает  результаты расчета  внутреннего  диаметра  диафрагмы,  устанавливаемой в качестве источника располагаемого напора для обеспечения постоянной  циркуляции теплоносителя в сети  открытой ГВС, исключающей  чрезмерное охлаждение воды  при  отсутствии  нагрузки  ГВС.   Диафрагма  рассчитывается   по расчетному  отопительному  расходу  и   расчетным  потерям  напора   в циркуляционной  сети   ГВС.    Подающий  трубопровод   сети  ГВС   при водоразборе  из  обратного  трубопровода  подключается  ко  входу этой диафрагмы,  а  выход  циркуляционного  трубопровода  -  к  выходу этой диафрагмы.  При водоразборе из подающего трубопровода эта диафрагма не рассчитывается и не устанавливается.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (68, N'DR_OUT', N'DR', N'b37', N'38.ГасНапДиафЦирк', N'38.Гасимый напор на подпорно-цирк.диафр.в откр.', N'Гасимый напор на подпорно-циркуляционной диафр. в откр.', N'"Гасимый напор на подпорно-циркуляционной диафрагме в открытой  ГВС" -  числовое  поле,  значение  которого  отражает  результаты   расчета гасимого напора,  на упомянутой  диафрагме в  соответствии с принципом двухступенчатого  дросселирования   располагаемого  напора   теплового пункта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (69, N'DR_OUT', N'DR', N'b38', N'39.РасхДиафЦирк', N'39.Расч.расход через подпорно-цирк.диафр. в откр.', N'Расчетный расход через подпорно-циркуляционную диафр. в откр.', N'"Расчетный расход через подпорно-циркуляционную диафрагму в открытой ГВС"  -  числовое  поле,  значение  которого отражает расчетный расход теплоносителя на  выходе системы  отопления, который  используется для создания  подпора,  обеспечивающего  циркуляцию  в циркуляционной сети открытой системы ГВС.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (70, N'DR_OUT', N'DR', N'b39', N'40.DвнДиафЦиркОгр', N'40.Внутр. диам. ограничит.-цирк. дросс. диафр. в откр.', N'Внутр. диам. ограничит.-циркуляционной дросс. диафр. в откр.', N'"Внутренний   диаметр   ограничительно-циркуляционной    дроссельной диафрагмы в открытой ГВС" - числовое поле, значение которого  отражает результаты расчета внутреннего диаметра диафрагмы, устанавливаемой  на выходе циркуляционного трубопровода  открытой ГВС с  целью ограничения циркуляционного расхода сетевой воды.  В открытых ГВС без рециркуляции теплоносителя эта  диафрагма не  рассчитывается и  не устанавливается.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (71, N'DR_OUT', N'DR', N'b4', N'5.НапорВхТП', N'5.Напор в подающем трубопроводе на входе в ИТП', N'Напор в подающем трубопроводе на входе в ИТП', N'"Напор в  подающем трубопроводе  на входе  в ИТП"  - цифровое  поле, значение  которого  определяется  в  процессе  расчета гидравлического режима распределительной сети и переписывается в настоящий документ  в форме  пьезометрического  напора.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (72, N'DR_OUT', N'DR', N'b40', N'41.РасхДиафЦиркОгр', N'41.Гасимый напор на ограничит.-цирк.диафр. в откр.', N'Гасимый напор на ограничит.-циркуляц. диафр. в откр.', N'"Гасимый напор на ограничительно-циркуляционной диафрагме в открытой ГВС"  -  числовое  поле,значение  которого отражает результаты расчета гасимого напора,  на упомянутой  диафрагме в  соответствии с принципом двухступенчатого  дросселирования   располагаемого  напора   теплового пункта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (73, N'DR_OUT', N'DR', N'b41', N'42.ГасНапДиафЦиркОгр', N'42.Расч.расход через ограничит.-цирк.диафр. в откр.', N'Расчетный расход через ограничит.-циркуляц. диафр.  в откр.', N'"Расчетный  расход  через  ограничительно-циркуляционную диафрагму в открытой ГВС"  - числовое  поле, значение  которого отражает расчетный расход  теплоносителя  в  циркуляционном  трубопроводе  открытой ГВС и определено во входной информации расчета дроссельных органов теплового пункта.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (74, N'DR_OUT', N'DR', N'b42', N'43.ОбъемСО', N'43.Объем воды в СО', N'Объем воды в системе отопления потребителя тепла.', N'"Объем воды в системе отопления потребителя тепла" - числовое  поле, значение  которого  определяется  через  нагрузку отопления и удельный объем в системе отопления.', NULL, N'м^3')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (75, N'DR_OUT', N'DR', N'b43', N'44.ОбъемВент', N'44.Объем воды в системе вентиляции', N'Объем воды в системе вентиляции потребителя тепла.', N'"Объем воды в системе вентиляции потребителя тепла" - числовое поле, значение которого  определяется через  нагрузку вентиляции  и удельный объем в системе вентиляции.', NULL, N'м^3')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (76, N'DR_OUT', N'DR', N'b5', N'6.НапорВыхТП', N'6.Напор в обратном трубопроводе на входе в ИТП', N'Напор в обратном трубопроводе на входе в ИТП', N'"Напор в  обратном трубопроводе  на входе  в ИТП"  - цифровое  поле, значение  которого  определяется  в  процессе  расчета гидравлического режима распределительной сети и переписывается в настоящий документ  в форме  пьезометрического  напора.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (77, N'DR_OUT', N'DR', N'b6', N'7.РаспНапВхТП', N'7.Располагаемый напор на входе в ИТП', N'Располагаемый напор на входе в ИТП', N' "Располагаемый  напор  на  входе  в  ТПП"  - цифровое поле, значение которого  отражает  располагаемый  напор  на  входе  теплового пункта, полученный в процессе расчета гидравлического режима распределительной сети и переписывается в  настоящий документ в форме  пьезометрического напора.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (78, N'DR_OUT', N'DR', N'b7', N'8.DсоплаЭл', N'8.Диаметр сопла элеватора', N'Диаметр сопла элеватора', N'"Диаметр  сопла  элеватора"  -   цифровое  поле,  значение  которого рассчитывается  в  процессе   обработки  текущего  теплового   пункта расчетной   схемы   при   наличии   нагрузки   отопления  потребителя, присоединенной по элеваторной схеме  и указанной во входной информации по потребителю.  Расчет диаметра сопла выполняется по следующей формуле 
             Dс=9,6*(Gр^2/Hг)^(1/4), мм (1), где  Dс - рассчитанный диаметр сопла элеватора,мм; Gр - расчетный расход   сетевой   воды   на   отопление, т/ч; Hг - напор, гасимый соплом элеватора, м.вод.ст.; 
             Hг = 2*(1,4*Hс*(1+U)^2),м.вод.ст.   (2), где U  -  расчетный  коэффициент смешения; Hc - потери напора в гидравлическом тракте системы отопления при расчетном расходе смешанной воды, м.вод.ст.; 
     Во избежание шума и  вибрации при работе элеватора  гасимый напор не  превышает  двух  минимально  необходимых  располагаемых напоров на входе элеватора, что и отражено в формуле (2).', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (79, N'DR_OUT', N'DR', N'b8', N'9.ГасНапСоплоЭл', N'9.Гасимый напор на сопле элеватора', N'Гасимый напор на сопле элеватора', N'"Гасимый  напор  на  сопле  элеватора  "  -  числовое  поле,значение которого  отражает  результаты  расчета  гасимого напора на упомянутой диафрагме в соответствии с принципом двухступенчатого  дросселирования располагаемого  напора   теплового  пункта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (80, N'DR_OUT', N'DR', N'b9', N'10.РасхСоплоЭл', N'10.Расчетный расход через сопло элеватора', N'Расчетный расход через сопло элеватора', N'"Расчетный расход через сопло элеватора " - числовое поле,  значение которого отражает расчетный расход теплоносителя на систему  отопления теплового пункта, указанный во входной информации расчета дроссельных органов теплового пункта. Для  систем  с  последовательной  схемой включения подогревателей ГВС, расчетный  расход  через  сопло   элеватора  принимают  равным   сумме расчетных  расходов  на  отопление   и  ГВС, в  случае   отопительного температурного  графика, и  расчетному  расходу  на отопление, в случае повышенного   температурного    графика.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (81, N'DR_OUT', N'DR', N'balans', N'47.Балансовая принадлежность', N'47.Балансовая принадлежность', N'Балансовая принадлежность', N'Организация несущая ответственность при эксплуатации и техническом обслуживании объекта системы теплоснабжения, при возникновении аварийных ситуаций на объекте.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (82, N'DR_OUT', N'DR', N'comment', N'46.Комментарий', N'46.Комментарий', N'Комментарий по расчету режима дроссельного органа', N'Комментарий по расчету и выбору дроссельных органов индивидуального теплового пункта по заданной входной информации  расчета дроссельных органов теплового пункта.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (83, N'DR_OUT', N'DR', N'dop17', N'QгвЗакр', N'48.Получ.тепл.нагрузка на ГВ в закр.сист.', N'Тепл.нагрузка на ГВ в закрытой системе', N'"Полученная тепловая нагрузка потребителя на горячее водоснабжение в закрытой системе" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на горячее водоснабжение в закрытой системе, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя  при фиксированных сопротивлениях (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети при заданных температуре наружного воздуха и нагрузке на на горячее водоснабжение, а также тепловых характеристик  оборудования закрытой системы горячего водоснабжения, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (84, N'DR_OUT', N'DR', N'dop18', N'QгвПод', N'49.Получ.тепл.нагрузка на ГВ из под.теплопр.', N'Тепл.нагрузка на ГВ из под.теплопр. в откр.сист.', N'"Полученная тепловая нагрузка потребителя на горячее водоснабжение из подающего теплопровода в открытой системе" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на горячее водоснабжение из подающего теплопровода потребителя, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях (фактический режим)  и температурой этого потока, полученной в процессе расчета теплового режима сети при заданных температуре наружного воздуха и нагрузке на на горячее водоснабжение.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (85, N'DR_OUT', N'DR', N'dop19', N'QгвОбр', N'50.Тепл.нагрузка на ГВ из обр.теплопр.', N'Тепл.нагрузка на ГВ из обр.теплопр. в откр.сист.', N'"Полученная тепловая нагрузка потребителя на горячее водоснабжение из обратного теплопровода в открытой системе" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на горячее водоснабжение из обратного теплопровода потребителя, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях (фактический режим) и температурой этого потока, полученной в процессе расчета теплового режима сети при заданных температуре наружного воздуха и нагрузке на на горячее водоснабжение.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (86, N'DR_OUT', N'DR', N'dop20', N'QгвЦирк', N'51.Тепл.нагрузка в цирк.теплопр.ГВС', N'Тепл.нагрузка в цирк.теплопроводе ГВС', N'"Полученная тепловая нагрузка потребителя в циркуляционном теплопроводе ГВС" - цифровое поле, значение которого для закрытых систем горячего водоснабжения вычисляется в соответствии с величиной расхода  сетевой воды в циркуляционном теплопроводе системы горячего водоснабжения, полученной в процессе расчета потокораспределения сети  и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях (фактический режим), для открытых - величиной расхода циркулируемой горячей воды, а также температурой этого потока, полученной в процессе расчета теплового режима сети при заданных температуре наружного воздуха и нагрузке на на горячее водоснабжение, а также тепловых характеристик оборудования системы горячего водоснабжения, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (87, N'DR_OUT', N'DR', N'kod', N'КодРСПотр', N'2.Код расчетнoй схемы', N'Код расчетнoй схемы', N'"Код расчетной схемы" - символьное поле, значение  которого однозначно  определяет  расчетную  схему,  которой   принадлежит потребитель, с установленным дроссельным устройством.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (88, N'DR_OUT', N'DR', N'kod_p', N'КодРСУзПрис', N'Код расч.сх.узла присоед.', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы потребителя, куда дроссельное устройство входит как один из составляющих её элементов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (89, N'DR_OUT', N'DR', N'pr_p', N'ПризнУзПрис', N'Признак теплопр.узла присоед.', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы потребителя, куда дроссельное устройство входит как один из составляющих её элементов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (90, N'DR_OUT', N'DR', N'Qotn', N'Qсо_незав', N'42.Тепл.нагрузка на отопл., незав.сх.', N'Тепл.нагрузка  на отопление, незав.сх.', N'"Полученная тепловая нагрузка потребителя на отопление, независимая схема" -   цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на независимую систему отопления, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях элементов оборудования (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла, а также  тепловых характеристик оборудования  независимой системы отопления, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (91, N'DR_OUT', N'DR', N'Qotz', N'Qсо_зав', N'41.Тепл.нагрузка на отопл., зав.сх.', N'Тепл.нагрузка  на отопление, зав.сх.', N'"Полученная тепловая нагрузка потребителя на отопление, зависимая схема" -   цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на  зависимую систему отопления, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях элементов оборудования (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла, а также  тепловых характеристик оборудования зависимой системы отопления, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (92, N'DR_OUT', N'DR', N'uzel', N'НаимУзПотр', N'3.Наим.узла присоед.потребителя', N'Наименование узла присоединения потребителя', N'"Наименование  узла  присоединения потребителя"  -  символьное  поле, значение которого  однозначно  определяет  имя потребителя на данной расчетной схеме, с установленным дроссельным устройством.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (93, N'DR_OUT', N'DR', N'uzel_p', N'НаимУзУзПрис', N'Наим.узла присоед.', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы потребителя, куда дроссельное устройство входит как один из составляющих её элементов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (94, N'DR_OUT', N'PR', N'cxema', N'НомРасчСх', N'Номер расчетной схемы', N'Номер расчетной схемы', N'Номер расчетной схемы', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (95, N'DR_OUT', N'PR', N'diam_o', N'46.ВнутрДиамОбратка', N'46.Внутренний диаметр трубопров. на выходе потребителя', N'Внутренний диаметр трубопров. на выходе потребителя', N'"Внутренний диаметр трубопровода на выходе потребителя" - цифровое поле, значение которого отображает внутренний диаметр участка трубопровода на выходе потребителя.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (96, N'DR_OUT', N'PR', N'diam_p', N'45.ВнутрДиамПодача', N'45.Внутренний диаметр трубопров. на входе потребителя', N'Внутренний диаметр трубопрод. на входе потребителя', N'"Внутренний диаметр трубопровода на входе потребителя" - цифровое поле, значение которого отображает внутренний диаметр участка трубопровода на входе потребителя.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (97, N'DR_OUT', N'PR', N'gvoo', N'СреднНагрОткрГВОбр', N'Сред.тепл.нагрузка на ГВ, обратный теплопровод', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая  нагрузка  горячего  водоснабжения потребителя  в  открытой  системе  из  обратного трубопровода" - цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления.  Величина  среднечасовой нагрузки  принимается  по  типовым  или  индивидуальным проектам систем  горячего  водоснабжения,  выполненным  в  соответствии с требованиями  СНиП для  проектирования  горячего  водоснабжения. Кроме  того, значение  поля  может  быть  получено  на основании анализа фактических данных водоразбора для конкретного теплового пункта. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (98, N'DR_OUT', N'PR', N'gvop', N'РасчНагрОткрГВПод', N'Сред.тепл.нагрузка на ГВ, подающий теплопровод', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая  нагрузка  горячего  водоснабжения потребителя  в  открытой  системе  из  подающего трубопровода" - цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления.  Величина  среднечасовой нагрузки  принимается  по  типовым  или  индивидуальным проектам систем  горячего  водоснабжения,  выполненным  в  соответствии с требованиями  СНиП для  проектирования  горячего  водоснабжения. Кроме  того, значение  поля  может  быть  получено  на основании анализа фактических данных водоразбора для конкретного теплового пункта. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (99, N'DR_OUT', N'PR', N'gvpr', N'СреднНагрПаралГВ', N'Сред.тепл.нагрузка на ГВ, параллельная сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  параллельном включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (100, N'DR_OUT', N'PR', N'gvps', N'СреднНагрПоследГВ', N'Сред.тепл.нагрузка на ГВ последовательная сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  последовательном включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (101, N'DR_OUT', N'PR', N'gvpw', N'СреднНагрПредвклГВ', N'Сред.тепл.нагрузка на ГВ, предвключ.сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  предвключенном включении подогревателя  ГВ"   -  цифровое   поле,  значение    которого соответствует среднедельной часовой тепловой нагрузке  на ГВ для указанной схемы включения подогревателей  и назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (102, N'DR_OUT', N'PR', N'gvsm', N'СреднНагрСмешГВ', N'Сред.тепл. нагрузка на ГВ, смешанная сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка  на   ГВ потребителя  в  закрытой   системе   при  смешанном   включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (103, N'DR_OUT', N'PR', N'kondiz', N'РасчНагрКондиц', N'Расчетная нагрузка на кондиционирование', N'Расчетная  тепловая нагрузка на кондиционирование', N'"Расчетная тепловая  нагрузка  или  расход  на  кондиционирование"  - цифровое  поле,  значение  которого  принимается  по типовым или индивидуальным    проектам    потребителей    или    назначается пользователем. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (104, N'DR_OUT', N'PR', N'otopln', N'РасчНагрСОнезав', N'Расчетная  нагрузка на отопление, незав.СО', N'Расчетная тепловая нагрузка на  отопление', N'"Расчетная тепловая  нагрузка  или  расход  на отопление, независимая схема"- цифровое поле, значение которого принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по независимой  схеме  или  назначается  пользователем,  исходя  из определенных  целей  расчета. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (105, N'DR_OUT', N'PR', N'otoplz', N'РасчНагрСОзав', N'Расчетная нагрузка на отопление, зав.СО', N'Расчетная тепловая нагрузка на  отопление', N' "Расчетная тепловая  нагрузка на  отопление,  зависимая схема"- цифровое поле, значение которого принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по зависимой    схеме    или   назначается   пользователем,  исходя из   определенных   целей   расчета. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (106, N'DR_OUT', N'PR', N'rez', N'ТеплПотери в рециркулКонтуре', N'Расчетные тепловые потери в рецирк. контуре ГВС', N'Расчетные тепловые потери в рециркуляц. контуре ГВС', N'"Расчетные тепловые потери в рециркуляцинном контуре ГВС"   -  цифровое поле, значение которого определяется тепловыми  потерями   в трубопроводах    циркуляционной  ГВС (Qтп). На практике значение потерь определяют долей от среднечасовой  нагрузки ГВС, т.е.   Qтп=Qср*К, где  К=0.05-0.3. Значение  поля  используется при расчете теплогидравлических режимов тепловых пунктов (ЦТП) только с открытой  ГВС  циркуляционного  типа. Значение   поля   имеет  процентную  размерность и вводится, например, в виде целочисленной  константы  20 (при 20%-ых потерях). Поле заполняется при наличии у данного потребителя рециркуляции.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (107, N'DR_OUT', N'PR', N'ventil', N'РасчНагрВент', N'Расчетная нагрузка на вентиляцию', N'Расчетная тепловая нагрузка  на вентиляцию', N'"Расчетная тепловая  нагрузка  или  расход  на вентиляцию" - цифровое поле,   значение   которого    принимается   по   типовым    или индивидуальным    проектам    потребителей    или    назначается пользователем, исходя из  определенных целей расчета. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (108, N'DRO_OUT', N'BP', N'a10', N'ПотНап', N'Потери напора', N'Потери напора на диафрагме', N'"Потери  напора  на  диафрагме"  - цифровое поле,значение  которого определяется  в  процессе   расчета  гидравлического  режима  потребителя как разность напоров  входного  и выходного узлов  диафрагмы.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (109, N'DRO_OUT', N'BP', N'a11', N'ГидрСопр', N'Полное гидравлическое сопротивление', N'Полное гидравлическое сопротивление диафрагмы', N'"Полное  гидравлическое  сопротивление дроссельного устройства"  - цифровое поле, значение которого определяется через диаметр диафрагмы.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (110, N'DRO_OUT', N'BP', N'a12', N'РаспНапКонУз', N'Располагаемый напор в конечном узле', N'Располагаемый напор в конечном узле диафрагмы', N'"Располагаемый  напор  в  конечном  узле дроссельного устройства"  - цифровое  поле,  значение  которого  определяется  в  процессе расчета гидравлического     режима      потребителя     как      разность      между полными (пьезометрическими) напорами в подающем и обратном трубопроводе дроссельного устройства  для  конечного  узла.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (111, N'DRO_OUT', N'BP', N'a13', N'ПьезНапКонУз', N'Пьзометрический напор в конечном узле', N'Пьзометрический напор в конечном узле диафрагмы', N'"Пьезометрический  напор  в конечном  узле трубопровода диафрагмы" - цифровое  поле,  значение  которого  определяется  в  процессе расчета гидравлического  режима  сети  как  разность  между  полным  напором и геодезической отметкой  местности в  конечном узле диафрагмы.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (112, N'DRO_OUT', N'BP', N'a14', N'ГеодОтмКонУз', N'Геодезические отметки местности в конечном узле', N'Геодезические отметки местности в конечном узле диафрагмы', N'"Геодезическая отметка местности" - цифровое поле, значение которого определяется значением геодезической отметки оси трубопроводов в месте расположения данного узла присоединения  диафрагмы.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (113, N'DRO_OUT', N'BP', N'a15', N'ПолнНапКонУз', N'Полный напор в конечном узле', N'Полный напор в конечном узле диафрагмы', N'"Полный напор в конечном узле трубопровода с диафрагмой" - цифровое поле, значение  которого  определяется  в  процессе  расчета гидравлического режима  потребителя путем  суммирования  полного  напора  в  начальном  узле диафрагмы и  общих  потерь  напора  на устройстве  с учетом  направления расхода.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (114, N'DRO_OUT', N'BP', N'a8', N'Место установки', N'Место установки', N'Место установки диафрагмы', N'"Место установки диафрагиы" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения диафрагмы на теплопроводах потребителя.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (115, N'DRO_OUT', N'BP', N'kod_p', N'КодРСУзПрис', N'Код расч.сх.узла присоед.', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (116, N'DRO_OUT', N'BP', N'kod1', N'КодРСНачУз', N'Код расч.сх.нач.узла', N'Код расчетной схемы начального узла диафрагмы', N'«Код расчетной схемы начального узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на входе диафрагмы.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (117, N'DRO_OUT', N'BP', N'kod2', N'КодРСКонУз', N'Код расч.сх.кон.узла', N'Код расчетной схемы конечного узла диафрагмы', N'«Код расчетной схемы конечного узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на выходе диафрагмы.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (118, N'DRO_OUT', N'BP', N'nomer', N'1.№', N'1.№', N'Порядковый номер экземпляра', N'Порядковый номер экземпляра данного класса. Недопустимая  для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (119, N'DRO_OUT', N'BP', N'pr_p', N'ПризТеплУзПрис', N'Признак теплопр.узла присоед.', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (120, N'DRO_OUT', N'BP', N'pr1', N'ПризТеплНачУз', N'Признак трубопровода начального узла', N'Признак трубопровода начального узла диафрагмы', N'"Признак теплопровода начального узла" - символьное поле, значение которого значения "Подача" или "Обратка" используются для указания принадлежности узла на входе диафрагмы только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (121, N'DRO_OUT', N'BP', N'pr2', N'ПризТеплКонУз', N'Признак трубопровода конечного узла', N'Признак трубопровода конечного узла диафрагмы', N'"Признак теплопровода конечного узла" - символьное поле, значение которого "Подача" или "Обратка" используются для указания принадлежности узла на выходе диафрагмы только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (122, N'DRO_OUT', N'BP', N'ras', N'Расход', N'Расход сетевой воды через диафрагму', N'Расход сетевой воды через диафрагму', N'"Расход  сетевой  воды  через  диафрагму"  - цифровое поле, значение которого   определяется   в   процессе   расчета  потокораспределения потребителя.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (123, N'DRO_OUT', N'BP', N'sos', N'Состояние', N'Состояние', N'Состояние', N'"Состояние диафрагмы" - символьное поле, значение которого однозначно определяет состояние, в котором находится диафрагма.', NULL, NULL)
