INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (125, N'DRO_OUT', N'BP', N'uzel1', N'НаимНачУз', N'Наим.нач.узла', N'Наименование начального узла диафрагмы', N'"Наименование начального узла" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения диафрагмы на теплопроводах потребителя и задания направления потока теплоносителя через диафрагму.', NULL, NULL)
