INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (478, N'MAIN_OUT', N'UT', N'uzel2', N'НаимКонУзУч', N'Наим.кон.узла участка трубопр.', N'Наименование конечного узла участка трубопровода', N'Наименование конечного узла участка трубопровода', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (479, N'NS_OUT', N'NS', N'a10', N'РабЗона:1тчк-G', N'11.Коорд.рабочей зоны: 1-я точка -расход', N'Координаты рабочей зоны: 1-я точка -расход', N'"Координаты  рабочей  зоны:   1-я  точка-расход"  -  цифровое поле, значение  которого  определяет  абсциссу  левой  границы  рабочей зоны характеристики  насоса   (насосной группы). Значение  поля представляет собой  значение соответствующего входного свойства объекта.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (480, N'NS_OUT', N'NS', N'a11', N'РабЗона:2тчк-H', N'12.Коорд.рабочей зоны:2-я точка -напор', N'Координаты рабочей зоны:2-я точка -напор', N'"Координаты  рабочей  зоны:   2-я  точка-напор"  -  цифровое  поле, значение  которого  определяет  ординату  правой  границы рабочей зоны характеристики  насоса (насосной группы). Значение  поля представляет собой  значение соответствующего входного свойства объекта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (481, N'NS_OUT', N'NS', N'a12', N'РабЗона:2тчк-G', N'13.Коорд.рабочей зоны:2-я точка -расход', N'Координаты рабочей зоны:2-я точка -расход', N'"Координаты  рабочей  зоны:   2-я  точка-расход"  -  цифровое поле, значение  которого  определяет  абсциссу  правой  границы рабочей зоны характеристики  насоса (насосной группы). Значение  поля представляет собой  значение соответствующего входного свойства объекта.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (482, N'NS_OUT', N'NS', N'a13', N'РабНапор', N'14.Рабочий напор', N'Рабочий напор насоса', N'"Рабочий  напор насоса (насосной  группы)" -  цифровое поле, значение которого  соответствует  заданному  во  входном свойстве объекта значению напора (случай описания характеристики насоса (насосной группы) в  виде параллельной оси расходов линией)  и в данный документ  переписывается из входной записи, или же равно напору, развиваемому насосной станцией для  рассчитанного  расхода  в  данном  гидравлическом режиме сети при задании  параболлической  характеристики  насоса  (насосной  группы).', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (483, N'NS_OUT', N'NS', N'a14', N'Расход', N'15.Расход воды через насос', N'Расход воды через насос', N'Расход  воды  через  насос (насосную  группу)  -  цифровое  поле, значение  которого  представляет  собой  расход  сетевой  воды   через насос (насосную  группу)   (производительность    насосной группы)    для вычисленного   гидравлического   режима.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (484, N'NS_OUT', N'NS', N'a15', N'ПьзНапНаВх', N'16.Пьез.напор в узле на входе', N'Пьезометрический напор в узле на входе насоса', N'"Пьезометрический  напор  на  входе  насоса (насосной  группы)"   - цифровое поле,  значение которого  - это  вычисленный пьезометрический напор в узле, являющемся  входом насоса ( насосной группы).', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (485, N'NS_OUT', N'NS', N'a16', N'ПьзНапНаВых', N'17.Пьез.напор в узле на выходе', N'Пьезометрический напор в узле на выходе', N'"Пьезометрический напор на выходе насоса (насосной группы)" -  цифровое поле, значение  которого -  это вычисленный  пьезометрический напор  в узле,  являющемся   выходом  насоса (   насосной  группы).', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (486, N'NS_OUT', N'NS', N'a17', N'Загрузка', N'18.Загрузка', N'Загрузка насосной станции', N'"Загрузка  насоса (насосной  группы)"  -  символьное  поле, значение которого  определяется  режимом  работы  насосной  станции  в   данном гидравлическом  режиме.   В   качестве  значений  используются   слова "перегруз.",   "недогруз.",   "рабочая",   соответственно  фиксирующие положение рабочей точки насосной станции в рабочей зоне характеристики или за ее пределами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (487, N'NS_OUT', N'NS', N'a18', N'КолНас', N'19.Кол.насосов', N'Количество насосов', N'"Количество   насосов"   -   цифровое   поле,   значение  которого соответствует количеству насосов установленных в насосной группе.', NULL, N'штук(и)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (488, N'NS_OUT', N'NS', N'a19', N'ТипНас', N'20.Тип насосов', N'Тип насосов', N' "Тип насосов" - символьное поле, значение которого характеризует тип установленных в насосной группе насосов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (489, N'NS_OUT', N'NS', N'a3', N'ГеодОтмВхУз', N'Геодез. отметка верха вх.узла', N'Геодезическая отметка верха трубы узла на входе', N'"Геодезическая отметка верха трубы узла на входе" - цифровое поле, значение которого определяет геодезическую отметку верха трубопровода в месте расположения узла на входе  насоса (насосной группы) и используется при расчете гидравлического режима расчетной схемы.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (490, N'NS_OUT', N'NS', N'a4', N'ГеодОтмЗемВхУз', N'5.Геод.отметка поверхн.земли вх.узла', N'Геодезическая отметка поверхности земли узла на входе', N'"Геодезическая отметка поверхности земли узла на входе" - цифровое поле, значение которого определяет геодезическую отметку поверхности земли в месте расположения узла на входе насоса (насосной группы).', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (491, N'NS_OUT', N'NS', N'a7', N'ГеодОтмВыхУз', N'Геодез. отметка верха вых.узла', N'Геодезическая отметка верха трубы узла на выходе', N'"Геодезическая отметка верха трубы узла на выходе" - цифровое поле, значение которого определяет геодезическую отметку верха трубопровода в месте расположения узла на выходе  насоса (насосной группы) и используется при расчете гидравлического режима расчетной схемы.', NULL, N'м')
