INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (493, N'NS_OUT', N'NS', N'a9', N'РабЗона:1тчк-H', N'10.Коорд.раб.зоны: 1-я точка -напор', N'Координаты рабочей зоны: 1-я точка -напор', N'"Координаты рабочей зоны:  1-я точка-напор" - цифровое поле, значение которого определяет ординату левой границы рабочей зоны характеристики насоса  (насосной группы). Значение  поля представляет собой  значение соответствующего входного свойства объекта.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (494, N'NS_OUT', N'NS', N'kod_p', N'КодРСУзПрис', N'21.Код расч.сх.узла присоед.', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда насос входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (495, N'NS_OUT', N'NS', N'kod1', N'КодРСВхУз', N'2.Код расч.сх.узла на входе насоса', N'Код расчетной схемы узла на входе насоса', N'Код  расчетной схемы  узла на  входе насоса"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на входе насоса  (насосной группы).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (496, N'NS_OUT', N'NS', N'kod2', N'КодРСВыхУз', N'6.Код расч.сх.узла на выходе насоса', N'Код расчетной схемы узла на выходе насоса', N'Код  расчетной схемы  узла на  выходе насоса"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на выходе насоса  (насосной группы).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (497, N'NS_OUT', N'NS', N'nomer', N'№', N'1.№', N'Порядковый номер экземпляра', N'Порядковый номер экземпляра данного класса. Закрытая для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (498, N'NS_OUT', N'NS', N'pr_p', N'ПризУзПрис', N'23.Признак теплопровода узла присоединения', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда насос входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (499, N'NS_OUT', N'NS', N'pr1', N'ПризВхУз', N'4.Признак трубопровода узла на входе насоса', N'Признак трубопровода узла на входе насоса', N'"Признак  трубопровода узла  на входе насоса  (насосной группы)" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  начального  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  трубопроводам  на  расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (500, N'NS_OUT', N'NS', N'pr2', N'ПризВыхУз', N'8.Признак трубопровода узла на выходе насоса', N'Признак трубопровода узла на выходе насоса', N'"Признак  трубопровода узла  на выходе насоса  (насосной группы)" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности конечного  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  трубопроводам  на  расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (501, N'NS_OUT', N'NS', N'sos', N'Состояние', N'Состояние', N'Состояние насосного агрегата', N' Состояние насосного агрегата"- символьное поле, значение которого  "Закрыто"  - закрыт(отключен)  или "Открыто"-  открыт(подключен) позволяет пользователю, не удаляя данный объект закрыть насосный агрегат.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (502, N'NS_OUT', N'NS', N'uzel_p', N'НаимУзПрис', N'22.Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда насос входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (503, N'NS_OUT', N'NS', N'uzel1', N'НаимВхУз', N'3.Наименование узла на входе насоса', N'Признак трубопровода узла на входе насоса', N'"Наименование узла  на входе насоса  (насосной группы)"  - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно определяет узел на  расчетной  схеме.   Это  наименование  используется  для  указания заданного   направления    потока   сетевой    воды   через    насос  (насосную группы).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (504, N'NS_OUT', N'NS', N'uzel2', N'НаимВыхУз', N'7.Наименование узла на выходе насоса', N'Признак трубопровода узла на выходе насоса', N'"Наименование узла  на выходе насоса  (насосной группы)"  - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно определяет узел на  расчетной  схеме.   Это  наименование  используется  для  указания заданного   направления    потока   сетевой    воды   через    насос  (насосную группы).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (505, N'NST_OUT', N'ST', N'Dp', N'ПотериНап', N'Потери  напора', N'Потери  напора  на  насосной станции', N'"Потери  напора  на  насосной станции" - цифровое поле, значение  которого  определяется  в  процессе  расчета гидравлического режима  сети  как  абсолютная  разность  полных  напоров  в конечном и начальном узлах присоединения насосной станции .', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (506, N'NST_OUT', N'ST', N'kod', N'КодРС', N'Код расчетной схемы', N'Код расчетной схемы', N'"Код расчетной схемы" - символьное поле, значение которого определяет расчетную схему, которой принадлежит узел насосной станции.', NULL, NULL)

