INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (512, N'NST_OUT', N'ST', N'pr_p', N'ПризнТеплопрУзПрисоед', N'Признак теплопровода  узла присоединения', N'Признак теплопровода  узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами. Узел присоединения определяет узел присоединения расчетной схемы насосной станции, если она создана командой "Создать схему".', NULL, NULL)
