INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (583, N'PT_OUT', N'PT', N'a10', N'GтехнОбр', N'12.Расход на техн.из обр.теплопр. в откр сист.', N'Расход на техн. из обр.теплопр. в откр.cистеме', N'Полученный  расход  сетевой  воды  на  технологические процессы в открытой системе  из обратного  трубопровода - цифровое  поле, значение  которого при расчете планового режима (с  фиксированными  нагрузками  потребителей) тепловой сети равен расчетному  (заданному)  расходу,  вычисленному на основании исходных данных по потребителю (удельным расходам, расчетной тепловой нагрузки, эксплуатационному температурному графику). При расчете фактического гидравлического режима (с  фиксированными  гидравлическими   сопротивлениями) тепловой сети  полученный расход может определятся двумя способами. Первый способ, расход  вычисляется в результате расчета пототокораспределения сетевой воды и определяется параметрами тепловой сети и гидравлическим сопротивлением потребителя. Второй способ, если значение поля "Признак расчета аварийного режима потребителя" равен "Нагрузка", то полученный расход фиксируется и определяется его расчетным (заданным) расходом.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (584, N'PT_OUT', N'PT', N'a11', N'GгвЗакр', N'13.Расход на Г.В. в закрытой сист.', N'Расход  на ГВ в закрытой системе', N'"Полученный расход потребителя на горячее водоснабжение в  закрытой системе"  -  цифровое  поле, значение  которого при расчете планового режима (с  фиксированными  нагрузками  потребителей) тепловой сети равен расчетному  (заданному)  расходу,  вычисленному на основании исходных данных по потребителю (удельным расходам, расчетной тепловой нагрузки, эксплуатационному температурному графику). При расчете фактического гидравлического режима (с  фиксированными  гидравлическими   сопротивлениями) тепловой сети  полученный расход может определятся двумя способами. Первый способ, расход  вычисляется в результате расчета пототокораспределения сетевой воды и определяется параметрами тепловой сети и гидравлическим сопротивлением потребителя. Второй способ, если значение поля "Признак расчета аварийного режима потребителя" равен "Нагрузка", то полученный расход фиксируется и определяется его расчетным (заданным) расходом.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (585, N'PT_OUT', N'PT', N'a12', N'GгвПод', N'14..Расход на Г.В. из под.трубопр. в откр.сист.', N'Расход на ГВ из под.трубопр. в откр.системе', N'"Полученный расход сетевой воды на горячее водоснабжение в открытой системе  из  подающего  теплопровода" -  цифровое  поле, значение  которого при расчете планового режима (с  фиксированными  нагрузками  потребителей) тепловой сети равен расчетному  (заданному)  расходу,  вычисленному на основании исходных данных по потребителю (удельным расходам, расчетной тепловой нагрузки, эксплуатационному температурному графику). При расчете фактического гидравлического режима (с  фиксированными  гидравлическими   сопротивлениями) тепловой сети  полученный расход может определятся двумя способами. Первый способ, расход  вычисляется в результате расчета пототокораспределения сетевой воды и определяется параметрами тепловой сети и гидравлическим сопротивлением потребителя. Второй способ, если значение поля "Признак расчета аварийного режима потребителя" равен "Нагрузка", то полученный расход фиксируется и определяется его расчетным (заданным) расходом.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (586, N'PT_OUT', N'PT', N'a13', N'GгвОбр', N'15.Расход на Г.В. из обр.теплопр. в откр.сист.', N'Расход  на ГВ из обр.теплопр. в откр.системе', N'"Полученный расход сетевой воды на горячее водоснабжение в открытой системе  из  обратного  трубопровода" -  цифровое  поле, значение  которого при расчете планового режима (с  фиксированными  нагрузками  потребителей) тепловой сети равен расчетному  (заданному)  расходу,  вычисленному на основании исходных данных по потребителю (удельным расходам, расчетной тепловой нагрузки, эксплуатационному температурному графику). При расчете фактического гидравлического режима (с  фиксированными  гидравлическими   сопротивлениями) тепловой сети  полученный расход может определятся двумя способами. Первый способ, расход  вычисляется в результате расчета пототокораспределения сетевой воды и определяется параметрами тепловой сети и гидравлическим сопротивлением потребителя. Второй способ, если значение поля "Признак расчета аварийного режима потребителя" равен "Нагрузка", то полученный расход фиксируется и определяется его расчетным (заданным) расходом.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (587, N'PT_OUT', N'PT', N'a14', N'GгвЦирк', N'16.Расход в цирк.теплопр.ГВС', N'Расход в циркуляционном теплопроводе ГВС', N'"Полученный  расход   потребителя   в   циркуляционном  трубопроводе трубопроводе ГВС" - цифровое поле, значение которого  определяется  двумя способами. При   моделировании  плановых  режимов  (режимы   с фиксированными  нагрузками  потребителей)  оно  просто  считываются  из исходных данных по потребителю в расчетной Базе данных. При моделировании  фактических режимов ( режимы   с  фиксированными  гидравлическими   сопротивлениями потребителей ) оно вычисляется  следующим образом: Gрец=Qтп/(dt*с), где dt=((Тг-Тх)-Тост), где Тг - температура горячей воды в системе горячего водоснабжения с непосредственным водоразбором, Тх - температура водопроводной воды, Qтп - тепловые потери в рециркуляционном контуре, Тост - температура остыва, до которой допустимо остывание сетевой воды в рециркуляционном трубопроводе ГВС за счет тепловых потерь, при нулевой нагрузке ГВС.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (588, N'PT_OUT', N'PT', N'a15', N'GsumЗакр', N'17.Суммарный расход в закрытой системе', N'Суммарный расход  в закрытой системе', N'"Полученный расход  сетевой воды  в закрытой  системе суммарный" - цифровое поле,  значение которого  определяется простым  суммированием значений нагрузок на все виды теплопотребления в закрытой системе  при расчете гидравлического режима  на заданную нагрузку  потребителя или, вычисляются  в  процессе  расчета  потокораспределения  при   заданном гидравлическом  сопротивлении   потребителя  для   закрытой   системы.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (589, N'PT_OUT', N'PT', N'a16', N'GsumПод', N'18.Сумм.расход из под.теплопр. в откр.сист.', N'Суммарный расход  из под.трубопр. в откр.системе', N'"Полученный  расход сетевой  воды в  открытой системе  из подающего теплопровода суммарный" - цифровые поле, значение которого определяется простым суммированием  значений расходов  на все  виды водоразбора  из подающего теплопровода при расчете гидравлического режима на  заданную нагрузку   потребителя    или   вычисляется    в   процессе    расчета потокораспределения   при   заданном   для   подающего  теплопровода гидравлическом сопротивлении потребителя в открытой системе.', N'Расход', NULL)

