INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (590, N'PT_OUT', N'PT', N'a17', N'GsumОбр', N'19.Сумм.расход из обр.теплопр. в откр.сист.', N'Суммарный расход потребителя из обр.теплопр. в откр.системе', N'"Полученный  расход сетевой  воды в  открытой системе  из обратного теплопровода, суммарный" - цифровое поле, значение которого определяется простым суммированием  значений расходов  на все  виды водоразбора  из обратного теплопровода при расчете гидравлического режима на  заданную нагрузку   потребителя    или   вычисляется    в   процессе    расчета потокораспределения   при   заданном   для   обратного    теплопровода гидравлическом сопротивлении потребителя.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (591, N'PT_OUT', N'PT', N'a18', N'GотнЗакр', N'20.Отн.расход сет.воды в закр.сист.', N'Относительный расход сетевой воды в закрытой системе', N'"Относительный расход  сетевой воды в  закрытой системе" -  цифровое поле, значение  которого определяется  отношением суммарного  полученного расхода сетевой  воды в закрытой  системе к суммарному  заданному расходу сетевой воды в закрытой системе. Значение поля -  безразмерная величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (592, N'PT_OUT', N'PT', N'a19', N'GутечПод', N'21.Заданная утечка из под.теплопр.', N'Заданное значение утечки из подающего теплопровода', N'"Заданное значение утечки из подающего теплопровода" - цифровое поле, значение  которого  считываются  из  исходных данных по потребителю  и  позволяет моделировать   негерметичность  сальниковых  компенсаторов и различной арматуры,  расположенной  в   непосредственной    близости   от  узла присоединения  данного потребителя  на  подающем теплопроводе.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (593, N'PT_OUT', N'PT', N'a20', N'GутечОбр', N'22.Заданная утечка из обр.теплопр.', N'Заданное значение утечки из обратного теплопровода', N'"Заданное значение утечки из обратного теплопровода" - цифровое поле, значение  которого  считываются   из исходных данных по потребителю  и позволяет моделировать  негерметичность  сальниковых  компенсаторов  и различной арматуры,  расположенной   в   непосредственной   близости   от   узла присоединения  данного  потребителя на обратном теплопроводе.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (594, N'PT_OUT', N'PT', N'a21', N'PпьезПод', N'23.Пьез.напор в под.теплопроводе', N'Пьезометрический напор в подающем теплопроводе', N'"Пьезометрический  напор  в  подающем теплопроводе" - цифровое поле, значение которого определяется в процессе расчета  потокораспределения как  разность  между  полным  напором  и  геодезической  отметкой  верха трубы в  узле присоединения  потребителя.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (595, N'PT_OUT', N'PT', N'a22', N'PпьезОбр', N'24.Пьез.напор в обр.теплопроводе', N'Пьезометрический напор в обратном теплопроводе', N'"Пьезометрический  напор  в  обратном теплопроводе" - цифровое поле, значение которого определяется в процессе расчета  потокораспределения как  разность  между  полным  напором  и  геодезической  отметкой  верха трубы в  узле присоединения  потребителя.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (596, N'PT_OUT', N'PT', N'a23', N'РаспНапор', N'25.Распол.напор в узле присоед.потреб.', N'Располагаемый напор в узле присоединения потребителя', N'"Располагаемый   напор"   -   цифровое   поле,  значение  которого определяется по результатам  расчета потокораспределения как  разность между  полными (пьезометрическими)   напорами  в   узле   присоединения потребителя  на  подающем  и  обратном  теплопроводах.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (597, N'PT_OUT', N'PT', N'a3', N'НаимПотр', N'5.Содержательное наим.потреб.', N'Содержательное наименование', N'"Содержательное наименование потребителя" - символьное поле, значение которого определяет полное наименование потребителя,  например, "ДетСад "Солнышко".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (598, N'PT_OUT', N'PT', N'a4', N'GсоЗав', N'6.Расход на отопл., зав.сх.', N'Расход на отопление, зав.сх.', N'"Полученный  расход  потребителя  на  отопление, зависимая  схема"  - цифровое поле,  значение которого  считываются из  исходных данных по потребителю, если   для   данного   потребителя   отсутствует   его  гидравлическое сопротивление  в  этой  записи   и,  следовательно  при  этом   расчет гидравлического режима ведется  на фиксированную нагрузку  потребителя или же,  при наличии  гидравлического сопротивления  во входной записи значение поля вычисляется следующим образом: 
           Qпо=k* Qзо ; k=Qc1/Qc2 , где 
    Qпо - полученный расход на отопление; 
    Qзо - расчетный (заданный) расход на отопление; 
    Qc1 - суммарный полученный расход потребителя, 
    вычисленный в процессе расчета потокораспределения; 
    Qc2 - cуммарный расчетный (заданный) расход потребителя, 
    вычисленный на основании исходных данных по потребителю.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (599, N'PT_OUT', N'PT', N'a5', N'GсоНез', N'7.Расход на отопл., незав.сх.', N'Расход на отопление, незав.сх.', N'"Полученный    расход   потребителя    на    отопление, независимая схема" -цифровое поле, значение  которого считываются из исходных данных по потребителю  если  для  данного  потребителя  отсутствует  его гидравлическое сопротивление  в  этой  записи   и,  следовательно, при  этом   расчет гидравлического режима ведется  на фиксированную нагрузку  потребителя или же,  при наличии  гидравлического сопротивления  в исходных данных по потребителю,  значение поля вычисляется следующим образом: 
           Qпо=k* Qзо ; k=Qc1/Qc2 ,где 
    Qпо - полученный расход на отопление; 
    Qзо - расчетный (заданный) расход на отопление; 
    Qc1 - суммарный полученный расход потребителя, 
    вычисленный в процессе расчета потокораспределения; 
    Qc2 - cуммарный расчетный (заданный) расход потребителя, 
    вычисленный на основании исходных данных по потребителю.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (600, N'PT_OUT', N'PT', N'a6', N'Gвент', N'8.Расход на вент.', N'Расход на вентиляцию', N'"Полученный  расход  потребителя  на  вентиляцию"  -  цифровое поле, значение которого считываются из исходных данных по потребителю, если для  данного потребителя отсутствует его гидравлическое сопротивление в этой записи и, следовательно  при этом  расчет гидравлического  режима ведется  на фиксированную нагрузку потребителя или же, при наличии гидравлического сопротивления в исходных данных по потребителю,  значение поля  вычисляются следующим образом: 
           Qпв=k* Qзв ;  k=Qc1/Qc2 , где 
    Qпв -  полученный расход  на вентиляцию; 
    Qзв -  расчетный (заданный) расход на вентиляцию; 
    Qc1   -   суммарный   полученный   расход   потребителя, 
    вычисленный в процессе расчета потокораспределения; 
    Qc2 - cуммарный расчетный (заданный) расход потребителя, 
    вычисленный на основании исходных данных по потребителю.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (601, N'PT_OUT', N'PT', N'a7', N'Gконд', N'9.Расход на конд.', N'Расход на кондиционирование', N'"Полученный  расход  потребителя  на  кондиционирование" -   цифровое поле, значение которого  считываются из   исходных данных по потребителю, если  для данного  потребителя  отсутствует  его  гидравлическое сопротивление в этой записи  и, следовательно  при этом  расчет гидравлического режима ведется  на  фиксированную  нагрузку  потребителя  или же, при наличии гидравлического  сопротивления   в исходных данных по потребителю,  значение   поля вычисляется следующим образом: 
           Qпк=k* Qзк ;  k=Qc1/Qc2 , где 
    Qпк -  полученный расход  на вентиляцию; 
    Qзк -  расчетный (заданный) расход на вентиляцию; 
    Qc1   -   суммарный   полученный   расход   потребителя, 
    вычисленный в процессе расчета потокораспределения; 
    Qc2 - cуммарный расчетный (заданный) расход потребителя, 
    вычисленный на основании исходных данных по потребителю.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (602, N'PT_OUT', N'PT', N'a8', N'GтехнЗакр', N'10.Полученный расход на техн., закр.сист.', N'Расход на технологию в закр.сист.', N'"Полученный  расход  потребителя  на  технологические  процессы   в закрытой  системе"  -  цифровое  поле, значение  которого при расчете планового режима (с  фиксированными  нагрузками  потребителей) тепловой сети равен расчетному  (заданному)  расходу,  вычисленному на основании исходных данных по потребителю (удельным расходам, расчетной тепловой нагрузки, эксплуатационному температурному графику). При расчете фактического гидравлического режима (с  фиксированными  гидравлическими   сопротивлениями) тепловой сети  полученный расход может определятся двумя способами. Первый способ, расход  вычисляется в результате расчета пототокораспределения сетевой воды и определяется параметрами тепловой сети и гидравлическим сопротивлением потребителя. Второй способ, если значение поля "Признак расчета аварийного режима потребителя" равен "Нагрузка", то полученный расход фиксируется и определяется его расчетным (заданным) расходом.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (603, N'PT_OUT', N'PT', N'a9', N'GтехнПод', N'11.Расход на техн.из под.теплопр.', N'Расход на техн. из под.теплопр. в откр сист.', N'"Полученный  расход  сетевой  воды  на  технологические  процессы в открытой  системе  из  подающего  теплопровода" - цифровое  поле, значение  которого при расчете планового режима тепловой сети равен расчетному  (заданному)  расходу,  вычисленному на основании исходных данных по потребителю (удельным расходам, расчетной тепловой нагрузки, эксплуатационному температурному графику). При расчете фактического гидравлического режима (с  фиксированными  гидравлическими   сопротивлениями) тепловой сети  полученный расход может определятся двумя способами. Первый способ, расход  вычисляется в результате расчета пототокораспределения сетевой воды и определяется параметрами тепловой сети и гидравлическим сопротивлением потребителя. Второй способ, если значение поля "Признак расчета аварийного режима потребителя" равен "Нагрузка", то полученный расход фиксируется и определяется его расчетным (заданным) расходом.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (604, N'PT_OUT', N'PT', N'dop12', N'Qвент', N'43.Тепл.нагрузка на вент.', N'Тепловая нагрузка потребителя на вентиляцию', N'"Полученная тепловая нагрузка потребителя на вентиляцию" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на систему вентиляции, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях элементов оборудования сети и потребителя  (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети на заданную температуру наружного воздуха и тепловых характеристик оборудования системы вентиляции, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (605, N'PT_OUT', N'PT', N'dop13', N'Qконд', N'44.Полученная тепл.нагрузка на конд.', N'Тепл.нагрузка на кондиционирование', N'"Полученная тепловая нагрузка потребителя на кондиционирование" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на систему кондиционирования, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя  при фиксированных сопротивлениях элементов оборудования сети и потребителя (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети на заданную температуру наружного воздуха и тепловых характеристик оборудования системы кондиционирования, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (606, N'PT_OUT', N'PT', N'dop14', N'Qтехн', N'45.Тепл.нагрузка на техн., закр.сист.', N'Тепл.нагрузка на технологию в закрытой системе', N'"Полученная тепловая нагрузка потребителя на технологию в закрытой системе" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на технологию в закрытой системе, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети при заданных температуре наружного воздуха и нагрузке на технологию, а также тепловых характеристик оборудования системы технологии, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (607, N'PT_OUT', N'PT', N'dop15', N'QтехнПод', N'46.Тепл.нагрузка на техн. из под.трубопр.', N'Тепл.нагрузка на техн. из под.теплопр. в откр.сист.', N'"Полученная тепловая нагрузка потребителя на технологию из подающего теплопровода в открытой системе" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на технологию из подающего теплопровода в открытой системе, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях (фактический режим) и температурой этого потока, полученной в процессе расчета теплового режима сети  при заданных температуре наружного воздуха и нагрузке на технологию.', N'Тепловая мощность', NULL)
