INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (609, N'PT_OUT', N'PT', N'dop17', N'QгвЗакр', N'48.Получ.тепл.нагрузка на ГВ в закр.сист.', N'Тепл.нагрузка на ГВ в закрытой системе', N'"Полученная тепловая нагрузка потребителя на горячее водоснабжение в закрытой системе" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на горячее водоснабжение в закрытой системе, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя  при фиксированных сопротивлениях (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети при заданных температуре наружного воздуха и нагрузке на на горячее водоснабжение, а также тепловых характеристик  оборудования закрытой системы горячего водоснабжения, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (610, N'PT_OUT', N'PT', N'dop18', N'QгвПод', N'49.Получ.тепл.нагрузка на ГВ из под.теплопр.', N'Тепл.нагрузка на ГВ из под.теплопр. в откр.сист.', N'"Полученная тепловая нагрузка потребителя на горячее водоснабжение из подающего теплопровода в открытой системе" - цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на горячее водоснабжение из подающего теплопровода потребителя, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях (фактический режим)  и температурой этого потока, полученной в процессе расчета теплового режима сети при заданных температуре наружного воздуха и нагрузке на на горячее водоснабжение.', N'Тепловая мощность', NULL)
