INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (612, N'PT_OUT', N'PT', N'dop20', N'QгвЦирк', N'51.Тепл.нагрузка в цирк.теплопр.ГВС', N'Тепл.нагрузка в цирк.теплопроводе ГВС', N'"Полученная тепловая нагрузка потребителя в циркуляционном теплопроводе ГВС" - цифровое поле, значение которого для закрытых систем горячего водоснабжения вычисляется в соответствии с величиной расхода  сетевой воды в циркуляционном теплопроводе системы горячего водоснабжения, полученной в процессе расчета потокораспределения сети  и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях (фактический режим), для открытых - величиной расхода циркулируемой горячей воды, а также температурой этого потока, полученной в процессе расчета теплового режима сети при заданных температуре наружного воздуха и нагрузке на на горячее водоснабжение, а также тепловых характеристик оборудования системы горячего водоснабжения, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (613, N'PT_OUT', N'PT', N'dop22', N'QsumПод', N'52.Сумм.тепл.нагрузка из обр.теплопр. в откр.сист.', N'Сумм.тепл.нагрузка  из под.теплопр.в откр.системе', N'"Полученная суммарная тепловая нагрузка потребителя из подающего теплопровода в открытой системе "  - цифровое поле,  значение которого  определяется простым  суммированием значений тепловых нагрузок на все виды теплопотребления в открытой системах потребителя при водоразборе из подающего теплопровода,   полученных  в  процессе  расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и потребителя  (фактический режим), для заданной температуры наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла  и заданном режиме работы системы горячего водоснабжения потребителя: расчетный, средненедельный, балансовый, максимальный режим нагрузки.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (614, N'PT_OUT', N'PT', N'dop23', N'QsumОбр', N'53.Сумм.тепл.нагрузка из обр.теплопр. в откр.сист.', N'Сумм.тепл.нагрузка  из обр.теплопр.в откр.системе', N'"Полученная суммарная тепловая нагрузка потребителя из обратного теплопровода в открытой системе "  - цифровое поле,  значение которого  определяется простым  суммированием значений тепловых нагрузок на все виды теплопотребления в открытой системах потребителя при водоразборе из обратного теплопровода,   полученных  в  процессе  расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и потребителя  (фактический режим), для заданной температуры наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла  и заданном режиме работы системы горячего водоснабжения потребителя: расчетный, средненедельный, балансовый, максимальный режим нагрузки.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (615, N'PT_OUT', N'PT', N'dop8', N'Твент', N'39.Темпер.нагретого возд.в сист.вент.', N'Темп.нагретого воздуха в системе вентиляции', N'"Температура нагретого воздуха в системе вентиляции" - цифровое поле,  значение которого  определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и потребителя  (фактический режим), для заданной температуры наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
