INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (618, N'PT_OUT', N'PT', N'Gm', N'GместСО', N'27.Расход воды на вх.мест.СО, незав.присоед.', N'Расход воды на входе мест. СО, незав.присоед.', N'"Полученный расход воды на входе местной системы, независимое присоединение" - цифровое поле,  значение которого является постоянной величиной, расчет которой производится через расчётные значения параметров независимой системы отопления.  Используется в расчете  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления потребителя  (фактический режим).', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (619, N'PT_OUT', N'PT', N'Gneob', N'НеобхРасполагНапор', N'54.Необх.располаг.напор', N'Необходимый располагаемый напор', N'"Необходимый располагаемый напор" - цифровое поле, значение которого определяет необходимый располагаемый напор в узлах присоединения  потребителя и которое  используется при анализе степени  теплообеспеченности текущего потребителя.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (620, N'PT_OUT', N'PT', N'Gsm', N'GсмСО', N'26.Расход воды в СО после узла смеш.', N'Расход сет.воды в СО после узла смешения', N'"Полученный расход сетевой воды в системе отопления после узла смешения" -цифровое поле,  значение которого  определяется расход воды в системе отопления после узла смешения в зависимости от значения коэффициента смешения установленного элеватора.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (621, N'PT_OUT', N'PT', N'Gx', N'Gхол', N'28.Расход водопр.воды в закр.ГВС', N'Расход водопроводной воды в закрытой ГВС', N'"Полученный расход водопроводной воды в закрытой системе горячего водоснабжения" - цифровое поле,  значение которого определяется в зависимости от заданного режима работы системы горячего водоснабжения потребителя: расчетный, средненедельный, балансовый, максимальный режим нагрузки.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (622, N'PT_OUT', N'PT', N'kod', N'КодРСПотр', N'2.Код расч.сх.узла присоед.потреб.', N'Код расч.схемы узла присоединения потребителя', N'"Код  расчетной схемы  узла присоединения  потребителя" -  символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит потребитель.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (623, N'PT_OUT', N'PT', N'kod_p', N'КодРС', N'64.Код расч.сх.узла присоед.', N'Код расчетной схемы  присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы потребителя.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (624, N'PT_OUT', N'PT', N'nomer', N'№', N'1.№', N'Порядковый номер', N'Порядковый номер экземпляра данного класса. Недопустимая для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (625, N'PT_OUT', N'PT', N'pr', N'ПризУзПотр', N'4.Призн.узла присоед.потреб.', N'Признак теплопровода узла присоед.потребителя', N'"Признак теплопровода узла присоединения потребителя" -  символьное поле, значение  которого    используются  для указания принадлежности узла  только  подающему  -  "Подача",   только  обратному  -   "Обратка"   теплопроводам  на  расчетной схеме. Если в поле "Пробел" (или "Общий"), то это означает, что узел принадлежит  и подающему и обратному трубопроводам.  Значение поля "Признак узла присоединения потребителя" для потребителя по умолчанию принимается равным "Пробел",  что свидетельствует о том, что потребитель расположен между одноимёнными узлами, расположенными на подающем и на обратном теплопропроводах расчётной схемы.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (626, N'PT_OUT', N'PT', N'pr_p', N'ПризУз', N'66.Призн.теплопр.узла просоед.', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подача» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (627, N'PT_OUT', N'PT', N'Q_obesp_gvs_min', N'Теплообеспеченность горячего водоснабжения', N'Теплообеспеченность нагрузки горячего водоснабжения', N'Теплообеспеченность нагрузки горячего водоснабжения', N'"Теплообеспеченность нагрузки горячего водоснабжения потребителя" - цифровое поле, значение которого представляет собой процентное отношение полученного тепла в системе горячего водоснабжения потребителя к требуемому теплу, необходимого  на покрытие заданной тепловой нагрузки в этой системе.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (628, N'PT_OUT', N'PT', N'Q_obesp_min', N'Суммарная теплообеспеченность', N'Суммарная теплообеспеченность', N'Суммарная теплообеспеченность', N'"Суммарная теплообеспеченность потребителя" - цифровое поле, значение которого представляет собой процентное отношение полученного тепла во всех системах теплопотребления (отопления, вентиляции, горячего водоснабжения) потребителя к требуемому теплу, необходимого  на покрытие тепловой нагрузки во всех его системах теплопотребления  при текущей температуре наружного воздуха и заданной нагрузке горячего водоснабжения.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (629, N'PT_OUT', N'PT', N'Q_obesp_otopl_min', N'Теплообеспеченность отопления', N'Теплообеспеченность  отопительной нагрузки', N'Теплообеспеченность отопительной нагрузки', N'"Теплообеспеченность отопительной нагрузки  потребителя" - цифровое поле, значение которого представляет собой процентное отношение полученного тепла в системах отопления, вентиляции и кондиционирования потребителя к требуемому теплу, необходимого  на покрытие тепловой нагрузки в этих системах теплопотребления  при текущей температуре наружного воздуха.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (630, N'PT_OUT', N'PT', N'Qfact', N'Qсумм_факт', N'60.Суммарная тепловая нагрузка', N'Суммарная тепловая нагрузка систем теплопотребления', N'"Суммарная тепловая нагрузка систем теплопотребления"  - цифровое поле, значение которого определяет, полученное в процессе расчета фактического теплогидравлического режима сети,  суммарное количество тепла потребляемое системами теплопотребления, при заданных текущих условиях ее режима работы. Значение этой величины используется при анализе степени теплообеспеченности текущего теплового пункта, путем сравнения её со значением поля ''''Требуемая тепловая нагрузка систем теплопотребления"', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (631, N'PT_OUT', N'PT', N'Qgvoo_treb', N'ТребНагрузОткрГВОбратка', N'61.Требуемый расход тепла  на горячее водоснабжение в открытой системе, обратка', N'Требуемый расход тепла  на горячее водоснабжение  в открытой системе из обр.трубопр.', N'"Требуемый расход тепла  на горячее водоснабжения в открытой системе, обратный трубопровод"- цифровое поле,  значение которого определяет количество теплоты, необходимое для обеспечения расчетных  значений горячей воды из обратного трубопровода в открытой системе горячего водоснабжения при текущем режиме работы системы теплоснабжения. Значение этой величины используется при анализе степени теплообеспеченности текущего теплового пункта.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (632, N'PT_OUT', N'PT', N'Qgvop_treb', N'ТребНагрузОткрГВПодача', N'60.Требуемый расход тепла  на горячее водоснабжение в открытой системе, подача', N'Требуемый расход тепла  на горячее водоснабжение  в открытой системе из под.трубопр.', N'"Требуемый расход тепла  на горячее водоснабжения в открытой системе, подающий трубопровод"- цифровое поле,  значение которого определяет количество теплоты, необходимое для обеспечения расчетных  значений горячей воды из подающего трубопровода в открытой системе горячего водоснабжения при текущем режиме работы системы теплоснабжения. Значение этой величины используется при анализе степени теплообеспеченности текущего теплового пункта.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (633, N'PT_OUT', N'PT', N'Qgvz_treb', N'РасчНагрузЗакрГВ', N'59.Требуемый расход тепла  на горячее водоснабжение в закрытой системе', N'Требуемый расход тепла  на горячее водоснабжение  в закрытой системе', N'''Требуемый расход тепла  на горячего водоснабжения в  закрытой системе" - цифровое поле, значение которого определяет количества тепла, необходимое для обеспечения расчетных  значений температур   горячей воды на выходе водоподогревательных установок при текущем режиме работы системы теплоснабжения.  Значение этой величины используется при анализе степени теплообеспеченности текущего теплового пункта.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (634, N'PT_OUT', N'PT', N'Qotn', N'Qсо_незав', N'42.Тепл.нагрузка на отопл., незав.сх.', N'Тепл.нагрузка  на отопление, незав.сх.', N'"Полученная тепловая нагрузка потребителя на отопление, независимая схема" -   цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на независимую систему отопления, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях элементов оборудования (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла, а также  тепловых характеристик оборудования  независимой системы отопления, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (635, N'PT_OUT', N'PT', N'Qotn_treb', N'ТребНагрузкаНСО', N'57.Требуемый расход тепла на отопление,незав.схема', N'Требуемый расход тепла на отопление при текущей температуре наружного воздуха,незав.схема', N'''''Требуемый расход тепла на отопление, незав.схема" - цифровое поле, значение которого определяет количества тепла, необходимое для обеспечения расчетных  значений температур воздуха внутри отапливаемых помещений при текущей температуре наружного воздуха, при независимой схеме включения систем отопления. Значение этой величины используется при анализе степени теплообеспеченности текущего теплового пункта', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (636, N'PT_OUT', N'PT', N'Qotz', N'Qсо_зав', N'41.Тепл.нагрузка на отопл., зав.сх.', N'Тепл.нагрузка  на отопление, зав.сх.', N'"Полученная тепловая нагрузка потребителя на отопление, зависимая схема" -   цифровое поле, значение которого вычисляется в соответствии с величиной расхода сетевой воды на  зависимую систему отопления, полученной в процессе расчета потокораспределения сети и схем включения систем теплопотребления потребителя при фиксированных сопротивлениях элементов оборудования (фактический режим), температурой этого потока, полученной в процессе расчета теплового режима сети на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла, а также  тепловых характеристик оборудования зависимой системы отопления, определённых в исходных данных потребителя.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (637, N'PT_OUT', N'PT', N'Qotz_treb', N'ТребНагрузкаЗСО', N'56.Требуемый расход тепла на отопление,зав.схема', N'Требуемый расход тепла на отопление при текущей температуре наружного воздуха,зав.схема', N'''''Требуемый расход тепла на отопление, зав.схема" - цифровое поле, значение которого определяет количества тепла, необходимое для обеспечения расчетных  значений температур воздуха внутри отапливаемых помещений при текущей температуре наружного воздуха, при зависимой схеме включения систем отопления. Значение этой величины используется при анализе степени теплообеспеченности текущего теплового пункта', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (638, N'PT_OUT', N'PT', N'Qras_gv_z', N'РасчНагрузкаЗакрытГВС', N'55.Расчетная нагрузка в закрытых ГВС', N'Расчетная тепловая нагрузка в закрытых ГВС', N'''''Расчетная тепловая нагрузка в закрытой системе горячего водоснабжения " - цифровое поле, значение которого определяет расчетную тепловую нагрузку в  закрытой системе горячего воводоснабжения теплового пункта. Для параллельной и смешанной схем включения водоподогревателей системы горячего водоснабжения расчетная нагрузка на ГВС равна: Qрасч = Qср*k,  где Qср, k - исходные значения, соответственно, Qср - среднечасовая нагрузка на ГВС, k - коэффициент часовой неравномерности (В.И. Манюк и др. "Наладка и эксплуатация водяных тепловых сетей"). Для последовательного и предвключенного схем включения водоподогревателей ГВС Qрасч = Qср*f,  где f - коэффициент расчета балансовой нагрузки горячего водоснабжения (см. Сервис>Справочная информация >28_Коэффициенты расчета балансовой нагрузки ГВ). Для открытой ГВС расчетная нагрузка на ГВ равна Qср (В.И. Манюк).', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (639, N'PT_OUT', N'PT', N'Qrez_treb', N'ТребНагрузРецОткрГВ', N'62.Требуемый расход тепла  на рециркуляцию в  в открытой системе ГВ', N'Требуемый расход тепла на рециркуляцию в  в открытой системе ГВ', N'"Требуемый расход тепла на рециркуляцию в открытой системе ГВ" -  цифровое поле, значение которого определяется тепловыми  потерями (Qтп) в трубопроводах  циркуляционной  ГВС  при текущей нагрузке ГВС. Согласно В.И. Манюк "Наладка и эксплуатация водянных тепловых сетей" при Qгвс_максимальное, рециркуляция отсутствует (Qтп=0), при  Qгвс_средняя, Qтп=0.85*Qрец_расчетная, при  Qгвс_нулевая, Qтп=Qрец_расчетная.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (640, N'PT_OUT', N'PT', N'Qsum_z', N'Qsum_Закр', N'52.Сумм.тепл.нагрузка в закр.сист.', N'Суммарная тепл.нагрузка  в закрытой системе', N'"Полученная суммарная тепловая нагрузка потребителя в закрытой системе "  - цифровое поле,  значение которого  определяется простым  суммированием значений тепловых нагрузок на все виды теплопотребления в закрытой системе потребителя,   полученных  в  процессе  расчета  теплогидравлического режима сети при   заданных гидравлических  сопротивлениях элементов оборудования сети и потребителя  (фактический режим), на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла  и заданном режиме работы системы горячего водоснабжения потребителя: расчетный, средненедельный, балансовый, максимальный режим нагрузки.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (641, N'PT_OUT', N'PT', N'Qtreb', N'Qтреб', N'63.Суммарный требуемый расход тепла в системах теплопотребления', N'Суммарный требуемый расход тепла в системах теплопотребления теплового пункта', N'''''Суммарный требуемый расход тепла в системах теплопотребления" - цифровое поле, значение которого определяет суммарное количества тепла в системах теплопотребления теплового пункта, необходимое для обеспечения расчетных  значений температур воздуха внутри отапливаемых помещений и  горячей воды в системе горячего водоснабжения для заданных текущих значений температуры наружного воздуха.  Значение этой величины используется при анализе степени теплообеспеченности теплового пункта, путем сравнения её со значением поля ''''Суммарная тепловая нагрузка систем теплопотребления"', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (642, N'PT_OUT', N'PT', N'Qvent_treb', N'СуммРасчНагрузкаВент', N'58.Требуемый расход тепла на вентиляцию', N'Требуемый расход тепла на вентиляцию при текущей температуре наружного воздуха', N'''''Требуемый расход тепла на вентиляцию" - цифровое поле, значение которого определяет количества тепла, необходимое для обеспечения расчетных  значений температур воздуха в системе вентиляции или воздушного отопления при текущей температуре наружного воздуха. Значение этой величины используется при анализе степени теплообеспеченности текущего теплового пункта', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (643, N'PT_OUT', N'PT', N't01', N'Т1со', N'32.Темпер.в под.теплопр.СО', N'Температура в подающем теплопроводе СО', N'"Полученная температура воды в подающем теплопроводе системы отопления" - цифровое поле,  значение которой определяет температуру сетевой воды на входе зависимой системы отопления потребителя или температуру воды на входе  местной системы отопления при независимой системе отопления потребителя. Данная величина определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления потребителя  (фактический режим),  на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (644, N'PT_OUT', N'PT', N't02', N'Т2со', N'33.Темпер.в обр.теплопр.СО', N'Температура в обратном теплопроводе СО', N' "Полученная температура воды в обратном теплопроводе системы отопления" - цифровое поле,  значение которой определяет температуру сетевой воды на выходе зависимой системы отопления или температуру воды на выходе  местной системы отопления при независимой системе отопления потребителя. Данная величина определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления потребителя  (фактический режим),  на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (645, N'PT_OUT', N'PT', N't03', N'Т3со', N'34.Темпер.после узла смеш.в СО', N'Температура после узла смешения в СО', N'"Полученная температура воды после узла смешения системы отопления" - цифровое поле,  значение которой определяет температуру сетевой воды после элеваторного узла смешения зависимой системы отопления потребителя или температуру воды  после элеваторного узла смешения местной системы отопления при независимом присоединении системы отопления потребителя. Данная величина определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления потребителя  (фактический режим),  на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (646, N'PT_OUT', N'PT', N't1', N'ТвхТП', N'30.Темпер.сет.воды на вх.ТП', N'Температура сет.воды на входе теплового пункта', N'"Полученная температура сетевой воды на входе теплового пункта" - цифровое поле,  значение которой определяется в процессе расчета  теплогидравлического режима   сети и систем теплопотребления потребителя при фиксированных гидравлических  сопротивлениях элементов оборудования (фактический режим),  на заданную нагрузку горячего водоснабжения и температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (647, N'PT_OUT', N'PT', N't2', N'ТвыхТП', N'31.Темпер.сет.воды на вых.ТП', N'Температура сет.воды на выходе теплового пункта', N'"Полученная температура сетевой воды на выходе теплового пункта" - цифровое поле,  значение которой определяется в процессе расчета  теплогидравлического режима   сети и систем теплопотребления потребителя при фиксированных гидравлических  сопротивлениях элементов оборудования (фактический режим),  на заданную нагрузку горячего водоснабжения и температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (648, N'PT_OUT', N'PT', N't2co', N'Т2незСО', N'35.Темпер.сет.воды на вых.подогр.СО', N'Температура сет.воды на выходе подогревателя СО', N'"Полученная температура сетевой воды на выходе подогревателя независимой системы отопления" - цифровое поле,  значение которой определяет температуру сетевой воды на выходе подогревателя независимой системы отопления  потребителя. Данная величина определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления потребителя  (фактический режим),  на заданную температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (649, N'PT_OUT', N'PT', N't2gws', N'Т2_2стГВ', N'36.Темпер.сет.воды на вых.подогр. 2 ст.ГВС', N'Температура сет.воды на вых.подогревателя 2 ст.ГВС', N'"Полученная температура сетевой воды на выходе подогревателя второй ступени системы горячего водоснабжения" -  цифровое поле,  значение которой определяет температуру сетевой воды на выходе подогревателя  второй (верхней) ступени подогревателя системы горячего водоснабжения потребителя. Данная величина определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления потребителя  (фактический режим),  на заданные нагрузку горячего водоснабжения (расчетную, средненедельную, балансовую, максимальную) и температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (650, N'PT_OUT', N'PT', N'tg', N'Тгор', N'38.Горяч.вода на вых.водоразб.приб.в ГВС', N'Горячая вода на выходе водоразб.приборов в ГВС', N'"Полученная горячая вода на выходе водоразборных приборов в системе горячего водоснабжения" -  цифровое поле,  значение которой определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления потребителя  (фактический режим),  на заданные нагрузку горячего водоснабжения (расчетную, средненедельную, балансовую, максимальную) и температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (651, N'PT_OUT', N'PT', N'tv', N'Твн', N'37.Темпер.внутри отапл.помещ.', N'Температура внутри отапливаемых помещений', N'"Полученная температура внутри отапливаемых помещений" - цифровое поле,  значение которой определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления потребителя  (фактический режим),  на заданные нагрузку горячего водоснабжения (расчетную, средненедельную, балансовую, максимальную) и температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (652, N'PT_OUT', N'PT', N'uzel', N'НаимУзПотр', N'3.Наим.узла присоед.потреб.', N'Наименование узла присоединения потребителя', N'"Наименование  узла присоединения  потребителя" -  символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет потребителя на данной расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (653, N'PT_OUT', N'PT', N'uzel_p', N'НаимУз', N'65.Наим.узла присоед.', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы потребителя.', NULL, NULL)
