INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (686, N'RASPAR_OUT', N'RP', N'pr_p', N'ПризнТеплопровУзлаПрисоед', N'Признак теплопровода  узла присоединения', N'Признак теплопровода  внешнего узла присоединения', N'«Признак теплопровода внешнего узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с внешним узлом присоединения. Значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами.', NULL, NULL)
