INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (739, N'RPP_OUT', N'RS', N'a11', N'Расход', N'Расход сет.воды', N'Расход воды через клапан регулятора', N'"Полученный расход воды через клапан регулятора" - цифровое поле, значение которого  представляет   собой  расход   сетевой  воды   через  клапан регулятора  определённый в процессе расчёта данного гидравлического  режима сети.', N'Расход', NULL)
