INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (744, N'RPP_OUT', N'RS', N'a16', N'ЗадРегНап', N'Зад.значение рег.напора', N'Заданное значение регулируемого напора, м.вод.ст. или расход', N'"Значение  регулируемого напора  заданное" - цифровое  поле, значение которого  представляет   собой  заданный   пьезометрический  напор   в соответствующем узле сети ( для регуляторов давления).  Значение поля переписывается из исходных данных по регулятору.', NULL, NULL)
