INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (746, N'RPP_OUT', N'RS', N'a18', N'ДопОтклон', N'Допуст.отклон.', N'Допустимое отклонение', N'"Допустимое отклонение полученного значения регулируемого напора от заданного"  -  цифровое  поле,  значение  которого  переписывается из исходных данных по регулятору.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (747, N'RPP_OUT', N'RS', N'a19', N'ПоложКлап', N'Положение клапана', N'Положение клапана регулятора', N'"Положение клапана регулятора" - символьное поле, значение  которого определяется    в   данном    гидравлическим    режиме   рассчитанным сопротивлением регулирующего клапана  регулятора. Для регуляторов  это слова  "закр."  -  "откр.   -  или  "раб.",  соответсвенно фиксирующие состояние  регулятора  при  полностью  закрытой,  полностью   открытой площади прохода седла клапана или фиксирующие промежуточное  положение клапана регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (748, N'RPP_OUT', N'RS', N'a4', N'ГеодОтмМестВх', N'Геод.отметка верха трубы узла на входе рег.', N'Геод.отметка верха трубы узла на входе регулятора', N'"Геодезическая  отметка верха трубы узла на входе регулятора"  -  цифровое  поле,  значение которого   определяется    значением   геодезической отметки верха трубы в месте  расположения узла на  входе регулятора  и используется при расчете гидравлического режима сети.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (749, N'RPP_OUT', N'RS', N'a8', N'ГеодОтмВых', N'Геод.отметка верха трубы узла на выходе рег.', N'Геод.отметка верха трубы узла на выходе регулятора', N'"Геодезическая  отметка верха трубы узла на выходе регулятора"  -  цифровое  поле,  значение которого   определяется    значением   геодезической отметки верха трубы в месте  расположения узла на  выходе регулятора  и используется при расчете гидравлического режима сети.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (750, N'RPP_OUT', N'RS', N'dx', N'Разница заданной/полученой  регулир.величины', N'Разница заданной/полученой  регулируемой величины', N'Разница между заданным и полученым значениями регулируемой величина', N'"Разница заданной/полученой  регулируемой величины" - цифровое поле,  значение которого   определяется    значением  разницы между заданным и полученым значениями регулируемого расхода  (напора в регулируемом узле), полученных в процессе расчета  регулирующих устройств (регулятора расхода, регулятора давления).  Размерность поля лпределяется типом регулирующего устройства - или т/ч или м.вод.ст.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (751, N'RPP_OUT', N'RS', N'kod_p', N'КодРСУзПрис', N'Код расч.сх.узла присоед.', N'Код расчетной схемы узла присоединения', N'"Код расчетной схемы узла присоединения" -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда регулятор  входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (752, N'RPP_OUT', N'RS', N'kod1', N'КодРСВхУз', N'Код расч.сх.узла на вх.', N'Код расчетной схемы узла на входе регулятора', N'"Код  расчетной схемы  узла на  входе регулятора"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на входе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (753, N'RPP_OUT', N'RS', N'kod2', N'КодРСВыхУз', N'Код расч.сх.узла на вых.', N'Код расчетной схемы узла на выходе регулятора', N'"Код  расчетной схемы  узла на  выходе регулятора"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на выходе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (754, N'RPP_OUT', N'RS', N'kod3', N'КодРСсРегНап', N'Код расч.сх.узла с рег.напором  (импул.трубки)', N'Код расч.сх.узла с рег.напором  (импул.трубки)', N'"Код расчетной схемы узла с регулируемым напором" - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел  c регулируемым  напором (установки импульсной трубки).  Значение поля переписывается из исходных данных по регулятору.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (755, N'RPP_OUT', N'RS', N'nomer', N'№', N'Порядковый номер', N'Порядковый номер экземпляра', N'Порядковый номер экземпляра данного объекта. Недопустимая  для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (756, N'RPP_OUT', N'RS', N'pr_p', N'ПризУзПрис', N'Признак теплопр.узла присоед.', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подача» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда регулятор  входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (757, N'RPP_OUT', N'RS', N'pr1', N'ПризВхУз', N'Признак теплопр. узла на вх.', N'Признак теплопровода узла на входе регулятора', N'"Признак  теплопровода узла  на входе  регулятора" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  начального  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  теплопроводам  на  расчетной схеме.  Если в поле "Общий", то это означает, что узел принадлежит  и подающему и обратному теплопроводам.  Наличие признака "Общий" или  пробела в полях "Признак трубопровода" для начального и конечного узлов свидетельствует о том , что участок "общий", т.е. его характеристики одинаковы для подающего и обратного теплопроводов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (758, N'RPP_OUT', N'RS', N'pr2', N'ПризВыхУз', N'Признак теплопр. узла на вых.', N'Признак теплопровода узла на выходе регулятора', N'"Признак  теплопровода узла  на выходе  регулятора" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  начального  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  теплопроводам  на  расчетной схеме.  Если в поле "Общий" или пробел, то это означает, что узел принадлежит  и подающему и обратному теплопроводам.  Наличие признака "Общий" или  пробела в полях "Признак трубопровода" для начального и конечного узлов свидетельствует о том , что участок "общий", т.е. его характеристики одинаковы для подающего и обратного теплопроводов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (759, N'RPP_OUT', N'RS', N'pr3', N'НаимСРегНап', N'Признак теплопр. регулируемого узла (импул.трубки)', N'Признак теплопр. регулируемого узла (импул.трубки)', N'Признак теплопр. регулируемого узла (импул.трубки)', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (760, N'RPP_OUT', N'RS', N'sos', N'Состояние', N'Состояние', N'Состояние', N'"Состояние регулятора" - символьное поле, значение которого однозначно определяет состояние, в котором находится клапан регулятора. Если в поле присутствует в качестве его значения "Неактивен", то это говорит о том, что клапан открыт, его сопротивление минимально, а регулирующее воздействие отключено. Если в поле отсутствуют какие-либо значения - "Открыт", то клапан в рабочем состоянии (регулятор активен), его сопротивление меняется в зависимости от изменения регулирующего воздействия. Если в поле присутствует символ - "Закрыт", то клапан закрыт,  регулирующее воздействие на него не формируется.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (761, N'RPP_OUT', N'RS', N'uzel_p', N'НаимУзПрис', N'Наим.узла присоед.', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда регулятор  входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (762, N'RPP_OUT', N'RS', N'uzel1', N'НаимВхУз', N'Наим.узла на входе', N'Наименование узла на входе регулятора', N'"Наименование узла  на входе регулятора"  - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно определяет узел на  расчетной  схеме.   Это  наименование используется для указания заданного   направления  потока  сетевой воды через регулятор.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (763, N'RPP_OUT', N'RS', N'uzel2', N'НаимВыхУз', N'Наим.узла на выходе', N'Наименование узла на выходе регулятора', N'"Наименование узла  на выходе регулятора"  - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно определяет узел на  расчетной  схеме.   Это  наименование используется для указания заданного   направления  потока  сетевой воды через регулятор.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (764, N'RPP_OUT', N'RS', N'uzel3', N'НаимСРегНап', N'Наим.узла с регул.напором (импул.трубки)', N'Наим.узла с регул.напором (импул.трубки)', N'"Наименование  узла  с  регулируемым  напором"  -  символьное поле, значение  которого  совместно  с  кодом  расчетной  схемы,  однозначно определяет узел с  регулируемым  напором на расчетной схеме (установки импульсной трубки).  Значение поля переписывается из исходных данных по регулятору.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (765, N'RS_OUT', N'RS', N'a11', N'Расход', N'Расход сет.воды', N'Расход воды через клапан регулятора', N'"Полученный расход воды через клапан регулятора" - цифровое поле, значение которого  представляет   собой  расход   сетевой  воды   через  клапан регулятора  определённый в процессе расчёта данного гидравлического  режима сети.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (766, N'RS_OUT', N'RS', N'a12', N'ГидрСопр', N'Гидравл.сопрот.клапана', N'Гидравлическое сопротивление клапана регулятора', N'"Гидравлическое  сопротивление" -  цифровое поле,  значение которого определяется  путем  деления  потерь  напора  на клапане регулятора на квадрат  расхода  через  клапан.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (767, N'RS_OUT', N'RS', N'a13', N'ПьезНапВхУз', N'Пьез.напор в узле на вх.', N'Пьезометрический напор в узле на входе регулятора', N'"Пьезометрический  напор  на  входе  регулятора"  -  цифровое поле, значение которого  - это  вычисленный пьезометрический  напор в  узле, являющимся  входом  регулятора.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (768, N'RS_OUT', N'RS', N'a14', N'ПьезНапВыхУз', N'Пьез.напор в узле на вых.', N'Пьезометрический напор в узле на выходе регулятора', N'"Пьезометрический напор в узле на выходе регулятора" - цифровое поле, значение которого  - это  вычисленный пьезометрический  напор в  узле, являющимся  выходом  регулятора.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (769, N'RS_OUT', N'RS', N'a15', N'Признак', N'Признак', N'Признак регулятора', N'"Вид  регулятора"  -  символьное поле,  значения  которого   для регуляторов давления "давл",  для регуляторов расхода "расх"  указывает на назначение регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (770, N'RS_OUT', N'RS', N'a16', N'ЗадРегНап', N'Зад.значение рег.напора', N'Заданное значение регулируемого напора, м.вод.ст. или расход', N'"Значение  регулируемого напора  заданное" - цифровое  поле, значение которого  представляет   собой  заданный   пьезометрический  напор   в соответствующем узле сети ( для регуляторов давления).  Значение поля переписывается из исходных данных по регулятору.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (771, N'RS_OUT', N'RS', N'a17', N'ПолРегНап', N'Получ.значение рег.напора', N'Полученное значение регулируемого напора, м.вод.ст. или расход', N'"Значение регулируемого напора полученное" - цифровое поле, значение которого представляет собой  пьезометрический напор в  соответствующем узле сети (для регуляторов давления), полученное в результате  расчета данного гидравлического  режима  сети.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (772, N'RS_OUT', N'RS', N'a18', N'ДопОтклон', N'Допуст.отклон.', N'Допустимое отклонение', N'"Допустимое отклонение полученного значения регулируемого напора от заданного"  -  цифровое  поле,  значение  которого  переписывается из исходных данных по регулятору.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (773, N'RS_OUT', N'RS', N'a19', N'ПоложКлап', N'Положение клапана', N'Положение клапана регулятора', N'"Положение клапана регулятора" - символьное поле, значение  которого определяется    в   данном    гидравлическим    режиме   рассчитанным сопротивлением регулирующего клапана  регулятора. Для регуляторов  это слова  "закр."  -  "откр.   -  или  "раб.",  соответсвенно фиксирующие состояние  регулятора  при  полностью  закрытой,  полностью   открытой площади прохода седла клапана или фиксирующие промежуточное  положение клапана регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (774, N'RS_OUT', N'RS', N'a4', N'ГеодОтмМестВх', N'Геод.отметка верха трубы узла на входе рег.', N'Геод.отметка верха трубы узла на входе регулятора', N'"Геодезическая  отметка верха трубы узла на входе регулятора"  -  цифровое  поле,  значение которого   определяется    значением   геодезической отметки верха трубы в месте  расположения узла на  входе регулятора  и используется при расчете гидравлического режима сети.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (775, N'RS_OUT', N'RS', N'a8', N'ГеодОтмВых', N'Геод.отметка верха трубы узла на выходе рег.', N'Геод.отметка верха трубы узла на выходе регулятора', N'"Геодезическая  отметка верха трубы узла на выходе регулятора"  -  цифровое  поле,  значение которого   определяется    значением   геодезической отметки верха трубы в месте  расположения узла на  выходе регулятора  и используется при расчете гидравлического режима сети.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (776, N'RS_OUT', N'RS', N'dx', N'Разница заданной/полученой  регулир.величины', N'Разница заданной/полученой  регулируемой величины', N'Разница между заданным и полученым значениями регулируемой величина', N'"Разница заданной/полученой  регулируемой величины" - цифровое поле,  значение которого   определяется    значением  разницы между заданным и полученым значениями регулируемого расхода  (напора в регулируемом узле), полученных в процессе расчета  регулирующих устройств (регулятора расхода, регулятора давления).  Размерность поля лпределяется типом регулирующего устройства - или т/ч или м.вод.ст.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (777, N'RS_OUT', N'RS', N'kod_p', N'КодРСУзПрис', N'Код расч.сх.узла присоед.', N'Код расчетной схемы узла присоединения', N'"Код расчетной схемы узла присоединения" -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда регулятор  входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (778, N'RS_OUT', N'RS', N'kod1', N'КодРСВхУз', N'Код расч.сх.узла на вх.', N'Код расчетной схемы узла на входе регулятора', N'"Код  расчетной схемы  узла на  входе регулятора"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на входе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (779, N'RS_OUT', N'RS', N'kod2', N'КодРСВыхУз', N'Код расч.сх.узла на вых.', N'Код расчетной схемы узла на выходе регулятора', N'"Код  расчетной схемы  узла на  выходе регулятора"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на выходе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (780, N'RS_OUT', N'RS', N'kod3', N'КодРСсРегНап', N'Код расч.сх.узла с рег.напором  (импул.трубки)', N'Код расч.сх.узла с рег.напором  (импул.трубки)', N'"Код расчетной схемы узла с регулируемым напором" - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел  c регулируемым  напором (установки импульсной трубки).  Значение поля переписывается из исходных данных по регулятору.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (781, N'RS_OUT', N'RS', N'nomer', N'№', N'Порядковый номер', N'Порядковый номер экземпляра', N'Порядковый номер экземпляра данного объекта. Недопустимая  для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (782, N'RS_OUT', N'RS', N'pr_p', N'ПризУзПрис', N'Признак теплопр.узла присоед.', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подача» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда регулятор  входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (783, N'RS_OUT', N'RS', N'pr1', N'ПризВхУз', N'Признак теплопр. узла на вх.', N'Признак теплопровода узла на входе регулятора', N'"Признак  теплопровода узла  на входе  регулятора" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  начального  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  теплопроводам  на  расчетной схеме.  Если в поле "Общий", то это означает, что узел принадлежит  и подающему и обратному теплопроводам.  Наличие признака "Общий" или  пробела в полях "Признак трубопровода" для начального и конечного узлов свидетельствует о том , что участок "общий", т.е. его характеристики одинаковы для подающего и обратного теплопроводов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (784, N'RS_OUT', N'RS', N'pr2', N'ПризВыхУз', N'Признак теплопр. узла на вых.', N'Признак теплопровода узла на выходе регулятора', N'"Признак  теплопровода узла  на выходе  регулятора" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  начального  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  теплопроводам  на  расчетной схеме.  Если в поле "Общий" или пробел, то это означает, что узел принадлежит  и подающему и обратному теплопроводам.  Наличие признака "Общий" или  пробела в полях "Признак трубопровода" для начального и конечного узлов свидетельствует о том , что участок "общий", т.е. его характеристики одинаковы для подающего и обратного теплопроводов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (785, N'RS_OUT', N'RS', N'pr3', N'НаимСРегНап', N'Признак теплопр. регулируемого узла (импул.трубки)', N'Признак теплопр. регулируемого узла (импул.трубки)', N'Признак теплопр. регулируемого узла (импул.трубки)', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (786, N'RS_OUT', N'RS', N'sos', N'Состояние', N'Состояние', N'Состояние', N'"Состояние регулятора" - символьное поле, значение которого однозначно определяет состояние, в котором находится клапан регулятора. Если в поле присутствует в качестве его значения "Неактивен", то это говорит о том, что клапан открыт, его сопротивление минимально, а регулирующее воздействие отключено. Если в поле отсутствуют какие-либо значения - "Открыт", то клапан в рабочем состоянии (регулятор активен), его сопротивление меняется в зависимости от изменения регулирующего воздействия. Если в поле присутствует символ - "Закрыт", то клапан закрыт,  регулирующее воздействие на него не формируется.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (787, N'RS_OUT', N'RS', N'uzel_p', N'НаимУзПрис', N'Наим.узла присоед.', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы фрагмента сети, куда регулятор  входит как один из составляющих её элементов и если  такая расчётная схема создана командой "Создать схему".', NULL, NULL)

