INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (869, N'TG_Развернутый температурный график', N'TG', N'Q_otn', N'ОтнонРасходНаОтопление', N'Относительный расход на отопление', N'Относительный расход на отопление', N'"Относительный расход на отопление"- числовое поле,  значение которого определяет отношение нагрузки на отопление при текущей температуре наружного воздуха к расчетной тепловой нагрузки при при текущих значениях температуры сетевой воды в подающей линии сети и температуре наружного воздуха.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (870, N'TG_Развернутый температурный график', N'TG', N't_bn', N'Температура внутри отапливаемых помещений', N'Температура внутри отапливаемых помещений', N'Температура внутри отапливаемых помещений', N'"Температура внутри отапливаемых помещений" - числовое поле,  значение которого определяет температуру внутри отапливаемых помещений при текущих значениях температуры сетевой воды в подающей линии сети и температуре наружного воздуха.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (871, N'TK_График температур качественного регулирования', N'TK', N'year', N'Год отопительного сезона', NULL, N'Год отопительного сезона', N'"Год отопительного сезона" - текстовое поле, значение которого для отопительного сезона  соответствуют  году первой  половины  отопительного сезона (осень, зима) и году второй  половины отопительного сезона (зима, весна). Например: 2010 - 2011. Для летнего периода:  2011. Значения поля совместно со значение поля "Код источника тепла" используется для автоматического формирования значение поля "Код развернутого температурного графика" текущей таблицы. Значение поля используется для формирования заголовочной части документа температурного графика.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (872, N'TK_График температур качественного регулирования', N'TK', N'kod_ist', N'Код источника тепла', NULL, N'Код источника тепла', N'"Код источника тепла"- текстовое поле, значение которого определяет принадлежность температурного графика соответствующему источнику тепла тепловой сети. Значение поля также используется для формирования заголовочной части документа температурного графика.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (873, N'TK_График температур качественного регулирования', N'TK', N'name', N'Наименование графика', NULL, N'Наименование графика', N'"Наименование температурного графика" - текстовое поле, значение которого однозначно идентифицирует данный температурный график. Значение поля используется для формирования заголовочной части документа температурного график.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (874, N'TK_График температур качественного регулирования', N'TK', N'tip', N'ТгТип', NULL, N'Тип графика', N'"Отопительный" - отопительный  температурный  график применяется  в тепловых  сетях   при    центральном   качественном    регулировании    с  преобладающей тепловой нагрузкой на отопление.   Рассчитывается  из условия постоянного расхода воды в тепловой сети, при котором обеспечивается  комфортная  температура  воздуха в отапливаемых помещениях на расчетном диапазоне температур наружного воздуха.                                             "Повышенный" - повышенный температурный график применяется  при центральном качественном  регулировании  в закрытых системах  теплоснабжения,  когда   не   менее  75%  потребителей   имеют  системы   горячего  водоснабжения с двухступенчатой последовательной схемой включения подогревателей, а  соотношение   нагрузок  горячего водоснабжения и отопления  примерно одинаковые (типовые абоненты). Рассчитывается из  условия  постоянства  суммы  расчетных расходов сетевой  воды  на отопление и горячее водоснабжение типовых абонентов.                                                               "Cкорректированный    повышенный" - скорректированный    повышенный    температурный  график  применяется в открытых  системах  теплоснабжения,  сети которых проектировались без учета  нагрузки   горячего   водоснабжения.  При этом имеет место неравенство 0.1 < Р < 0.2-0.3 ,  где   Р -  отношение средней тепловой  нагрузки  на  ГВС к расчетной
 тепловой   нагрузке   системы   теплоснабжения.    При  Р < 0.1  скорректированный     повышенный    температурный  график будет  эквивалентен отопительному графику." "Cкорректированный    пониженный" - скорректированный   пониженный   температурный    график  применяется   в   открытых  системах теплоснабжения, сети которых проектировались с учетом  тепловой  нагрузки ГВС. При этом имеет  место неравенство  Р > 0.3.', NULL, NULL)
