INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (889, N'TK_График температур качественного регулирования', N'TK', N't_gv1', N'ПвНедогр1ступениГВ', NULL, N'Величина недогрева в первой ступени подогревателя', NULL, NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (890, N'TK_График температур качественного регулирования', N'TK', N'kod_tg', N'КодПолногоГраф', NULL, N'Код развернутого температурного графика', NULL, NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (891, N'TN_График нормативных температур', N'TN', N'year', N'ГодСезона', N'Календарный год', N'Календарный год', N'"Календарный год" - текстовое поле, значение которого для отопительного сезона  соответствуют  году первой  половины  отопительного сезона (осень, зима) и году второй  половины отопительного сезона (зима, весна). Например: 2010 - 2011. Для летнего периода:  2011. Значения поля совместно со значение поля "Код источника тепла" используется для автоматического формирования значение поля "Код развернутого температурного графика" текущей таблицы. Значение поля используется для формирования заголовочной части документа температурного графика.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (892, N'TN_График нормативных температур', N'TN', N'kod_ist', N'КодИст', N'Код источника тепла', N'Код источника тепла', N'"Код источника тепла"- текстовое поле, значение которого определяет принадлежность температурного графика соответствующему источнику тепла тепловой сети. Значение поля также используется для формирования заголовочной части документа температурного графика.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (893, N'TN_График нормативных температур', N'TN', N'name', N'НаимТГ', N'Наим.температурного графика', N'Наименование температурного графика', N'"Наименование температурного графика" - текстовое поле, значение которого однозначно идентифицирует данный температурный график. Значение поля используется для формирования заголовочной части документа температурного график.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (894, N'TN_График нормативных температур', N'TN', N'tip', N'ТипТГ', N'Тип графика', N'Тип графика', N' "Отопительный" - отопительный  температурный  график применяется  в тепловых  сетях   при    центральном   качественном    регулировании    с  преобладающей тепловой нагрузкой на отопление.   Рассчитывается  из условия постоянного расхода воды в тепловой сети, при котором обеспечивается  комфортная  температура  воздуха в отапливаемых помещениях на расчетном диапазоне температур наружного воздуха.                                             "Повышенный" - повышенный температурный график применяется  при центральном качественном  регулировании  в закрытых системах  теплоснабжения,  когда   не   менее  75%  потребителей   имеют  системы   горячего  водоснабжения с двухступенчатой последовательной схемой включения подогревателей, а  соотношение   нагрузок  горячего водоснабжения и отопления  примерно одинаковые (типовые абоненты). Рассчитывается из  условия  постоянства  суммы  расчетных расходов сетевой  воды  на отопление и горячее водоснабжение типовых абонентов.                                                               "Cкорректированный    повышенный" - скорректированный    повышенный    температурный  график  применяется в открытых  системах  теплоснабжения,  сети которых проектировались без учета  нагрузки   горячего   водоснабжения.  При этом имеет место неравенство 0.1 < Р < 0.2-0.3 ,  где   Р -  отношение средней тепловой  нагрузки  на  ГВС к расчетной
 тепловой   нагрузке   системы   теплоснабжения.    При  Р < 0.1  скорректированный     повышенный    температурный  график будет  эквивалентен отопительному графику." "Cкорректированный    пониженный" - скорректированный   пониженный   температурный    график  применяется   в   открытых  системах теплоснабжения, сети которых проектировались с учетом  тепловой  нагрузки ГВС. При этом имеет  место неравенство  Р > 0.3.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (895, N'TN_График нормативных температур', N'TN', N'tn_1', N'ТемпНачОтопСез', N'Температура наружн.воздуха начала/конца отоп. Сезона', N'Температура наружного воздуха начала/конца отопительного сезона', N'"Температура наружного воздуха начала/конца отопительного сезона" -  среднесуточная температура наружного воздуха равная  10 Град.С и ниже, определяющая продолжительность отопительного  периода для каждого климатического района в соответствии со СНиП 23-01-99* Строительная климатология.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (896, N'TN_График нормативных температур', N'TN', N'tn_5', N'ТгТемпНарВоздВерхСрез', N'Расчетная темп.наружн.воздуха для отопления', N'Расчетная температура наружного воздуха для отопления', N' "Расчетная   температура   наружного   воздуха"  - темпеpатуpа наиболее холодной пятидневки отопительного сезона, ноpмиpуемая СНиП 23-01-99*  Строительная климатология. Ввод и редактирование значения осуществляется в окне входной формы объекта "Система теплоснабжения"', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (897, N'TN_График нормативных температур', N'TN', N'tvn_r', N'ТгРасчТемВоздВнПомещ', N'Расчетная темп. воздуха внутри отапл.помещений', N'Расчетная температура воздуха внутри отапливаемых помещений', N'  "Расчетная температура воздуха внутри помещения"- определяется  значением   температуры  воздуха  в отапливаемых  помещениях,  исходя из норм допустимых комфотных условий по СНиП 2.04.05-91  Отопление, вентиляция и кондициониpование воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (898, N'TN_График нормативных температур', N'TN', N't1_r', N'ТгРасчТемпПодТруб', N'Расчетная температура сет.воды в под.теплопр.', N'Расчетная температура сетевой воды в подающем теплопроводе', N' "Расчетная температура сетевой  воды в подающем трубопроводе" - параметр температурного графика ,  определяющий совместно с расчетной температурой воды в обратном трубопроводе температурный перепад сетевой воды в теплопотребляющих системах при расчетной температуре наружного воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (899, N'TN_График нормативных температур', N'TN', N't2_r', N'ТгРасчТемпОбрТруб', N'Расчетная температура сет.воды в обр.теплопр.', N'Расчетная температура сетевой воды в обратном трубопроводе', N' "Расчетная    температура    сетевой     воды     в   обратном трубопроводе" - параметр температурного графика ,  определяющий совместно с расчетной температурой воды в подающем трубопроводе температурный перепад сетевой воды в теплопотребляющих системах при расчетной температуре наружного воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (900, N'TN_График нормативных температур', N'TN', N't3_r', N'ТгРасчТемпУзлаСмеш', N'Расчетная температура сет.воды после узла смешения', N'Расчетная температура сетевой воды после узла смешения', N'"Расчетная  температура  сетевой воды  после узла  смешения"-  определяется  значением  температуры сетевой воды  в подающем  стояке местной системы после  смешения на вводе при расчетной температуре наружного воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (901, N'TN_График нормативных температур', N'TN', N'q_r', N'ТгРасчТеплНагр', N'Расчетная нагрузка на отопление', N'Расчетная тепловая нагрузка на отопление', N'"Расчетная  тепловая нагрузка   отопления" -   часовой  расход  тепла,  обеспечивающий  компенсацию  тепловых  потерь  зданий через их ограждающие  конструкции  и  комфортное  значение  температуры воздуха внутри отапливаемых помещений. Значение поля используется при расчетах повышенного и скорректированного температурных графиков качественного регулирования. Ввиду этого при расчете данных графиков значение величины должно быть >0.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (902, N'TN_График нормативных температур', N'TN', N't1_2r', N'ТгТемпСетВодНижнСрез', N'Температура воды нижней срезки графика', N'Температура сетевой воды нижней срезки графика', N'"Температура   нижней    срезки   температурного графика" - минимально-допустимая температура сетевой воды  в  подающем трубопроводе в начале отопительного сезона,  поддерживаемая на уровне 50-55 Град.С (для закрытых ГВС) или  65-70  Град.С (для  открытых  ГВС). При  расчете  отопительных графиков со срезкой температуры воды в обратном трубопроводе на  пуско-наладочный период значение этой величины можно не задавать, оставить нулевое  значение в  экранном меню  ввода исходной информации.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (903, N'TN_График нормативных температур', N'TN', N't1_4r', N'ТгТемпСетВодВерхСрез', N'Температура воды верхней срезки графика', N'Температура сетевой воды верхней срезки графика', N'"Температура   верхней   срезки   температурного   графика" -  максимально-возможная   температуры  сетевой  воды в подающем  трубопроводе, определяемая ограничением установленной тепловой мощности источника тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (904, N'TN_График нормативных температур', N'TN', N'tvb_tr', N'ТгТребТемВоздВнПомещ', N'Требуемая температура воздуха внутри отапл.помещений', N'Требуемая температура воздуха внутри отапливаемых помещений', N'"Требуемая температура  воздуха  внутри помещения" - позволяет задать значение воздуха внутри помещения , если оно отличается от  расчетного  значния ,   регламентируемого    СНиП 2.04.05-91 "Отопление,вентиляция и кондиционирование воздуха", при расчете температурных графиков.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (905, N'TN_График нормативных температур', N'TN', N'uf', N'ТгФактКоэфСмеш', N'Фактический коэфф.смещения', N'Фактический коэффициент смещения', N'"Фактический коэффициент смешения" -  коэффициент смешения  элеваторного или насосного смесительного  узла отопительной  системы, полученный в процессе наладочных работ. Коэффициент смешения, определяется из выражений: U=(t1-t3)/(t3-t2),   где  t1, t2, t3 - температура воды при расчетной  температуре наружного воздуха, соответственно, в подающем трубопроводе тепловой сети, в обратном трубопроводе  на  выходе системы отопления,  в подающем трубопроводе системы отопления, Град.С.  Коэффициент смешения, также можно определить из выражения: U=G/Go, где  G, Go-  массовый расход воды ,соответственно,  через смесительную перемычку и на входе системы  отопления (после узла смешения).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (906, N'TN_График нормативных температур', N'TN', N't2_2r', N'ОтСкТемпНижСрезОбрВоды', N'Температура воды нижней срезки обрат.воды', N'Температура сетевой воды нижней срезки обратной воды', N'"Температура  нижней  срезки  обратной воды"-  температура  воды  в  обратном  трубопроводе,поддерживаемая  на  период  пуска  системы  теплоснабжения  от  начала   отопительного  сезона  до   некоторой  заданной   температуры   наружного  воздуха (пуско-наладочный  период). Для   обеспечения   этой температуры   в   обратном   трубопроводе   корректируется  температура   в   подающем   трубопроводе. Для    уточнения температуры наружного  воздуха в конце   пуско-наладочного  периода необходимо выполнить расчет температурного графика  при нулевой температуре нижней срезки и по  температурному 
 графику на экране  определить точное значение  температуры воды  в  обратном  трубопроводе  для  желаемой температуры  наружного возждуха конца пуска- наладочного периода .Затем  полученное  значение  "Температуры  нижней срезки обратной  воды" поместить  в соответствующую  строку экранного  меню  ввода  исходной  информации  и  выполнить повторный расчет  температурного графика. В  последнем температурном  графике  "Температура  нижней   срезки  обратной воды" будет  строго  увязана  со  всеми   исходными  данными  в  рассчитываемом  температурном графике. Рекомендуется при расчете температурных графиков задавать или значение "Температура сетевой воды нижней срезки обратной воды",  или значение "Температура сетевой воды верхней срезки графика (в подающем трубопроводе)", т.е. в одном поле 0, другом значение.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (907, N'TN_График нормативных температур', N'TN', N'q_gv', N'СкПвРасчНагоГВ', N'Расчетная  нагрузка в ГВС', N'Расчетная тепловая нагрузка на горячее  водоснабжение', N'"Расчетная тепловая нагрузка на горячее водоснабжение"- при качественном регулировании по совмещенной нагрузке отопления и горячего водоснабжения в качестве расчетной нагрузки на горячее водоснабжение принимается балансовая нагрузка Qбал=n*Qср [Е.Я. Соколов, Теплофикация и тепловые сети], где Qср - средненедельный расход теплоты на бытовое горячее водоснабжение, регламентируемыми  СНиП 2.04.01-85  Внутренний водопровод и канализация зданий, n - поправочный коэффициент для компенсации небаланса теплоты на отопление, ваызываемого неравномерностью суточного графика горячего водоснабжения. При наличии аккумуляторов горячей воды n=0, при отсутствии для жилых зданий ориентировочно n=1.2. Значение поля используется при расчетах повышенного и скорректированного температурных графиков качественного регулирования. Ввиду этого при расчете данных графиков значение величины должно быть >0.', N'Тепловая мощность', N'Гкал/ч')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (908, N'TN_График нормативных температур', N'TN', N'tg_r', N'СкПвТемпГорВоды', N'Темпер.горячей воды в точках водоразбора', N'Температура горячей воды в точках водоразбора', N'"Температура  горячей   воды  в  местах    водоpазбоpа" - pегламентиуется тpебованиями СНиП 2.04.01-85. Внутpенний водопpовод и канализация зданий: не ниже 60 Гpад.С в ГВС,
пpисоединеных    к   откpытым системам    теплоснабжения; не ниже  50  Гpад.С, пpисоединенных  к закpытым системам теплоснабжения.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (909, N'TN_График нормативных температур', N'TN', N'tx_r', N'СкПвТемпХолВоды', N'Темпер.холодной  воды', N'Температура холодной воды', N' "Температура холодной  воды" - pасчетная  темпеpатуpа водопpоводной
 воды, поступающая на вход подогревателей ГВС. Обычно в зимний пеpиод пpинимается
 pавной +5°C, а в летний пеpиод - +15°C.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (910, N'TN_График нормативных температур', N'TN', N'pr', N'СкПризнВодоразб', N'Признак способа водоразбора горячей воды', N'Признак способа водоразбора горячей воды: c переключением,из подающего, из обратного, из обоих', N'"Признак   способа   водоразбора:  из подающего, из обратного, c переключением, из обоих" - определяет возможность выбора  одного из способов водоразбора сетевой воды в открытой  ГВС:     Водоразбор осуществляется полностью из подающего  трубопровода;    Водоразбор осуществляется  полностью из обратного трубопровода;    Водоразбор  из  подающего  трубопроводов  сети с  переключением    на обратный трубопровод при заданной температуре сетевой воды в    обратном трубопроводе;                                            Автоматизированный   водоразбор  со  смешением  в  смесительном    клапане регулятора температуры воды, подаваемой в сеть ГВС.      Выбор требуемого способа водоразбора осуществляется в выпадающем меню поля .', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (911, N'TN_График нормативных температур', N'TN', N't2_gv', N'СкТемрОбрТрубПерекл', N'Темпер.воды в обратном трубопр.для переключения водоразбора', N'Температура воды в обратном трубопроводе для переключения водоразбора', N'"Температура   воды   в  обратном  трубопроводе  для  переключения  водоразбора в  ГВС"-  значение температуры сетевой воды в обратном  трубопроводе,  при   котором   должно  выполняться  переключение  водоразбора из  подающего  на  обратный  трубопровод   в неавтоматизированных  открытых ГВС.', NULL, N'Град.С')

