INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (912, N'TN_График нормативных температур', N'TN', N'g1', N'СкКоэфГидрУстПодТруб', N'Коэфф.гидравл.устойчивости под.теплопровода', N'Коэффициент гидравлической устойчивости подающего трубопровода', N'"Коэффициент,характеризующий гидравлическую устойчивость подающего трубопровода"-отношение изменения расхода  воды  в подающем трубопроводе, за счет изменения  водоразбора из этого трубопровода, к разности между фактическим расходом  из подающего трубопровода и расчетным расходом на ГВС. Для реальных сетей c неавтоматизированными потребителями  и  различной гидравлической устойчивостью  значения этого  коэффициента находятся в диапозоне 0.5-0.7.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (913, N'TN_График нормативных температур', N'TN', N'g2', N'СкКоэфГидрУстОбрТруб', N'Коэфф.гидравл.устойчивости обр.теплопровода', N'Коэффициент гидравлической устойчивости обратного трубопровода', N'"Коэффициент, характеризующий гидравлическую устойчивость  oбратного трубопровода"-отношение изменения расхода  воды  в подающем трубопроводе, за счет изменения водоразбора  из  обратного  трубопровода,  к  фактическому водоразбору  на  ГВС из этого трубопровода.  Для реальных сетей c неавтоматизированными потребителями  и  различной гидравлической устойчивостью  значения этого  коэффициента находятся в диапазоне 0.2-0.4.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (914, N'TN_График нормативных температур', N'TN', N't_gv1', N'ПвНедогр1ступениГВ', N'Величина недогрева в первой ступени подогр. ГВС', N'Величина недогрева в первой ступени подогревателя', N'"Температура недогрева  водопроводной  воды  в  первой  ступени  подогревателя" -  разность  между  температурой  обратной  воды  после системы отопления и температурой водопроводной воды после  первой ступени  подогревателя  ГВС при  "балансовой"   нагрузке  в  системе горячего водоснабжения в точке излома температурного 
 графика.   Обычный диапазон значений 5-10 Град.C.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (915, N'TN_График нормативных температур', N'TN', N'tn_2', N'ТгТемпПод2', N'Температура наружного воздуха  в 2-ой характерной точки', N'Температура наружного воздуха  в 2-ой характерной точке графика ( нижней точке срезки графика)', N'Температура наружного воздуха  в 2-ой характерной точке графика ( нижней точке срезки графика) - результирующее значение получаемое в ходе расчета выбранного температурного графика.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (916, N'TN_График нормативных температур', N'TN', N'tn_3', N'ТгТемпПод3', N'Температура наружного воздуха  в 3-ой характерной точки', N'Температура наружного воздуха  в 3-ой характерной точке графика (промежуточная точка)', N'Температура наружного воздуха  в 3-ой характерной точке графика (промежуточная точка) - результирующее значение получаемое в ходе расчета выбранного температурного графика.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (917, N'TN_График нормативных температур', N'TN', N'tn_4', N'ТгТемпПод4', N'Температура наружного воздуха  в 4-ой характерной точки', N'Температура наружного воздуха  в 4-ой характерной точке графика ( верхней точке срезки графика)', N'Температура наружного воздуха  в 4-ой характерной точке графика ( верхней точке срезки графика) - результирующее значение получаемое в ходе расчета выбранного температурного графика.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (918, N'TN_График нормативных температур', N'TN', N'kod_tg', N'КодПолногоГраф', N'Код развернутого температурного графика', N'Код развернутого температурного графика', N'Код развернутого температурного графика - строка в таблице "TG_Развернутый температурный график", хранящей температурный график, рассчитанным по заданным входным данным.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (919, N'TN_График нормативных температур', N'TN', N'v', N'СкоростьВетер', N'Скорость ветра', N'Скорость ветра', N'"Скорость ветра"- для систем  с преобладающей  отопительной  нагрузкой  скорость  ветра  более  3 м/с должна учитываться  как  дополнительный  фактор  теплопотерь у потребителей при  расчете температурных графиков качественного регулирования.', NULL, N'м/c')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (920, N'TN_График нормативных температур', N'TN', N'date_on', N'ДатаИcполнения', N'Дата иcполнения', N'Дата иcполнения', N'"Дата иcполнения" - поля, значение которого предназначено для определения дату расчета температурного графика.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (921, N'TN_График нормативных температур', N'TN', N'name_exe', N'Исполнитель', N'Исполнитель', N'Исполнитель', N'"Исполнитель" -  лицо, отстветственное за достоверность входных данных, используемых для расчета температурного графика.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (922, N'TN_График нормативных температур', N'UG', N'dt2_co', N'РазностьТ2СОзав_незав', N'Разность обрат.воды при зав.СО и нез.', N'Разница между расч.обратными температурами после  незав. и зависимой СО', N'Разница между расчетными температурами сетевой воды после водоподогревателя системы отопления при независимом её присоединении  и от отопления при зависимом присоединении. Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (923, N'TN_График нормативных температур', N'UG', N't2pod_parl', N'Т2подогр_паралГВт.изл', N'Темп.на вых.подогр.паралл.ГВ, т.излома', N'Температура сет. воды в т.изл. темп.графика после подогревателя ГВ, при парал. схеме ГВ', N'Температура сетевой  воды в точке излома температурного графика после подогревателя системы горячего водоснабжения, при параллельном его включении.  Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (924, N'TN_График нормативных температур', N'UG', N'dt2v_sm_noavm', N'НедХолВоды1ступСмешНеавт', N'Недогрев водопр.воды в 1ступ.,смеш.ГВ, част.авт.ТП', N'Недогрев водопров.воды до обратной после СО, при частично автомат.смеш. схеме ГВ', N'"Величина недогрева водопроводной воды в первой  ступени смешанной системы горячего водоснабжения до температуры обратной, поступающей из системы отопления (и вентиляции)" - цифровое   поле,  значение    которого определяет разность  между  температурой  обратной  воды после системы отопления и температурой водопроводной воды после первой ступени  подогревателя  ГВС при  "балансовой"   нагрузке в  смешанной системе горячего водоснабжения в точке излома температурного  графика.  При наличии на тепловых пунктах автоматических регуляторов, поддерживающих постоянную температуру воды для горячего водоснабжения величина недогрева обычно принимается равной  5 Град.C. Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (925, N'TN_График нормативных температур', N'UG', N'dt2v_sm_avm', N'НедВодВоды1ступСмешАвт', N'Недогрев водопр.воды в 1ступ.,смеш.ГВ, авт.ТП', N'Недогрев водопров.воды до обратной после СО,  при автоматизир. смеш. схеме ГВ', N'"Величина недогрева водопроводной воды в первой  ступени смешанной системы горячего водоснабжения до температуры обратной, поступающей из системы отопления (и вентиляции)" - цифровое   поле,  значение    которого определяет разность  между  температурой  обратной  воды после системы отопления и температурой водопроводной воды после первой ступени  подогревателя  ГВС при  "балансовой"   нагрузке в  смешанной системе горячего водоснабжения в точке излома температурного  графика.  При наличии на тепловых пунктах регуляторов постоянства расхода на систему отопления и  регуляторов, поддерживающих постоянную температуру воды для горячего водоснабжения величина недогрева обычно принимается равной  10 Град.C. Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла задается в  "Установках расчета планового режима".', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (926, N'TN_График нормативных температур', N'UG', N't1pod_posll', N'Т2СО_последГВт.изл', N'Темп.на вых.СО,послед.ГВ, т.излома', N'Температура обратной  воды после СО в т.излома темп.графика, при последовательной схеме ГВ', N'"Температура обратной  воды поступающей от системы отопления  в точке излома темпепературного графика, при последовательной схеме включения системы горячего водоснабжения" -  цифровое   поле,  значение    которого определяет температуру обратной воды, поступающей из системы отопления (и вентиляции) в точке излома температурного графика ( t2изл). При температуре воды в подающем теплопроводе тепловой сети в точке излома равной t1изл=150 Град.С  t2изл=41.7 Град.С,  при  t1изл=130 Град.С,  t2изл=44.8 Град.С. Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".(при t1=150 -> 41.7, при t1=130 -> 44.8)', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (927, N'TN_График нормативных температур', N'UG', N'dt2v_posl', N'НедХолВоды1ступПослГВ', N'Недогрев водопр.воды в 1ступ.,посл.ГВ', N'Недогрев водопроводной воды до обратной из СО, при последовательной схеме ГВ', N'"Величина недогрева водопроводной воды до температуры обратной, поступающей из системы отопления, при последовательной схеме включения  ГВС в первой ступене подогревателя" - цифровое   поле,  значение    которого определяет разность  между  температурой  обратной  воды после системы отопления и температурой водопроводной воды после первой ступени  подогревателя  ГВС при  "балансовой"   нагрузкев  системе горячего водоснабжения в точке излома температурного  графика.  При наличии на тепловых пунктах автоматических регуляторов, поддерживающих постоянный расход сетевой воды и постоянную температуру воды для горячего водоснабжения величина недогрева обычно принимается равной  5 Град.C.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (928, N'TN_График нормативных температур', N'UG', N't1pod_sm', N'Т2СО_смешГВт.изл', N'Темп.на вых.СО,смеш.ГВ, т.излома', N'Температура обратной  воды после СО в т.излома темп.графика, при смешанной схеме ГВ', N'"Температура обратной  воды поступающей от системы отопления  в точке излома темпепературного графика, при смешанной схеме включения системы горячего водоснабжения" -  цифровое   поле,  значение    которого определяет температуру обратной воды, поступающей из системы отопления (и вентиляции) в точке излома температурного графика.  Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (929, N'US_OUT', N'US', N'kod', N'КодРС', N'Код расч.сх.ненагруж.узла', N'Код расчетной схемы ненагруженного узла', N'"Код расчетной схемы ненагруженного узла" - символьное поле, значение  которого однозначно  определяет  расчетную  схему,  которой   принадлежит ненагруженный узел сети.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (930, N'US_OUT', N'US', N'kod_p', N'КодРСПотр', N'Код расч.сх.узла присоед.потреб.', N'Код расчетной схемы узла присоединения', N'"Код расчетной схемы узла присоединения" -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы ненагруженного узла, если она создана  для данного ненагруженного узла командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (931, N'US_OUT', N'US', N'nomer', N'№', N'№', N'Порядковый номер экземпляра', N'Порядковый номер экземпляра данного объекта. Недопустимая  для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (932, N'US_OUT', N'US', N'pih', N'ПьезНапор', N'ПьезНапорУзле', N'Пьезометрический напор', N'"Полученный пьезометрический напор в ненагруженном узле" -  цифровое поле, значение которого определяется в процессе расчета  потокораспределения как  разность  между  полным  напором  и  геодезической  отметкой  верха трубы в  узле присоединения ненагруженного узла.', NULL, N'м.вод.ст')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (933, N'US_OUT', N'US', N'pr', N'ПризУз', N'ПризнТеплопрНенагрУзла', N'Признак теплопровода ненагруженного узла', N'"Признак теплопровода ненагруженного узла " - символьное поле, значение которого определяет принадлежность ненагруженного узла подающему, значение "Подача", или обратному, значение "Обратка" теплопроводу. Значение «Общий» или пробел говорит о том,  что одноимённые ненагруженные узлы, с одинаковыми исходными данными, имеются и на подающем и обратном теплопроводах.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (934, N'US_OUT', N'US', N'pr_p', N'ПризТеплопрУзПрисоед', N'ПризнТеплопрУзла присоед.', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подача» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий» или пробел,  что расчетная схема локализована между подающим и обратным трубопроводами. Узел присоединения определяет узел присоединения расчетной схемы ненагруженного узла, если она создана  для данного ненагруженного узла командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (935, N'US_OUT', N'US', N't', N'Температура', N'ТемпВУзле', N'Температура сетевой воды', N'"Полученная температура сетевой воды в ненагруженном узле" -  цифровое поле,  значение которой определяется в процессе расчета  теплогидравлического режима сети при фиксированных гидравлических  сопротивлениях элементов оборудования сети и систем теплопотребления (фактический режим),  на заданные тепловые нагрузку систем горячего водоснабжения  и температуру наружного воздуха, по значению величины которой определяется температура сетевой воды в подающих теплопроводах на источниках тепла.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (936, N'US_OUT', N'US', N'uzel', N'НаимНенагрУз', N'НаимНенагрузла', N'Наименование ненагруженного узла', N'"Наименование ненагруженного узла"  -  символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет ненагруженный узел на данной расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (937, N'US_OUT', N'US', N'uzel_p', N'НаимУзПрисоед', N'Наим.узла присоед. .', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения. Узел присоединения определяет узел присоединения расчетной схемы ненагруженного узла, если она создана  для данного ненагруженного узла командой "Создать схему".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (938, N'UT_OUT', N'x', N'a10', N'Скорость', N'Скорость потока', N'Скорость потока сетевой воды', N'"Скорость  воды на  участке трубопровода"  - цифровое  поле, значение которого  определяется  в  процессе  расчета гидравлического режима на основе классической формулы.', NULL, N'м/c')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (939, N'UT_OUT', N'UT', N'a11', N'Время', N'Время прохождения потока воды', N'Время прохождения потока воды', N'"Время прохождения потока  воды" - цифровое поле,  значение которого определяется  как  отношение  длины  участка  трубопровода  к скорости потока  сетевой  воды  на  этом  участке  и  позволяет  оценить  время прохождения тепловой волны от начального до конечного узлов участка и, следовательно,может  быть  использовано  для  ориентировочной   оценки времени  ожидания   потребителем  потока   нагретой  до   определенной температуры сетевой воды.', NULL, N'час')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (940, N'UT_OUT', N'UT', N'a12', N'Sуч', N'Полное гидр.сопротивление', N'Полное гидравлическое сопротивление участка', N'"Полное  гидравлическое  сопротивление  участка"  -  цифровое поле, значение  которого  переписывается  из  соответствующих  полей  объекта "Участок теплопровода".', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (941, N'UT_OUT', N'UT', N'a13', N'Gуч', N'Расход сет. воды', N'Расход сетевой воды на участке', N'"Расход  сетевой  воды  на  участке  трубопровода" - цифровое поле, значение которого определяется в процессе расчета потокораспределения.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (942, N'UT_OUT', N'UT', N'a14', N'УдЛинПот', N'Уд.лин.потери напора', N'Удельные линейные потери напора на участке', N'"Удельные линейные потери напора на участке трубопровода" -  цифровое поле,   значение    которого   определяется    в   процессе    расчета гидравлического  режима  сети  как  отношение значения линейных потерь напора  к   строительной  длине   трубопровода.', NULL, N'мм.вод.ст./м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (943, N'UT_OUT', N'UT', N'a15', N'ЛинПот', N'Лин.потери напора', N'Линейные потери напора на участке', N'"Линейные  потери напора  на участке  трубопровода" - цифровое  поле, значение  которого  определяется  в  процессе  расчета гидравлического режима  сети  как  разность  между  общими  потерями напора и потерями напора в  местных сопротивлениях.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (944, N'UT_OUT', N'UT', N'a16', N'МестПот', N'Мест.потери напора', N'Местные потери напора на участке', N'"Местные  потери  напора  на  участке трубопровода" - цифровое поле, значение  которого  определяется  в  процессе  расчета гидравлического режима  сети  как  разность  между  общими  потерями напора и потерями напора в  местных сопротивлениях.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (945, N'UT_OUT', N'UT', N'a17', N'SumПот', N'Общие потери напора', N'Общие потери напора на участке', N'"Общие  потери  напора  на  участке  трубопровода" - цифровое поле, значение  которого  определяется  в  процессе  расчета гидравлического режима  сети  как  абсолютная  разность  полных  напоров  в конечном и начальном узлах участка.', N'Напор', NULL)
