INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (948, N'UT_OUT', N'UT', N'a20', N'ГеодКонУз', N'Геод.отмет.местности в кон.уз.', N'Геодезич.отметка местности в конечном узле участка', N'"Геодезическая отметка местности" - цифровое поле, значение которого определяется значением геодезической отметки оси трубопроводов в месте расположения данного узла присоединения нагрузки потребителя.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (949, N'UT_OUT', N'UT', N'a21', N'ПолНапКонУз', N'Полный напор в кон.узле', N'Полный напор в конечном узле участка', N'"Полный напор в конечном узле участка трубопровода" - цифровое поле, значение  которого  определяется  в  процессе  расчета гидравлического режима сети путем суммирования полного напора в начальном узле участка и общих потерь  напора на этом  участке с учетом  направления расхода.', N'Напор', NULL)
