INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (957, N'UT_OUT', N'UT', N'pr_p', N'ПризУз', N'Признак теплопр.узла просоед.', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (958, N'UT_OUT', N'UT', N'pr1', N'ПризНачУзУч', N'Признак теплопр.нач.узла участка трубопр.', N'Признак трубопровода начальн. узла участка теплопровода', N'"Признак трубопровода начального узла участка теплопровода"   -  символьное   поле,   значение которого  используется  для   указания принадлежности  начального узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» трубопроводам на расчетной схеме. Если  поле имеет значение «Общий», то  это  означает, что узел принадлежит  и подающему и обратному  трубопроводам.   Наличие значения «Общий» в  полях «Признак  теплопровода»  для   начального  и   конечного   узлов свидетельствует  о  том,   что  участок «общий»,  т.е.   его характеристики    одинаковы    для   подающего    и    обратного теплопроводов. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (959, N'UT_OUT', N'UT', N'pr2', N'ПризКонУзУч', N'Признак теплопр.кон.узла участка трубопр.', N'Признак трубопровода конечного узла участка теплопровода', N'"Признак трубопровода конечного узла участка теплопровода"  - символьное   поле,   значение которого  используется  для   указания принадлежности  конечного узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» трубопроводам на расчетной схеме. Если  поле имеет значение «Общий», то  это  означает, что узел принадлежит  и подающему и обратному  трубопроводам.   Наличие значения «Общий» в  полях «Признак  теплопровода»  для   начального  и   конечного   узлов свидетельствует  о  том,   что  участок «общий»,  т.е.   его характеристики    одинаковы    для   подающего    и    обратного теплопроводов. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел. П', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (960, N'UT_OUT', N'UT', N'qq', N'Нормы тепловых потерь', N'Нормы тепловых потерь', N'Нормы тепловых потерь', N'Нормы потерь тепла для текущей температуры наружного воздуха (грунта) для заданного наружного диаметра труб участка теплопровода. Нормы потерь тепла определяется типом прокладки теплопровода (канальная, бесканальная, надземная) и годом ввода или ремонта труб. Значение норм потерь тепла для фиксированных темпратурных перепадов приведены в таблицах Справочной информации 02, 03, 04,15.', N'Нормы тепловых потерь(плотности теплового потока)', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (961, N'UT_OUT', N'UT', N'sos', N'Состояние', N'Состояние', N'Состояние участка', N' "Состояние участка"- символьное поле, значение которого  "Закрыто"  - закрыт(отключен)  или "Открыто"-  открыт(подключен) позволяет пользователю, не удаляя данный объект закрыть участок теплопровода.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (962, N'UT_OUT', N'UT', N't1', N'ТемпВхУзел', N'Темп.сет. воды  во входном узле', N'Температура сет. воды  во входном узле', N'"Температура сететевой воды во входном узле участка теплопровода" - цифровое поле, определяется в результате  расчета теплового режима сети.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (963, N'UT_OUT', N'UT', N't2', N'ТемпОстывания', N'Температура остывания сет. воды', N'Температура остывания сет. воды', N'"Температура остывания сетевой воды на участке" - цифровое поле, определяется значением тепловых потерь через теплоизоляционную конструкцию трубопровода участка.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (964, N'UT_OUT', N'UT', N'tpot', N'ТеплПотери', N'Тепловые потери', N'Тепловые потери  теплопроводом', N'"Полученные тепловые потери участком теплопровода через изоляционную конструкцию" - цифровое поле, значение которого определяется выбранным методом расчёта тепловых потерь через теплоизоляционные конструкции в исходных данных по участку теплопровода:
"Тепловые потери" - с использованием "Норм тепловых потерь теплопроводами";  
"Тепловой поток" - с использованием "Норм плотности теплового потока через изоляционную поверхность";
Изоляция - с использование "Коэффициентов теплопроводности теплоизоляционных материалов".
Таблицы значений указанных величин (РД 153-34.0-20.523-98) приведены в разделе Сервис->Справочная информация.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (965, N'UT_OUT', N'UT', N'tzam', N'ВремяЗамерзания', N'Время остывания при остановке движения', N'Время остывания воды при остановке движения', N'"Время остывания воды при остановке движения" -  цифровое поле, значение  которого  определяет время остывания или до начала замерзания теплоносителя в трубопроводе до заданной температуры в случае приостановки его движения. Расчет времени производится через значения нормируемых тепловых для текущих значений температур теплоносителя и окружающей среды (наружнего воздуха, грунта). В случае подземной прокладки температура остываятеплоносителя  не может быть ниже температуры грунта.', NULL, N'час')
