INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (973, N'ZD_OUT', N'ZD', N'a14', N'ГеодОтмКонУз', N'Геод.отметки мест.в кон.узле', N'Геодезические отметки местности в конечном узле задвижки', N'"Геодезическая отметка местности" - цифровое поле, значение которого определяется значением геодезической отметки оси трубопроводов в месте расположения данного узла присоединения  задвижки.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (974, N'ZD_OUT', N'ZD', N'a15', N'ПолнНапКонУз', N'Полный напор в кон.узле', N'Полный напор в конечном узле задвижки', N'"Полный напор в конечном узле задвижки трубопровода" - цифровое поле, значение  которого  определяется  в  процессе  расчета гидравлического режима  сети  путем  суммирования  полного  напора  в  начальном  узле задвижки и  общих  потерь  напора  на  задвижке  с учетом  направления расхода.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (975, N'ZD_OUT', N'ZD', N'a7', N'Сост', N'Состояние', N'Состояние задвижки', N'"Состояние  задвижки"  - символьное поле, в котором может отображаться численое значение в процентах частичного  открытия  задвижки.', NULL, N'%')
