INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (979, N'ZD_OUT', N'ZD', N'kod1', N'КодРСНачУз', N'Код расч.сх.нач.узла', N'Код расчетной схемы начального узла задвижки', N'«Код расчетной схемы начального узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на входе задвижки.', NULL, NULL)
