INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (981, N'ZD_OUT', N'ZD', N'nomer', N'№', N'№', N'Порядковый номер', N'Порядковый номер записи', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (982, N'ZD_OUT', N'ZD', N'pr_p', N'ПризТеплУзПрис', N'Признак теплопр.узла присоед.', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (983, N'ZD_OUT', N'ZD', N'pr1', N'ПризТеплНачУз', N'Признак теплопр.нач.узла', N'Признак трубопровода начального узла задвижки', N'"Признак теплопровода начального узла" - символьное поле, значение которого значения "Подача" или "Обратка" используются для указания принадлежности узла на входе задвижки только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (984, N'ZD_OUT', N'ZD', N'pr2', N'ПризТеплКонУз', N'Признак теплопр.кон.узла', N'Признак трубопровода конечного узла задвижки', N'"Признак теплопровода конечного узла" - символьное поле, значение которого "Подача" или "Обратка" используются для указания принадлежности узла на выходе задвижки только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (985, N'ZD_OUT', N'ZD', N'sos', N'Состояние', N'Состояние', N'Состояние', N'"Состояние задвижки" - символьное поле, значение которого однозначно определяет состояние, в котором находится затвор задвижки. Если в поле присутствует в качестве его значения символы - "Открыто", то это говорит о том, что затвор открыт, и его сопротивление минимально. Если в поле присутствует в качестве его значения символы - "Закрыто", то это говорит о том, что затвор закрыт, а гидравлическое сопротивление задвижки максимально. Если в поле установлено значение "Частично" - частично открыта, то это свидетельствует о том, что затвор задвижки находится в некотором промежуточном положении и гидравлическое сопротивление задвижки будет вычислено через установленное в поле "Частичного открытия задвижки в % от KV" значение.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (986, N'ZD_OUT', N'ZD', N'uzel_p', N'НаимУзПрис', N'Наим.узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (987, N'ZD_OUT', N'ZD', N'uzel1', N'НаимНачУз', N'Наим.нач.узла', N'Наименование начального узла задвижки', N'"Наименование начального узла" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения задвижки на теплопроводах тепловой сети и задания направления потока теплоносителя через задвижку.', NULL, NULL)
