INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1009, N'Байпас', N'BP', N'sost', N'Сост', N'Состояние', N'Состояние', N'"Состояние байпаса" - символьное поле, значение которого  однозначно определяет состояние, в котором находится байпас.  Если в поле установлено значение - "Активен", то это  соответствуует включенному состоянию байпаса, т.е. поток может  проходить через байпас, дросселироваться до нужного уровня и на  этой основе рассчитывается дроссельная диафрагма. Если в поле  установлено значение - "Закрыт", то байпас отключен, расход через него  физически прерывается. Если в поле установлено значение - "Неактивен",  то байпас находится в неактивном состоянии, т.е. разрыв потока  не происходит, дросселирование и расчет дроссельной диафрагмы  не выполняются, т.е. байпас представляет собой участок  теплопровода с сопротивлением обусловленным геометрическими  характеристиками уложенной на участке трубы. Если в поле  установлено значение - "Установлен", то байпас находится в неактивном  состоянии, т.е. разрыв потока не происходит, дросселирование и  расчет дроссельной диафрагмы не выполняются, но байпас  представляет собой участок трубопровода с сопротивлением,  обусловленным геометрическими характеристиками уложенной на  участке трубы и сопротивлением расcчитанной ранее и  установленной на байпасе дроссельной диафрагмы.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1010, N'Байпас', N'BP', N'kod1', N'КодРСНачУз', N'Код расч.схемы нач.узла', N'Код  расчетной схемы  узла на  входе байпаса', N'"Код  расчетной схемы  узла на  входе байпаса"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на входе байпаса.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1011, N'Байпас', N'BP', N'uzel1', N'НаимНачУз', N'Наим. нач.узла', N'Наименование узла  на входе байпаса', N'"Наименование узла  на входе байпаса"  - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно определяет узел на  расчетной  схеме.   Это  наименование  используется  для  указания заданного   направления    потока   сетевой    воды   через    байпас.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1012, N'Байпас', N'BP', N'pr1', N'ПризнТеплНачУз', N'Признак теплопр. нач.узла', N'Признак  теплопровода узла  на входе  байпаса', N'"Признак  теплопровода узла  на входе  байпаса" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  начального  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  теплопроводам  на  расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1013, N'Байпас', N'BP', N'kod2', N'КодРСКонУз', N'Код расч.схемы кон.узла', N'Код  расчетной схемы  узла на  выходе байпаса', N'"Код  расчетной схемы  узла на  выходе байпаса"  - символьное  поле, значение  которого  однозначно  определяет  расчетную  схему,  которой принадлежит узел на выходе байпаса.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1014, N'Байпас', N'BP', N'uzel2', N'НаимКонУз', N'Наим. кон.узла', N'Наименование узла  на выходе байпаса', N'"Наименование узла  на выходе байпаса"  - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно определяет узел на  расчетной  схеме.   Это  наименование  используется  для  указания заданного   направления    потока   сетевой    воды   через    байпас.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1015, N'Байпас', N'BP', N'pr2', N'ПризнТеплКонУз', N'Признак теплопр. кон.узла', N'Признак  теплопровода узла  на выходе  байпаса', N'"Признак  теплопровода узла  на выходе  байпаса" -  символьное поле, значение  которого   "Подача"  или  "Обратка"  используются  для указания принадлежности  конечного  узла  только  подающему  -  "Подача" или только  обратному  -   "Обратка"  трубопроводам  на  расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1016, N'Байпас', N'BP', N'uzu_pr', N'РегВел', N'Регулируемая величина', N'Регулируемая величина', N'"Регулируемая величина" - символное поле, значение которого "Расход", говорит о том, байпас обеспечивает дросселирование по  расходу с целью его стабилизации на этом участке посредством  рассчитанной дроссельной диафрагмы. При этом байпас выполняет  функции регулятора расхода и устанавливается на перемычках  между подающим и обратным трубопроводами квартального  ответвления с целью реализации заданного коэффициента смешения,  т.е. заданного температурного графика ответвления, значение "Напор" - говорит о том, что байпас выполняет функции регулятора давления, предназначенного для гашения избыточного напора на  заданном участке подающего или обратного теплопроводов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1017, N'Байпас', N'BP', N'uzu_k', N'КодРСРегУз', N'Код расч. сх. узла с регул.напором', N'Код расчетной схемы узла с регулируемым напором', N'"Код расчетной схемы узла с регулируемым напором" -  символьное поле, значение которого однозначно определяет  расчетную схему, которой принадлежит узел с регулируемым напором.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1018, N'Байпас', N'BP', N'uzu', N'НаимРегУз', N'Наим. узла с регул.напором', N'Наименование узла с регулируемым напором', N'"Наименование узла с регулируемым напором" - символьное поле,  значение которого совместно с кодом расчетной схемы, однозначно  определяет узел на байпасном участке, в котором должен быть  обеспечен заданный напор.  Дросселирование по напору используется при расчете диаметра  диафрагм, предназначенных для гашения избыточного напора на  заданном участке подающего или обратного теплопроводов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1019, N'Байпас', N'BP', N'przu', N'ПризнТеплРегУз', N'Признак теплопр. с регул.напором', N'Признак теплопровода с  регулируемым   напором', N'"Признак теплопровода" - символьное поле, значение которого  символы "Подача" или "Обратка" используются для указания принадлежности  узла c регулированным напором только подающему - символы "Подача" или  только обратному - символы "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1020, N'Байпас', N'BP', N'h', N'РегНап', N'Регул.напор', N'Значение  регулируемого  напора', N' "Значение регулируемого напора" -  цифровое поле, значение которого определяется величиной регулируемого напора при дросселировании по заданному напору.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1021, N'Байпас', N'BP', N'delta_h', N'ДопОтклНап', N'Допуст.откл.напора', N'Допустимое отклонение напора от требуемого', N'"Допустимое отклонение напора от требуемого " -  цифровое поле, значение которого определяется допустимым  отклонением регулируемого напора при дросселировании по заданному напору.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1022, N'Байпас', N'BP', N'q', N'РегРасх', N'Регул.расход', N'Значение  регулируемого  расхода', N'"Значение регулируемого расхода" -  цифровое поле, значение которого определяется величиной регулируемого расхода при дросселировании по заданному расходу. Дросселирование по заданному расходу позволяет  автоматически определить диаметр диафрагмы, устанавливаемой на  перемычке между подающим и обратным трубопроводами  распределительной сети , подключенной к ЦТП и обеспечивающей  фиксацию заданного расхода смешения, посредством которого  реализуется требуемый коэффициент смешения и требуемый  температурный график сети.Требуемый коэффициент смешения обычно  рассчитывают по формуле:  Ксм=(Т1-Т3)/(Т3-Т2) ,  где Т1,Т3 - соответственно,расчетная температура сетевой воды  в подающем трубопроводе до и после смешения;  Т2 - расчетная температура сетевой воды в обратном трубопроводе  распределительной сети.  ВНИМАНИЕ!!! При использовании в распределительной сети  температурного графика , реализуемого путем смешения потоков  сетевой воды, удельные расходы для тепловых нагрузок  потребителя следует определять по температурному графику  Т3-Т2, а расход воды по смесительной перемычке , который  является исходным значением поля "Значение регулируемого расхода" следует  определять по формуле :  Gсм= Ксм*Gр/(1+Ксм), т/ч  где Gсм, Gр - соответственно, расчетный расход по смесительной  перемычке и суммарный расчетный расход всех потребителей,  подключенных к распределительной сети.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1023, N'Байпас', N'BP', N'delta_q', N'ДопОтклРасх', N'Допуст.откл.расхода', N'Допустимое отклонение расхода от требуемого', N'"Допустимое отклонение расхода от требуемого " -  цифровое поле, значение которого определяется  допустимым отклонением регулируемого расхода при  дросселировании по заданному расходу.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1024, N'Байпас', N'BP', N'standard', N'Труба', N'Стандарт', N'Стандарт труб на участке', N'"Стандарт труб на участке теплопровода", поле определяющее стандарт используемых труб на участке.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1025, N'Байпас', N'BP', N'kod_truba', NULL, N'Ссылка на стандартную трубу', N'Ссылка на стандартную трубу', N'Ссылка на стандартную трубу', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1026, N'Байпас', N'BP', N'dln', N'Длина', N'Длина', N'Длина', N'"Длина" - цифровое поле, значение которого определяется  строительной длиной байпаса.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1027, N'Байпас', N'BP', N'diam', N'Диам', N'Внутр.диам.', N'Внутренний диаметр', N'"Внутренний диаметр" - цифровое поле, значение которого  определяется внутренним диаметром трубы, используемой для  байпасного теплопровода. Произвольный выбор внутреннего  диаметра байпасной трубы может привести к тому, что внутренний  диаметр рассчитанной дроссельной диафрагмы будет превышать  диаметр трубы, что недопустимо по физическому условию  дросселирования путем сжатия потока. ВНИМАНИЕ!!! При  возникновении такой ситуации на любом байпасе расчетной схемы  следует изменить диаметр байпасной трубы, взяв ближайший  больший из стандартного ряда. Для этого необходимо воспользоваться функцией поля выбора  диаметра труб стандартного ряда и выберить ближайший  диаметр, превышающий рассчитанный диаметр дроссельной  диафрагмы. После записи нового диаметра байпасной трубы  повторите расчет планового режима. Такой прием  гарантированно исключает упомянутый парадокс с диаметрами трубы  и диафрагмы.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1028, N'Байпас', N'BP', N'scher', N'ЭквШерх', N'Экв. шерохов.трубы', N'Эквивалентная шероховатость  трубы', N'"Эквивалентная шероховатость трубы" - цифровое поле,  значение которого характеризует шероховатость (негладкость)  внутренних стенок байпасной трубы по средней высоте  выступов. Определяется в условиях эксплуатации трубопроводов,  как правило, по данным гидравлических испытаний тепловых сетей,  либо по справочным данным,приводимым для труб различного типа и  различных условий эксплуатации. По умолчанию значение принимается равным 0.5 мм , что  соответствует шероховатости новых стальных труб.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1029, N'Байпас', N'BP', N'sum_m_s', N'СумМестСопр', N'Сумма  коэфф местных сопр..', N'Сумма коэффициентов местных сопротивлений', N'"Сумма коэффициентов местных сопротивлений" - цифровое  поле, значение которого определяется суммой коэффициентов  местных сопротивлений, имеющих место на данном участке  теплопровода. Рекомендуется при заполнении данного поля использовать функцию поля определения состава, количества и суммы коэффициентов местных сопротивлений, имеющих место на данном участке  теплопровода.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1030, N'Байпас', N'BP', N'sopr', N'ГидрСопр', N'Гидр. сопротив.', N'Гидравлическое сопротивление', N'"Гидравлическое сопротивление байпаса" - цифровое  поле, значение которого рассчитывается программными средствами  на основании геометрических характеристик трубопроводов,  шероховатости труб, характеристик местных сопротивлений и  диаметра дроссельной диафрагмы, выбранной из заданного условия  дросселирования. ВНИМАНИЕ!!! Если сопротивление получено в  результате расчета гидравлического(планового) режима тепловых сетей с  фиксированными нагрузками и записано программными средствами,  то оно используется в режиме с фиксированными сопротивлениями (фактического) как константа, т. е. байпасный участок в режиме с  фиксированными сопротивлениями рассматривается программными  средствами как обычный теплопровод с фиксированными  параметрами, а значение признака дросселирования игнорируется.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1031, N'Байпас', N'BP', N'ustanovka', N'Установка', N'Место установки', N'Место установки', N'"Место установки байпаса с дроссельной диафрагмой на внешнем  теплопроводе" - символьное поле, значение которого произвольно  определяется пользователем и служит для идентификации места  установки байпаса на внешних теплопроводах распределительной  сети, в головной части которой и должна размещатся диафрагма.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1032, N'Байпас', N'BP', N'kod_owner', N'Принадлеж', N'Баланс.принадлежность', N'Балансовая принадлежность', N'Балансовая принадлежность', NULL, NULL)
