INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1090, N'График нагрузки ГВС', N'GN', N'gvs_00_01', N'Нагрузка ГВ с 00 до 01 часов, в будний день', N'Нагрузка ГВ с 00 до 01 часов суток в будний день', N'Нагрузка горячего водоснабжения с 00 до 01 часов суток в будний день', N'Символьное поле, определяющее величину почасовой нагрузки в системе теплопотребления горячего водоснабжения потребителя в будний день недели. Значение поля может принимать значения: расчетная, средняя, балансовая (только для закрытых систем горячего водоснабжения), максимальная, нулевая, k*Qср, где k - коэффициент, определяющий величину почасовой   нагрузки горячего водоснабжения относительно величины средней нагрузки, k может принимать значения в пределах от 0.1 до 0.9, с шагом 0.1.', NULL, NULL)
