INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1182, N'Задвижка', N'ZD', N'sost', N'Сост', N'Состояние', N'Состояние', N'"Состояние задвижки" - символьное поле, значение которого однозначно определяет состояние, в котором находится затвор задвижки. Если в поле присутствует в качестве его значения символы - "Открыто", то это говорит о том, что затвор открыт, и его сопротивление минимально. Если в поле присутствует в качестве его значения символы - "Закрыто", то это говорит о том, что затвор закрыт, а гидравлическое сопротивление задвижки максимально. Если в поле установлено значение "Частично" - частично открыта, то это свидетельствует о том, что затвор задвижки находится в некотором промежуточном положении и гидравлическое сопротивление задвижки будет вычислено через установленное в поле "Частичного открытия задвижки в % от KV" значение.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1183, N'Задвижка', N'ZD', N'kod_p', N'КодРСУзПрис', N'Код расч.сх.узла прис.', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
