INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1185, N'Задвижка', N'ZD', N'pr_p', N'ПризнТеплУзПрис', N'Признак теплопр.узла прис.', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1186, N'Задвижка', N'ZD', N'kod1', N'КодРСНачУз', N'Код расч.сх.нач.узла', N'Код расчетной схемы начального узла', N'«Код расчетной схемы начального узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на входе задвижки.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1187, N'Задвижка', N'ZD', N'uzel1', N'НаимНачУз', N'Наим.нач.узла', N'Наименование начального узла', N'"Наименование начального узла" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения задвижки на теплопроводах тепловой сети и задания направления потока теплоносителя через задвижку.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1188, N'Задвижка', N'ZD', N'pr1', N'ПризнТеплНачУз', N'Признак тепл.кон.узла', N'Признак теплопровода начального узла', N'"Признак теплопровода начального узла" - символьное поле, значение которого значения "Подача" или "Обратка" используются для указания принадлежности узла на входе задвижки только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1189, N'Задвижка', N'ZD', N'kod2', N'КодРСКонУз', N'Код расч.сх.коч.узла', N'Код расчетной схемы конечного узла', N'«Код расчетной схемы конечного узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на выходе задвижки.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1190, N'Задвижка', N'ZD', N'uzel2', N'НаимКонУз', N'Наим.кон.узла', N'Наименование конечного узла участка', N'"Наименование конечного узла" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения задвижки на теплопроводах тепловой сети и задания направления потока теплоносителя через задвижку.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1191, N'Задвижка', N'ZD', N'pr2', N'ПризнТеплКонУз', N'Признак тепл.кон.узла', N'Признак теплопровода конечного узла', N'"Признак теплопровода конечного узла" - символьное поле, значение которого "Подача" или "Обратка" используются для указания принадлежности узла на выходе задвижки только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1192, N'Задвижка', N'ZD', N'name_zd', N'Место установки', N'Место установки', N'Место установки', N'"Место установки" - символьное поле, значение которого определяет место установки  установленной задвижки, "Секционирующая"- Секционирующая задвижка на магистральном/распределительном теплопроводе;
"Вход ТП" - Входная на подающем трубопроводе теплового пункта;
"Выход ТП" - Выходная на обратном трубопроводе теплового пункта;
"Перед НС" - Перед насосом;
"После насоса" - После насоса;
"Вход СО" - На подающем трубопроводе перед системой отопления;
"Выход СО" - На обратном трубопроводе после системы отопления;
"Летняя" - На перемычке для летнего режима работы подогревателя ГВ при двухступенчатой схеме;
"Вх.подогр.ГВ" - На подающем трубопроводе сетевой воды перед подогревателем ГВ;
"Вых.подогр.ГВ" - На трубопроводе сетевой воды после подогревателем ГВ (в двухступенчатых схемах - после II ступени);
"Вх.I ступен.ГВ" - На трубопроводе сетевой воды перед подогревателем ГВ I ступени;
"Вых.I ступен.ГВ" - На трубопроводе сетевой воды после подогревателем ГВ I ступени;
"Обвод СО Iст.ГВ" - На обратном трубопроводе от СО в обвод подогревателя ГВ I ступени;
"ГВ после подогр." - На трубопроводе горячего водоснабжения после подогревателя;
"Циркуляционная" - На циркуляционном трубопроводе ГВ.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1193, N'Задвижка', N'ZD', N'diametr', N'ДиаметрУсловн', N'Диаметр условный', N'Диаметр условный', N'"Диаметр условный" ? цифровое поле, значение(Dу) которого определяется типом установленной задвижки. Значение поля имеет размерность  ?  мм. Значение величины используется для расчета гидравлического сопротивления (Sзад) задвижки, при разной степени открытия её затвора. Sзад=10/(Kv)^2, где Kv ? пропускная способность установленной задвижки.  Kv=(5.04*0.785*((Dу)^2/100)* Kп /(Kси)^0.5, где Kси ? коэффициент сопротивления, Kп ? поправочный коэффициент входного сечения, Kп=0.95. Kси=f(No), где No ? относительное число оборотов приводного маховика задвижки, No =N/max, где max, N ?  соответственно максимально возможное и установленное число оборотов маховика, величины определяющее степень открытия затвора задвижки. Значение N определяется в поля   "Частичное открытие задвижки".', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1194, N'Задвижка', N'ZD', N'otn_kv', N'ОтнПротеч', N'Негерм.затвора, % от KV', N'Относительная протечка в % от KV (негерметичность затвора)', N'"Относительная протечка в % от KV (негерметичность затвора)" - цифровое поле, значение которого определяет величину протечки в % от пропускной способности (KV) через затвор задвижки в закрытом состоянии (при минимальной площади прохода). Значение поля численно определяется расходом через задвижку при минимальной площади прохода и перепаде давления на нем, равным 1 кгс/см2.  На основе этих данных может быть определено максимальное сопротивление задвижки при полном ее закрытии. Значение поля имеет размерность - %.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1195, N'Задвижка', N'ZD', N'proz_kv', N'ЧастОткр', N'Част.откр.задв., % от KV', N'Частичное открытие задвижки в % от KV', N'"Частичное открытие задвижки"  -  цифровое поле, значение которого определяет число оборотов приводного маховика задвижки  в % от максимально возможного количества оборотов  в частично открытом состоянии. Значение поля имеет размерность  -  %. Значение поля активизируется и изменяет гидравлическое сопротивление задвижки в зависимости от установленной степени открытия в %, если в поле  "Состояние задвижки" установлено значение Ч  ?  частично открыта. В состоянии задвижки *  -  закрыта, и пробел(открыта) установленное значение поля "Частичное открытие задвижки " не активно, т.е. не влияет на значение гидравлического сопротивления задвижки, а поэтому не сможет повлиять на потокораспределение и потери напора на участке сети с установленной задвижкой.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1196, N'Задвижка', N'ZD', N'sopr', N'ГидрСопр', N'Гидр.сопр.', N'Гидравлическое сопротивление', N'"Гидравлическое сопротивление задвижки" - цифровое поле, значение которого может определяться в процессе гидравлических испытаний.  ВНИМАНИЕ!!! Если сопротивление задвижки задано, то поля 5-7 во Входной форме игнорируются, т.е.их можно не заполнять.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1197, N'Задвижка', N'ZD', N'name', N'Наимен', N'Наименование', N'Содержательное наименование', N' "Содержательное наименование задвижки" - символьное поле, значение которого произвольно и служит для идентификации установленной задвижки в процессе имитации переключений потоков в сети.', NULL, NULL)
