INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1283, N'Источник тепла', N'IS', N'name_ist', N'Наименование источника тепла', N'Наименование источника тепла', N'Наименование источника тепла', N'Наименование совокупности (или одной) теплогенерирующих установок системы теплоснабжения, в которых производится нагрев теплоносителя за счет передачи теплоты сжигаемого топлива, а также путем электронагрева или другим, в том числе нетрадиционными способами, участвующих в теплоснабжении.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1284, N'Источник тепла', N'IS', N'a24', N'УдОбъемСО', N'Удельный  объем  воды  в  системе  отопления', N'Уд.объем воды в системе отопления обобщенного потребителя', N' "Удельный объем воды в системе отопления" - числовое поле, значение которого определяет удельный объем воды в системе отопления в зависимости от расчетного температурного перепада и типа отопительных приборов. Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1285, N'Источник тепла', N'IS', N'a25', N'УдОбъемВент', N'Удельный  объем  воды  в  системе  вентиляции', N'Уд.объем воды в системе вентиляции обобщенного потребителя', N'"Удельный объем воды в системе вентиляции" - числовое поле, значение которого определяет удельный объем воды в отопительно-вентиляционной системе, оборудованной калориферами, в зависимости от расчетного температурного перепада. Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1286, N'Источник тепла', N'IS', N'memo', N'Комментарий', N'Комментарий', N'Комментарий', N'"Поле комментария" -  символьное поле, содержащее произвольный текст, позволяющий пользователю конкретизировать назначение данных, зафиксировать выполненные изменения в описании расчетной схемы и т.п.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1287, N'Источник тепла', N'IS', N'geodz', NULL, N'Геодезическая отметка верха труб', N'Геодезическая отметка верха труб', N'"Геодезическая отметка верха разводящих труб" - цифровое поле, значение которого определяет геодезическую отметку верха разводящих труб в коллекторе источника тепла.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1288, N'Источник тепла', N'IS', N't1_leto', N'Тподающая в летниий период', N'Температура воды в подающем трубопроводе в летний период', N'Температура сетевой воды в подающем трубопроводе в летний период', N'"Температура сетевой воды в подающем теплопроводе в летний период"- числовое поле,  значение которого определяет нормативное  значение температуры сетевой воды в подающем теплопроводе тепловой сети в летнем периоде. Значение температуры постоянно для всех температур наружного воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1289, N'Источник тепла', N'IS', N't2_leto', N'Тобратная в летниий период', N'Температура воды в обратном трубопроводе в летний период', N'Температура сетевой воды в обратном трубопроводе в летний период', N'"Температура сетевой воды в обратном теплопроводе в летний период"- числовое поле,  значение которого определяет нормативное  значение температуры сетевой воды в обратном теплопроводе тепловой сети в летнем периоде при средней нагрузке горячего водоснабжения. Значение температуры постоянно для всех температур наружного воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1290, N'Источник тепла', N'IS', N'begin_year', N'ДатаНачОтопПер', N'Дата начала отоп.периода', N'Дата начала отопительного периода', N'"Дата начала отопительного периода" - поле типа Дата, значение  которого определяет календарную дату начала отопительного периода системы теплоснабжения. Значение  поля используется для определения начала отопительного периода (конца летнего периода) при расчете среднемесячных тепловых потерь.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1291, N'Источник тепла', N'IS', N'end_year', N'ДатаОкончОтопПер', N'Дата окончания отоп.периода', N'Дата окончания отопительного периода', N'"Дата окончания отопительного периода" - поле типа Дата, значение  которого определяет календарную дату окончания отопительного периода системы теплоснабжения. Значение  поля используется для определения  конца отопительного периода (начала летнего периода) при расчете среднемесячных тепловых потерь.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1292, N'Источник тепла', N'IS', N't1_god_ist', N'Среднегод.температура, под.трубопр.', NULL, N'Среднегод.температура сетевой воды, подающий трубопровод', N'Среднегодовая температура сетевой воды, подающий трубопровод.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1293, N'Источник тепла', N'IS', N't2_god_ist', N'Среднегод.температура, обр.трубопр.', NULL, N'Среднегод.температура сетевой воды, обратный трубопровод', N'Среднегодовая температура сетевой воды, обратный трубопровод.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1294, N'Источник тепла', N'IS', N'remont_leto', N'Планируемая продолжительность ремонтного периода', N'Планируемая продолжительность ремонтного периода', N'Планируемая продолжительность ремонтного периода', N'"Планируемая продолжительность ремонтного периода"- цифровое поле значение которого определяет количество дней планового ремонта, испытаний. Значение  поля используется  при расчете нормируемых (расчетных) Потерь сетевой воды (ПСВ) связанных с пусковым заполнением  тепловых сетей и местных систем в эксплуатацию после планового ремонта и с подключением новых сетей и систем после монтажа. ПСВ данного типа рекомендуется принимать равным 1.2-1.5 кратному объему тепловых сетей и систем теплопотребления.', NULL, N'дня(ей)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1295, N'Источник тепла', N'TN', N'year', N'ГодСезона', N'Календарный год', N'Календарный год', N'"Календарный год" - текстовое поле, значение которого для отопительного сезона  соответствуют  году первой  половины  отопительного сезона (осень, зима) и году второй  половины отопительного сезона (зима, весна). Например: 2010 - 2011. Для летнего периода:  2011. Значения поля совместно со значение поля "Код источника тепла" используется для автоматического формирования значение поля "Код развернутого температурного графика" текущей таблицы. Значение поля используется для формирования заголовочной части документа температурного графика.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1296, N'Источник тепла', N'TN', N'name', N'НаимТГ', N'Наим.температурного графика', N'Наименование температурного графика', N'"Наименование температурного графика" - текстовое поле, значение которого однозначно идентифицирует данный температурный график. Значение поля используется для формирования заголовочной части документа температурного график.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1297, N'Источник тепла', N'TN', N'tip', N'ТипТГ', N'Тип графика', N'Тип графика', N' "Отопительный" - отопительный  температурный  график применяется  в тепловых  сетях   при    центральном   качественном    регулировании    с  преобладающей тепловой нагрузкой на отопление.   Рассчитывается  из условия постоянного расхода воды в тепловой сети, при котором обеспечивается  комфортная  температура  воздуха в отапливаемых помещениях на расчетном диапазоне температур наружного воздуха.                                             "Повышенный" - повышенный температурный график применяется  при центральном качественном  регулировании  в закрытых системах  теплоснабжения,  когда   не   менее  75%  потребителей   имеют  системы   горячего  водоснабжения с двухступенчатой последовательной схемой включения подогревателей, а  соотношение   нагрузок  горячего водоснабжения и отопления  примерно одинаковые (типовые абоненты). Рассчитывается из  условия  постоянства  суммы  расчетных расходов сетевой  воды  на отопление и горячее водоснабжение типовых абонентов.                                                               "Cкорректированный    повышенный" - скорректированный    повышенный    температурный  график  применяется в открытых  системах  теплоснабжения,  сети которых проектировались без учета  нагрузки   горячего   водоснабжения.  При этом имеет место неравенство 0.1 < Р < 0.2-0.3 ,  где   Р -  отношение средней тепловой  нагрузки  на  ГВС к расчетной
 тепловой   нагрузке   системы   теплоснабжения.    При  Р < 0.1  скорректированный     повышенный    температурный  график будет  эквивалентен отопительному графику." "Cкорректированный    пониженный" - скорректированный   пониженный   температурный    график  применяется   в   открытых  системах теплоснабжения, сети которых проектировались с учетом  тепловой  нагрузки ГВС. При этом имеет  место неравенство  Р > 0.3.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1298, N'Источник тепла', N'TN', N'tn_1', N'ТемпНачОтопСез', N'Температура наружн.воздуха начала/конца отоп. Сезона', N'Температура наружного воздуха начала/конца отопительного сезона', N'"Температура наружного воздуха начала/конца отопительного сезона" -  среднесуточная температура наружного воздуха равная  10 Град.С и ниже, определяющая продолжительность отопительного  периода для каждого климатического района в соответствии со СНиП 23-01-99* Строительная климатология.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1299, N'Источник тепла', N'TN', N'tn_5', N'ТгТемпНарВоздВерхСрез', N'Расчетная темп.наружн.воздуха для отопления', N'Расчетная температура наружного воздуха для отопления', N' "Расчетная   температура   наружного   воздуха"  - темпеpатуpа наиболее холодной пятидневки отопительного сезона, ноpмиpуемая СНиП 23-01-99*  Строительная климатология. Ввод и редактирование значения осуществляется в окне входной формы объекта "Система теплоснабжения"', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1300, N'Источник тепла', N'TN', N'tvn_r', N'ТгРасчТемВоздВнПомещ', N'Расчетная темп. воздуха внутри отапл.помещений', N'Расчетная температура воздуха внутри отапливаемых помещений', N'  "Расчетная температура воздуха внутри помещения"- определяется  значением   температуры  воздуха  в отапливаемых  помещениях,  исходя из норм допустимых комфотных условий по СНиП 2.04.05-91  Отопление, вентиляция и кондициониpование воздуха.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1301, N'Источник тепла', N'TN', N't1_r', N'ТгРасчТемпПодТруб', N'Расчетная температура сет.воды в под.теплопр.', N'Расчетная температура сетевой воды в подающем теплопроводе', N' "Расчетная температура сетевой  воды в подающем трубопроводе" - параметр температурного графика ,  определяющий совместно с расчетной температурой воды в обратном трубопроводе температурный перепад сетевой воды в теплопотребляющих системах при расчетной температуре наружного воздуха.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1302, N'Источник тепла', N'TN', N't2_r', N'ТгРасчТемпОбрТруб', N'Расчетная температура сет.воды в обр.теплопр.', N'Расчетная температура сетевой воды в обратном трубопроводе', N' "Расчетная    температура    сетевой     воды     в   обратном трубопроводе" - параметр температурного графика ,  определяющий совместно с расчетной температурой воды в подающем трубопроводе температурный перепад сетевой воды в теплопотребляющих системах при расчетной температуре наружного воздуха.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1303, N'Источник тепла', N'TN', N't3_r', N'ТгРасчТемпУзлаСмеш', N'Расчетная температура сет.воды после узла смешения', N'Расчетная температура сетевой воды после узла смешения', N'"Расчетная  температура  сетевой воды  после узла  смешения"-  определяется  значением  температуры сетевой воды  в подающем  стояке местной системы после  смешения на вводе при расчетной температуре наружного воздуха.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1304, N'Источник тепла', N'TN', N'q_r', N'ТгРасчТеплНагр', N'Расчетная нагрузка на отопление', N'Расчетная тепловая нагрузка на отопление', N'"Расчетная  тепловая нагрузка   отопления" -   часовой  расход  тепла,  обеспечивающий  компенсацию  тепловых  потерь  зданий через их ограждающие  конструкции  и  комфортное  значение  температуры воздуха внутри отапливаемых помещений. Значение поля используется при расчетах повышенного и скорректированного температурных графиков качественного регулирования. Ввиду этого при расчете данных графиков значение величины должно быть >0.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1305, N'Источник тепла', N'TN', N't1_2r', N'ТгТемпСетВодНижнСрез', N'Температура воды нижней срезки графика', N'Температура сетевой воды нижней срезки графика', N'"Температура   нижней    срезки   температурного графика" - минимально-допустимая температура сетевой воды  в  подающем трубопроводе в начале отопительного сезона,  поддерживаемая на уровне 50-55 Град.С (для закрытых ГВС) или  65-70  Град.С (для  открытых  ГВС). При  расчете  отопительных графиков со срезкой температуры воды в обратном трубопроводе на  пуско-наладочный период значение этой величины можно не задавать, оставить нулевое  значение в  экранном меню  ввода исходной информации.', N'Град.С', N'1')

SET IDENTITY_INSERT [dbo].[HELP_OLD] OFF
