SET IDENTITY_INSERT [dbo].[HELP_OLD] ON 
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1306, N'Источник тепла', N'TN', N't1_4r', N'ТгТемпСетВодВерхСрез', N'Температура воды верхней срезки графика', N'Температура сетевой воды верхней срезки графика', N'"Температура   верхней   срезки   температурного   графика" -  максимально-возможная   температуры  сетевой  воды в подающем  трубопроводе, определяемая ограничением установленной тепловой мощности источника тепла.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1307, N'Источник тепла', N'TN', N'tvb_tr', N'ТгТребТемВоздВнПомещ', N'Требуемая температура воздуха внутри отапл.помещений', N'Требуемая температура воздуха внутри отапливаемых помещений', N'"Требуемая температура  воздуха  внутри помещения" - позволяет задать значение воздуха внутри помещения , если оно отличается от  расчетного  значния ,   регламентируемого    СНиП 2.04.05-91 "Отопление,вентиляция и кондиционирование воздуха", при расчете температурных графиков.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1308, N'Источник тепла', N'TN', N'uf', N'ТгФактКоэфСмеш', N'Фактический коэфф.смещения', N'Фактический коэффициент смещения', N'"Фактический коэффициент смешения" -  коэффициент смешения  элеваторного или насосного смесительного  узла отопительной  системы, полученный в процессе наладочных работ. Коэффициент смешения, определяется из выражений: U=(t1-t3)/(t3-t2),   где  t1, t2, t3 - температура воды при расчетной  температуре наружного воздуха, соответственно, в подающем трубопроводе тепловой сети, в обратном трубопроводе  на  выходе системы отопления,  в подающем трубопроводе системы отопления, Град.С.  Коэффициент смешения, также можно определить из выражения: U=G/Go, где  G, Go-  массовый расход воды ,соответственно,  через смесительную перемычку и на входе системы  отопления (после узла смешения).', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1309, N'Источник тепла', N'TN', N't2_2r', N'ОтСкТемпНижСрезОбрВоды', N'Температура воды нижней срезки обрат.воды', N'Температура сетевой воды нижней срезки обратной воды', N'"Температура  нижней  срезки  обратной воды"-  температура  воды  в  обратном  трубопроводе,поддерживаемая  на  период  пуска  системы  теплоснабжения  от  начала   отопительного  сезона  до   некоторой  заданной   температуры   наружного  воздуха (пуско-наладочный  период). Для   обеспечения   этой температуры   в   обратном   трубопроводе   корректируется  температура   в   подающем   трубопроводе. Для    уточнения температуры наружного  воздуха в конце   пуско-наладочного  периода необходимо выполнить расчет температурного графика  при нулевой температуре нижней срезки и по  температурному 
 графику на экране  определить точное значение  температуры воды  в  обратном  трубопроводе  для  желаемой температуры  наружного возждуха конца пуска- наладочного периода .Затем  полученное  значение  "Температуры  нижней срезки обратной  воды" поместить  в соответствующую  строку экранного  меню  ввода  исходной  информации  и  выполнить повторный расчет  температурного графика. В  последнем температурном  графике  "Температура  нижней   срезки  обратной воды" будет  строго  увязана  со  всеми   исходными  данными  в  рассчитываемом  температурном графике. Рекомендуется при расчете температурных графиков задавать или значение "Температура сетевой воды нижней срезки обратной воды",  или значение "Температура сетевой воды верхней срезки графика (в подающем трубопроводе)", т.е. в одном поле 0, другом значение.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1310, N'Источник тепла', N'TN', N'q_gv', N'СкПвРасчНагоГВ', N'Расчетная  нагрузка в ГВС', N'Расчетная тепловая нагрузка на горячее  водоснабжение', N'"Расчетная тепловая нагрузка на горячее водоснабжение"- при качественном регулировании по совмещенной нагрузке отопления и горячего водоснабжения в качестве расчетной нагрузки на горячее водоснабжение принимается балансовая нагрузка Qбал=n*Qср [Е.Я. Соколов, Теплофикация и тепловые сети], где Qср - средненедельный расход теплоты на бытовое горячее водоснабжение, регламентируемыми  СНиП 2.04.01-85  Внутренний водопровод и канализация зданий, n - поправочный коэффициент для компенсации небаланса теплоты на отопление, ваызываемого неравномерностью суточного графика горячего водоснабжения. При наличии аккумуляторов горячей воды n=0, при отсутствии для жилых зданий ориентировочно n=1.2. Значение поля используется при расчетах повышенного и скорректированного температурных графиков качественного регулирования. Ввиду этого при расчете данных графиков значение величины должно быть >0.', N'Гкал/ч', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1311, N'Источник тепла', N'TN', N'tg_r', N'СкПвТемпГорВоды', N'Темпер.горячей воды в точках водоразбора', N'Температура горячей воды в точках водоразбора', N'"Температура  горячей   воды  в  местах    водоpазбоpа" - pегламентиуется тpебованиями СНиП 2.04.01-85. Внутpенний водопpовод и канализация зданий: не ниже 60 Гpад.С в ГВС,
пpисоединеных    к   откpытым системам    теплоснабжения; не ниже  50  Гpад.С, пpисоединенных  к закpытым системам теплоснабжения.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1312, N'Источник тепла', N'TN', N'tx_r', N'СкПвТемпХолВоды', N'Темпер.холодной  воды', N'Температура холодной воды', N' "Температура холодной  воды" - pасчетная  темпеpатуpа водопpоводной
 воды, поступающая на вход подогревателей ГВС. Обычно в зимний пеpиод пpинимается
 pавной +5°C, а в летний пеpиод - +15°C.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1313, N'Источник тепла', N'TN', N'pr', N'СкПризнВодоразб', N'Признак способа водоразбора горячей воды', N'Признак способа водоразбора горячей воды: c переключением,из подающего, из обратного, из обоих', N'"Признак   способа   водоразбора:  из подающего, из обратного, c переключением, из обоих" - определяет возможность выбора  одного из способов водоразбора сетевой воды в открытой  ГВС:     Водоразбор осуществляется полностью из подающего  трубопровода;    Водоразбор осуществляется  полностью из обратного трубопровода;    Водоразбор  из  подающего  трубопроводов  сети с  переключением    на обратный трубопровод при заданной температуре сетевой воды в    обратном трубопроводе;                                            Автоматизированный   водоразбор  со  смешением  в  смесительном    клапане регулятора температуры воды, подаваемой в сеть ГВС.      Выбор требуемого способа водоразбора осуществляется в выпадающем меню поля .', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1314, N'Источник тепла', N'TN', N't2_gv', N'СкТемрОбрТрубПерекл', N'Темпер.воды в обратном трубопр.для переключения водоразбора', N'Температура воды в обратном трубопроводе для переключения водоразбора', N'"Температура   воды   в  обратном  трубопроводе  для  переключения  водоразбора в  ГВС"-  значение температуры сетевой воды в обратном  трубопроводе,  при   котором   должно  выполняться  переключение  водоразбора из  подающего  на  обратный  трубопровод   в неавтоматизированных  открытых ГВС.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1315, N'Источник тепла', N'TN', N'g1', N'СкКоэфГидрУстПодТруб', N'Коэфф.гидравл.устойчивости под.теплопровода', N'Коэффициент гидравлической устойчивости подающего трубопровода', N'"Коэффициент,характеризующий гидравлическую устойчивость подающего трубопровода"-отношение изменения расхода  воды  в подающем трубопроводе, за счет изменения  водоразбора из этого трубопровода, к разности между фактическим расходом  из подающего трубопровода и расчетным расходом на ГВС. Для реальных сетей c неавтоматизированными потребителями  и  различной гидравлической устойчивостью  значения этого  коэффициента находятся в диапозоне 0.5-0.7.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1316, N'Источник тепла', N'TN', N'g2', N'СкКоэфГидрУстОбрТруб', N'Коэфф.гидравл.устойчивости обр.теплопровода', N'Коэффициент гидравлической устойчивости обратного трубопровода', N'"Коэффициент, характеризующий гидравлическую устойчивость  oбратного трубопровода"-отношение изменения расхода  воды  в подающем трубопроводе, за счет изменения водоразбора  из  обратного  трубопровода,  к  фактическому водоразбору  на  ГВС из этого трубопровода.  Для реальных сетей c неавтоматизированными потребителями  и  различной гидравлической устойчивостью  значения этого  коэффициента находятся в диапазоне 0.2-0.4.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1317, N'Источник тепла', N'TN', N't_gv1', N'ПвНедогр1ступениГВ', N'Величина недогрева в первой ступени подогр. ГВС', N'Величина недогрева в первой ступени подогревателя', N'"Температура недогрева  водопроводной  воды  в  первой  ступени  подогревателя" -  разность  между  температурой  обратной  воды  после системы отопления и температурой водопроводной воды после  первой ступени  подогревателя  ГВС при  "балансовой"   нагрузке  в  системе горячего водоснабжения в точке излома температурного 
 графика.   Обычный диапазон значений 5-10 Град.C.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1318, N'Источник тепла', N'TN', N'tn_2', N'ТгТемпПод2', N'Температура наружного воздуха  в 2-ой характерной точки', N'Температура наружного воздуха  в 2-ой характерной точке графика ( нижней точке срезки графика)', N'Температура наружного воздуха  в 2-ой характерной точке графика ( нижней точке срезки графика) - результирующее значение получаемое в ходе расчета выбранного температурного графика.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1319, N'Источник тепла', N'TN', N'tn_3', N'ТгТемпПод3', N'Температура наружного воздуха  в 3-ой характерной точки', N'Температура наружного воздуха  в 3-ой характерной точке графика (промежуточная точка)', N'Температура наружного воздуха  в 3-ой характерной точке графика (промежуточная точка) - результирующее значение получаемое в ходе расчета выбранного температурного графика.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1320, N'Источник тепла', N'TN', N'tn_4', N'ТгТемпПод4', N'Температура наружного воздуха  в 4-ой характерной точки', N'Температура наружного воздуха  в 4-ой характерной точке графика ( верхней точке срезки графика)', N'Температура наружного воздуха  в 4-ой характерной точке графика ( верхней точке срезки графика) - результирующее значение получаемое в ходе расчета выбранного температурного графика.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1321, N'Источник тепла', N'TN', N'kod_tg', N'КодПолногоГраф', N'Код развернутого температурного графика', N'Код развернутого температурного графика', N'Код развернутого температурного графика - строка в таблице "TG_Развернутый температурный график", хранящей температурный график, рассчитанным по заданным входным данным.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1322, N'Источник тепла', N'TN', N'v', N'СкоростьВетер', N'Скорость ветра', N'Скорость ветра', N'"Скорость ветра"- для систем  с преобладающей  отопительной  нагрузкой  скорость  ветра  более  3 м/с должна учитываться  как  дополнительный  фактор  теплопотерь у потребителей при  расчете температурных графиков качественного регулирования.', N'м/c', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1323, N'Источник тепла', N'TN', N'date_on', N'ДатаИcполнения', N'Дата иcполнения', N'Дата иcполнения', N'"Дата иcполнения" - поля, значение которого предназначено для определения дату расчета температурного графика.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1324, N'Источник тепла', N'TN', N'name_exe', N'Исполнитель', N'Исполнитель', N'Исполнитель', N'"Исполнитель" -  лицо, отстветственное за достоверность входных данных, используемых для расчета температурного графика.', NULL, N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1325, N'Источник тепла', N'UG', N'dt2_co', N'РазностьТ2СОзав_незав', N'Разность обрат.воды при зав.СО и нез.', N'Разница между расч.обратными температурами после  незав. и зависимой СО', N'Разница между расчетными температурами сетевой воды после водоподогревателя системы отопления при независимом её присоединении  и от отопления при зависимом присоединении. Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1326, N'Источник тепла', N'UG', N't2pod_parl', N'Т2подогр_паралГВт.изл', N'Темп.на вых.подогр.паралл.ГВ, т.излома', N'Температура сет. воды в т.изл. темп.графика после подогревателя ГВ, при парал. схеме ГВ', N'Температура сетевой  воды в точке излома температурного графика после подогревателя системы горячего водоснабжения, при параллельном его включении.  Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1327, N'Источник тепла', N'UG', N'dt2v_sm_noavm', N'НедХолВоды1ступСмешНеавт', N'Недогрев водопр.воды в 1ступ.,смеш.ГВ, част.авт.ТП', N'Недогрев водопров.воды до обратной после СО, при частично автомат.смеш. схеме ГВ', N'"Величина недогрева водопроводной воды в первой  ступени смешанной системы горячего водоснабжения до температуры обратной, поступающей из системы отопления (и вентиляции)" - цифровое   поле,  значение    которого определяет разность  между  температурой  обратной  воды после системы отопления и температурой водопроводной воды после первой ступени  подогревателя  ГВС при  "балансовой"   нагрузке в  смешанной системе горячего водоснабжения в точке излома температурного  графика.  При наличии на тепловых пунктах автоматических регуляторов, поддерживающих постоянную температуру воды для горячего водоснабжения величина недогрева обычно принимается равной  5 Град.C. Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1328, N'Источник тепла', N'UG', N'dt2v_sm_avm', N'НедВодВоды1ступСмешАвт', N'Недогрев водопр.воды в 1ступ.,смеш.ГВ, авт.ТП', N'Недогрев водопров.воды до обратной после СО,  при автоматизир. смеш. схеме ГВ', N'"Величина недогрева водопроводной воды в первой  ступени смешанной системы горячего водоснабжения до температуры обратной, поступающей из системы отопления (и вентиляции)" - цифровое   поле,  значение    которого определяет разность  между  температурой  обратной  воды после системы отопления и температурой водопроводной воды после первой ступени  подогревателя  ГВС при  "балансовой"   нагрузке в  смешанной системе горячего водоснабжения в точке излома температурного  графика.  При наличии на тепловых пунктах регуляторов постоянства расхода на систему отопления и  регуляторов, поддерживающих постоянную температуру воды для горячего водоснабжения величина недогрева обычно принимается равной  10 Град.C. Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла задается в  "Установках расчета планового режима".', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1329, N'Источник тепла', N'UG', N't1pod_posll', N'Т2СО_последГВт.изл', N'Темп.на вых.СО,послед.ГВ, т.излома', N'Температура обратной  воды после СО в т.излома темп.графика, при последовательной схеме ГВ', N'"Температура обратной  воды поступающей от системы отопления  в точке излома темпепературного графика, при последовательной схеме включения системы горячего водоснабжения" -  цифровое   поле,  значение    которого определяет температуру обратной воды, поступающей из системы отопления (и вентиляции) в точке излома температурного графика ( t2изл). При температуре воды в подающем теплопроводе тепловой сети в точке излома равной t1изл=150 Град.С  t2изл=41.7 Град.С,  при  t1изл=130 Град.С,  t2изл=44.8 Град.С. Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".(при t1=150 -> 41.7, при t1=130 -> 44.8)', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1330, N'Источник тепла', N'UG', N'dt2v_posl', N'НедХолВоды1ступПослГВ', N'Недогрев водопр.воды в 1ступ.,посл.ГВ', N'Недогрев водопроводной воды до обратной из СО, при последовательной схеме ГВ', N'"Величина недогрева водопроводной воды до температуры обратной, поступающей из системы отопления, при последовательной схеме включения  ГВС в первой ступене подогревателя" - цифровое   поле,  значение    которого определяет разность  между  температурой  обратной  воды после системы отопления и температурой водопроводной воды после первой ступени  подогревателя  ГВС при  "балансовой"   нагрузкев  системе горячего водоснабжения в точке излома температурного  графика.  При наличии на тепловых пунктах автоматических регуляторов, поддерживающих постоянный расход сетевой воды и постоянную температуру воды для горячего водоснабжения величина недогрева обычно принимается равной  5 Град.C.', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1331, N'Источник тепла', N'UG', N't1pod_sm', N'Т2СО_смешГВт.изл', N'Темп.на вых.СО,смеш.ГВ, т.излома', N'Температура обратной  воды после СО в т.излома темп.графика, при смешанной схеме ГВ', N'"Температура обратной  воды поступающей от системы отопления  в точке излома темпепературного графика, при смешанной схеме включения системы горячего водоснабжения" -  цифровое   поле,  значение    которого определяет температуру обратной воды, поступающей из системы отопления (и вентиляции) в точке излома температурного графика.  Значение данной величины используется при расчете удельных расходов сетевой воды на системы теплопотребления абонентских вводов   подключенных к данному источнику тепла и  работающего с данным температурным графиком. Использование удельных расходов, указанных в таблице "Удельные расходы", или рассчитанных для текущего температурного графика источника тепла определяется в  "Установках расчета планового режима".', N'Град.С', N'1')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1332, N'Источник тепла - Источник тепла2', N'IS', N'nomer', N'№', N'Порядковый номер', N'Порядковый номер', N'Порядковый номер экземпляра данного класса. Недопустимая  для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1333, N'Источник тепла - Источник тепла2', N'IS', N'kod_ist', N'Код теплогенерирующей установки', N'Код теплогенерирующей установки', N'Код теплогенерирующей установки источника тепла', N'"Код теплогенерирующей установки источника тепла" - символьное поле, значение которого определяет  наименование теплогенерирующей установки источника тепла. Значение поля используется в объекте Расчетная схема  для определения принадлежности  Расчетной схемы теплогенерирующей установке источника тепла при расчете тепловых потерь и непроизводственных утечек.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1334, N'Источник тепла - Источник тепла2', N'IS', N'nomer_sys', N'НаимСистТепл', N'Наим.сист.теплоснабж.', N'Наименование системы теплоснабжения', N'Наименование теплоснабжающей организации, получающей тепловую энергию от данного источника тепла.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1335, N'Источник тепла - Источник тепла2', N'IS', N'sost', N'СостИст', N'Состояние', N'Состояние теплогенерирующей установки источника тепла', N'"Состояние теплогенерирующей установки источника тепла"- символьное поле, с помощью значения которого,  моделируется отключение подачи тепла от теплогенерирующей установки  источника тепла  в тепловую сеть системы теплоснабжения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1336, N'Источник тепла - Источник тепла2', N'IS', N'kod_p', N'КодРСУзПрис', N'Код  расч.сх.узла присоед.', N'Код  расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения теплогенерирующей установки источника тепла.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1337, N'Источник тепла - Источник тепла2', N'IS', N'uzel_p', N'НаимУзПрис', N'Наим.узла присоед.', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения теплогенерирующей установки источника тепла.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1338, N'Источник тепла - Источник тепла2', N'IS', N'pr_p', N'ПризнТеплУзПрис', N'Призн.теплопр.узла присоед.', N'Признак  теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1339, N'Источник тепла - Источник тепла2', N'IS', N'kod', N'КодРСУзИст', N'Код  расч.сх.узла присоед.источн.', N'Код расчетной схемы узла присоединения', N'  "Код расчетной схемы" - символьное поле, значение  которого однозначно  определяет  расчетную  схему,  которой   принадлежит теплогенерирующая установка источника тепла.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1340, N'Источник тепла - Источник тепла2', N'IS', N'uzel', N'НаимУзИст', N'Наим.узла присоед.источника', N'Наименование узла присоединения', N'"Наименование  узла  присоединения"  -  символьное  поле  , значение которого  однозначно  определяет  имя теплогенерирующей установки источника тепла на данной расчетной схеме".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1341, N'Источник тепла - Источник тепла2', N'IS', N'pr', N'ПризнТеплУзИст', N'Призн.теплопр.узла присоед.источн.', N'Признак теплопровода  узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения. Значение «Общий», означает,  что расчетная схема теплогенерирующей установки источника тепла локализована между подающим и обратным трубопроводами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1342, N'Источник тепла - Источник тепла2', N'IS', N'tip', N'ТипИст', N'Тип', N'Тип источника теплоснабжения', N'"Тип источника теплоснабжения"- символьное поле, с помощью которого определяется локализация совокупности теплогенерирующих установок. Значение "ТЭЦ" - тепловая электростанция, "РК" - районная котельная, "МК" - местная котельная. Значение поля носит информационный характер.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1343, N'Источник тепла - Источник тепла2', N'IS', N'nomer_building', N'СсылкаНаЗдан', N'Здание', N'Порядковый  номер  здания', N'Номер  здания  улицы.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1344, N'Источник тепла - Источник тепла2', N'IS', N'name_building', N'НаимИст', N'Наим.источника', N'Содержательное наименование источника', N'"Содержательное наименование источника" - официальное название источника тепла.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1345, N'Источник тепла - Источник тепла2', N'IS', N'geod_z', N'ГеодОтмМестн', N'Геодезическая отметка местности', N'Геодезическая отметка местности коллектора', N'"Геодезическая отметка коллектора" - цифровое поле, значение которого  определяется  значением   геодезической отметкой  коллекторного узла источника тепла.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1346, N'Источник тепла - Источник тепла2', N'IS', N'n_rasp', N'РасполМощн', N'Распол.мощность', N'Располагаемая тепловая мощность', N'"Располагаемая тепловая мощность теплогенерирующей установки источника" -  цифровое поле,  значение  которого определяет предельно возможную тепловую мощность теплогенерирующей установки источника тепла в системе теплоснабжения.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1347, N'Источник тепла - Источник тепла2', N'IS', N'n_ustan', N'УстанМощн', N'Установл.мощность', N'Установленная мощность', N'«Установленная тепловая мощность теплогенерирующей установки источника» -  цифровое поле,  значение  которого  определяется сумму номинальных тепловых мощностей всего принятого по акту в эксплуатацию оборудования теплогенерирующей установки, предназначенного для отпуска тепла внешним потребителям и на собственные нужды с паром и горячей водой.', N'Тепловая мощность', NULL)

