INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1368, N'Источник тепла - Источник тепла2', N'IS', N'a24', N'УдОбъемСО', N'Удельный  объем  воды  в  системе  отопления', N'Уд.объем воды в системе отопления обобщенного потребителя', N' "Удельный объем воды в системе отопления" - числовое поле, значение которого определяет удельный объем воды в системе отопления в зависимости от расчетного температурного перепада и типа отопительных приборов. Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1369, N'Источник тепла - Источник тепла2', N'IS', N'a25', N'УдОбъемВент', N'Удельный  объем  воды  в  системе  вентиляции', N'Уд.объем воды в системе вентиляции обобщенного потребителя', N'"Удельный объем воды в системе вентиляции" - числовое поле, значение которого определяет удельный объем воды в отопительно-вентиляционной системе, оборудованной калориферами, в зависимости от расчетного температурного перепада. Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1370, N'Источник тепла - Источник тепла2', N'IS', N'memo', N'Комментарий', N'Комментарий', N'Комментарий', N'"Поле комментария" -  символьное поле, содержащее произвольный текст, позволяющий пользователю конкретизировать назначение данных, зафиксировать выполненные изменения в описании расчетной схемы и т.п.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1371, N'Источник тепла - Источник тепла2', N'IS', N'geodz', NULL, N'Геодезическая отметка верха труб', N'Геодезическая отметка верха труб', N'"Геодезическая отметка верха разводящих труб" - цифровое поле, значение которого определяет геодезическую отметку верха разводящих труб в коллекторе источника тепла.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1372, N'Источник тепла - Источник тепла2', N'IS', N't1_leto', N'Тподающая в летниий период', N'Температура воды в подающем трубопроводе в летний период', N'Температура сетевой воды в подающем трубопроводе в летний период', N'"Температура сетевой воды в подающем теплопроводе в летний период"- числовое поле,  значение которого определяет нормативное  значение температуры сетевой воды в подающем теплопроводе тепловой сети в летнем периоде. Значение температуры постоянно для всех температур наружного воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1373, N'Источник тепла - Источник тепла2', N'IS', N't2_leto', N'Тобратная в летниий период', N'Температура воды в обратном трубопроводе в летний период', N'Температура сетевой воды в обратном трубопроводе в летний период', N'"Температура сетевой воды в обратном теплопроводе в летний период"- числовое поле,  значение которого определяет нормативное  значение температуры сетевой воды в обратном теплопроводе тепловой сети в летнем периоде при средней нагрузке горячего водоснабжения. Значение температуры постоянно для всех температур наружного воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1374, N'Источник тепла - Источник тепла2', N'IS', N'begin_year', N'ДатаНачОтопПер', N'Дата начала отоп.периода', N'Дата начала отопительного периода', N'"Дата начала отопительного периода" - поле типа Дата, значение  которого определяет календарную дату начала отопительного периода системы теплоснабжения. Значение  поля используется для определения начала отопительного периода (конца летнего периода) при расчете среднемесячных тепловых потерь.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1375, N'Источник тепла - Источник тепла2', N'IS', N'end_year', N'ДатаОкончОтопПер', N'Дата окончания отоп.периода', N'Дата окончания отопительного периода', N'"Дата окончания отопительного периода" - поле типа Дата, значение  которого определяет календарную дату окончания отопительного периода системы теплоснабжения. Значение  поля используется для определения  конца отопительного периода (начала летнего периода) при расчете среднемесячных тепловых потерь.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1376, N'Источник тепла - Источник тепла2', N'IS', N't1_god_ist', N'Среднегод.температура, под.трубопр.', NULL, N'Среднегод.температура сетевой воды, подающий трубопровод', N'Среднегодовая температура сетевой воды, подающий трубопровод.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1377, N'Источник тепла - Источник тепла2', N'IS', N't2_god_ist', N'Среднегод.температура, обр.трубопр.', NULL, N'Среднегод.температура сетевой воды, обратный трубопровод', N'Среднегодовая температура сетевой воды, обратный трубопровод.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1378, N'Источник тепла - Источник тепла2', N'IS', N'remont_leto', N'Планируемая продолжительность ремонтного периода', N'Планируемая продолжительность ремонтного периода', N'Планируемая продолжительность ремонтного периода', N'"Планируемая продолжительность ремонтного периода"- цифровое поле значение которого определяет количество дней планового ремонта, испытаний. Значение  поля используется  при расчете нормируемых (расчетных) Потерь сетевой воды (ПСВ) связанных с пусковым заполнением  тепловых сетей и местных систем в эксплуатацию после планового ремонта и с подключением новых сетей и систем после монтажа. ПСВ данного типа рекомендуется принимать равным 1.2-1.5 кратному объему тепловых сетей и систем теплопотребления.', NULL, N'дня(ей)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1379, N'Источник тепла - Источник тепла2', N'US', N'nomer', N'№', N'№', N'Номер записи', N'Порядковый номер записи', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1380, N'Источник тепла - Источник тепла2', N'US', N'kod_p', NULL, N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1381, N'Источник тепла - Источник тепла2', N'US', N'uzel_p', NULL, N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1382, N'Источник тепла - Источник тепла2', N'US', N'pr_p', NULL, N'Признак теплопровода  узла присоединения', N'Признак теплопровода  узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1383, N'Источник тепла - Источник тепла2', N'US', N'kod', NULL, N'Код расчетной схемы узла', N'Код расчетной схемы узла', N'"Код расчетной схемы" - символьное поле, значение которого определяет расчетную схему, которой принадлежит узел без нагрузки теплопотребления.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1384, N'Источник тепла - Источник тепла2', N'US', N'uzel', NULL, N'Наим.узла расчетной схемы', N'Наименование узла расчетной схемы', N'"Наименование узла расчетной схемы" - символьное поле, значение которого вместе с кодом расчетной схемы однозначно определяет узел, без нагрузки теплопотребления.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1385, N'Источник тепла - Источник тепла2', N'US', N'pr', NULL, N'Признак теплопров. расчетной схемы', N'Признак теплопровода расчетной схемы', N'"Признак теплопровода расчетной схемы" - символьное поле, значение которого определяет принадлежность узла подающему (значение Подача ) или обратному значение Обратка) теплопроводу.', NULL, NULL)
