INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1533, N'Клапан трехходовой', N'KP', N'A_treb', NULL, N'Требуемый авторитет клапана', N'Требуемый авторитет клапана', N'Авторитет(А+) трехходового клапана равен отношению потерь напора на клапане к потерям напора на клапане и регулируемом участке. Значение авторитета для трехходовых клапанов определяет колебание суммарного расхода через выходной порт клапана (АВ). 10% отклонение мгновенного расхода через порт АВ во время движения штока обеспечивается при следующих значениях авторитета: А+=(0.8-1.0)- для клапана с линейно/линейной характеристикой;  А+=(0.3-0.5)- для клапана с логарифмическо(равнопроцентной)/линейной характеристикой;  А+=(0.1-0.2)- для клапана с логарифмическо/логарифмической характеристикой. Для каждого типа Регулирующего органа существует такой диапазон расходных характеристик (Атреб), в котором клапан будет обеспечивать качественное регулирование: 1) клапаны с линейной пропускной характеристикой следует принимать, задаваясь Атреб > 0.4; 2) для клапанов с равнопроцентной(логарифмической) пропускной характеристикой  0.1< Атреб <0.3; 3) для диапазона 0.3< Атреб <0.4 можно выбирать любую из двух форм пропускной характеристики, так как в этом диапазоне они дают примерно одинаковую нелинейность 4)', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1534, N'Клапан трехходовой', N'KP', N'k_kvs_treb', NULL, N'Отклонение расчетной пропускной способности от требуемой', N'Отклонение расчетной пропускной способности от требуемой', N'Отношение выбираемого kv_s/ kvs_treb', NULL, NULL)
