INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1754, N'Насосный агрегат', N'HC', N'sost', NULL, N'Состояние', N'Состояние', N'"Состояние насосного агрегата" - символьное поле, значение которого однозначно определяет состояние, в котором находится насосный агрегат. Если в поле присутствует значение - "Открыто", то насосный агрегат подключен (находится в работе). Если в поле присутствуют символы - "Закрыто", то насосный агрегат отключен, расход теплоносителя через него отсутствует.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1755, N'Насосный агрегат', N'HC', N'kod_p', NULL, N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1756, N'Насосный агрегат', N'HC', N'uzel_p', NULL, N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1757, N'Насосный агрегат', N'HC', N'pr_p', NULL, N'Признак теплопровода узла просоединения', N'Признак теплопровода узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1758, N'Насосный агрегат', N'HC', N'kod1', NULL, N'Код расчетной схемы начального узла', N'Код расчетной схемы начального узла', N'«Код расчетной схемы начального узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на входе насосного агрегата.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1759, N'Насосный агрегат', N'HC', N'uzel1', NULL, N'Наименование начального узла', N'Наименование начального узла', N'"Наименование начального узла" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения насосного агрегата на теплопроводах тепловой сети и задания направления потока теплоносителя через задвижку.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1760, N'Насосный агрегат', N'HC', N'pr1', NULL, N'Признак теплопровода начального узла', N'Признак теплопровода начального узла', N'"Признак теплопровода начального узла" - символьное поле, значение которого значения "Подача" или "Обратка" используются для указания принадлежности узла на входе задвижки только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1761, N'Насосный агрегат', N'HC', N'kod2', NULL, N'Код расчетной схемы конечного узла', N'Код расчетной схемы конечного узла', N'«Код расчетной схемы конечного узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на выходе насосного агрегата.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1762, N'Насосный агрегат', N'HC', N'uzel2', NULL, N'Наименование конечного узла', N'Наименование конечного узла', N'"Наименование конечного узла" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения насосного агрегата на теплопроводах тепловой сети и задания направления потока теплоносителя через задвижку.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1763, N'Насосный агрегат', N'HC', N'pr2', NULL, N'Признак теплопровода конечного узла', N'Признак теплопровода конечного узла', N'"Признак теплопровода конечного узла" - символьное поле, значение которого значения "Подача" или "Обратка" используются для указания принадлежности узла на выходе насосного агрегата  только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1764, N'Насосный агрегат', N'HC', N'h', NULL, N'Заданный рабочий напор', N'Заданный рабочий напор', N'"Заданный рабочий напор насосного агрегата" - цифровое поле, значение которого представляет собой разность пьезометрических напоров на выходных коллекторах подающего и обратного теплопроводов.Как правило эту информацию можно получить на основании анализа записей показаний манометров, установленных на напорных и выходных коллекторах насосной станции и зафиксированных в журналах на насосных станциях. Пользователь задает таким способом параллельную (идеальную) характеристику насосного агрегата, т.е.напор насосного агрегата не зависит от ее расхода, остальные поля при этом можно не заполнять..', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1765, N'Насосный агрегат', N'HC', N'tip_nas', NULL, N'Тип насосного агрегата', N'Тип насосного агрегата', N'"Тип насосного агрегата" - символьное поле, значение которого характеризует тип установленного насосного агрегата. Рекомендуется использовать функцию записи, с помощью которой определяются одновременно значения полей 4-18 вкладки "Основные"  и все поля вкладки "Коэффициенты аппроксимации" .', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1766, N'Насосный агрегат', N'HC', N'k_nas', NULL, N'Количество параллельно включенных агрегатов в группе', N'Количество параллельно включенных агрегатов в группе', N'"Количество параллельно включенных агрегатов в группе" - цифровое поле, значение которого определяется количеством параллельно включенных насосов при аппроксимации характеристики насосного агрегата. Рекомендуется использовать функцию поля, с помощью которой  одновременно определяются значения полей 4-18 вкладки "Основные"  и все поля вкладки "Коэффициенты аппроксимации" .', NULL, N'штук(и)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1767, N'Насосный агрегат', N'HC', N'pr_privod', NULL, N'Привод', N'Привод', N'"Привод"- символьное поле, значение которого "Нерегулируемый", определяет тип используемого  электропривода. Нерегулируемый электропривод обеспечивает стационарный режим работы насосного агрегата с постоянной частотой вращения рабочего колеса. Регулирование режима работы насосного агрегата обеспечивается с помощью дроссельных регуляторов давления или расхода. Частотно-регулируемый электропривод, значение поля "Частотно-регулируемый", оснащен преобразователем частоты и микропроцессорной системой управления и обеспечивает автоматическое управление режимом работы насосного агрегата в широком диапазоне частоты вращения рабочего колеса.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1768, N'Насосный агрегат', N'HC', N'pr_diametr', NULL, N'Диаметр рабочего колеса', N'Диаметр рабочего колеса', N'"Диаметр рабочего колеса"-  символьное поле, значение которого "Срезанный" определяет способ обработки рабочего колеса, путем обточки с целью уменьшения его диаметра. Применяется с целью получения новых энергетических характеристик насосного агрегата, отличающихся от номинальных в сторону снижения параметров. Рекомендуется использовать функцию поля, с помощью которой  одновременно определяются значения полей 4-18 вкладки "Основные"  и все поля вкладки "Коэффициенты аппроксимации" .', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1769, N'Насосный агрегат', N'HC', N'tip_el', N'ТипЭлДв', N'Тип установленного электродвигателя', N'Тип установленного электродвигателя', N'Тип установленного электродвигателя', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1770, N'Насосный агрегат', N'HC', N'r0', NULL, N'Коэффициент  апроксимации R0 характеристики напора H(G)', N'Коэффициент  апроксимации R0 характеристики напора H(G)', N'"Коэффициент  апроксимации R0 характеристики напора H(G)", есть коэффициент аппроксимации характеристики характеристики насосного агрегата, значение которого используется в модели  характеристики насоса при расчете  потокораспределения. Заполнение поля осуществляется средствами  функции записи, но может быть заполнено пользователем  самостоятельно.', NULL, NULL)
