INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1834, N'Неподвижная опора', N'OP', N'pr1', NULL, N'Признак  теплопровода начального узла', N'Признак  теплопровода начального узла', N'«Признак  теплопровода»   -  символьное   поле,   значение которого  используется  для   указания принадлежности  начального узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» трубопроводам на расчетной схеме. Если  поле имеет значение «Общий», то  это  означает, что узел принадлежит  и подающему и обратному  трубопроводам.   Наличие значения «Общий» в  полях «Признак  теплопровода»  для   начального  и   конечного   узлов свидетельствует  о  том,   что  участок «общий»,  т.е.   его характеристики    одинаковы    для   подающего    и    обратного теплопроводов. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел', NULL, NULL)
