INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1903, N'Объекты с измеряемыми параметрами', N'RP', N'Qo_fakt', N'Фактическая тепловая нагрузка в обр.теплопров.', N'Фактическая  тепловая нагрузка в обратном теплопроводе', N'Фактическая тепловая нагрузка в обратном теплопроводе', N'"Фактическая тепловая нагрузка  в обратном теплопроводе" - цифровое  поле,  значение  которого определяет измеренную тепловую нагрузку  в узле на обратном теплопроводе контролируемого объекта.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1904, N'Объекты с измеряемыми параметрами', N'RP', N'pr', N'ПризнТеплопровКонтрУзла', N'Признак теплопровода узла с контролируемыми параметрами', N'Признак теплопровода узла с контролируемыми параметрами', N'«Признак теплопровода узла с контролируемыми параметрами»   -  символьное   поле,   значение которого  однозначно определяет локализацию расчетной схемы, связанную с узлом с измеренными и контролируемыми параметрами, значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1905, N'Объекты с измеряемыми параметрами', N'RP', N'name_typ', N'Район местонахождения теплопровода', N'Район местонахождения теплопровода с приборами учета', N'Наименование района местонахождения теплопровода, на котором установлены приборы учета', N'"Наименование района местонахождения теплопровода"   -  символьное   поле,   значение которого  однозначно определяет наименование фрагмента расчетной схемы системы теплоснабжения:  Насосной станции, ЦТРП, Контрольной точки местонахождения теплопровода с описываемым прибором учета. В случае для прибора учета, установленном на магистральном теплопроводе Источника тепла, указывается наименование района системы теплоснабжения, в который осуществляется подача тепла посредством данного магистрального теплопровода. Список наименований районов местонахождения теплопроводов с установленными на них приборами учета  представлен в таблице "36_Наименование района местонахождения теплопровода" БД Справочная.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1906, N'Объекты с измеряемыми параметрами', N'RP', N'name_ist', N'Источник тепла', N'Источник тепла', N'Источник теплоты', N'"Источник теплоты" - символьное   поле,   значение которого  однозначно определяет наименование источника тепла системы теплоснабжения, для которого производися контроль параметров теплоносителя на входящих/выходящих магистралях и контроль величины подпиточной воды.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1907, N'Организация', N'OR', N'nomer_owner', N'№', N'Порядковый номер', N'Порядковый номер', N'Порядковый номер экземпляра данного класса. Недопустимая  для редактирования пользователем величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1908, N'Организация', N'OR', N'name', N'Наименование', N'Наименование', N'Наименование', N'"Наименование" - символьное пое, значение которого определяет наименование организации несущей ответственность при эксплуатации и техническом обслуживании объекта системы теплоснабжения. Значение данного поля используется при заполнении значений полей "Балансовая принадлежность" объектов тепловой сети и систем теплопотребления. Организации делятся на "Энергоснабжающие" и "Другие". Тепловые сети Других организаций классифицируются на "С прибором учета", "Без прибора учета", "Между границами", смотри значение поля "Признак организации".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1909, N'Организация', N'OR', N'phone', N'Телефон', N'Телефон', N'Телефон', N'Контактный телефон', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1910, N'Организация', N'OR', N'street', N'Улица', N'Улица', N'Улица', N'Наименование улица местонахождения центрального органа управления предприятия/организации', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1911, N'Организация', N'OR', N'house_numer', N'Номер дома', N'Номер дома', N'Номер дома', N'Номер дома местонахождения центрального органа управления предприятия/организации', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1912, N'Организация', N'OR', N'tip_owner', N'Категория', N'Категория', N'Категория', N'"Категория" - символьное поле, используемое для разбиения объектов тепловой сети по принадлежности. Значение поле может принимать значения "Энергоснабжающая", "С прибором учета", "Без прибора учета", "Между границами". Значение "Энергоснабжающая" -  обозначает, что  объекты, принадлежащие данной организации,  находятся на балансе энергоснабжающей организации, значения "С прибором учета", "Без прибора учета", "Между границами" - обозначают, что организация не является энергоснабжающающей  организацией и  объекты, принадлежащие данной организации, не находятся на балансе энергоснабжающей организации. Значение "С прибором учета" означает, что объекты тепловой сети расположены за прибором учета расхода сетевой воды, "Без прибора учета" - означает, что прибор учета отсутствует, "Между границами" - означает, что объекты тепловой сети, принадлежащие данной организации,  расположены между границей раздела и прибором учета. .', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1913, N'Организация', N'OR', N'phone_boss', N'ТелРуков', N'Телефон ответсвенного', N'Телефон руководителя/ответсвенного   предприятия/организации', N'Телефон руководителя/ответственного   предприятия/организации', NULL, NULL)
