INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1915, N'Организация', N'OR', N'kod_p_gran', NULL, N'Код расчетной схемы узла присоединения  узла границы раздела', N'Код расчетной схемы узла присоединения  узла границы раздела', N'«Код расчетной схемы узла присоединения границы раздела» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения границы раздела', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1916, N'Организация', N'OR', N'uzel_p_gran', NULL, N'Наименование узла присоединения  узла границы раздела', N'Наименование узла присоединения  узла границы раздела', N'«Наименование узла присоединения границы раздела» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения границы раздела.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1917, N'Организация', N'OR', N'pr_p_gran', NULL, N'Признак теплопровода  узла  присоединения  узла границы раздела', N'Признак теплопровода  узла  присоединения  узла границы раздела', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами. Признак теплопровода  узла  присоединения  узла границы раздела', NULL, NULL)

