INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1928, N'Потребитель обобщенный', N'РО', N'sost', NULL, N'Состояние потребителя', N'Состояние потребителя', N' "Состояние потребителя"- символьное поле, значение которого "Закрыто" - закрыт(отключен) или "Открыто"- открыт(подключен) позволяет пользователю, не удаляя объект тепловой сети  убрать нагрузку теплопотребления из данного узла расчетной схемы (значение "Закрыто") или вновь ее назначить("Открыто").', NULL, NULL)
