INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1932, N'Потребитель обобщенный', N'РО', N'kod', NULL, N'Код  расчетной схемы узла обобщенного  потребителя', N'Код  расчетной схемы узла присоединения', N'"Код расчетной схемы" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит обобщенный потребитель. Рекомендуется при заполнении поля использовать функцию поля (выбор расчетной схемы из списка описанных).', NULL, NULL)
