INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1934, N'Потребитель обобщенный', N'РО', N'pr', NULL, N'Признак теплопровода узла присоединения обобщенного  потребителя', N'Признак теплопровода узла присоединения обобщенного  потребителя', N'Признак теплопровода узла присоединения обобщенного  потребителя', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1935, N'Потребитель обобщенный', N'РО', N'name_building', NULL, N'Содержательное наименование обобщенного потребителя', N'Содержательное наименование', N'"Содержательное  наименование  обобщенного потребителя"  -   символьное поле,   значение   которого   определяет наименование магистрального фрагмента сетей, представленного данным обобщенным потребителем. Например, "КРП на ул.Гоголя", "мкр.Степной 1". Заполнение поля желательно.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1936, N'Потребитель обобщенный', N'РО', N'h', NULL, N'Наибольшая высота здания', N'Наибольшая высота здания', N'Наибольшая высота здания', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1937, N'Потребитель обобщенный', N'РО', N'geodz', N'Геодезическая отметка низа труб', N'Геодезическая отметка верха труб', N'Геодезическая отметка верха труб', N'"Геодезическая отметка низа труб в камере присоединения" - цифровое поле, значение которого определяет геодезическую отметку верха труб в камере присоединения ответветвления обобщенной нагрузки.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1938, N'Потребитель обобщенный', N'РО', N'kodur', NULL, N'Код удельных расходов тепло/вода, для расчетного режима', N'Код удельных расходов тепло/вода', N'"Код  удельных  расходов  т/в"  -символьное  поле, значение которого однозначно определяет группу удельных расходов по  всем видам теплопотребления, заданным в объекте "Удельные расходы", и предназначенных для пересчета нагрузок по всем видам теплопотребления из  единиц теплового  потока  (Гкал/ч)  в  единицы массового расхода (т/ч). Наличие непустого  значения в  этом поле  свидетельствует о том, что  в  этом  объектах  "Реальный потребитель" и "Обобщеный потребитель"   могут  быть  приведены  нагрузки  по отдельным  видам  теплопотребления,  представленные  в  единицах теплового  потока  (Гкал/ч),  а  соответствующие им расходы воды (т/ч) могут быть  вычисленны автоматически и  использованны при расчете  плановых теплогидравлических  режимов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1939, N'Потребитель обобщенный', N'РО', N'kodkv', NULL, N'Код группы коэффициентов вариации', N'Код группы коэффициентов вариации', N'"Код  группы  коэффициентов  вариации"  - свойство, значение  которого  однозначно  определяет группу коэффициентов вариации  значений   исходных  данных,   определяющих   вариант теплогидравлического режима тепловой сети.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1940, N'Потребитель обобщенный', N'РО', N'otopl_zco', NULL, N'Расчетная тепловая нагрузка на  отопление, зависимая СО', N'Расчетная тепловая нагрузка на  отопление', N' "Расчетная тепловая  нагрузка на  отопление,  зависимая схема"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузкок на  отопление  по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с зависимым подключением системы отопления.  Расчетная тепловая  нагрузка на  отопление реального потребителя принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по зависимой    схеме    или   назначается   пользователем,  исходя из   определенных   целей   расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1941, N'Потребитель обобщенный', N'РО', N'otopl_tp_zco', NULL, N'Расчетные внутренние тепловыделения, зависимая СО', N'Расчетные внутренние тепловыделения', N'"Расчетные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с зависимым подключением системы отопления.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1942, N'Потребитель обобщенный', N'РО', N'Tr_tv_co_zco', NULL, N'Расчетная температура в отапливаемых помещениях, зависимая СО', N'Расчетная температура воздуха в отапливаемых помещениях', N'"Расчетная температура воздуха в отапливаемых помещений" - определяется как средняя величина значений Расчетных температур воздуха в отапливаемых помещений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с зависимым подключением системы отопления. Расчетная температура воздуха в отапливаемых помещений  реального потребителя определяется  значением   температуры  воздуха  в отапливаемых  помещениях,  исходя из норм допустимых комфотных условий по СНиП 2.04.05-91.  Отопление, вентиляция и кондициониpование воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1943, N'Потребитель обобщенный', N'РО', N'cx_zco', NULL, N'Схема присоединения зависимой СО', N'Схема присоединения СО', N'"Схема присоединения зависимой системы отопление" - символьное поле, значение которого определяет схему присоединения по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с зависимым подключением системы отопления, значение "элеваторное"означает, что более 50% подключены через элеваторный  узел смешения, значение "безэлеваторное"означает, что более 50%  подключены без узла смешения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1944, N'Потребитель обобщенный', N'РО', N'uf_zco', NULL, N'Фактический коэффициент смешения, зависимая СО', N'Фактический коэффициент смешения', N'"Фактический коэффициент смешения элеватора" - цифровое поле, значение которого определяет доминирующее значение коэффициента смешения по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с зависимым элеваторным подключением системы отопления. Значение коэффициент смешения элеватора у реального потребителя однозначно определяется температурным графиком сетевой воды, установленным для системы отопления потребителя. Как известно, коэффициент смешения элеватора U определяется с помощью следующих выражений: 1. U=Gп/Gс, где Gп - массовый расход подмешиваемой воды, т/ч; Gс - массовый расход воды, потребляемой из сети на систему отопления потребителя, т/ч; 2. U=(t1-t3)/(t3-t2), где t1, t2 - соответственно, температура сетевой воды в подающем и обратном трубопроводах теплового пункта реального потребителя; t3 - температура смешанной воды, поступающей в систему отопления потребителя. Например, для температурного графика сетевой воды 150-70 Град.С и графика - подмешанной воды 95-70 Град.С коэффициент смешения принимается равным U=2.2. Это значение принимается в качестве исходного значения этого свойства по умолчанию.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1945, N'Потребитель обобщенный', N'РО', N'otopl_nco', NULL, N'Расчетная тепловая нагрузка на  отопление, независимая СО', N'Расчетная тепловая нагрузка на  отопление', N' "Расчетная тепловая  нагрузка на  отопление,  независимая схема"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с независимым подключением системы отопления через водо-водянные подогреватели.  Расчетная тепловая  нагрузка на  отопление реального потребителя принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по независимой    схеме    или   назначается   пользователем,  исходя из   определенных   целей   расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1946, N'Потребитель обобщенный', N'РО', N'otopl_tp_nco', NULL, N'Расчетные внутренние тепловыделения, независимая СО', N'Расчетные внутренние тепловыделения', N'"Расчетные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с независимым подключением системы отопления  через водо-водянные подогреватели.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1947, N'Потребитель обобщенный', N'РО', N'Tr_tv_co_nco', NULL, N'Расчетная температура в отапливаемых помещениях, независимая СО', N'Расчетная температура воздуха в отапливаемых помещениях', N'"Расчетная температура воздуха в отапливаемых помещений" - определяется как средняя величина значений Расчетных температур воздуха в отапливаемых помещений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с независимым подключением системы отопления  через водо-водянные подогреватели. Расчетная температура воздуха в отапливаемых помещений  реального потребителя определяется  значением   температуры  воздуха  в отапливаемых  помещениях,  исходя из норм допустимых комфотных условий по CНиП II-33.  Отопление, вентиляция и кондициониpование воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1948, N'Потребитель обобщенный', N'РО', N'uf_nco', NULL, N'Фактический коэффициент смешения, независимая СО', N'Фактический коэффициент смешения', N'"Фактический коэффициент смешения элеватора" - цифровое поле, значение которого определяет доминирующий коэффициент смешения по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с независимым элеваторным подключением системы отопления. Значение коэффициент смешения элеватора у реального потребителя однозначно определяется температурным графиком сетевой воды, установленным для местной системы отопления потребителя. Как известно, коэффициент смешения элеватора U определяется с помощью следующих выражений: 1. U=Gп/Gс, где Gп - массовый расход подмешиваемой воды, т/ч; Gс - массовый расход воды, потребляемой из сети на систему отопления потребителя, т/ч; 2. U=(t1-t3)/(t3-t2), где t1, t2 - соответственно, температура сетевой воды в подающем и обратном трубопроводах теплового пункта реального потребителя; t3 - температура смешанной воды, поступающей в систему отопления потребителя. Например, для температурного графика сетевой воды 140-70 Град.С и графика - подмешанной воды 95-70 Град.С коэффициент смешения принимается равным U=2.8.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1949, N'Потребитель обобщенный', N'РО', N'ventil_cv', NULL, N'Расчетная тепловая нагрузка  на вентиляцию', N'Расчетная тепловая нагрузка  на вентиляцию', N'"Расчетная тепловая  нагрузка на вентиляцию"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузок на  вентиляцию   группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Расчетная тепловая  нагрузка реального потребителя принимается по типовым или индивидуальным    проектам потребителей или назначается пользователем, исходя из  определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1950, N'Потребитель обобщенный', N'РО', N'dolja_vent_cv', NULL, N'Доля расхода сетевой воды  через КУ от расчётного, при отключеннии её  по воздуху', N'Доля расхода сет.воды  через КУ от расчётного, при откл.её  по воздуху', N'"Доля расхода сетевой воды через КУ от расчетного, при отключении её по воздуху" - цифровое поле, значение которого определяет доминирующее значение доли расхода сетевой воды через КУ, при отключении её по воздуху по группе реальных потребителей с нагрузкой вентиляции или воздушного отопления, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Доля расхода сетевой воды через КУ, при отключении её по воздуху у реального потребителя    принимается   по   типовым    или индивидуальным    проектам    потребителей    или    назначается пользователем, исходя из  определенных целей расчета.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1951, N'Потребитель обобщенный', N'РО', N'Tr_tv_cv', NULL, N'Расч.темп. нагретого воздуха  в системе вентиляции или возд.отопления', N'Расчетная температура нагретого воздуха', N'"Расчетная температура нагретого воздуха  в системе вентиляции или воздушного  отопления " - определяется как средняя величина значений Расчетных температур нагретого воздуха в системе вентиляции или воздушного  отопления по группе реальных потребителей с нагрузкой вентиляции или воздушного  отопления, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Расчетная температура нагретого воздуха в системе вентиляции или воздушного  отопления реального потребителя определяется  значением   температуры  воздуха  в отапливаемых  помещениях,  исходя из норм допустимых комфотных условий по CНиП II-33.  Отопление, вентиляция и кондициониpование воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1952, N'Потребитель обобщенный', N'РО', N'otopl_pr', NULL, N'Расчетная тепловая нагрузка на  отопление парал.ГВС', N'Расчетная тепловая нагрузка на отопление', N'"Расчетная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с параллельной схемой включения подогревателей горячего водоснабжения.  Расчетная тепловая  нагрузка на  отопление реального потребителя принимается по типовым или  индивидуальным  проектам потребителей или назначается пользователем,  исходя из определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1953, N'Потребитель обобщенный', N'РО', N'otopl_tp_pr', NULL, N'Внутренние тепловыделения, парал.ГВС', N'Внутренние тепловыделения', N'"Расчетные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе  с параллельной схемой включения подогревателей горячего водоснабжения.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1954, N'Потребитель обобщенный', N'РО', N'cx_co_pr', NULL, N'Схема присоединения  СО, при парал.ГВС', N'Схема присоединения СО', N'"Схема присоединения зависимой системы отопление" - символьное поле, значение которого определяет схему присоединения системы отопления по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с параллельным подключением подогревателей горячего водоснабжения, значение "элеваторное"означает, что у наибольшего процента реальных потребителей группы система отопления подключена по зависимой схеме с элеваторным узлом смешения, "безэлеваторное" -  система отопления подключена по зависимой схеме без узла смешения,  "независимое" - система отопления подключена по независимой схеме через водо-водянные подогреватели.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1955, N'Потребитель обобщенный', N'РО', N'gv_pr', NULL, N'Средняя тепловая нагрузка на ГВС, парал.сх.', N'Средняя тепловая нагрузка на ГВС', N'"Среднечасовая  тепловая   нагрузка горячего водоснабжения   потребителя"   -  цифровое поле, значение которого определяется как сумма  значений среднечасовых  тепловых   нагрузок  горячего водоснабжения группы реальных потребителей с паралелльномым включением подогревателей  горячего водоснабжения,  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Среднечасовая  тепловая   нагрузка горячего водоснабжения   реального потребителя соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1956, N'Потребитель обобщенный', N'РО', N'gvs_max_pr', NULL, N'Коэф. часовой неравномерности нагрузки парал.ГВС', N'Коэффициент часовой неравномерности нагрузки ГВС', N'"Коэффициент часовой неравномерности нагрузки горячего водоснабжения" - цифровое поле, значение которого определяет доминирующий коэффициент часовой неравномерности (kч) расхода тепла за сутки наибольшего водопотребления у группы реальных потребителей с паралелльномым включением подогревателей  горячего водоснабжения и  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Значение этого свойства используется при расчете максимального расхода тепла на горячее водоснабжение жилых зданий, гостиниц, больниц и т.д.: Qгвс_макс=kч*Qгвс_средн.  При определении расхода тепла на горячее  водоснабжение микрорайонов (кварталов) городов kч= 1.7 - 2.2, промышленных предприятий kч= 1. При отсутствии данных о назначении общественных зданий допускается определении коэффициента часовой неравномерности условное количество жителей принимать с коэффициентом 1.2.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1957, N'Потребитель обобщенный', N'РО', N'rez_pr', NULL, N'Расчетная тепловая нагрузка на компенсацию тепловых потерь в трубопр. цирк-ой ГВС, парал.сх.', N'Расчетная тепл.нагрузка на компенсацию тепл.потерь в цирк.труб.ГВС', N'"Тепловая  нагрузка   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС"  -  цифровое поле, значение которого определяется как сумма тепловых  нагрузок   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с параллельной схемой включения подогревателей горячего водоснабжения. Значение тепловой  нагрузки   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС реального потребителя определяется  долей от среднечасовой  нагрузки ГВ, т.е.   Qц=Qср*К, где  К=0.1-0.3. Наиболее  часто в  практике проектирования ГВС используют 20-ти процентную долю, т.е. К=0.2. Значение  поля  используется при расчете теплогидравлических режимов тепловых пунктов только с открытой  ГВС  циркуляционного  типа. Значение   поля   имеет  процентную  размерность и вводится, например, в виде целочисленной  константы  20 (при 20%-ых потерях).', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1958, N'Потребитель обобщенный', N'РО', N'Tr_tv_co_pr', NULL, N'Расчетная температура в отапливаемых помещениях, парал.ГВС', N'Расчетная температура воздуха в отапливаемых помещениях', N'"Расчетная температура воздуха в отапливаемых помещений" - цифровое поле, определяется как средняя величина значений Расчетных температур воздуха в отапливаемых помещений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с параллельной схемой включения подогревателей горячего водоснабжения. Расчетная температура воздуха в отапливаемых помещений реального потребителя определяется значением температуры воздуха в отапливаемых помещениях, исходя из норм допустимых комфотных условий по CНиП II-33-75. Отопление, вентиляция и кондициониpование воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1959, N'Потребитель обобщенный', N'РО', N'Tr_gvs_pr', NULL, N'Расчетная температура горячей воды в местах водоразбора, парал.ГВС', N'Расчетная температура горячей воды в местах водоразбора', N'"Расчетная температура горячей воды " -  числовое поле, определяется как средняя величина значений Расчетных температур горячей воды в  местах водоразбора по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с параллельной схемой включения подогревателей горячего водоснабжения. Расчетная температура горячей воды в местах водоразбора реального потребителя определяет температуру бытовой горячей воды по выходу ее из подогревательных установок, нижнее и верхнее значение которой pегламентиуется тpебованиями СНиП 2.04.01-85: не ниже 60 Гpад.С в ГВС,пpисоединеных    к   откpытым системам    теплоснабжения; не ниже  50  Гpад.С , пpисоединенных  к закpытым системам теплоснабжения и не выше 75 Град.С для всех вышерассмотренных случаев. Для уменьшения циркуляционной воды температуру бытовой воды по выходе ее из подогревательных установок рекомендуется принимать равной в закрытых системах 50+10=60 Град.С, в открытых 60+5= 65 Град.С. Где 5-10 охлаждение циркуляционной воды в водоразборных стояках  многоэтажных зданий по системе в целом.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1960, N'Потребитель обобщенный', N'РО', N'uf_zco_pr', NULL, N'Фактический коэффициент смешения,зав.СО,  парал.ГВС', N'Фактический коэффициент смешения СО', N'"Фактический коэффициент смешения элеватора" - цифровое поле, определяет доминирующий фактический коэффициет смешения по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с зависимым элеваторным подключением системы отопления и параллельным включением подогревателей горячего водоснабжения. Фактическое значение коэффициент смешения элеватора у реального потребителя однозначно определяется температурным графиком сетевой воды, установленным для системы отопления потребителя. Как известно, коэффициент смешения элеватора U определяется с помощью следующих выражений: 1. U=Gп/Gс, где Gп - массовый расход подмешиваемой воды, т/ч; Gс - массовый расход воды, потребляемой из сети на систему отопления потребителя, т/ч; 2. U=(t1-t3)/(t3-t2), где t1, t2 - соответственно, температура сетевой воды в подающем и обратном трубопроводах теплового пункта реального потребителя; t3 - температура смешанной воды, поступающей в систему отопления потребителя. Например, для температурного графика сетевой воды 150-70 Град.С и графика - подмешанной воды 90-70 Град.С коэффициент смешения принимается равным U=2.2. Это значение принимается в качестве исходного значения этого свойства по умолчанию.', NULL, NULL)

