INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1961, N'Потребитель обобщенный', N'РО', N'otopl_sm', NULL, N'Расчетная тепловая нагрузка на  отопление, смеш.ГВС', N'Расчетная тепловая нагрузка на  отопление', N'"Расчетная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе со смешанной схемой включения подогревателей горячего водоснабжения.  Расчетная тепловая  нагрузка на  отопление реального потребителя принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по независимой    схеме    или   назначается   пользователем,  исходя из   определенных   целей   расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1962, N'Потребитель обобщенный', N'РО', N'otopl_tp_sm', NULL, N'Внутренние тепловыделения,смеш.ГВС', N'Внутренние тепловыделения', N'"Расчетные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе  со смешанной схемой включения подогревателей горячего водоснабжения.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1963, N'Потребитель обобщенный', N'РО', N'gv_sm', NULL, N'Средняя  тепловая нагрузка на ГВС, смеш.', N'Средняя тепловая нагрузка на ГВС.', N'"Среднечасовая  тепловая   нагрузка горячего водоснабжения   потребителя"   -  цифровое поле, значение которого определяется как сумма  значений среднечасовых  тепловых   нагрузок  горячего водоснабжения группы реальных потребителей со смешанным включением подогревателей  горячего водоснабжения,  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Среднечасовая  тепловая   нагрузка горячего водоснабжения   реального потребителя соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1964, N'Потребитель обобщенный', N'РО', N'gvs_max_sm', NULL, N'Коэф. часовой неравномерности нагрузки, смеш.ГВС', N'Коэффициент часовой неравномерности нагрузки ГВС', N'"Коэффициент часовой неравномерности нагрузки горячего водоснабжения" - цифровое поле, значение которого определяет доминирующий коэффициент часовой неравномерности (kч) расхода тепла за сутки наибольшего водопотребления у группы реальных потребителей со смешанным  включением подогревателей  горячего водоснабжения и  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Значение этого свойства используется при расчете максимального расхода тепла на горячее водоснабжение жилых зданий, гостиниц, больниц и т.д.: Qгвс_макс=kч*Qгвс_средн.  При определении расхода тепла на горячее  водоснабжение микрорайонов (кварталов) городов kч= 1.7 - 2.2, промышленных предприятий kч= 1. При отсутствии данных о назначении общественных зданий допускается определении коэффициента часовой неравномерности условное количество жителей принимать с коэффициентом 1.2.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1965, N'Потребитель обобщенный', N'РО', N'rez_sm', NULL, N'Расчетная тепловая нагрузка на компенсацию тепловых потерь в трубопр. цирк-ой ГВС, смеш.сх.', N'Расчетная тепл.нагрузка на компенсацию тепл.потерь в цирк.труб.ГВС', N'"Тепловая  нагрузка   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС"  -  цифровое поле, значение которого определяется как сумма тепловых  нагрузок   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе со смешанной схемой включения подогревателей горячего водоснабжения. Значение тепловой  нагрузки   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС реального потребителя определяется  долей от среднечасовой  нагрузки ГВ, т.е.   Qц=Qср*К, где  К=0.1-0.3. Наиболее  часто в  практике проектирования ГВС используют 20-ти процентную долю, т.е. К=0.2. Значение  поля  используется при расчете теплогидравлических режимов тепловых пунктов только с открытой  ГВС  циркуляционного  типа. Значение   поля   имеет  процентную  размерность и вводится, например, в виде целочисленной  константы  20 (при 20%-ых потерях).', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1966, N'Потребитель обобщенный', N'РО', N'Tr_tv_co_sm', NULL, N'Расчетная температура в отапливаемых помещениях, смеш.ГВС', N'Расчетная температура воздуха  в отапливаемых помещениях', N'"Расчетная температура воздуха в отапливаемых помещений" - цифровое поле, определяется как средняя величина значений Расчетных температур воздуха в отапливаемых помещений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе со смешанной схемой включения подогревателей горячего водоснабжения. Расчетная температура воздуха в отапливаемых помещений реального потребителя определяется значением температуры воздуха в отапливаемых помещениях, исходя из норм допустимых комфотных условий по CНиП II-33-75. Отопление, вентиляция и кондициониpование воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1967, N'Потребитель обобщенный', N'РО', N'Tr_gvs_sm', NULL, N'Расчетная температура горячей воды в местах водоразбора, смеш.ГВС', N'Расчетная температура горячей воды в местах водоразбора', N'"Расчетная температура горячей воды " -  числовое поле, определяется как средняя величина значений Расчетных температур горячей воды в  местах водоразбора по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе со смешанной схемой включения подогревателей горячего водоснабжения. Расчетная температура горячей воды в местах водоразбора реального потребителя определяет температуру бытовой горячей воды по выходу ее из подогревательных установок, нижнее и верхнее значение которой pегламентиуется тpебованиями СНиП 2.04.01-85: не ниже 60 Гpад.С в ГВС,пpисоединеных    к   откpытым системам    теплоснабжения; не ниже  50  Гpад.С , пpисоединенных  к закpытым системам теплоснабжения и не выше 75 Град.С для всех вышерассмотренных случаев. Для уменьшения циркуляционной воды температуру бытовой воды по выходе ее из подогревательных установок рекомендуется принимать равной в закрытых системах 50+10=60 Град.С, в открытых 60+5= 65 Град.С. Где 5-10 охлаждение циркуляционной воды в водоразборных стояках  многоэтажных зданий по системе в целом.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1968, N'Потребитель обобщенный', N'РО', N'uf_zco_sm', NULL, N'Фактический коэффициент смешения,зав.СО, смеш.ГВС', N'Фактический коэффициент смешения зависимой СО', N'"Фактический коэффициент смешения элеватора" - цифровое поле, определяет доминирующий фактический коэффициет смешения по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с зависимым элеваторным подключением системы отопления и смешанным включением подогревателей горячего водоснабжения. Фактическое значение коэффициент смешения элеватора у реального потребителя однозначно определяется температурным графиком сетевой воды, установленным для системы отопления потребителя. Как известно, коэффициент смешения элеватора U определяется с помощью следующих выражений: 1. U=Gп/Gс, где Gп - массовый расход подмешиваемой воды, т/ч; Gс - массовый расход воды, потребляемой из сети на систему отопления потребителя, т/ч; 2. U=(t1-t3)/(t3-t2), где t1, t2 - соответственно, температура сетевой воды в подающем и обратном трубопроводах теплового пункта реального потребителя; t3 - температура смешанной воды, поступающей в систему отопления потребителя. Например, для температурного графика сетевой воды 150-70 Град.С и графика - подмешанной воды 90-70 Град.С коэффициент смешения принимается равным U=2.2. Это значение принимается в качестве исходного значения этого свойства по умолчанию.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1969, N'Потребитель обобщенный', N'РО', N'otopl_ps', NULL, N'Расчетная тепловая нагрузка на  отопление, посл.ГВС', N'Расчетная тепловая нагрузка на  отопление', N'"Расчетная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с последовательной схемой включения подогревателей горячего водоснабжения.  Расчетная тепловая  нагрузка на  отопление реального потребителя принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по последовательной  схеме ГВ  или   назначается   пользователем,  исходя из   определенных   целей   расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1970, N'Потребитель обобщенный', N'РО', N'otopl_tp_ps', NULL, N'Внутренние тепловыделения,посл.ГВС', N'Внутренние тепловыделения', N'"Расчетные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе  с последовательной схемой включения подогревателей горячего водоснабжения.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1971, N'Потребитель обобщенный', N'РО', N'gv_ps', NULL, N'Средняя тепловая нагрузка на ГВС,посл. ГВС', N'Средняя тепловая нагрузка на ГВС', N'"Среднечасовая  тепловая   нагрузка горячего водоснабжения   потребителя"   -  цифровое поле, значение которого определяется как сумма  значений среднечасовых  тепловых   нагрузок  горячего водоснабжения группы реальных потребителей с последовательным включением подогревателей  горячего водоснабжения,  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Среднечасовая  тепловая   нагрузка горячего водоснабжения   реального потребителя соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1972, N'Потребитель обобщенный', N'РО', N'gvs_max_ps', NULL, N'Коэф. часовой неравномерности, посл.ГВС', N'Коэффициент часовой неравномерности нагрузки ГВС', N'"Коэффициент часовой неравномерности нагрузки горячего водоснабжения" - цифровое поле, значение которого определяет доминирующий коэффициент часовой неравномерности (kч) расхода тепла за сутки наибольшего водопотребления у группы реальных потребителей с последовательным включением подогревателей  горячего водоснабжения и  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Значение этого свойства используется при расчете максимального расхода тепла на горячее водоснабжение жилых зданий, гостиниц, больниц и т.д.: Qгвс_макс=kч*Qгвс_средн.  При определении расхода тепла на горячее  водоснабжение микрорайонов (кварталов) городов kч= 1.7 - 2.2, промышленных предприятий kч= 1. При отсутствии данных о назначении общественных зданий допускается определении коэффициента часовой неравномерности условное количество жителей принимать с коэффициентом 1.2.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1973, N'Потребитель обобщенный', N'РО', N'rez_ps', NULL, N'Расчетная тепловая нагрузка на компенсацию тепловых потерь в трубопр. цирк-ой ГВС, посл.сх.', N'Расчетная тепл.нагрузка на компенсацию тепл.потерь в цирк.труб.ГВС', N'"Тепловая  нагрузка   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС"  -  цифровое поле, значение которого определяется как сумма тепловых  нагрузок   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с последовательной схемой включения подогревателей горячего водоснабжения. Значение тепловой  нагрузки   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС реального потребителя определяется  долей от среднечасовой  нагрузки ГВ, т.е.   Qц=Qср*К, где  К=0.1-0.3. Наиболее  часто в  практике проектирования ГВС используют 20-ти процентную долю, т.е. К=0.2. Значение  поля  используется при расчете теплогидравлических режимов тепловых пунктов только с открытой  ГВС  циркуляционного  типа. Значение   поля   имеет  процентную  размерность и вводится, например, в виде целочисленной  константы  20 (при 20%-ых потерях).', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1974, N'Потребитель обобщенный', N'РО', N'Tr_tv_co_ps', NULL, N'Расчетная температура в отапливаемых помещениях, посл.ГВС', N'Расчетная температура воздуха в отапливаемых помещениях', N'"Расчетная температура воздуха в отапливаемых помещений" - цифровое поле, определяется как средняя величина значений Расчетных температур воздуха в отапливаемых помещений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с последовательной схемой включения подогревателей горячего водоснабжения. Расчетная температура воздуха в отапливаемых помещений реального потребителя определяется значением температуры воздуха в отапливаемых помещениях, исходя из норм допустимых комфотных условий по CНиП II-33-75. Отопление, вентиляция и кондициониpование воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1975, N'Потребитель обобщенный', N'РО', N'Tr_gvs_ps', NULL, N'Расчетная температура горячей воды в местах водоразбора, посл.ГВС', N'Расчетная температура горячей воды в местах водоразбора', N'"Расчетная температура горячей воды " -  числовое поле, определяется как средняя величина значений Расчетных температур горячей воды в  местах водоразбора по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с последовательной схемой включения подогревателей горячего водоснабжения. Расчетная температура горячей воды в местах водоразбора реального потребителя определяет температуру бытовой горячей воды по выходу ее из подогревательных установок, нижнее и верхнее значение которой pегламентиуется тpебованиями СНиП 2.04.01-85: не ниже 60 Гpад.С в ГВС,пpисоединеных    к   откpытым системам    теплоснабжения; не ниже  50  Гpад.С , пpисоединенных  к закpытым системам теплоснабжения и не выше 75 Град.С для всех вышерассмотренных случаев. Для уменьшения циркуляционной воды температуру бытовой воды по выходе ее из подогревательных установок рекомендуется принимать равной в закрытых системах 50+10=60 Град.С, в открытых 60+5= 65 Град.С. Где 5-10 охлаждение циркуляционной воды в водоразборных стояках  многоэтажных зданий по системе в целом.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1976, N'Потребитель обобщенный', N'РО', N'uf_zco_ps', NULL, N'Фактический коэффициент смешения,зав.СО,посл.ГВС', N'Фактический коэффициент смешения зависимой СО', N'"Фактический коэффициент смешения элеватора" - цифровое поле, определяет доминирующий фактический коэффициет смешения по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с зависимым элеваторным подключением системы отопления и последовательным включением подогревателей горячего водоснабжения. Фактическое значение коэффициент смешения элеватора у реального потребителя однозначно определяется температурным графиком сетевой воды, установленным для системы отопления потребителя. Как известно, коэффициент смешения элеватора U определяется с помощью следующих выражений: 1. U=Gп/Gс, где Gп - массовый расход подмешиваемой воды, т/ч; Gс - массовый расход воды, потребляемой из сети на систему отопления потребителя, т/ч; 2. U=(t1-t3)/(t3-t2), где t1, t2 - соответственно, температура сетевой воды в подающем и обратном трубопроводах теплового пункта реального потребителя; t3 - температура смешанной воды, поступающей в систему отопления потребителя. Например, для температурного графика сетевой воды 150-70 Град.С и графика - подмешанной воды 90-70 Град.С коэффициент смешения принимается равным U=2.2. Это значение принимается в качестве исходного значения этого свойства по умолчанию.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1977, N'Потребитель обобщенный', N'РО', N'gv_op', NULL, N'Средняя тепловая нагрузка на ГВС в открытой системе из подающего трубопровода', N'Средняя тепловая нагрузка на ГВС, подающий трубопровод', N'"Среднечасовая  тепловая   нагрузка на ГВ в открытой системе из подающего трубопровода"   -  цифровое поле, значение которого определяется как сумма  значений среднечасовых  тепловых   нагрузок  горячего водоснабжения группы реальных потребителей с открытой системой водоразбора из подающего трубопровода,  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Среднечасовая  тепловая   нагрузка горячего водоснабжения   реального потребителя соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1978, N'Потребитель обобщенный', N'РО', N'gv_oo', NULL, N'Средняя тепловая нагрузка на ГВС в открытой  системе из обратного трубопровода', N'Средняя тепловая нагрузка на ГВС, обратный трубопровод', N'"Среднечасовая  тепловая   нагрузка на ГВ в открытой системе из обратного трубопровода"   -  цифровое поле, значение которого определяется как сумма  значений среднечасовых  тепловых   нагрузок  горячего водоснабжения группы реальных потребителей с открытой системой водоразбора из обратного трубопровода,  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Среднечасовая  тепловая   нагрузка горячего водоснабжения   реального потребителя соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1979, N'Потребитель обобщенный', N'РО', N'rez_op', NULL, N'Расчетные тепловые потери в рециркуляц. контуре ГВС, откр.ГВС', N'Расчетные тепловые потери в рециркуляц. контуре ГВС', N'"Тепловая  нагрузка   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС"  -  цифровое поле, значение которого определяется как сумма тепловых  нагрузок   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС (Qтп) группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с открытой системой горячего водоснабжения.  На практике значение потерь определяют долей от среднечасовой  нагрузки ГВС, т.е.   Qтп=Qср*К, где  К=0.05-0.3. Значение  поля  используется при расчете теплогидравлических режимов тепловых пунктов (ЦТП) только с открытой  ГВС  циркуляционного  типа. Значение   поля   имеет  процентную  размерность и вводится, например, в виде целочисленной  константы  20 (при 20%-ых потерях). Поле заполняется при наличии у данного потребителя рециркуляции.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1980, N'Потребитель обобщенный', N'РО', N'utechp', NULL, N'Заданная утечка из подающего трубопровода', N'Заданная утечка из подающего трубопровода', N'"Заданная  утечка  из  подающего  трубопровода" -  цифровое поле, значение которого определяется как сумма  утечки  из  подающего  трубопровода группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.   Значение  утечки реального потребителя из  подающего  трубопровода задается  пользователем  исходя   из определенных целей моделирования аварийной ситуации.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1981, N'Потребитель обобщенный', N'РО', N'utecho', NULL, N'Заданная утечка из обратного  трубопровода', N'Заданная утечка из обратного  трубопровода', N'"Заданная  утечка  из  обратного  трубопровода" -  цифровое поле, значение которого определяется как сумма  утечки  из  обратного трубопровода группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.   Значение  утечки реального потребителя из  обратного трубопровода задается  пользователем  исходя   из определенных целей моделирования аварийной ситуации.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1982, N'Потребитель обобщенный', N'РО', N'gsz', NULL, N'Гидравлическое сопротивление для закрытой системы', N'Гидравл.сопротивление закрыт.системы теплопотребления', N'"Гидравлическое сопротивление потребителя в закрытой системе"  -   цифровое поле, значение которого представляет собой гидравлическое   сопротивление закрытых систем теплопотребления обобщенного потребителя, определенного как отношение располагаемого напора в узле присоединения потребителя к квадрату расхода в закрытых системах теплопотребления обобщенного потребителя в данном гидравлическом  режиме. Если сопротивление   не определено эксперементальным или расчетным путем, то значение поля не заполняется.  При этом  программные  средства системы  автоматически определяют требуемое значение сопротивления закрытых систем теплопотребления обобщенного потребителя, при котором  обеспечивается заданный   расчетный   расход на эту группу потребителей.  1. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение поля обновляется, если в поле  "Признак расчета на заданное сопротивление закрытой системы теплопотребления" выбрано значение "Рассчитанное"  2.Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если в поле "Признак расчета на заданную нагрузку" выбрано значение "Сопротивление".', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1983, N'Потребитель обобщенный', N'РО', N'gszpr', NULL, N'Признак расчета на заданное сопротивление закрытой системы теплопотребления', N'Признак расчета гидравл.сопротивл. в закр.системе', N'"Признак расчета гидравлического сопротивления в   закрытой системе"  - символьное поле,   значение которого "Заданное"  выбирается пользователем в  том случае, если гидравлическое сопротивление   закрытых систем обобщенного потребителя следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля  "Рассчитанное",  то значение поля обновляется при каждом расчете планового режима системы.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1984, N'Потребитель обобщенный', N'РО', N'gsop', NULL, N'Гидравлическое сопротивление для водоразбора из подающего трубопровода', N'Гидравл.сопротивл.откр.ГВС, подающ.трубопр.', N'"Гидравлическое  сопротивление открытой системы ГВ обобщенного потребителя при водоразборе  из подающего трубопровода"  - цифровое поле,  значение  которого  представляет  собой   гидравлическое сопротивление открытой системы ГВ обобщенного потребителя, определенное как отношение  разности между  пьезометрическим  напором  в подающей трубы присоединения обобщенного потребителя на магистральном трубопроводе  и   напором, соответствующим  атмосферному  давлению в узле присоединения  обобщенного потребителя,  к  квадрату суммарного расхода на ГВ из подающего трубопровода обобщенного потребителя в данном режиме.  Если  сопротивление не определено эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение сопротивления открытой СГВ обобщенного потребителя, при котором  обеспечивается заданный расчетный расход  на ГВ.  1. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение поля обновляется, если в поле  "Признак расчета гидравлического сопротивления открытой  ГВС, подающий трубопровод" выбрано значение "Рассчитанное"  2.Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если в поле "Признак расчета на заданную нагрузку" выбрано значение "Сопротивление".', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1985, N'Потребитель обобщенный', N'РО', N'gsoppr', NULL, N'Признак расчета на заданое сопротивление  открытой системы теплопотребления при водоразборе из подающего трубопровода', N'Признак расчета гидравл.сопротивл.откр. ГВС, подающ.трубопров.', N'"Признак  гидравлического сопротивления открытой ГВС, при водоразборе из подающего трубопровода"  - символьное поле,   значение которого "Заданное"  выбирается пользователем в  том случае, если гидравлическое сопротивление  открытой системы обобщенного потребителя при водоразборе  из подающего трубопровода   следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля задано  "Рассчитанное",  то значение поля обновляется при каждом расчете дроссельных устройств реального потребителя.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1986, N'Потребитель обобщенный', N'РО', N'gsoo', NULL, N'Гидравлическое сопротивление для водоразбора из обратного  трубопровода', N'Гидравл.сопрот.откр.ГВС, при водоразборе из обратн.труб.', N'"Гидравлическое  сопротивление открытой системы ГВ обобщенного потребителя при водоразборе  из обратного трубопровода"  - цифровое поле,  значение  которого  представляет  собой   гидравлическое сопротивление открытой системы ГВ обобщенного потребителя, определенное как отношение  разности между  пьезометрическим  напором  в обратной трубы присоединения обобщенного потребителя на магистральном трубопроводе  и   напором, соответствующим  атмосферному  давлению в узле присоединения  обобщенного потребителя,  к  квадрату суммарного расхода на ГВ из обратного трубопровода обобщенного потребителя в данном режиме.  Если  сопротивление не определено эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение сопротивления открытой СГВ обобщенного потребителя, при котором  обеспечивается заданный расчетный расход  на ГВ.  1. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение поля обновляется, если в поле  "Признак расчета гидравлического сопротивления открытой  ГВС, обратный трубопровод" выбрано значение "Рассчитанное"  2.Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если в поле "Признак расчета на заданную нагрузку" выбрано значение "Сопротивление".', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1987, N'Потребитель обобщенный', N'РО', N'gsoopr', NULL, N'Признак расчета на заданое сопротивление теплопотребителя для водоразбора из обратного  трубопровода, пробел или символ ''Н''автоматический', N'Признак расчета гидравл.сопротивл.откр. ГВС, обрат.трубопров', N'"Признак  гидравлического сопротивления открытой ГВС, при водоразборе из обратного трубопровода"  - символьное поле,   значение которого "Заданное"  выбирается пользователем в  том случае, если гидравлическое сопротивление  открытой системы обобщенного потребителя при водоразборе  из обратного трубопровода   следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля задано  "Рассчитанное",  то значение поля обновляется при каждом расчете дроссельных устройств реального потребителя.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1988, N'Потребитель обобщенный', N'РО', N'prznz', NULL, N'Признак расчета на заданную нагрузку в закрытых системах теплопотребления', N'Признак расчета на заданную нагрузку в закр.системах теплопотр.', N'Признак расчета на заданную нагрузку в закрытых системах теплопотребления, пробел или символ ''Н''автоматический', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1989, N'Потребитель обобщенный', N'РО', N'prznp', NULL, N'Признак расчета на  заданную нагрузку  из подающего трубопровода в открытых системах теплопотребления', N'Признак расчета на  заданную нагрузку  откр. ГВС, под.трубопр.', N'Признак расчета на  заданную нагрузку  из подающего трубопровода в открытых системах теплопотребления, пробел или символ ''Н''', NULL, NULL)
