INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (1992, N'Потребитель обобщенный', N'РО', N'kod_owner', NULL, N'Балансовая принадлежность  обобщенного потребителя', N'Балансовая принадлежность обобщенного потребителя', N'Организация несущая ответственность при эксплуатации и техническом обслуживании объекта системы теплоснабжения, при возникновении аварийных ситуаций на объекте.', NULL, NULL)
