INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2008, N'Потребитель обобщенный', N'РО', N'cx_co_sm', NULL, N'Схема присоединения  СО смеш.ГВС', N'Схема присоединения системы отопления', N'"Схема присоединения зависимой системы отопление" - символьное поле, значение которого определяет схему присоединения системы отопления по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе со смешанным подключением подогревателей горячего водоснабжения, значение "элеваторное"означает, что у наибольшего процента реальных потребителей группы система отопления подключена по зависимой схеме с элеваторным узлом смешения, "безэлеваторное" -  система отопления подключена по зависимой схеме без узла смешения,  "независимое" - система отопления подключена по независимой схеме через водо-водянные подогреватели.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2009, N'Потребитель обобщенный', N'РО', N'cx_co_ps', NULL, N'Схема присоединения  СО посл.ГВС', N'Схема присоединения системы отопления', N'"Схема присоединения зависимой системы отопление" - символьное поле, значение которого определяет схему присоединения системы отопления по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с последовательным подключением подогревателей горячего водоснабжения, значение "элеваторное"означает, что у наибольшего процента реальных потребителей группы система отопления подключена по зависимой схеме с элеваторным узлом смешения, "безэлеваторное" -  система отопления подключена по зависимой схеме без узла смешения,  "независимое" - система отопления подключена по независимой схеме через водо-водянные подогреватели.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2010, N'Потребитель обобщенный', N'РО', N'kodtr', N'КодРасТемп', N'Код расчетных температур', N'Код расчетных температур', N'"Код  расчетных температур"  - символьное  поле, значение которого однозначно определяет группу расчетных температур и температур в точке излома температурного графика теплоносителя, наружного воздуха, нагреваемой водопроводной воды, предназначенных для расчета коэффициентов темплопередачи приборов отопления, вентиляции,  теплообменных аппаратов закрытых систем горячего водоснабжения.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2011, N'Потребитель обобщенный', N'РО', N'otopl_pw', NULL, N'Расчетная тепловая нагрузка на  отопление, предвкл.ГВС', N'Расчетная тепловая нагрузка на  отопление', N'"Расчетная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с предвключенной схемой включения подогревателей горячего водоснабжения.  Расчетная тепловая  нагрузка на  отопление реального потребителя принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по независимой    схеме    или   назначается   пользователем,  исходя из   определенных   целей   расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2012, N'Потребитель обобщенный', N'РО', N'otopl_tp_pw', NULL, N'Внутренние тепловыделения, предвкл.ГВС', N'Внутренние тепловыделения', N'"Расчетные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе  с предвключенной схемой включения подогревателей горячего водоснабжения.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2013, N'Потребитель обобщенный', N'РО', N'gv_pw', NULL, N'Средняя тепловая нагрузка на ГВС, предвкл. ГВС', N'Средняя тепловая нагрузка на ГВС', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  предвключенном включении подогревателя  ГВ"   -  цифровое   поле,  значение    которого соответствует среднедельной часовой тепловой нагрузке  на ГВ для указанной схемы включения подогревателей  и назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2014, N'Потребитель обобщенный', N'РО', N'gvs_max_pw', NULL, N'Коэф. часовой неравномерности,  предвкл.ГВС', N'Коэффициент часовой неравномерности нагрузки ГВС', N'"Коэффициент часовой неравномерности нагрузки горячего водоснабжения" - цифровое поле, значение которого определяет доминирующий коэффициент часовой неравномерности (kч) расхода тепла за сутки наибольшего водопотребления у группы реальных потребителей с предвключенной схемой включения подогревателей горячего водоснабжения и перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Значение этого свойства используется при расчете максимального расхода тепла на горячее водоснабжение жилых зданий, гостиниц, больниц и т.д.: Qгвс_макс=kч*Qгвс_средн. При определении расхода тепла на горячее водоснабжение микрорайонов (кварталов) городов kч= 1.7 - 2.2, промышленных предприятий kч= 1. При отсутствии данных о назначении общественных зданий допускается определении коэффициента часовой неравномерности условное количество жителей принимать с коэффициентом 1.2.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2015, N'Потребитель обобщенный', N'РО', N'rez_pw', NULL, N'Расчетная тепловая нагрузка на компенсацию тепловых потерь в трубопр. цирк-ой ГВС, предвкл.сх.', N'Расчетная тепл.нагрузка на компенсацию тепл.потерь в цирк.труб.ГВС', N'"Тепловая  нагрузка   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС"  -  цифровое поле, значение которого определяется как сумма тепловых  нагрузок   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с предвключенной схемой включения подогревателей горячего водоснабжения. Значение тепловой  нагрузки   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС реального потребителя определяется  долей от среднечасовой  нагрузки ГВ, т.е.   Qц=Qср*К, где  К=0.1-0.3. Наиболее  часто в  практике проектирования ГВС используют 20-ти процентную долю, т.е. К=0.2. Значение  поля  используется при расчете теплогидравлических режимов тепловых пунктов только с открытой  ГВС  циркуляционного  типа. Значение   поля   имеет  процентную  размерность и вводится, например, в виде целочисленной  константы  20 (при 20%-ых потерях).', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2016, N'Потребитель обобщенный', N'РО', N'Tr_tv_co_pw', NULL, N'Расчетная температура в отапливаемых помещениях,  предвкл.ГВС', N'Расчетная температура воздуха в отапливаемых помещениях', N'"Расчетная температура воздуха в отапливаемых помещений" - цифровое поле, определяется как средняя величина значений Расчетных температур воздуха в отапливаемых помещений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с предвключенной схемой включения подогревателей горячего водоснабжения. Расчетная температура воздуха в отапливаемых помещений реального потребителя определяется значением температуры воздуха в отапливаемых помещениях, исходя из норм допустимых комфотных условий по CНиП II-33-75. Отопление, вентиляция и кондициониpование воздуха.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2017, N'Потребитель обобщенный', N'РО', N'Tr_gvs_pw', NULL, N'Расчетная температура горячей воды в местах водоразбора,  предвкл.ГВС', N'Расчетная температура горячей воды в местах водоразбора', N'"Расчетная температура горячей воды " -  числовое поле, определяется как средняя величина значений Расчетных температур горячей воды в  местах водоразбора по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с предвключенной схемой включения подогревателей горячего водоснабжения. Расчетная температура горячей воды в местах водоразбора реального потребителя определяет температуру бытовой горячей воды по выходу ее из подогревательных установок, нижнее и верхнее значение которой pегламентиуется тpебованиями СНиП 2.04.01-85: не ниже 60 Гpад.С в ГВС,пpисоединеных    к   откpытым системам    теплоснабжения; не ниже  50  Гpад.С , пpисоединенных  к закpытым системам теплоснабжения и не выше 75 Град.С для всех вышерассмотренных случаев. Для уменьшения циркуляционной воды температуру бытовой воды по выходе ее из подогревательных установок рекомендуется принимать равной в закрытых системах 50+10=60 Град.С, в открытых 60+5= 65 Град.С. Где 5-10 охлаждение циркуляционной воды в водоразборных стояках  многоэтажных зданий по системе в целом.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2018, N'Потребитель обобщенный', N'РО', N'uf_zco_pw', NULL, N'Фактический коэффициент смешения,зав.СО, предвкл.ГВС', N'Фактический коэффициент смешения зависимой СО', N'"Фактический коэффициент смешения элеватора" - цифровое поле, определяет доминирующий фактический коэффициет смешения по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с зависимым элеваторным подключением системы отопления и предвключенным включением подогревателей горячего водоснабжения. Фактическое значение коэффициент смешения элеватора у реального потребителя однозначно определяется температурным графиком сетевой воды, установленным для системы отопления потребителя. Как известно, коэффициент смешения элеватора U определяется с помощью следующих выражений: 1. U=Gп/Gс, где Gп - массовый расход подмешиваемой воды, т/ч; Gс - массовый расход воды, потребляемой из сети на систему отопления потребителя, т/ч; 2. U=(t1-t3)/(t3-t2), где t1, t2 - соответственно, температура сетевой воды в подающем и обратном трубопроводах теплового пункта реального потребителя; t3 - температура смешанной воды, поступающей в систему отопления потребителя. Например, для температурного графика сетевой воды 150-70 Град.С и графика - подмешанной воды 90-70 Град.С коэффициент смешения принимается равным U=2.2. Это значение принимается в качестве исходного значения этого свойства по умолчанию.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2019, N'Потребитель обобщенный', N'РО', N'cx_co_pw', NULL, N'Схема присоединения  СО предвкл.ГВС', N'Схема присоединения системы отопления', N'Схема присоединения зависимой СО', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2020, N'Потребитель обобщенный', N'РО', N'kod_gvs', N'График нагрузки ГВ', N'Код суточного графика нагрузки ГВ', N'Код графика суточного нагрузки ГВ', N'Код графика нагрузки ГВ, символьное поле, определяющее краткое наименование суточного графика нагрузки горячего водоснабжения потребителя. Суточный график нагрузки горячего водоснабжения используется при расчете режима (анализирующего) системы, по результатам которого рассчитываются отклонения фактических (измеренных) значений параметров режима в контрольных точках расчетной схемы системы теплоснабжения. Для открытых систем горячего водоснабжение значение "Балансовая нагрузка" не используется, по умолчанию она будет приравнена средней нагрузке  горячего водоснабжения.', N'Гидравлическое сопротивление', NULL)
