INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2046, N'Потребитель обобщенный', N'РО', N'Tr_gvs_oo_op', N'Расч.температура горячей воды откр. ГВС', N'Расчетная температура горячей воды откр. ГВС', N'Расчетная температура горячей воды в местах водоразбора, откр.ГВС', N'"Расчетная температура горячей воды " -  числовое поле, определяется как средняя величина значений Расчетных температур горячей воды в  местах водоразбора по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с открытой системой  горячего водоснабжения. Расчетная температура горячей воды в местах водоразбора реального потребителя определяет температуру бытовой горячей воды по выходу ее из подогревательных установок, нижнее и верхнее значение которой pегламентиуется тpебованиями СНиП 2.04.01-85: не ниже 60 Гpад.С в ГВС,пpисоединеных    к   откpытым системам    теплоснабжения; не ниже  50  Гpад.С , пpисоединенных  к закpытым системам теплоснабжения и не выше 75 Град.С для всех вышерассмотренных случаев. Для уменьшения циркуляционной воды температуру бытовой воды по выходе ее из подогревательных установок рекомендуется принимать равной в закрытых системах 50+10=60 Град.С, в открытых 60+5= 65 Град.С. Где 5-10 охлаждение циркуляционной воды в водоразборных стояках  многоэтажных зданий по системе в целом.', NULL, N'Град.С')

