INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2049, N'Потребитель обобщенный', N'РО', N'pr_avar_TP', N'Признак расчета гидравл.аварийного потребителя', N'Признак расчета гидравл.аварийного потребителя: Ш - через шайбы, Д-через регулятор перепада давления, С - через сопротивления', N'Признак расчета аварийного режима потребителя', N'Признак расчета гидравлического режима потребителя в аварийном режиме: Ш - через шайбы, Д-через регулятор перепада давления, С - через сопротивления', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2050, N'Потребитель обобщенный', N'РО', N'geod_z', N'Геодезическая  отметка земли', N'Геодезическая отметка поверхности земли', N'Геодезическая отметка поверхности земли', N'"Геодезическая отметка поверхности земли" - цифровое поле, значение которого определяет геодезическую отметку поверхности земли в месте расположения камеры присоединения ответветвления обобщенной нагрузки.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2051, N'Потребитель обобщенный', N'РО', N'tpotepi__pod', N'ТеплПотери под.теплопр.', N'Норм.тепловые потери в под.теплопр.распр.сети', N'Норм.тепловые потери в подающем теплопроводе распр.сети', N'Нормируемые тепловые потери в подающем теплопроводе распределительной сети', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2052, N'Потребитель обобщенный', N'РО', N'tpotepi__obr', N'ТеплПотери обр.теплопр.', N'Норм.тепловые потери в обр.теплопр.распр.сети', N'Норм.тепловые потери в обратном теплопроводе распр.сети', N'Нормируемые тепловые потери в обратном теплопроводе распределительной сети', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2053, N'Потребитель обобщенный', N'РО', N'gszl', N'ГидрСопрот.ЗакрытСистем, летний период', N'Гидр.сопротивление закрытых систем в летний период', N'Гидр.сопротивление закрыт.систем  в летний период', N'"Гидравлическое сопротивление закрытых систем в летний период"  -   цифровое поле, значение которого представляет собой гидравлическое   сопротивление закрытых систем теплопотребления обобщенного потребителя в летний период.  Если сопротивление   не определено эксперементальным или расчетным путем, то значение поля не заполняется.  При этом  программные  средства системы  автоматически определяют  значение сопротивления закрытых систем теплопотребления обобщенного потребителя в летнем периоде, как сумму  гидравлических сопротивлений  технологических элементов, по тракту движению потока теплоносителя до приборов водоразбора в системе горячего водоснабжения, определяемую  при Плановом отопительном режиме. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима,  значение поля обновляется, если в поле  "Признак расчета на заданное сопротивление закрытой системы теплопотребления" выбрано значение "Рассчитанное"', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2054, N'Потребитель обобщенный', N'РО', N'kondiz', N'РасчТеплНагрузкаКондиц', N'Расчетная тепловая нагрузка на кондиционирование', N'Расчетная тепловая нагрузка на кондиционирование', N'"Расчетная тепловая  нагрузка  на кондиционирование"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузок на  кондиционирование   группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Расчетная тепловая  нагрузка реального потребителя    принимается   по   типовым    или индивидуальным    проектам    потребителей    или    назначается пользователем, исходя из  определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2055, N'Потребитель обобщенный', N'РО', N'txz', N'РасчТеплНагрузТехнЗакрыт', N'Расчетная тепловая нагрузка на технологию в закрытой системе', N'Расчетная тепловая нагрузка на технологию в закрытой системе', N'"Расчетная тепловая  нагрузка  на технологию в закрытой системе"- цифровое поле, значение которого определяется как сумма  значений расчетных тепловых  нагрузок на  технологию в закрытых системах  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Расчетная тепловая нагрузка реального потребителя принимается по типовым или индивидуальным проектам потребителей или назначается пользователем, исходя из  определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2056, N'Потребитель обобщенный', N'РО', N'txop', N'СреднТеплНагрузТехнОткрПод', N'Средняя нагрузка на технологию в открытой системе из подающего теплопровода', N'Средняя нагрузка на технологию в открытой системе из подающего теплопровода', N'"Среднечасовая тепловая  нагрузка  на технологию в закрытой системе"- цифровое поле, значение которого определяется как сумма  значений среднечасовых тепловых  нагрузок на  технологию в открытых системах из подающего теплопровода  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Среднечасовая  тепловая   нагрузка горячего водоснабжения   реального потребителя соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2057, N'Потребитель обобщенный', N'РО', N'txoo', N'СреднТеплНагрузТехнОткрОбрат', N'Средняя нагрузка на технологию в открытой системе из обратного теплопровода', N'Средняя нагрузка на технологию в открытой системе из обратного теплопровода', N'"Среднечасовая тепловая  нагрузка  на технологию в закрытой системе"- цифровое поле, значение которого определяется как сумма  значений среднечасовых тепловых  нагрузок на  технологию в открытых системах из обратного теплопровода  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Среднечасовая  тепловая   нагрузка горячего водоснабжения   реального потребителя соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2058, N'Потребитель обобщенный', N'РО', N'gvs_max_o', N'Коэф. часовой неравном., откр.ГВС', N'Коэф. часовой неравномерности, откр.ГВС', N'Коэффициент часовой неравномерности нагрузки ГВС', N'"Коэффициент часовой неравномерности нагрузки горячего водоснабжения" - цифровое поле, значение которого определяет доминирующий коэффициент часовой неравномерности (kч) расхода тепла за сутки наибольшего водопотребления у группы реальных потребителей с открытым включением горячего водоснабжения и  перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Значение этого свойства используется при расчете максимального расхода тепла на горячее водоснабжение жилых зданий, гостиниц, больниц и т.д.: Qгвс_макс=kч*Qгвс_средн.  При определении расхода тепла на горячее  водоснабжение микрорайонов (кварталов) городов kч= 1.7 - 2.2, промышленных предприятий kч= 1. При отсутствии данных о назначении общественных зданий допускается определении коэффициента часовой неравномерности условное количество жителей принимать с коэффициентом 1.2.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2059, N'Потребитель обобщенный', N'РО', N'a24', N'УдОбъемСО', N'Удельный  объем  воды  в  системе  отопления', N'Удельный объем воды в системе отопления', N' "Удельный объем воды в системе отопления" - числовое поле, значение которого определяет удельный объем воды в системе отопления в зависимости от расчетного температурного перепада и типа отопительных приборов. Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2060, N'Потребитель обобщенный', N'РО', N'a25', N'УдОбъемВент', N'Удельный  объем  воды  в  системе  вентиляции', N'Удельный объем воды в системе вентиляции', N'"Удельный объем воды в системе вентиляции" - числовое поле, значение которого определяет удельный объем воды в отопительно-вентиляционной системе, оборудованной калориферами, в зависимости от расчетного температурного перепада. Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2061, N'Потребитель обобщенный', N'РО', N'T_pot_rez_pr', NULL, N'Температура в рециркуляционном трубопроводе ГВС', N'Температура в рециркуляционном трубопроводе ГВС', N'"Температура в рециркуляционном трубопроводе открытой ГВС"- цифровое поле, которое определяет температуру (Тост), до которой допустимо остывание сетевой воды в рециркуляционном трубопроводе ГВС за счет тепловых потерь, при нулевой нагрузке ГВС, т.е. отсутствии водоразбора.  Значение поля  используется для определения расхода сетевой воды на рециркуляцию в открытых системах горячего водоснабжения.  Численное значение расхода  на рециркуляцию принимается  равным Gрец=Qтп/(dt*с), где dt=((Тг-Тх)-Тост), где Тг - температура горячей воды в системе горячего водоснабжения с непосредственным водоразбором, Тх - температура водопроводной воды, Qтп - тепловые потери в рециркуляционном контуре. Допустимое  остывание воды   рециркуляционном контуре  обычно  принимают  из  диапазона  30-50  Град.  С.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2062, N'Потребитель обобщенный', N'РО', N'T_pot_rez_sm', NULL, N'Температура в рециркуляционном трубопроводе ГВС', N'Температура в рециркуляционном трубопроводе ГВС', N'"Температура в рециркуляционном трубопроводе открытой ГВС"- цифровое поле, которое определяет температуру (Тост), до которой допустимо остывание сетевой воды в рециркуляционном трубопроводе ГВС за счет тепловых потерь, при нулевой нагрузке ГВС, т.е. отсутствии водоразбора.  Значение поля  используется для определения расхода сетевой воды на рециркуляцию в открытых системах горячего водоснабжения.  Численное значение расхода  на рециркуляцию принимается  равным Gрец=Qтп/(dt*с), где dt=((Тг-Тх)-Тост), где Тг - температура горячей воды в системе горячего водоснабжения с непосредственным водоразбором, Тх - температура водопроводной воды, Qтп - тепловые потери в рециркуляционном контуре. Допустимое  остывание воды   рециркуляционном контуре  обычно  принимают  из  диапазона  30-50  Град.  С.', NULL, N'Град.С')
