INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2066, N'Потребитель обобщенный', N'РО', N'G_otoplz', N'РасчРасходСОзав', N'Расчетный расход на  отопление, зав.СО', N'Расчетный расход на  отопление', N' "Расчетный расход на  отопление, зависимая схема"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на  отопление при зависимой схеме включения системы отопления потребителя, определяемое с учетом  заданной расчетной тепловой нагрузки (Гкал/ч) на отопление и фиксированного расчетного  температурного  перепада  теплоносителя  (Град.С)  (с учетом или без учета тепловых потерь).  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на отопление  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2067, N'Потребитель обобщенный', N'РО', N'G_otopln', N'РасчРасходСОнезав', N'Расчетный расход на  отопление, незав.СО', N'Расчетный расход на  отопление', N' "Расчетный расход на  отопление, независимая схема"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на  отопление при независимой схеме включения системы отопления потребителя, определяемое с учетом  заданной расчетной тепловой нагрузки (Гкал/ч) на отопление и фиксированного расчетного  температурного  перепада  теплоносителя  (Град.С)  (с учетом или без учета тепловых потерь).  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на отопление  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2068, N'Потребитель обобщенный', N'РО', N'G_ventil', N'РасчРасходВентил', N'Расчетный расход на  вентиляцию', N'Расчетный расход на  вентиляцию', N' "Расчетный расход на  вентиляцию"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на  отопление, определяемое с учетом  заданной расчетной тепловой нагрузки (Гкал/ч) на вентиляцию и фиксированного расчетного  температурного  перепада  теплоносителя  (Град.С)  (с учетом или без учета тепловых потерь).  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на ветиляцию  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2069, N'Потребитель обобщенный', N'РО', N'G_kondiz', N'РасчРасходКондицион', N'Расчетный расход на  кондиционирование', N'Расчетный расход на  кондиционирование', N' "Расчетный расход на кондиционирование"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на кондиционирование потребителя, определяемое с учетом  заданной расчетной тепловой нагрузки (Гкал/ч) на кондиционирование и фиксированного расчетного  температурного  перепада  теплоносителя  (Град.С)  (с учетом или без учета тепловых потерь).  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на кондиционирование  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
