INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2077, N'Потребитель обобщенный', N'РО', N'pP', N'Пьезом.напор ВходТП_План Режим', N'Пьезом.напор на входе тепл.пункта, плановый режим', N'Пьезом.напор на входе теплового пункта, плановый режим', N'"Пьезометрический напор на входе теплового пункта, плановый режим" - цифровое поле,  значение  которого  представляет  собой значение пьезометрического напора на входе теплового пункта при расчёте потокораспределения для планового режима.', N'Напор', NULL)
