INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2079, N'Потребитель обобщенный', N'РО', N'pr_uchet', N'Признак прибора учета', N'Признак установки прибора учета', N'Признак установки прибора учета', N'"Признак прибора учета расхода воды"- значение поля может принимать два значения: "Установлен" - прибор учета тепловой энергии (расхода сетевой воды) у данного потребителя установлен. "Не установлен" - прибор учета расхода воды у данного потребителя не установлен. Значение поля используется для классификации потребителей (с приборами учета/без приборов учета) в расчете нормируемых тепловых потерь с утечкой.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2080, N'Потребитель обобщенный', N'РО', N'f_ventil_cv', NULL, N'Договорная тепловая нагрузка  на вентиляцию', N'Договорная нагрузка  на вентиляцию', N'"Скорректированная расчетная тепловая  нагрузка на вентиляцию"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузок на  вентиляцию группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Договорная тепловая  нагрузка реальных потребителей принимается исходя из договорных обязательств с потребителями или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2081, N'Потребитель обобщенный', N'РО', N'f_otopl_sm', NULL, N'Договорная нагрузка на  отопление, смеш.ГВС', N'Договорная тепловая нагрузка на  отопление', N'"Договорная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе со смешанной схемой включения подогревателей горячего водоснабжения.  Договорная тепловая  нагрузка реальных потребителей принимается исходя из договорных обязательств с потребителями или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2082, N'Потребитель обобщенный', N'РО', N'f_otopl_ps', NULL, N'Договорная нагрузка на  отопление, посл.ГВС', N'Договорная нагрузка на  отопление', N'"Договорная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений сорректированныхрасчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с последовательной схемой включения подогревателей горячего водоснабжения.  Договорная тепловая  нагрузка реальных потребителей  принимается исходя из договорных обязательств с потребителями или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2083, N'Потребитель обобщенный', N'РО', N'f_otopl_zco', NULL, N'Договорная нагрузка на  отопление, зависимая СО', N'Договорная нагрузка на  отопление', N' "Договорная тепловая  нагрузка на  отопление,  зависимая схема"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с зависимым подключением системы отопления.  Договорная тепловая  нагрузка реальных потребителей    принимается по результам анализа фактического гидравлического режима или назначается исходя из определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2084, N'Потребитель обобщенный', N'РО', N'f_otopl_pw', NULL, N'Договорная нагрузка на  отопление, предвкл.ГВС', N'Договорная нагрузка на  отопление', N'"Договорная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с предвключенной схемой включения подогревателей горячего водоснабжения.  Договорная тепловая  нагрузка реальных потребителей  принимается исходя из договорных обязательств с потребителями или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2085, N'Потребитель обобщенный', N'РО', N'f_otopl_nco', NULL, N'Договорная нагрузка на  отопление, независимая СО', N'Договорная тепловая нагрузка на  отопление', N' "Договорная тепловая  нагрузка на  отопление,  независимая схема"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с независимым подключением системы отопления через водо-водянные подогреватели.  Договорная тепловая  нагрузка на отопление реальных потребителей принимается исходя из договорных обязательств с потребителями или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2086, N'Потребитель обобщенный', N'РО', N'f_kondiz', N'РасчТеплНагрузкаКондиц', N'Договорная нагрузка на кондиционирование', N'Договорная нагрузка на кондиционирование', N'"Договорная тепловая  нагрузка  на кондиционирование"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузок на  кондиционирование   группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Договорная тепловая  нагрузка реальных потребителей принимается исходя из договорных обязательств с потребителями или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2087, N'Потребитель обобщенный', N'РО', N'f_otopl_pr', NULL, N'Договорная нагрузка на  отопление парал.ГВС', N'Договорная нагрузка на отопление', N'"Договорная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с параллельной схемой включения подогревателей горячего водоснабжения.  Договорная тепловая  нагрузка реальных потребителей на отопление  принимается исходя из договорных обязательств с потребителями или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2088, N'Потребитель обобщенный', N'РО', N'f_txz', N'РасчТеплНагрузТехнЗакрыт', N'Договорная нагрузка на технологию в закрытой системе', N'Договорная нагрузка на технологию в закрытой системе', N'"Договорная тепловая  нагрузка  на технологию в закрытой системе"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузок на  технологию в закрытых системах  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Договорная тепловая  нагрузка реальных потребителей принимается по результам анализа фактического гидравлического режима или назначается исходя из определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2089, N'Потребитель обобщенный', N'РО', N'f_otopl_tp_nco', NULL, N'Договорные внутренние тепловыделения, независимая СО', N'Договорные внутренние тепловыделения', N'"Договорная внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  скорретированных расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с независимым подключением системы отопления  через водо-водянные подогреватели.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Договорные внутренние тепловыделения реальных потребителей принимаются исходя из договорных обязательств с потребителями или назначаются из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)

