INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2095, N'Потребитель обобщенный', N'РО', N'p_min', NULL, N'Мин.располагаемый напор в распред.сети', N'Мин.располагаемый напор в распред.сетях', N'"Минимальный располагаемый напор в распределенных сетях - цифровое поле, значение которого определяется в результате гидравлического расчета распределительных сетей, представителем которых в данной расчетной схеме является текущий обобщенный потребитель.', N'Напор', N'м.вод.ст')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2096, N'Потребитель обобщенный', N'PO', N'k_akkuml', N'Коэффициент аккумуляции здания', N'Коэффициент аккумуляции здания', N'Коэффициент аккумуляции здания', N'"Коэффициент аккумуляции здания" - цифровое поле, значение которого определяется по зданию с наименьшим  коэффициент аккумуляции и используется при расчета времени замерзания теплоносителя в системах отопления, при прекращена подачи тепла. Рекомендуется использовать функцию поля. Значения коэффициентов аккумуляции зданий в функции поля соответствуют МДС МДС 41-6.2000 РАО "Роскоммунэнерго".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2097, N'Потребитель обобщенный', N'РО', N'master', N'Начальник участка', N'Начальник участка', N'Начальник магистральной сети', N'"Начальник участка магистральной сети" символьное поле, значение которого определяет имя начальника участка магистральной сети, который представляет расчетная схема в данном районе эксплуатации. Значение поле заполняется с помощью функции поля.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2098, N'Потребитель обобщенный', N'PO', N'kvartal', NULL, N'Квартал', N'Квартал', N'Квартал', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2099, N'Потребитель обобщенный', N'РО', N'p_kondiz', N'РасчТеплНагрузкаКондиц', N'Перспективная нагрузка на кондиционирование', N'Перспективная нагрузка на кондиционирование', N'"Перспективная тепловая  нагрузка  на кондиционирование"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузок на  кондиционирование   группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Договорная тепловая  нагрузка реальных потребителей принимается исходя из договорных обязательств с потребителями по ТУ  или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2100, N'Потребитель обобщенный', N'РО', N'p_otopl_nco', NULL, N'Перспективная нагрузка на  отопление, независимая СО', N'Перспективная тепловая нагрузка на  отопление', N' "Перспективная тепловая  нагрузка на  отопление,  независимая схема"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с независимым подключением системы отопления через водо-водянные подогреватели.  Договорная тепловая  нагрузка на отопление реальных потребителей принимается исходя из договорных обязательств с потребителями по ТУ или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2101, N'Потребитель обобщенный', N'РО', N'p_otopl_pr', NULL, N'Перспективная нагрузка на  отопление парал.ГВС', N'Перспективная нагрузка на отопление', N'"Перспективная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе с параллельной схемой включения подогревателей горячего водоснабжения.  Договорная тепловая  нагрузка реальных потребителей на отопление  принимается исходя из договорных обязательств с потребителями по ТУ или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
