INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2104, N'Потребитель обобщенный', N'РО', N'p_otopl_sm', NULL, N'Перспективная нагрузка на  отопление, смеш.ГВС', N'Перспективная тепловая нагрузка на  отопление', N'"Перспективная тепловая  нагрузка на  отопление"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе со смешанной схемой включения подогревателей горячего водоснабжения.  Договорная тепловая  нагрузка реальных потребителей принимается исходя из договорных обязательств с потребителями по ТУ или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2105, N'Потребитель обобщенный', N'РО', N'p_otopl_tp_nco', NULL, N'Перспективные внутренние тепловыделения, независимая СО', N'Перспективные внутренние тепловыделения', N'"Перспективные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  скорретированных расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с независимым подключением системы отопления  через водо-водянные подогреватели.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Договорные внутренние тепловыделения реальных потребителей принимаются исходя из договорных обязательств с потребителями по ТУ или назначаются из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2106, N'Потребитель обобщенный', N'РО', N'p_otopl_tp_pr', NULL, N'Перспект.внутренние тепловыделения, парал.ГВС', N'Перспективные внутренние тепловыделения', N'"Перспективные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  скорретированных расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе  с параллельной схемой включения подогревателей горячего водоснабжения.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Перспективные  внутренние тепловыделения реальных потребителей принимаются по результам анализа фактического гидравлического режима или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2107, N'Потребитель обобщенный', N'РО', N'p_otopl_tp_ps', NULL, N'Перспект.внутренние тепловыделения,посл.ГВС', N'Перспективные внутренние тепловыделения', N'"Перспективные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма скорретированных расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе  с последовательной схемой включения подогревателей горячего водоснабжения.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Договорные внутренние тепловыделения реальных потребителей принимаются исходя из договорных обязательств с потребителями по ТУ или назначаются из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная  нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2108, N'Потребитель обобщенный', N'РО', N'p_otopl_tp_pw', NULL, N'Перспект.внутренние тепловыделения, предвкл.ГВС', N'Перспективные внутренние тепловыделения', N'"Перспективные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма скорретированных расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе  с предвключенной схемой включения подогревателей горячего водоснабжения.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Договорные внутренние тепловыделения реальных потребителей принимаются исходя из договорных обязательств с потребителями или назначаются из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2109, N'Потребитель обобщенный', N'РО', N'p_otopl_tp_sm', NULL, N'Перспект.внутренние тепловыделения,смеш.ГВС', N'Перспективные внутренние тепловыделения', N'"Перспективные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма скорретированных расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе  со смешанной схемой включения подогревателей горячего водоснабжения.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Договорные внутренние тепловыделения реальных потребителей принимаются исходя из договорных обязательств с потребителями или назначаются из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2110, N'Потребитель обобщенный', N'РО', N'p_otopl_tp_zco', NULL, N'Перспект.внутренние тепловыделения, зависимая СО', N'Перспективные внутренние тепловыделения', N'"Перспективные внутренние тепловыделения" - цифровое  поле,  значение которого определяется как сумма  скорретированных расчетных внутренних тепловыделений по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с зависимым подключением системы отопления.  Расчетный часовой расход тепла на отопление отдельного здания определяется как  Q = 1.1(Qн.о  - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания,   Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Договорные внутренние тепловыделения реальных потребителей принимаются исходя из договорных обязательств с потребителями или назначаются из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2111, N'Потребитель обобщенный', N'РО', N'p_otopl_zco', NULL, N'Перспективная нагрузка на  отопление, зависимая СО', N'Перспективная нагрузка на  отопление', N' "Перспективная тепловая  нагрузка на  отопление,  зависимая схема"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузкок на  отопление  по группе реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе   с зависимым подключением системы отопления.  Перспективная  тепловая  нагрузка реальных потребителей    принимается по результам анализа фактического гидравлического режима или назначается исходя из определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2112, N'Потребитель обобщенный', N'РО', N'p_txz', N'РасчТеплНагрузТехнЗакрыт', N'Перспективная нагрузка на технологию в закрытой системе', N'Перспективная нагрузка на технологию в закрытой системе', N'"Перспективная тепловая  нагрузка  на технологию в закрытой системе"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузок на  технологию в закрытых системах  группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе. Перспективная тепловая  нагрузка реальных потребителей принимается по результам анализа фактического гидравлического режима или назначается исходя из определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2113, N'Потребитель обобщенный', N'РО', N'p_ventil_cv', NULL, N'Перспективная тепловая нагрузка  на вентиляцию', N'Перспективная нагрузка  на вентиляцию', N'"Перспективная тепловая  нагрузка на вентиляцию"- цифровое поле, значение которого определяется как сумма  значений скорретированных расчетных тепловых  нагрузок на  вентиляцию группы реальных потребителей, перенесенных в узел присоединения распределительной сети на магистральном трубопроводе.  Договорная тепловая  нагрузка реальных потребителей принимается исходя из договорных обязательств с потребителями по ТУ или назначается из-за определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2114, N'Потребитель обобщенный', N'PO', N'name_typ', NULL, N'КонстрУзла', N'Конструкция узла', N'"Конструкция узла" - символьное поле, значение которого используется для указания типа ненагруженного узла расчетной схемы:
Коллектор - Коллектор;  
Камера     - Теплофикационная камера;
Нагрузка   - Присоединение нагрузки;  
Транзит     - Коммуникационный узел;
Павильон  - Надземный павильон; 
Поворот    - Угол поворота теплопровода;
Переход   - Переход диаметра трубопровода.
Значение поля безразмерная величина и имеет информационный характер.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2115, N'Потребитель реальный', N'PR', N'nomer', N'№', N'№', N'Порядковый номер записи', N'Порядковый номер записи', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2116, N'Потребитель реальный', N'PR', N'sost', N'Сост', N'Состояние', N'Состояние потребителя', N' "Состояние потребителя"- символьное поле, значение которого  "Закрыто"  - закрыт(отключен)  или "Открыто"-  открыт(подключен) позволяет пользователю, не удаляя данный объект убрать нагрузку теплопотребления из данного  узла расчетной схемы тепловой сети (значение  "Закрыто") или вновь ее назначить ("Открыто"). Заполнение поля обязательно.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2117, N'Потребитель реальный', N'PR', N'kod', N'КодРСУзПрис', N'Код расчетной схемы узла', N'Код расчетной схемы узла присоединения', N'"Код расчетной схемы" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит реальный потребитель. Рекомендуется при заполнении поля использовать функцию поля (выбор расчетной схемы из списка описанных).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2118, N'Потребитель реальный', N'PR', N'uzel', N'НаимУзПрис', N'Наименование узла', N'Наименование узла', N'"Наименование  узла  присоединения"  -  символьное  поле  , значение которого  однозначно  определяет  имя потребителя на данной расчетной схеме". Заполнение поля обязательно.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2119, N'Потребитель реальный', N'PR', N'pr', N'ПризнТеплУзПрис', N'Признак теплопровода узла узла присоединения', N'Признак теплопровода  узла просоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения. Значение «Общий», означает,  что расчетная схема потребителя локализована между подающим и обратным трубопроводами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2120, N'Потребитель реальный', N'PR', N'cxema', N'НомРасчСх', N'Номер расчетной схемы', N'Номер расчетной схемы', N'Номер расчетной схемы', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2121, N'Потребитель реальный', N'PR', N'nomer_building', N'Здание', N'Здание', N'Порядковый номер здания', N'Порядковый номер здания', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2122, N'Потребитель реальный', N'PR', N'name_building', N'НаимЗдан', N'Наим.здания', N'Содержательное наименование здания', N'"Содержательное  наименование  потребителя"  -   символьное поле,   значение   которого   определяет   полное   наименование реального потребителя магистральных или распределительных сетей. Например, "ул.Гоголя 27", "Ермекова 73/3". Заполнение поля желательно.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2123, N'Потребитель реальный', N'PR', N'h', N'ВысЗдан', N'Высота здания', N'Высота здания', N'"Высота  здания"  -  цифровое  поле,   значение которого  соответствует  высоте   самого  высокого  из   зданий, нагрузка теплопотребления которых "присоединена" к данному узлу. Значение поля имеет размерность, м. Заполнение поля обязательно.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2124, N'Потребитель реальный', N'PR', N'kodur', N'КодУР', N'Код УР', N'Код удельных расходов тепло/вода', N'"Код  удельных  расходов"  -символьное  поле, значение которого однозначно определяет группу удельных расходов по  всем видам теплопотребления, заданным в объекте "Удельные расходы", и предназначенных для пересчета нагрузок по всем видам теплопотребления из  единиц теплового  потока  (Гкал/ч)  в  единицы массового расхода (т/ч). Наличие непустого  значения в  этом поле  свидетельствует о том, что  в  этом  объектах  "Реальный потребитель" и "Обобщеный потребитель"   могут  быть  приведены  нагрузки  по отдельным  видам  теплопотребления,  представленные  в  единицах теплового  потока  (Гкал/ч),  а  соответствующие им расходы воды (т/ч) могут быть  вычисленны автоматически и  использованны при расчете  плановых теплогидравлических  режимов. Поле заполняется обязательно, в случае, если выбран вид расчета режима работы сети "По заданным удельным расходам".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2125, N'Потребитель реальный', N'PR', N'geodz', N'ГеодОтм', N'Геод.отметка подвальной прокладки', N'Геодезическая отметка низа трубы подвальной прокладки', N'"Геодезическая отметка низа трубы подвальной прокладки" - цифровое поле, значение которого  определяется  значением   геодезической  отметкой низа трубы подвальной прокладки здания в месте расположения  данного узла  присоединения нагрузки потребителя. Заполнение поля обязательно.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2126, N'Потребитель реальный', N'PR', N'otoplz', N'РасчНагрСОзав', N'Расчетная нагрузка на отопление, зав.СО', N'Расчетная тепловая нагрузка на  отопление', N' "Расчетная тепловая  нагрузка на  отопление,  зависимая схема"- цифровое поле, значение которого принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по зависимой    схеме    или   назначается   пользователем,  исходя из   определенных   целей   расчета. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2127, N'Потребитель реальный', N'PR', N'otopln', N'РасчНагрСОнезав', N'Расчетная  нагрузка на отопление, незав.СО', N'Расчетная тепловая нагрузка на  отопление', N'"Расчетная тепловая  нагрузка  на отопление, независимая схема"- цифровое поле, значение которого принимается по  типовым или  индивидуальным  проектам   потребителей,  подключенных   по независимой  схеме  или  назначается  пользователем,  исходя  из определенных  целей  расчета. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2128, N'Потребитель реальный', N'PR', N'otn_fs', N'ОтнНагрУлФас', N'Отн.нагрузка уличного фасада', N'Относительная нагрузка уличного фасада', N' "Относительная нагрузка уличного  фасада" - цифровое  поле, значение  которого  определяется  отношением  тепловой  нагрузки (расхода) на  отопление уличного  фасада потребителя  к тепловой нагрузке    (расходу)    на    отопление    потребителя   вцелом (Qул.ф/Qздания)  и  задается  пользователем  для  потребителей с пофасадным  распределением   нагрузки  отопления   при   наличии потребности расчета  дросельных регулирующих  устройств отдельно на  уличный  и  дворовой  фасады  потребителя.  Значение  поля - безразмерная величина.', NULL, N'%')

