INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2129, N'Потребитель реальный', N'PR', N'ventil', N'РасчНагрВент', N'Расчетная нагрузка на вентиляцию', N'Расчетная тепловая нагрузка  на вентиляцию', N'"Расчетная тепловая  нагрузка на вентиляцию" - цифровое поле,   значение   которого    принимается   по   типовым    или индивидуальным    проектам    потребителей    или    назначается пользователем, исходя из  определенных целей расчета. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2130, N'Потребитель реальный', N'PR', N'dolja_vent', N'ДоляРасхПриОтклКУ', N'Доля расхода воды через КУ при откл.по возд.', N'Доля расхода воды через КУ, при отключении её по воздуху', N'"Доля расхода сетевой воды через КУ, при отключении её по воздуху" - цифровое поле,   значение   которого    принимается   по   типовым    или индивидуальным    проектам    потребителей    или    назначается пользователем, исходя из  определенных целей расчета. Значение  поля - безразмерная величина. Заполнение поля обязательно.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2131, N'Потребитель реальный', N'PR', N'kondiz', N'РасчНагрКондиц', N'Расчетная нагрузка на кондиционирование', N'Расчетная  тепловая нагрузка на кондиционирование', N'"Расчетная тепловая  нагрузка на  кондиционирование"  - цифровое  поле,  значение  которого  принимается  по типовым или индивидуальным    проектам    потребителей    или    назначается пользователем. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2132, N'Потребитель реальный', N'PR', N'txz', N'РасчНагрТехнЗакр', N'Расчетная нагрузка на технологию, закрытая', N'Расчетная тепловая нагрузка на технологию в закрытой системе', N'"Тепловая нагрузка на технологические процессы в закрытой системе" - цифровое поле, значение которого принимается по типовым  или индивидуальным  проектам потребителей  тепла или назначается  пользователем.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2133, N'Потребитель реальный', N'PR', N'txop', N'СреднНагрТехнОткрПод', N'Средняя тепл.нагрузка на технологию, под.труб.', N'Расчетная нагрузка на технологию в открытой системе из подающего теплопровода', N'"Тепловая нагрузка на технологичеcкие процессы в открытой  системе  из  подающего  трубопровода" - цифровое поле, значение   которого   соответствует   величине   водоразбора  из подающего   трубопровода   и   принимается   по   типовым    или индивидуальным  проектам  потребителей  тепла  или   назначается пользователем.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2134, N'Потребитель реальный', N'PR', N'txoo', N'СреднНагрТехнОткрОбр', N'Средняя тепл.нагрузка на технологию, обр.труб.', N'Расчетная нагрузка на технологию в открытой системе из обратного теплопровода', N'"Тепловая нагрузка на технологичекие процессы  в открытой  системе  из  обратного  трубопровода" - цифровое поле, значение   которого   соответствует   величине   водоразбора  из подающего   трубопровода   и   принимается   по   типовыи    или индивидуальным  проектам  потребителей  тепла  или   назначается пользователем.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2135, N'Потребитель реальный', N'PR', N'gvop', N'СреднНагрОткрГВПод', N'Средняя тепл.нагрузка на ГВ, подающий теплопровод', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая  нагрузка  горячего  водоснабжения потребителя  в  открытой  системе  из  подающего трубопровода" - цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления.  Величина  среднечасовой нагрузки  принимается  по  типовым  или  индивидуальным проектам систем  горячего  водоснабжения,  выполненным  в  соответствии с требованиями  СНиП для  проектирования  горячего  водоснабжения. Кроме  того, значение  поля  может  быть  получено  на основании анализа фактических данных водоразбора для конкретного теплового пункта. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2136, N'Потребитель реальный', N'PR', N'gvoo', N'СреднНагрОткрГВОбр', N'Средняя тепл.нагрузка на ГВ, обратный теплопровод', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая  нагрузка  горячего  водоснабжения потребителя  в  открытой  системе  из  обратного трубопровода" - цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления.  Величина  среднечасовой нагрузки  принимается  по  типовым  или  индивидуальным проектам систем  горячего  водоснабжения,  выполненным  в  соответствии с требованиями  СНиП для  проектирования  горячего  водоснабжения. Кроме  того, значение  поля  может  быть  получено  на основании анализа фактических данных водоразбора для конкретного теплового пункта. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2137, N'Потребитель реальный', N'PR', N'rez', N'ТеплПотери в рециркулКонтуре', N'Расчетные тепловые потери в рецирк. контуре ГВС', N'Расчетные тепловые потери в рециркуляц. контуре ГВС', N'"Расчетные тепловые потери в рециркуляцинном контуре ГВС"   -  цифровое поле, значение которого определяется тепловыми  потерями   в трубопроводах    циркуляционной  ГВС (Qтп). На практике значение потерь определяют долей от среднечасовой  нагрузки ГВС, т.е.   Qтп=Qср*К, где  К=0.05-0.3. Значение  поля  используется при расчете теплогидравлических режимов тепловых пунктов (ЦТП) только с открытой  ГВС  циркуляционного  типа. Значение   поля   имеет  процентную  размерность и вводится, например, в виде целочисленной  константы  20 (при 20%-ых потерях). Поле заполняется при наличии у данного потребителя рециркуляции.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2138, N'Потребитель реальный', N'PR', N'gvpr', N'СреднНагрПараллГВ', N'Средняя тепл.нагрузка на ГВ, параллельная сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  параллельном включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2139, N'Потребитель реальный', N'PR', N'gvsm', N'СреднНагрСмешГВ', N'Средняя тепл.нагрузка на ГВ, смешанная сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка  на   ГВ потребителя  в  закрытой   системе   при  смешанном   включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2140, N'Потребитель реальный', N'PR', N'gvps', N'СреднНагрПоследГВ', N'Средняя тепл.нагрузка на ГВ последовательная сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  последовательном включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2141, N'Потребитель реальный', N'PR', N'utechp', N'УтечкПодТеплопр', N'Утечка из подающего теплопровода.', N'Заданная утечка из подающего теплопровода', N'"Заданная  утечка  из  подающего  трубопровода" - свойство,  значение  которого  задается  пользователем  исходя   из определенных целей моделирования аварийной ситуации.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2142, N'Потребитель реальный', N'PR', N'utecho', N'УтечкОбрТеплопр', N'Утечка из обратного теплопровода', N'Заданная утечка из обратного  теплопровода', N'"Заданная  утечка  из  подающего  трубопровода" - свойство,  значение  которого  задается  пользователем  исходя   из определенных целей моделирования аварийной ситуации.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2143, N'Потребитель реальный', N'PR', N'kodkv', N'КодКВ', N'Код КВ', N'Код группы коэффициентов вариации', N'"Код  группы  коэффициентов  вариации"  - свойство, значение  которого  однозначно  определяет группу коэффициентов вариации  значений   исходных  данных,   определяющих   вариант гидравлического режима тепловой сети. Значение поля заполняется из определенных целей моделирования ситуации.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2144, N'Потребитель реальный', N'PR', N'prznz', N'ПризнакРасчета ГидрРежЗакрТП', N'Признак  расчета гидр.реж.закрТП', N'Признак расчета гидравл. режима закрытых систем теплопотребл.', N'"Признак  расчета гидравлического режима потребителя с закрытыми системами теплопотребления". При значении свойства "Нагрузка" расчет гидравлического режима потребителя выполняется для заданных нагрузок закрытых систем теплопотребления потребителя.  При значении свойства "Сопротивление" расчет режима выполняется для заданных гидравлических сопротивлений закрытых систем теплопотребления потребителя. Заполнение поля обязательно. По умолчанию устанавливается значение "Нагрузка".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2145, N'Потребитель реальный', N'PR', N'prznp', N'ПризнакРасчетаГидрРежОткрГВСПодТеплопр.', N'Признак расчета гидр.реж.откр ГВС под.теплопр.', N'Признак расчета гидравл. режима открытых ГВС, из подающего трубопровода', N'"Признак  расчета  гидравлического режима потребителя с открытой ГВС, с водоразбором  из подающего теплопровода".  При значении свойства "Нагрузка" расчет гидравлического режима потребителя выполняется для заданной нагрузки ГВС. При значении свойства "Сопротивление" расчет режима выполняется для заданного гидравлического сопротивления ГВС  из  подающего теплопровода. Заполнение поля обязательно. По умолчанию устанавливается значение "Нагрузка".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2146, N'Потребитель реальный', N'PR', N'przno', N'ПризнакРасчетаГидрРежОткрГВСОбрТеплопр.', N'Признак расчета гидр.реж.открГВС обр.теплопр.', N'Признак расчета гидравл. режима открытых ГВС, из обратного трубопровода', N'"Признак  расчета  гидравлического режима потребителя с открытой ГВС, с водоразбором  из обратного теплопровода".  При значении свойства "Нагрузка" расчет гидравлического режима потребителя выполняется для заданной нагрузки ГВС. При значении свойства "Сопротивление" расчет режима выполняется для заданного гидравлического сопротивления ГВС  из  обратного теплопровода. Заполнение поля обязательно. По умолчанию устанавливается значение "Нагрузка".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2147, N'Потребитель реальный', N'PR', N'gsz', N'ГидрСопрЗакрТП', N'Гидр.сопротивл. закр. Систем', N'Гидравл.сопротивление закрыт. системы теплопотребления', N'"Гидравлическое  сопротивление   потребителя  в   закрытой системе"  -   цифровое  поле,  значение   которого представляет  собой    гидравлическое   сопротивление потребителя, определенного как отношение располагаемого  напора в узле присоединения потребителя к квадрату расхода в  закрытой схеме  потребителя  в   данном  гидравлическом  режиме.    Если сопротивление   не определено эксперементальным или расчетным путем, то значение поля не заполняется.  При этом  программные  средства системы  автоматически определяют требуемое значение сопротивления потребителя, при котором  обеспечивается заданный   расчетный   расход   и   осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета и значению "Признака расчета гидравлического сопротивления".  1. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение поля обновляется, если в поле  "Признак расчета гидравлического сопротивления  закрытой системы теплопотребления" выбрано значение "Рассчитанное"  2.Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если в поле "Признак расчета на заданную нагрузку" выбрано значение "Сопротивление".', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2148, N'Потребитель реальный', N'PR', N'gszpr', N'ПризнГидрСопрЗакрТП', N'Признак гид.сопр.закр.ТП', N'Признак расчета гидравл.сопротивл. закр.системы', N'"Признак расчета гидравлического сопротивления в   закрытой системе"  - символьное поле,   значение которого "Заданное"  выбирается пользователем в  том случае, если гидравлическое   сопротивление   потребителя   следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля  задано "Рассчитанное",  то значение поля обновляется при каждом расчете дроссельных устройств реального потребителя.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2149, N'Потребитель реальный', N'PR', N'gsop', N'ГидрСопрОткрПодТП', N'Гидр.сопротивл. откр. ГВС,  подающий трубпр.', N'Гидравл.сопротивление откр. ГВС', N'"Гидравлическое  сопротивление открытой системы ГВ потребителя при водоразборе  из подающего трубопровода"  - цифровое поле,  значение  которого  представляет  собой   гидравлическое сопротивление открытой системы ГВ потребителя, определенное как отношение  разности между  пьезометрическим  напором  в  подающей   трубе  и   напором, соответствующим  атмосферному  давлению в узле присоединения  потребителя,  к  квадрату расхода на ГВ в данном режиме.  Если  сопротивление    не определено эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение сопротивления открытой системы ГВ потребителя, при котором  обеспечивается заданный   расчетный   расход на ГВ  и   осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета и значению "Признака расчета гидравлического сопротивления откр. ГВС".  1. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение поля обновляется, если в поле  "Признак гидравлического сопротивления потребителя" выбрано значение "Рассчитанное"  2.Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если в поле "Признак расчета на заданную нагрузку" выбрано значение "Сопротивление".', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2150, N'Потребитель реальный', N'PR', N'gsoppr', N'ПризнГидрОткрПодТП', N'Признак гид.сопр.под.труб.', N'Признак расчета гидравл.сопротивления откр. ГВС', N'"Признак  гидравлического сопротивления открытой ГВС, при водоразборе из подающего трубопровода"  - символьное поле,   значение которого "Заданное"  выбирается пользователем в  том случае, если гидравлическое сопротивление    открытой системы потребителя при водоразборе  из подающего трубопровода   следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля задано  "Рассчитанное",  то значение поля обновляется при каждом расчете дроссельных устройств реального потребителя.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2151, N'Потребитель реальный', N'PR', N'gsoo', N'ГидрСопрОткрОбрТП', N'Гидр.сопротивл. откр. ГВС,  обратный трубпр.', N'Гидравл.сопротивление открытой ГВС', N'"Гидравлическое  сопротивление открытой системы ГВ потребителя при водоразборе  из обратного трубопровода" - цифровое поле,  значение  которого  представляет  собой   гидравлическое сопротивление потребителя, определенное как отношение  разности между  пьезометрическим  напором  в  обратной   трубе  и   напором, соответствующим  атмосферному  давлению в узле присоединения  потребителя,  к  квадрату  его  расхода в данном режиме.  Если  сопротивление    не определено эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение сопротивления потребителя, при котором  обеспечивается заданный   расчетный   расход   и   осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение поля обновляется, если в поле  "Признак гидравлического сопротивления потребителя" выбрано значение "Рассчитанное".   2.Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если в поле "Признак расчета на заданную нагрузку" выбрано значение "Сопротивление". Заполнение поля обязательно.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2152, N'Потребитель реальный', N'PR', N'gsoopr', N'ПризнГидрОткрОбрТП', N'Признак гид.сопр.обр.труб.', N'Признак расчета гидравл.сопротивления откр. ГВС', N'""Признак  расчета гидравлического сопротивления открытой ГВС, при водоразборе из обратного трубопровода"  - символьное поле,   значение которого "Заданное"  выбирается пользователем в  том случае, если гидравлическое   сопротивление   потребителя в  открытой системе при водоразборе  из обратного трубопровода  следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля задано  "Рассчитанное",  то значение поля обновляется при каждом расчете дроссельных устройств реального потребителя.  Заполнение поля обязательно.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2153, N'Потребитель реальный', N'PR', N'a13', N'СтупДросс', N'Ступень дросс.', N'Признак ступени дросселирования', N'"Признак ступени дросселирования" - свойство,  определяющее принятый пользователем способ расстановки дроссельных органов  в узлах присоединения теплопотребляющих систем теплового пункта на основе   принципа   ступенчатости   дросселирования  избыточного напора.   Значение  свойства "1"  означает  выбор  одноступенчатого способа  дросселирования  избыточного  напора, когда дроссельные органы   для   теплопотребляющих    систем   теплового    пункта рассчитываются   на   весь   располагаемый   напор.   В   случае элеваторного   присоединения   системы   отопления   дроссельная диафрагма  на  входе  системы  отопления  может  появиться   при значительных располагаемых напорах,  когда сопло элеватора  не в состоянии  обеспечить  гашение  избыточного  напора.   В  случае теплового  пункта   с  последовательной   схемой   присоединения подогревателей  ГВС  дроссельная  диафрагма  при   необходимости гашения   избыточного    напора   устанавливается    на    входе подогревателя ГВС второй  ступени.  Как  сопло элеватора, так  и упомянутая  диафрагма  раcсчитываются  на  суммарный   расчетный расход  отопления  и  ГВС  в случае отопительного температурного графика  и  только  на  расчетный  расход  отопления  - в случае повышенного температурного  графика. 
  Значение    свойства    "2"   означает    выбор    двухступенчатого дросселирования,  когда устанавливается  и  раcсчитывается общая головная дроссельная  диафрагма для  теплового пункта  и входные диафрагмы для его отдельных теплопотребляющих систем  (отопление, вентиляция, ГВС  и т.  д.). При  этом расчетный  расход головной диафрагмы определяется как средневзвешенный расход из  расчетных расходов отдельных теплоснабжающих систем теплового пункта.  Для потребителей  с  последовательным  присоединением подогревателей ГВС входная диафрагма на  входе подогревателя второй ступени  не раcсчитывается, так как ее роль выполняет головная диафрагма. 
  Значение    свойства    "3"   означает    выбор    двухступенчатого дросселирования, при котором гасимый напор на головной диафрагме рассчитывается   как   разность   между   располагаемым  напором теплового пункта  и минимально  необходиным напором  для системы отопления   с    элеваторным   присоединением.    Для   ГВС    с последовательной   схемой   присоединения   потребителей    роль диафрагмы  на  входе   подогревателей  второй  ступени   играет головная диафрагма. При  этом сопло элеватора раcсчитывается  на суммарный расчетный расход на  отопление и ГВС при  отопительном температурном   графике.   Область   применения   этого  способа дросселирования  -  тепловые  пункты  с  разнородной нагрузкой и элеваторным присоединением систем  отопления. 
  Значение   свойства   "4"  означает   выбор  специального   способа дросселирования   потребителя   с   открытой   нагрузкой    ГВС, подключенной к ЦТП по 4-х трубной схеме.  Обычно нагрузка ГВС  у таких потребителей  подключена по  двум отдельным  трубам, т. е. гидравлически развязана с  нагрузками отопления и  вентиляции, а внутренняя   разводка   сети   ГВС   выполнена   по   схеме    с посекционно-закольцованными стояками  ГВС внутри  секций здания. Нагрузка ГВС таких потребителей  должна описываться в строке  ПТ (поле 19 "Тепловая нагрузка или расход на ГВС в открытой системе из    подающего    трубопровода",   а    обязательная   нагрузка циркуляционного  (обратного)  трубопровода   сети   ГВС   должна описываться   в   поле  21  "Тепловая  нагрузка  на  компенсацию тепловых потерь в трубопроводах циркуляционной ГВС ". Циркуляционная   нагрузка  таких  потребителей замыкается обычно через полотенцесушители,которые по сути выполняют роль отопления ванных помещений.Отопительная нагрузка полотенцесушителей здания должна учитывать  тепловые  потери как  в полотенцесушителях,так и   потери  всеми   трубопроводами   сети   ГВС. Значение поля - безразмерная величина. 
  Значение   свойства  "5"  означает   выбор   специального  способа дросселирования    потребителей  с   открытой   нагрузкой   ГВС, подключенной к ЦТП по 4-х трубной схеме(аналогично значению поля "4").  Как  и  в  предыдущем   случае   нагрузка   подающего   и циркуляционного трубопроводов описывается в полях 19 и 21 строки ПТ. Однако, в  отличии  от  предыдущего варианта дросселирования дроссельная   диафрагма   расситывается  только  на  ограничение циркуляционного   расхода    и   устанавливается   на   обратном (циркуляционном) трубопроводе сети ГВС, выполняя  одновременно и подпорные функции.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2154, N'Потребитель реальный', N'PR', N'a15', N'МинДиамДросс', N'Мин.диам.дрос.диафр.', N'Диаметр дроссельной диафрагмы минимально допустимый', N'"Диаметр дроссельной диафрагмы минимально допустимый" - свойство,   определяющее   требования   к   минимальному    диаметру рассчитываемой   шайбы,   исходя   из   исключения   возможности засорения, вибрации и шума при работе теплопотребляющих  систем. Заполнение поля обязательно при расчете дроссельных диафрагм. По  умолчанию начальное значение принимается равным 3 мм .', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2155, N'Потребитель реальный', N'PR', N'a14', N'МинДиамСоплЭлев', N'Мин.диам.сопла элеват.', N'Диаметр сопла элеватора минимально допустимый', N'"Диаметр сопла элеватора минимально допустимый" - свойство, определяющее требования к минимальному диаметру  рассчитываемого сопла  исходя  из  исключения  возможности засорения, вибрации и шума при работе элеватора. Заполнение поля обязательно при расчете дроссельных диафрагм.  По умолчанию начальное значениепринимается равным 3 мм .', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2156, N'Потребитель реальный', N'PR', N'a17', N'ТемпГраф', N'Темп.график', N'Признак температурного графика', N'"Признак температурного графика" - свойства, определяющее температурный  график, на котором  работает  потребитель тепла, и служит   для   корректного   использования   нагрузки   ГВС  при последовательной  схеме  присоединения  горячего   водоснабжения потребителя. Заполнение поля обязательно при расчете дроссельных диафрагм.  Значение  свойства  "Отопительный" определяет отопительный график работы потребителя, значение "Повышенный" - повышенный график.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2157, N'Потребитель реальный', N'PR', N'pr_sopr', N'ГидрСопрФактРеж', N'Расчет сопротивления факт.режима', N'Метод расчета сопротивления в фактическом режиме', N'"Метод расчета гидравлического сопротивления" - свойство, значение которого определяет метод расчета гидравлического сопротивления теплопотребляющих систем теплового пункта при расчете фактического режима сети, при значении поля "Режим", гидравлическое сопротивление соответствующей системы теплопотребления теплового пункта производится через параметры расчетного режима (расчетный расход и расчетное падение напора),  при значении поля "Оборудование"- через конструктивные  размеры установленного оборудования (этот режим в данной версии не реализован).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2158, N'Потребитель реальный', N'PR', N'pr_teplo', N'ТеплопотрФактРеж', N'Расчет теплопотребл. факт.режима', N'Метод расчета тепловой нагрузки в фактическом режиме', N'"Метод расчета тепловой нагрузки" - свойство, значение которого определяет метод расчета теплового режима теплопотребляющих систем теплового пункта, при значении свойства "Режим" расчет режимных коэффициентов теплообменных аппаратов определяется точно только для одного произвольно выбранного режима, для систем горячего водоснабжения - это температура наружного воздуха, соответствующая нижней точке излома температурного графика, для систем отопления - это расчетная температура наружного воздуха для отопления. При всех других режимов работы аппаратов режимный коэффициент определяется по методике предложенной Соколовым Е.Я.  Расчет тепловой нагрузки производится через значения параметров расчетного режима данной системы теплопотребления. При значении свойства "Оборудование" - расчет режимных коэффициентов теплообменных аппаратов производися через конструктивные размеры установленного оборудования систем теплопотребления (этот режим в данной версии не реализован). Заполнение поля обязательно. По умолчанию установлено значение "Режим".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2159, N'Потребитель реальный', N'PR', N'a7', N'РасПотНапСО', N'Расч.потери напора в СО (подогр.)', N'Расчетные потери напора в отопит.системе (подогревателе)', N'"Расчетные потери  напора в  отопительной сети  или отопительном подогревателе" - свойство, определяющее значение  расчетных потерь  напора  на  гидравлическом  тракте системы отопления при зависимом   присоединении   или    на   гидравлическом    тракте отопительного  подогревателя   при  независимом   присоединении.  Заполнение поля обязательно. Начальное значение поля по умолчанию принимается равным 1.5 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2160, N'Потребитель реальный', N'PR', N'a8', N'РасПотНапКУ', N'Расч.потери напора в КУ', N'Расчетные потери напора в калориферах', N'"Расчетные  потери  напора  в  калориферах  "  -  свойство, определяющее  значение  потерь  напора  на гидравлическом тракте калориферов  присоединенной  калориферной  установки в расчетном режиме.  Заполнение поля обязательно. Начальное значение поля по умолчанию принимается равным 5 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2161, N'Потребитель реальный', N'PR', N'a9', N'РасПотНапКонд', N'Расч.потери напора на конд.', N'Расчетные потери напора в кондиционерах', N'"Расчетные  потери  напора  в  кондиционерах"  - свойство, определяющее  значение  потерь  напора  на гидравлическом тракте кондиционеров  присоединенной  установки  для  кондиционирования воздуха в  расчетном режиме. Заполнение поля обязательно. Начальное  значение  поля  по  умолчанию принимается равным 6 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2162, N'Потребитель реальный', N'PR', N'a10', N'РасПотНапПодТрубГВ', N'Расч.потери напора в под.труб.откр.ГВ', N'Расч.потери напора в подающем трубопроводе ГВС', N'"Расчетные потери напора в подающем трубопроводе  открытой системы ГВС"  -  свойство,  определяющее  расчетные  потери напора сетевой воды в подающем трубопроводе сети открытой ГВС теплового пункта.  Заполнение поля обязательно. Начальное значение поля по умолчанию принимается равным 3 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2163, N'Потребитель реальный', N'PR', N'a11', N'РасПотНапЦиркТрубГВ', N'Расч.потери напора в цирк.труб.отк.ГВС', N'Расчетные потери напора в циркул. трубопроводе ГВС', N'"Расчетные потери напора в циркуляционном трубопроводе открытой системы  ГВС"  - свойство, определяющее расчетные потери напора сетевой воды в циркуляционном трубопроводе сети  открытой ГВС теплового пункта. Заполнение поля обязательно. Начальное  значение  поля  по  умолчанию  принимается  равным  4 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2164, N'Потребитель реальный', N'PR', N'a12', N'РасПотНапПриборГВ', N'Расч.напор на вх.водоразб.приборов', N'Расчетный напор на входе водоразборных приборов', N'"Расчетный  напор  на  входе  водоразборных приборов" - свойство,  определяющее  ограничение  напора  сетевой  воды  в  сети открытой  ГВС  на  входе  водоразборных  приборов.   Ограничение регламентируется   СНИП   2.04.01.85   "Внутренний  водопровод". Заполнение поля обязательно. По умолчанию начальное значение принимается равное 25 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2165, N'Потребитель реальный', N'PR', N'a18', N'КолПодогр1стГВ', N'Кол.вкл.подогрев.1 ст.ГВ', N'Число параллельно включенных подогревателей 1 ступени', N'"Число параллельно включенных подогревателей 1-ой ступени ГВС" - свойство,    определяющее   количество    подогревателей, включенных параллельно в 1-ую ступень нагрева водопроводной воды с  целью  повышения  теплопроизводительности. Заполнение поля обязательно. Начальное значение поля  по умолчанию принимается равным 1, что означает один включенный подогревателей в первой ступени.', NULL, N'штук(и)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2166, N'Потребитель реальный', N'PR', N'a19', N'КолПодогр2стГВ', N'Кол.вкл.подогрев.2 ст.ГВ', N'Число параллельно включенных подогревателей 2 ступени', N'"Число параллельно включенных подогревателей 2-ой ступени ГВС" - свойство,    определяющее   количество    подогревателей, включенных параллельно в 2-ую ступень нагрева водопроводной воды с  целью  повышения  теплопроизводительности. Заполнение поля обязательно. Начальное значение поля  по умолчанию принимается равным 1, что означает один включенный подогревателей в первой ступени.', NULL, N'штук(и)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2167, N'Потребитель реальный', N'PR', N'a19_co', N'КолПодогрСОнез', N'Кол.вкл.подогрев.незав.СО', N'Число параллельно включенных подогревателей СО', N'"Число параллельно включенных подогревателей независимой системы отопления" -  свойство,    определяющее   количество    подогревателей, включенных параллельно для нагрева местной воды системы отопления с  целью  повышения  теплопроизводительности. Заполнение поля обязательно. Начальное значение поля  по умолчанию принимается равным 1, что означает один включенный подогревателей.', NULL, N'штук(и)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2168, N'Потребитель реальный', N'PR', N'a22', N'РасПотНап1стГВ', N'Расч.потери напора на 1 ст.ГВ', N'Расчетные потери напора на подогревателе 1-ой ступени ГВС', N'"Расчетные потери напора на одном подогревателе 1-ой ступени"  - свойство, определяющее расчетные потери напора на одном  из нескольких параллельно включенных подогревателей 1-ой ступени  в закрытой  ГВС  при  расчетном   расходе. Заполнение поля обязательно.  Начальное  значение  поля по умолчанию принимается равным 4 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2169, N'Потребитель реальный', N'PR', N'a23', N'РасПотНап2стГВ', N'Расч.потери напора на 2 ст.ГВ', N'Расчетные потери напора на подогревателе 2-ой ступени ГВС', N'"Расчетные потери напора на одном подогревателе 2-ой ступени"  - свойство, определяющее расчетные потери напора на одном  из нескольких параллельно включенных подогревателей 2-ой ступени  в закрытой  ГВС  при  расчетном   расходе. Заполнение поля обязательно.  Начальное  значение  поля по умолчанию принимается равным 4 м.вод.ст.', N'Напор', NULL)

