INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2170, N'Потребитель реальный', N'PR', N'Tr_tv_co', N'РасчТемпВнПомещ', N'Расч.темп. в отапл.помещениях', N'Расчетная температура в отапливаемых помещений', N'"Расчетная температура воздуха в отапливаемых помещений" - определяется
  значением   температуры  воздуха  в отапливаемых  помещениях,
  исходя из норм допустимых комфотных условий по СНиП 2.04.05-91.
  Отопление, вентиляция и кондициониpование воздуха. Заполнение поля обязательно.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2171, N'Потребитель реальный', N'PR', N'Tr_tv_cv', N'РасчТемпНагрВоздВент', N'Расч.темп.нагр.возд.после КУ', N'Расчетная температура нагретого воздуха после КУ', N'"Расчетная температура нагретого воздуха  в системе вентиляции или воздушного  отопления" - определяется  значением   температуры  воздуха  в отапливаемых  помещениях,  исходя из норм допустимых комфотных условий по СНиП 2.04.05-91.  Отопление, вентиляция и кондициониpование воздуха. Заполнение поля обязательно.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2172, N'Потребитель реальный', N'PR', N'Tr_gvs', N'Тгор_расчГВ', N'Расч.темп.горячей воды', N'Расчетная температура горячей воды', N'"Расчетная температура горячей воды " -  числовое поле, значение которого определяет температуру бытовой горячей воды по выходу ее из подогревательных установок, нижнее и верхнее значение которой pегламентиуется тpебованиями СНиП 2.04.01-85: не ниже 60 Гpад.С в ГВС,
пpисоединеных    к   откpытым системам    теплоснабжения;
не ниже  50  Гpад.С , пpисоединенных  к закpытым системам
теплоснабжения и не выше 75 Град.С для всех вышерассмотренных случаев. Для уменьшения циркуляционной воды температуру бытовой воды по выходе ее из подогревательных установок рекомендуется принимать равной в закрытых системах 50+10=60 Град.С, в открытых 60+5= 65 Град.С. Где 5-10 охлаждение циркуляционной воды в водоразборных стояках  многоэтажных зданий по системе в целом. Заполнение поля обязательно.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2173, N'Потребитель реальный', N'PR', N'gvs_max', N'Кч', N'Коэффициент часовой неравномерности нагрузки горячего водоснабжения', N'Коэфф.часовой неравномерности нагрузки горячего водоснабжения', N'"Коэффициент часовой неравномерности нагрузки горячего водоснабжения" - цифровое поле, значение которого определяет коэффициент часовой неравномерности (kч) расхода тепла за сутки наибольшего водопотребления.  Значение этого поля используется при расчете максимального расхода тепла на горячее водоснабжение жилых зданий, гостиниц, больниц и т.д.: Qгвс_макс=kч*Qгвс_средн.  При определении расхода тепла на горячее  водоснабжение микрорайонов (кварталов) городов kч= 1.7 - 2.2, промышленных предприятий kч= 1. При отсутствии данных о назначении общественных зданий допускается определении коэффициента часовой неравномерности условное количество жителей принимать с коэффициентом 1.2. Заполнение поля обязательно.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2174, N'Потребитель реальный', N'PR', N'a24', N'УдОбъемСО', N'Удельный  объем  воды  в  системе  отопления', N'Удельный объем воды в системе отопления', N' "Удельный объем воды в системе отопления" - числовое поле, значение которого определяет удельный объем воды в системе отопления в зависимости от расчетного температурного перепада и типа отопительных приборов.  При расчете нормируемых тепловых потерь с утечкой заполнение поля обязательно.  Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2175, N'Потребитель реальный', N'PR', N'a25', N'УдОбъемВент', N'Удельный  объем  воды  в  системе  вентиляции', N'Удельный объем воды в системе вентиляции', N'"Удельный объем воды в системе вентиляции" - числовое поле, значение которого определяет удельный объем воды в отопительно-вентиляционной системе, оборудованной калориферами, в зависимости от расчетного температурного перепада. При расчете нормируемых тепловых потерь с утечкой заполнение поля обязательно. Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2176, N'Потребитель реальный', N'PR', N'pr_avtomat', N'СтепеньАвтом', N'Степень автоматизации: А-автоматизированный, Ч-частично автоматизированный, Н-неавтоматизированная', N'Степень автоматизации', N'Степень автоматизации: А-автоматизированный, Ч-частично автоматизированный, Н-неавтоматизированная', NULL, NULL)
