INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2259, N'Потребитель реальный', N'PR', N'operator', N'ОператорАрх', N'Оператор архивации', N'Оператор архивации', N'Оператор архивации', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2260, N'Потребитель реальный', N'PR', N'kod_p', NULL, N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения потребителя.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2261, N'Потребитель реальный', N'PR', N'uzel_p', NULL, N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2262, N'Потребитель реальный', N'PR', N'pr_p', NULL, N'Признак теплопровода узла присоединения', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2263, N'Потребитель реальный', N'PR', N'otopl_tp', N'Q_тепловыд', N'Расчетные внутренние тепловыделения', N'Расчетные внутренние тепловыделения', N'"Расчетные внутренние тепловыделения" - цифровое  поле, значение которого используется при определении расчетного часового расхода тепла на отопление отдельного здания Q = 1.1(Qн.о + Qв - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания, Qв - тепло, затрачиваемое на вентиляцию  ( на подогре вентиляционного воздуха),  Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Заполняется при наличии у теплового пункта внутренних тепловыделений.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2264, N'Потребитель реальный', N'PR', N'uf', N'ФактКоэфСмеш', N'Коэффициент  смешения  элеватора', N'Коэффициент  смешения  элеватора', N'"Коэффициент  смешения  элеватора"  -  цифровое  поле,   значение которого однозначно определяется температурным графиком  сетевой воды,  установленным  для  системы  отопления реального потребителя.   Как   известно, коэффициент  смешения   элеватора  U   определяется  с   помощью следующих выражений:   1.   U=Gп/Gс, где  Gп -  массовый  расход подмешиваемой воды, т/ч; Gс - массовый расход воды, потребляемой из сети на  систему отопления, т/ч;  2.  U=(t1-t3)/(t3-t2),  где t1, t2 - соответственно,  температура сетевой воды в  подающем и обратном  трубопроводах  теплового  пункта;  t3  -   температура смешанной воды,  поступающей в  систему отопления.  Для типового температурного графика  сетевой воды  150-70 Град.С  и графика - подмешанной воды 95-70  Град.С коэффициент смешения  принимается равным  U=2.2.  Это  значение  принимается  в качестве исходного значения  этого  поля  по  умолчанию. После расчета теплогидравлического режима, пользователям программы, предлагается обновить значение данного поля, на скорректированное, рассчитанное на полученный температурный перепад на входе данного теплового пункта.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2265, N'Потребитель реальный', N'PR', N'kodtr', N'КодРасТемп', N'Код расчетных температур', N'Код расчетных температур', N'"Код  расчетных температур"  - символьное  поле, значение которого однозначно определяет группу расчетных температур и температур в точке излома температурного графика теплоносителя, наружного воздуха, нагреваемой водопроводной воды, предназначенных для расчета коэффициентов темплопередачи приборов отопления, вентиляции,  теплообменных аппаратов закрытых систем горячего водоснабжения. Заполнение поля обязательно.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2266, N'Потребитель реальный', N'PR', N'gvpw', N'СреднНагрПредвклГВ', N'Средняя тепл.нагрузка на ГВ, предвключ.сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  предвключенном включении подогревателя  ГВ"   -  цифровое   поле,  значение    которого соответствует среднедельной часовой тепловой нагрузке  на ГВ для указанной схемы включения подогревателей  и назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима. Заполнение поля обязательно.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2267, N'Потребитель реальный', N'PR', N'Gneob', N'НеобхРасполНапор', N'НеобхРасполНапор', N'Необходимый располагаемый напор', N'"Необходимый располагаемый напор (Нр)" -  цифровое   поле, значение    которого определяет величину располагаемого напора на входе данного теплового пункта, необходимого для его теплообеспечения. Значение поля используется при анализе режима работы теплового пункта. По умолчанию,  для зависимых безэлеваторных систем отопления Нр принимается равным 6 м.вод.ст, для для зависимых элеваторных систем отопления Нр=1.4*h*(1+Uф) м.вод.ст., где h-расчетные потери напора на трубопроводной сети системы отопления, для независимых систем отопления Нр=10 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2268, N'Потребитель реальный', N'PR', N'kod_cekz_p', N'КодCекцПотребителя', N'Код секционированного потребителя', N' Краткое содержательное наименование секционированного потребителя', N'Код секционированного потребителя, символьное поле, определяющее краткое содержательное наименование секционированного потребителя. Значение поля поля используется для указания принадлежности зависимой системы отопления секционированному потребителю.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2269, N'Потребитель реальный', N'PR', N'kod_gvs', N'График нагрузки ГВ', N'Код суточного графика нагрузки ГВ', N'Код графика суточного нагрузки ГВ', N'Код графика нагрузки ГВ, символьное поле, определяющее краткое наименование суточного графика нагрузки горячего водоснабжения потребителя. Суточный график нагрузки горячего водоснабжения используется при расчете режима (анализирующего) системы, по результатам которого рассчитываются отклонения фактических (измеренных) значений параметров режима в контрольных точках расчетной схемы системы теплоснабжения. Для открытых систем горячего водоснабжение значение "Балансовая нагрузка" не используется, по умолчанию она будет приравнена средней нагрузке  горячего водоснабжения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2270, N'Потребитель реальный', N'PR', N'pP_fact', N'ИзмерДавление', N'Измеренное давление на подающем теплопроводе', N'Измеренное давление на подающем теплопроводе', N'Измеренное давление на подающем теплопроводе. Значение поля используется при построении пьезометрического графика, по направлению в состав которого входит и данный узел.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2271, N'Потребитель реальный', N'PR', N'pO_fact', N'ИзмерДавление', N'Измеренное давление на обратном теплопроводе', N'Измеренное давление на обратном теплопроводе', N'Измеренное давление на обратном теплопроводе. Значение поля используется при построении пьезометрического графика, по направлению в состав которого входит и данный узел.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2272, N'Потребитель реальный', N'PR', N'pr_shaibi', N'Признак  шайбы в потребитель', N'Признак  шайбы в потребитель Р -разрешить, Н-нельзя записывать', N'Признак  записи шайбы в потребитель', N'Признак записи (сохранения) рассчитанных диаметров (сопротивлений) дроссельных устройств  данного потребителя: "Разрешить"  - запись разрешить, "Нельзя записывать" -запись запрещена, в данном случае предполагается, что диаметры дроссельных устройств при расчете Фактического режима задаются, отличные от рассчитанных в Плановом режиме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2273, N'Потребитель реальный', N'PR', N'pr_avar_TP', N'Признак расчета аварийного режима потребителя', N'Признак расчета аварийного режима потребителя', N'Признак расчета аварийного режима потребителя', N'"Признак расчета гидравлического режима потребителя в аварийном режиме"- значение поля может принимать следующие значения: "Шайбы" - через установленные (рассчитанные) дроссельные устройства, "Регулятор перепада"-через регулятор перепада давления, "Сопротивления" - через гидравлическое сопротивления потребителя, "Нагрузки" - через заданные тепловые нагрузки. Заполнение поля обязательно.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2274, N'Потребитель реальный', N'PR', N'pr_per_PD', N'Место установки клапана перепада напора', N'Место установки клапана перепада напора: П- подача, О- Обратка', N'Место установки клапана перепада напора', N'Место установки клапана перепада напора - значение поля может принимать два значения:  "Подача"- клапан перепада напора уставлен на подающем трубопроводе на входе теплового пункта, "Обратка"- клапан перепада давления уставлен на обратном трубопроводе на выходе теплового пункта. Заполнение поля обязательно при значении поля "Признак расчета гидравлического режима потребителя в аварийном режиме" равном "Регулятор перепада".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2275, N'Потребитель реальный', N'PR', N'p_per_PD', N'Заданный перепад напора на регуляторе', N'Заданный перепад напора на регуляторе', N'Заданный перепад напора на регуляторе', N'"Заданный перепад напора на регуляторе" - числовое поле, определяет значение перепада напора, поддерживаемое регулятором  перепада на входе теплового пункта.  Заполнение поля обязательно при значении поля "Признак расчета гидравлического режима потребителя в аварийном режиме" равном "Регулятор перепада".', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2276, N'Потребитель реальный', N'PR', N'memo', N'Комментарий', N'Комментарий', N'Комментарий', N'"Поле комментария" -  символьное поле, содержащее произвольный текст, позволяющий пользователю конкретизировать назначение данных, зафиксировать выполненные изменения в описании расчетной схемы и т.п.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2277, N'Потребитель реальный', N'PR', N'gszl', N'ГидрСопр,лето', N'Гидр.сопротивл.потребителя в летний период', N'Гидравл.сопротивление потребителя в летний перид', N'"Гидравлическое сопротивление потребителя в летний период"  -   цифровое поле, значение которого представляет собой гидравлическое   сопротивление  реального потребителя  в летний период.  Если сопротивление   не определено эксперементальным или расчетным путем, то значение поля не заполняется.  При этом  программные  средства системы  автоматически определяют  значение сопротивления  реального потребителя в летний период, как сумму  гидравлических сопротивлений  технологических элементов, по тракту движению потока теплоносителя до приборов водоразбора в системе горячего водоснабжения, определяемую  при Плановом отопительном режиме. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима,  значение поля обновляется, если в поле  "Признак расчета на заданное сопротивление закрытой системы теплопотребления" выбрано значение "Рассчитанное"', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2278, N'Потребитель реальный', N'PR', N'pr_uchet', N'Признак прибора учета', N'Признак установки прибора учета', N'Признак установки прибора учета', N'"Признак установки прибора учета"- значение поля может принимать два значения: "Установлен" - прибор учета тепловой энергии (расхода сетевой воды) у данного потребителя установлен. "Не установлен" - прибор учета расхода воды у данного потребителя не установлен. Значение поля используется для классификации потребителей (с приборами учета/без приборов учета) в расчете нормируемых тепловых потерь с утечкой.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2279, N'Потребитель реальный', N'PR', N'T_pot_rez', NULL, N'Температура в рециркуляционном трубопроводе ГВС', N'Температура в рециркуляционном трубопроводе ГВС', N'"Температура в рециркуляционном трубопроводе открытой ГВС"- цифровое поле, которое определяет температуру (Тост), до которой допустимо остывание сетевой воды в рециркуляционном трубопроводе ГВС за счет тепловых потерь, при нулевой нагрузке ГВС, т.е. отсутствии водоразбора.  Значение поля  используется для определения расхода сетевой воды на рециркуляцию в открытых системах горячего водоснабжения.  Численное значение расхода  на рециркуляцию принимается  равным Gрец=Qтп/(dt*с), где dt=((Тг-Тх)-Тост), где Тг - температура горячей воды в системе горячего водоснабжения с непосредственным водоразбором, Тх - температура водопроводной воды, Qтп - тепловые потери в рециркуляционном контуре. Допустимое  остывание воды   рециркуляционном контуре  обычно  принимают  из  диапазона  30-50  Град.  С', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2280, N'Потребитель реальный', N'PR', N'G_otoplz', N'РасчРасходСОзав', N'Расчетный расход на  отопление, зав.СО', N'Расчетный расход на  отопление', N' "Расчетный расход на  отопление, зависимая схема"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на  отопление при зависимой схеме включения системы отопления потребителя, определяемое с учетом  заданной расчетной тепловой нагрузки (Гкал/ч) на отопление и фиксированного расчетного  температурного  перепада  теплоносителя  (Град.С)  (с учетом или без учета тепловых потерь).  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на отопление  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2281, N'Потребитель реальный', N'PR', N'G_otopln', N'РасчРасходСОнезав', N'Расчетный расход на  отопление, незав.СО', N'Расчетный расход на  отопление', N' "Расчетный расход на  отопление, независимая схема"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на  отопление при независимой схеме включения системы отопления потребителя, определяемое с учетом  заданной расчетной тепловой нагрузки (Гкал/ч) на отопление и фиксированного расчетного  температурного  перепада  теплоносителя  (Град.С)  (с учетом или без учета тепловых потерь).  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на отопление  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2282, N'Потребитель реальный', N'PR', N'G_ventil', N'РасчРасходВентил', N'Расчетный расход на  вентиляцию', N'Расчетный расход на  вентиляцию', N' "Расчетный расход на  вентиляцию"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на  отопление, определяемое с учетом  заданной расчетной тепловой нагрузки (Гкал/ч) на вентиляцию и фиксированного расчетного  температурного  перепада  теплоносителя  (Град.С)  (с учетом или без учета тепловых потерь).  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на ветиляцию  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2283, N'Потребитель реальный', N'PR', N'G_kondiz', N'РасчРасходКондицион', N'Расчетный расход на  кондиционирование', N'Расчетный расход на  кондиционирование', N' "Расчетный расход на кондиционирование"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на кондиционирование потребителя, определяемое с учетом  заданной расчетной тепловой нагрузки (Гкал/ч) на кондиционирование и фиксированного расчетного  температурного  перепада  теплоносителя  (Град.С)  (с учетом или без учета тепловых потерь).  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на кондиционирование  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
