INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2286, N'Потребитель реальный', N'PR', N'G_rez', N'РасчРасходРециркулГВСоткрыт', N'Расчетный расход на рецирк., откр.ГВС', N'Расчетный расход на рециркуляцию в открытой ГВС', N' "Расчетный расход на рециркуляцию в открытой ГВС"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход в  рециркуляционном трубопроводе открытой системы горячего водоснабжения.  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на рециркуляцию в открытой системе ГВ  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2287, N'Потребитель реальный', N'PR', N'G_gvpr', N'РасчРасходГВСпаралл.', N'Расчетный расход на ГВС, параллельная', N'Расчетный расход на горячее водоснабжение', N' "Расчетный расход на ГВС, при параллельной схеме включения"-  цифровое поле,  значение  которого  представляет  собой  расчетный расход на горячее водоснабжение при при параллельной схеме включения подогревателей горячего водоснабжения.  Если  расчетный расход   не определен эксперементальным или расчетным путем,  то  значение поля не заполняется.   При этом  программные  средства системы  автоматически определяют требуемое значение расчетного значения расхода на горячее водоснабжение в закрытой системе ГВ  и  осуществляют   запись по указанию, выполненному   в   процессе  настройки запуска расчета.  1. При повторных  расчетах  новых вариантов планового гидравлического режима  значение поля обновляется, если в поле  "Признак расчетного расхода потребителя" выбрано значение "Рассчитанное".   2. Если в поле  "Признак расчетного расхода потребителя" выбрано значение "Заданное", то предполагается, что значение данного поля вводится в "ручную" и не обновляется в процессе расчета планового режима, т.е. при значении поля  "Признак расчетного расхода потребителя"  - "Заданное", заполнение данного поля обязательно.', N'Расход', NULL)
