INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2306, N'Потребитель реальный', N'PR', N'f_gvsm', N'ДоговорНагрСмешГВ', N'Договор.средняя нагрузка на ГВ,  смешанная сх.', N'Договорная средняя нагрузка на ГВ', N'"Договорная  среднечасовая  тепловая   нагрузка  на   ГВ потребителя  в  закрытой   системе   при  смешанном   включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается исходя из договорных обязательств с данным потребителем или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
