INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2308, N'Потребитель реальный', N'PR', N'f_gvpw', N'ДоговорПредвклГВ', N'Договор.средняя тепл.нагрузка на ГВ, предвключ.сх.', N'Договорная средняя нагрузка на ГВ', N'"Договорная среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  предвключенном включении подогревателя  ГВ"   -  цифровое   поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается   исходя из договорных обязательств с данным потребителем или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2309, N'Потребитель реальный', N'PR', N'f_otopl_tp', N'Q_тепловыд', N'Договор ВнутрТепловыделения', N'Договорные внутренние тепловыделения', N'"Договорные внутренние тепловыделения" - цифровое  поле, значение которого используется при определении расчетного часового расхода тепла на отопление отдельного здания Q = 1.1(Qн.о + Qв - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания, Qв - тепло, затрачиваемое на вентиляцию  ( на подогре вентиляционного воздуха),  Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Заполняется при наличии у теплового пункта внутренних тепловыделений. Договорные  внутренние тепловыделения  назначаются исходя из договорных обязательств с данным потребителем или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Договорная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2310, N'Потребитель реальный', N'PR', N'k_akkuml', N'Коэффициент аккумуляции здания', N'Коэффициент аккумуляции здания', N'Коэффициент аккумуляции здания', N'"Коэффициент аккумуляции здания" - цифровое поле, значение которого  используется при расчета времени замерзания теплоносителя в системах отопления здания, при прекращена в него подачи тепла. Рекомендуется использовать функцию поля. Значения коэффициентов аккумуляции зданий в функции поля соответствуют МДС МДС 41-6.2000 РАО "Роскоммунэнерго".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2311, N'Потребитель реальный', N'PR', N'p_otoplz', N'ПерспектНагрСОзав', N'Перспективнаянагрузка на отопление, зав.СО', N'Перспективная тепловая нагрузка на  отопление', N' "Перспективная тепловая  нагрузка на  отопление,  зависимая схема"- цифровое поле, значение которого  назначается исходя из договорных обязательств с данным потребителем  по ТУ или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2312, N'Потребитель реальный', N'PR', N'p_otopln', N'ПерспектНагрСОнезав', N'Перспективная нагрузка на отопление, незав.СО', N'Перспективная тепловая нагрузка на  отопление', N'"Перспективная расчетная тепловая  нагрузка на отопление, независимая схема"- цифровое поле, значение которого   назначается исходя из договорных обязательств с данным потребителем по ТУ или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2313, N'Потребитель реальный', N'PR', N'p_otn_fs', N'ПерспектОтнНагрУлФас', N'Перспенкт.отн.нагрузка уличного фасада', N'Перспективная относит. нагрузка уличного фасада', N'"Перспективная относительная нагрузка уличного  фасада" - цифровое  поле, значение  которого  определяется  отношением  тепловой  нагрузки на  отопление уличного  фасада потребителя  к тепловой нагрузке  на  отопление  потребителя  в целом (Qул.ф/Qздания)  и  задается  пользователем  для  потребителей с пофасадным  распределением   нагрузки  отопления   при   наличии потребности расчета  дросельных регулирующих  устройств отдельно на  уличный  и  дворовой  фасады  потребителя. Значение поля задается   исходя из договорных обязательств с данным потребителем по ТУ или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', NULL, N'%')
