INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2321, N'Потребитель реальный', N'PR', N'p_gvpr', N'ДоговорНагрПараллГВ', N'Перспект.средняя нагрузка на ГВ, параллельная сх.', N'Перспективная средняя нагрузка на ГВ', N'"Перспективная  среднечасовая  тепловая   нагрузка   на   горячее водоснабжение потребителя  в  закрытой  системе   при  параллельном включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Значение поля  назначается исходя из договорных обязательств с данным потребителем по ТУ или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2322, N'Потребитель реальный', N'PR', N'p_gvsm', N'ПерспектНагрСмешГВ', N'Перспект.средняя нагрузка на ГВ,  смешанная сх.', N'Перспективная средняя нагрузка на ГВ', N'"Перспективная среднечасовая  тепловая   нагрузка  на   ГВ потребителя  в  закрытой   системе   при  смешанном   включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается исходя из договорных обязательств с данным потребителем по ТУ или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2323, N'Потребитель реальный', N'PR', N'p_gvps', N'ПерспектНагрПоследГВ', N'Перспект.средняя нагрузка на ГВ, последовательная сх.', N'Перспективная средняя нагрузка на ГВ', N'"Перспективная  среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  последовательном включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается  исходя из договорных обязательств с данным потребителем по ТУ или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2324, N'Потребитель реальный', N'PR', N'p_gvpw', N'ПерспектПредвклГВ', N'Перспект.средняя тепл.нагрузка на ГВ, предвключ.сх.', N'Перспективная средняя нагрузка на ГВ', N'"Перспективная среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  предвключенном включении подогревателя  ГВ"   -  цифровое   поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается   исходя из договорных обязательств с данным потребителем по ТУ или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2325, N'Потребитель реальный', N'PR', N'p_otopl_tp', N'Q_тепловыд', N'Перспект ВнутрТепловыделения', N'Перспективные внутренние тепловыделения', N'"Перспективные  внутренние тепловыделения" - цифровое  поле, значение которого используется при определении расчетного часового расхода тепла на отопление отдельного здания Q = 1.1(Qн.о + Qв - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания, Qв - тепло, затрачиваемое на вентиляцию  ( на подогре вентиляционного воздуха),  Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину. Заполняется при наличии у теплового пункта внутренних тепловыделений. Договорные  внутренние тепловыделения  назначаются исходя из договорных обязательств с данным потребителем по ТУ или назначается исходя из определенных целей расчета. Заполнение поля обязательно для расчета Планового режима с установкой "Перспективная нагрузка".', N'Тепловая мощность', NULL)
