INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2343, N'Потребитель секционированный', N'PR', N'name_building', N'НаимЗдан', N'Наим.здания', N'Содержательное наименование здания', N'"Содержательное  наименование  потребителя"  -   символьное поле,   значение   которого   определяет   полное   наименование потребителя магистральных или распределительных сетей. Например, "КРП на ул.Гоголя", "Ермекова 73/3, тепловой пункт 12".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2344, N'Потребитель секционированный', N'PR', N'h', N'ВысЗдан', N'Высота здания', N'Высота здания', N'"Высота  здания"  -  цифровое  поле,   значение которого  соответствует  высоте   самого  высокого  из   зданий, нагрузка теплопотребления которых "присоединена" к данному узлу. Значение поля имеет размерность, м.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2345, N'Потребитель секционированный', N'PR', N'kodur', N'КодУР', N'Код УР', N'Код удельных расходов тепло/вода', N'"Код  удельных  расходов  т/в"  -символьное  поле, значение которого однозначно определяет группу удельных расходов по  всем видам теплопотребления, заданным в объекте "Удельные расходы", и предназначенных для пересчета нагрузок по всем видам теплопотребления из  единиц теплового  потока  (Гкал/ч)  в  единицы массового расхода (т/ч). Наличие непустого  значения в  этом поле  свидетельствует о том, что  в  этом  объектах  "Реальный потребитель" и "Обобщеный потребитель"   могут  быть  приведены  нагрузки  по отдельным  видам  теплопотребления,  представленные  в  единицах теплового  потока  (Гкал/ч),  а  соответствующие им расходы воды (т/ч) могут быть  вычисленны автоматически и  использованны при расчете  плановых гидравлических  режимов.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2346, N'Потребитель секционированный', N'PR', N'geodz', N'ГеодОтм', N'Геод.отметка подвальной прокладки', N'Геодезическая отметка низа трубы подвальной прокладки', N'"Геодезическая отметка низа трубы подвальной прокладки" - цифровое поле, значение которого  определяется  значением   геодезической  отметкой низа трубы подвальной прокладки здания в месте расположения  данного узла  присоединения нагрузки потребителя.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2347, N'Потребитель секционированный', N'PR', N'ventil', N'РасчНагрВент', N'Расч.тепл.нагрузка на вентиляцию', N'Расчетная нагрузка  на вентиляцию', N'"Тепловая  нагрузка  или  расход  на вентиляцию" - цифровое поле,   значение   которого    принимается   по   типовым    или индивидуальным    проектам    потребителей    или    назначается пользователем, исходя из  определенных целей расчета.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2348, N'Потребитель секционированный', N'PR', N'dolja_vent', N'ДоляРасхПриОтклКУ', N'Доля расхода воды через КУ при откл.по возд.', N'Доля расхода воды через КУ, при откл.её по возд.', N'"Доля расхода сетевой воды через КУ, при отключении её по воздуху" - цифровое поле,   значение   которого    принимается   по   типовым    или индивидуальным    проектам    потребителей    или    назначается пользователем, исходя из  определенных целей расчета. Значение  поля - безразмерная величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2349, N'Потребитель секционированный', N'PR', N'kondiz', N'РасчНагрКондиц', N'Расч.тепл.нагрузка на кондиц.', N'Расчетная  нагрузка на кондиционирование', N'"Тепловая  нагрузка  или  расход  на  кондиционирование"  - цифровое  поле,  значение  которого  принимается  по типовым или индивидуальным    проектам    потребителей    или    назначается пользователем.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2350, N'Потребитель секционированный', N'PR', N'txz', N'РасчНагрТехнЗакр', N'Расч.тепл.нагрузка на технол. закр.', N'Расчетная нагрузка на технологию в закр.системе', N'"Тепловая нагрузка или расход на технологические процессы в закрытой системе" - цифровое поле, значение которого принимается по типовым  или индивидуальным  проектам потребителей  тепла или назначается  пользователем.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2351, N'Потребитель секционированный', N'PR', N'txop', N'РасчНагрТехнОткрПод', N'Расч.тепл.нагрузка на технол., под.труб.', N'Расчетная нагрузка на технологию в откр.сист.из под.труб.', N'"Тепловая нагрузка или расход на технологичеcкие процессы в открытой  системе  из  подающего  трубопровода" - цифровое поле, значение   которого   соответствует   величине   водоразбора  из подающего   трубопровода   и   принимается   по   типовым    или индивидуальным  проектам  потребителей  тепла  или   назначается пользователем.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2352, N'Потребитель секционированный', N'PR', N'txoo', N'РасчНагрТехнОткрОбр', N'Расч.тепл.нагрузка на технол. обр.труб.', N'Расчетная нагрузка на технологию в откр.сист.из обр.труб.', N'"Тепловая нагрузка или расход на технологичекие процессы  в открытой  системе  из  обратного  трубопровода" - цифровое поле, значение   которого   соответствует   величине   водоразбора  из подающего   трубопровода   и   принимается   по   типовыи    или индивидуальным  проектам  потребителей  тепла  или   назначается пользователем.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2353, N'Потребитель секционированный', N'PR', N'gvop', N'РасчНагрОткрГВПод', N'Расч.тепл.нагрузка на ГВ, под.труб.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая  нагрузка  горячего  водоснабжения потребителя  в  открытой  системе  из  подающего трубопровода" - цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления.  Величина  среднечасовой нагрузки  принимается  по  типовым  или  индивидуальным проектам систем  горячего  водоснабжения,  выполненным  в  соответствии с требованиями  СНиП для  проектирования  горячего  водоснабжения. Кроме  того, значение  поля  может  быть  получено  на основании анализа фактических данных водоразбора для конкретного теплового пункта.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2354, N'Потребитель секционированный', N'PR', N'gvoo', N'РасчНагрОткрГВОбр', N'Расч.тепл.нагрузка на ГВ, обр.труб. на ГВ, обр.труб.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая  нагрузка  горячего  водоснабжения потребителя  в  открытой  системе  из  обратного трубопровода" - цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления.  Величина  среднечасовой нагрузки  принимается  по  типовым  или  индивидуальным проектам систем  горячего  водоснабжения,  выполненным  в  соответствии с требованиями  СНиП для  проектирования  горячего  водоснабжения. Кроме  того, значение  поля  может  быть  получено  на основании анализа фактических данных водоразбора для конкретного теплового пункта.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2355, N'Потребитель секционированный', N'PR', N'rez', N'РасчНагрТеплПотерьЦиркГВ', N'Расч.тепл.нагрузка компенсации цирк.тепл.потерь ГВ', N'Расч.тепл.нагрузка на компенсацию тепл.потерь в теплопр.цирк. ГВС', N'"Тепловая  нагрузка   на  компенсацию   тепловых  потерь   в трубопроводах    циркуляционной  ГВС"  -  цифровое поле, значение которого определяется  долей от среднечасовой  нагрузки ГВ, т.е.   Qц=Qср*К, где  К=0.1-0.3. Наиболее  часто в  практике проектирования ГВС используют 20-ти процентную долю, т.е. К=0.2. Значение  поля  используется при расчете теплогидравлических режимов тепловых пунктов (ЦТП) только с открытой  ГВС  циркуляционного  типа. Значение   поля   имеет  процентную  размерность и вводится, например, в виде целочисленной  константы  20 (при 20%-ых потерях).', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2356, N'Потребитель секционированный', N'PR', N'gvpr', N'РасчНагрПараллГВ', N'Расч.тепл.нагрузка на ГВ, парал.сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  параллельном включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2357, N'Потребитель секционированный', N'PR', N'gvsm', N'РасчНагрСмешГВ', N'Расч.тепл.нагрузка на ГВ, смеш.сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка  на   ГВ потребителя  в  закрытой   системе   при  смешанном   включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2358, N'Потребитель секционированный', N'PR', N'gvps', N'РасчНагрПоследГВ', N'Расч.тепл.нагрузка на ГВ послед.сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  последовательном включении подогревателей  ГВ"   -  цифровое  поле,  значение  которого соответствует среднечасовому расходу тепла на горячее водоснабжение потребителя за сутки наибольшего водопотребления. Назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2359, N'Потребитель секционированный', N'PR', N'utechp', N'УтесПодТеплопр', N'Утечка из под.труб.', N'Утечка из подающего теплопровода', N'"Заданная  утечка  из  подающего  трубопровода" - свойство,  значение  которого  задается  пользователем  исходя   из определенных целей моделирования аварийной ситуации.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2360, N'Потребитель секционированный', N'PR', N'utecho', N'УтесОбрТеплопр', N'Утечка из обр.труб.', N'Утечка из обратного  теплопровода', N'"Заданная  утечка  из  подающего  трубопровода" - свойство,  значение  которого  задается  пользователем  исходя   из определенных целей моделирования аварийной ситуации.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2361, N'Потребитель секционированный', N'PR', N'kodkv', N'КодКВ', N'Код КВ', N'Код группы коэффициентов вариации', N'"Код  группы  коэффициентов  вариации"  - свойство, значение  которого  однозначно  определяет группу коэффициентов вариации  значений   исходных  данных,   определяющих   вариант гидравлического режима тепловой сети.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2362, N'Потребитель секционированный', N'PR', N'prznz', N'ПризнакРасчета ГидрРежЗакрТП', N'Признак  расчета гидр.реж.закрТП', N'Признак расчета гидравлического режима', N'"Признак  расчета гидравлического режима потребителя с закрытыми системами теплопотребления". При значении свойства "Нагрузка" расчет гидравлического режима потребителя выполняется для заданных нагрузок закрытых систем теплопотребления потребителя.  При значении свойства "Сопротивление" расчет режима выполняется для заданных гидравлических сопротивлений закрытых систем теплопотребления потребителя.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2363, N'Потребитель секционированный', N'PR', N'prznp', N'ПризнакРасчетаГидрРежОткрГВСПодТеплопр.', N'Признак расчета гидр.реж.откр ГВС под.теплопр.', N'Признак расчета гидравлического режима', N'"Признак  расчета  гидравлического режима потребителя с открытой ГВС, с водоразбором  из подающего теплопровода".  При значении свойства "Нагрузка" расчет гидравлического режима потребителя выполняется для заданной нагрузки ГВС. При значении свойства "Сопротивление" расчет режима выполняется для заданного гидравлического сопротивления ГВС  из  подающего теплопровода.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2364, N'Потребитель секционированный', N'PR', N'przno', N'ПризнакРасчетаГидрРежОткрГВСОбрТеплопр.', N'Признак расчета гидр.реж.открГВС обр.теплопр.', N'Признак расчета гидравлического режима', N'"Признак  расчета  гидравлического режима потребителя с открытой ГВС, с водоразбором  из обратного теплопровода".  При значении свойства "Нагрузка" расчет гидравлического режима потребителя выполняется для заданной нагрузки ГВС. При значении свойства "Сопротивление" расчет режима выполняется для заданного гидравлического сопротивления ГВС  из  обратного теплопровода.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2365, N'Потребитель секционированный', N'PR', N'gsz', N'ГидрСопрЗакрТП', N'Гидр.сопротивл.', N'Гидравлическое сопротивление потребителя', N'"Гидравлическое  сопротивление   потребителя  в   закрытой системе  -  мантисса"  -   цифровое  поле,  значение   которого представляет  собой    гидравлическое   сопротивление потребителя, определенного как отношение располагаемого  напора в узле присоединения потребителя к квадрату расхода в  закрытой схеме  потребителя  в   данном  гидравлическом  режиме.    Если сопротивление неизвестно, то значение поля не заполняется.  При этом  программные  средства сисчтемы  автоматически определяют требуемое значение сопротивления потребителя, при котором  обеспечивается заданный   расчетный   расход   и   осуществляют   запись    по указанию, выполненному   в   процессе   запуска   расчета.   При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение  сопротивления  обновляется, если   указано значение "Рассчитанное" свойства "Признак гидравлического сопротивления потребителя".     Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если значения признака "Признак расчета на заданную нагрузку"  равно "Сопротивление" расчета   на   заданную   нагрузку.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2366, N'Потребитель секционированный', N'PR', N'gszpr', N'ПризнГидрСопрЗакрТП', N'Признак гид.сопр.закр.ТП', N'Признак гидравлического сопротивления потребителя', N'"Признак  гидравлического сопротивления"  - свойство,   значение которого символ "Заданное"  записывается пользователем в  случае, если гидравлическое   сопротивление   потребителя   следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля  "Рассчитанное",  то  рассчитанное сопротивление записывается на место старого значения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2367, N'Потребитель секционированный', N'PR', N'gsop', N'ГидрСопрОткрПодТП', N'Гидр.сопротивл.', N'Гидравлическое сопротивление потребителя', N'"Гидравлическое  сопротивление   потребителя  в   открытой системе при водоразборе  из подающего трубопровода"  - цифровое поле,  значение  которого  представляет  собой   гидравлическое сопротивление потребителя, определенное как отношение  разности между  пьезометрическим  напором  в  подающей   трубе  и   напором, соответствующим  атмосферному  давлению  -10  м.вод.cт.  в узле присоединения  потребителя,  к  квадрату  его  расхода в данном режиме.  Если  сопротивление  неизвестно,  то  значение поля не заполняется.   При  этом  программные  средства   автоматически определяют  требуемое  значение  сопротивления потребителя, при котором обеспечивается заданный расчетный расход и осуществляют запись по  указанию, выполненному  в процессе  запуска расчета.  При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение  сопротивления  обновляется, если   указано значение "Рассчитанное" свойства "Признак сопротивления".     Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если значения признака "Признак расчета на заданную нагрузку"  равно "Сопротивление" расчета   на   заданную   нагрузку.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2368, N'Потребитель секционированный', N'PR', N'gsoppr', N'ПризнГидрОткрПодТП', N'Признак гид.сопр.под.труб.', N'Признак гидравлическогосопротивления  потребителя', N'"Признак  гидравлического сопротивления"  -  свойство,   значение которого символ "Заданное"  записывается пользователем в  случае, если гидравлическое   сопротивление   потребителя   следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля  "Рассчитанное",  то  рассчитанное сопротивление записывается на место старого значения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2369, N'Потребитель секционированный', N'PR', N'gsoo', N'ГидрСопрОткрОбрТП', N'Гидр.сопротивл.', N'Гидравлическое сопротивление потребителя', N'"Гидравлическое  сопротивление   потребителя  в   открытой системе при водоразборе  из обратного трубопровода"  - цифровое поле,  значение  которого  представляет  собой   гидравлическое сопротивление потребителя, определенное как отношение  разности между  пьезометрическим  напором  в  обратной   трубе  и   напором, соответствующим  атмосферному  давлению  -10  м.вод.cт.  в узле присоединения  потребителя,  к  квадрату  его  расхода в данном режиме.  Если  сопротивление  неизвестно,  то  значение поля не заполняется.   При  этом  программные  средства   автоматически определяют  требуемое  значение  сопротивления потребителя, при котором обеспечивается заданный расчетный расход и осуществляют запись по  указанию, выполненному  в процессе  запуска расчета. При повторных  расчетах,  расчетах  новых вариантов гидравлического режима  значение  сопротивления  обновляется, если   указано значение "Рассчитанное" свойства "Признак сопротивления".     Если   заданы одновременно сопротивление потребителя и его тепловая нагрузка, то при расчете  потокораспределения в качестве  исходных данных используется сопротивление потребителя, если значения признака "Признак расчета на заданную нагрузку"  равно "Сопротивление" расчета   на   заданную   нагрузку.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2370, N'Потребитель секционированный', N'PR', N'gsoopr', N'ПризнГидрОткрОбрТП', N'Признак гид.сопр.обр.труб.', N'Признак гидравлического сопротивления потребителя', N'"Признак  гидравлического сопротивления"  -  свойство,   значение которого символ "Заданное"  записывается пользователем в  случае, если гидравлическое   сопротивление   потребителя   следует  считать заданным,  а  запись  рассчитанного  сопротивления недопустима. Если  значение  поля  "Рассчитанное",  то  рассчитанное сопротивление записывается на место старого значения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2371, N'Потребитель секционированный', N'PR', N'a13', N'СтупДросс', N'Ступень дросс.', N'Признак ступени дросселирования', N'"Признак ступени дросселирования" - свойство,  определяющее принятый пользователем способ расстановки дроссельных органов  в узлах присоединения теплопотребляющих систем теплового пункта на основе   принципа   ступенчатости   дросселирования  избыточного напора.   Значение  свойства "1"  означает  выбор  одноступенчатого способа  дросселирования  избыточного  напора, когда дроссельные органы   для   теплопотребляющих    систем   теплового    пункта рассчитываются   на   весь   располагаемый   напор.   В   случае элеваторного   присоединения   системы   отопления   дроссельная диафрагма  на  входе  системы  отопления  может  появиться   при значительных располагаемых напорах,  когда сопло элеватора  не в состоянии  обеспечить  гашение  избыточного  напора.   В  случае теплового  пункта   с  последовательной   схемой   присоединения подогревателей  ГВС  дроссельная  диафрагма  при   необходимости гашения   избыточного    напора   устанавливается    на    входе подогревателя ГВС второй  ступени.  Как  сопло элеватора, так  и упомянутая  диафрагма  раcсчитываются  на  суммарный   расчетный расход  отопления  и  ГВС  в случае отопительного температурного графика  и  только  на  расчетный  расход  отопления  - в случае повышенного температурного  графика. 
  Значение    свойства    "2"   означает    выбор    двухступенчатого дросселирования,  когда устанавливается  и  раcсчитывается общая головная дроссельная  диафрагма для  теплового пункта  и входные диафрагмы для его отдельных теплопотребляющих систем  (отопление, вентиляция, ГВС  и т.  д.). При  этом расчетный  расход головной диафрагмы определяется как средневзвешенный расход из  расчетных расходов отдельных теплоснабжающих систем теплового пункта.  Для потребителей  с  последовательным  присоединением подогревателей ГВС входная диафрагма на  входе подогревателя второй ступени  не раcсчитывается, так как ее роль выполняет головная диафрагма. 
  Значение    свойства    "3"   означает    выбор    двухступенчатого дросселирования, при котором гасимый напор на головной диафрагме рассчитывается   как   разность   между   располагаемым  напором теплового пункта  и минимально  необходиным напором  для системы отопления   с    элеваторным   присоединением.    Для   ГВС    с последовательной   схемой   присоединения   потребителей    роль диафрагмы  на  входе   подогревателей  второй  ступени   играет головная диафрагма. При  этом сопло элеватора раcсчитывается  на суммарный расчетный расход на  отопление и ГВС при  отопительном температурном   графике.   Область   применения   этого  способа дросселирования  -  тепловые  пункты  с  разнородной нагрузкой и элеваторным присоединением систем  отопления. 
  Значение   свойства   "4"  означает   выбор  специального   способа дросселирования   потребителя   с   открытой   нагрузкой    ГВС, подключенной к ЦТП по 4-х трубной схеме.  Обычно нагрузка ГВС  у таких потребителей  подключена по  двум отдельным  трубам, т. е. гидравлически развязана с  нагрузками отопления и  вентиляции, а внутренняя   разводка   сети   ГВС   выполнена   по   схеме    с посекционно-закольцованными стояками  ГВС внутри  секций здания. Нагрузка ГВС таких потребителей  должна описываться в строке  ПТ (поле 19 "Тепловая нагрузка или расход на ГВС в открытой системе из    подающего    трубопровода",   а    обязательная   нагрузка циркуляционного  (обратного)  трубопровода   сети   ГВС   должна описываться   в   поле  21  "Тепловая  нагрузка  на  компенсацию тепловых потерь в трубопроводах циркуляционной ГВС ". Циркуляционная   нагрузка  таких  потребителей замыкается обычно через полотенцесушители,которые по сути выполняют роль отопления ванных помещений.Отопительная нагрузка полотенцесушителей здания должна учитывать  тепловые  потери как  в полотенцесушителях,так и   потери  всеми   трубопроводами   сети   ГВС. Значение поля - безразмерная величина. 
  Значение   свойства  "5"  означает   выбор   специального  способа дросселирования    потребителей  с   открытой   нагрузкой   ГВС, подключенной к ЦТП по 4-х трубной схеме(аналогично значению поля "4").  Как  и  в  предыдущем   случае   нагрузка   подающего   и циркуляционного трубопроводов описывается в полях 19 и 21 строки ПТ. Однако, в  отличии  от  предыдущего варианта дросселирования дроссельная   диафрагма   расситывается  только  на  ограничение циркуляционного   расхода    и   устанавливается   на   обратном (циркуляционном) трубопроводе сети ГВС, выполняя  одновременно и подпорные функции.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2372, N'Потребитель секционированный', N'PR', N'a15', N'МинДиамДросс', N'Мин.диам.дрос.диафр.', N'Диаметр дроссельной диафрагмы минимально допустимый', N'"Диаметр дроссельной диафрагмы минимально допустимый" - свойство,   определяющее   требования   к   минимальному    диаметру рассчитываемой   шайбы,   исходя   из   исключения   возможности засорения, вибрации и шума при работе теплопотребляющих  систем. По  умолчанию начальное значениепринимается равным 3 мм .', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2373, N'Потребитель секционированный', N'PR', N'a17', N'ТемпГраф', N'Темп.график', N'Признак температурного графика', N'"Признак температурного графика" - свойства, определяющее температурный  график, на котором  работает  потребитель тепла, и служит   для   корректного   использования   нагрузки   ГВС  при последовательной  схеме  присоединения  горячего   водоснабжения потребителя.  Значение  свойства  "Отопительный" определяет отопительный график работы потребителя, значение "Повышенный" - повышенный график.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2374, N'Потребитель секционированный', N'PR', N'pr_sopr', N'ГидрСопрФактРеж', N'Расчет сопротивления факт.режима', N'Метод расчета сопротивления в фактическом режиме', N'"Метод расчета гидравлического сопротивления" - свойство, значение которого определяет метод расчета гидравлического сопротивления теплопотребляющих систем теплового пункта при расчете фактического режима сети, при значении поля "Режим", гидравлическое сопротивление соответствующей системы теплопотребления теплового пункта производится через параметры расчетного режима (расчетный расход и расчетное падение напора),  при значении поля "Оборудование"- через конструктивные  размеры установленного оборудования (этот режим в данной версии не реализован).', NULL, NULL)

SET IDENTITY_INSERT [dbo].[HELP_OLD] OFF
GO
