INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2375, N'Потребитель секционированный', N'PR', N'pr_teplo', N'ТеплопотрФактРеж', N'Расчет теплопотребл. факт.режима', N'Метод расчета тепловой нагрузки в фактическом режиме', N'"Метод расчета тепловой нагрузки" - свойство, значение которого определяет метод расчета теплового режима теплопотребляющих систем теплового пункта, при значении свойства "Режим" расчет режимных коэффициентов теплообменных аппаратов определять точно только для одного произвольно выбранного режима, для систем горячего водоснабжения  это температура наружного воздуха, соответствующая нижней точке излома температурного графика, для систем отопления - это расчетная температура наружного воздуха для отопления. При всех других режимов работы аппаратов режимный коэффициент определяется по методике предложенной Сколовым Е.Я. .  расчет тепловой нагрузки производится через значения параметров расчетного режима данной системы теплопотребления, при значении свойства "Оборудование" - через конструктивные размеры установленного оборудования систем теплопотребления (этот режим в данной версии не реализован).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2376, N'Потребитель секционированный', N'PR', N'a8', N'РасПотНапКУ', N'Расч.потери напора в КУ', N'Расчетные потери напора в калориферах', N'"Расчетные  потери  напора  в  калориферах  "  -  свойство, определяющее  значение  потерь  напора  на гидравлическом тракте калориферов  присоединенной  калориферной  установки в расчетном режиме.  Начальное значение поля по умолчанию принимается равным 5 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2377, N'Потребитель секционированный', N'PR', N'a9', N'РасПотНапКонд', N'Расч.потери напора на конд.', N'Расчетные потери напора в кондиционерах', N'"Расчетные  потери  напора  в  кондиционерах"  - свойство, определяющее  значение  потерь  напора  на гидравлическом тракте кондиционеров  присоединенной  установки  для  кондиционирования воздуха в  расчетном режиме.  Начальное  значение  поля  по  умолчанию принимается равным 6 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2378, N'Потребитель секционированный', N'PR', N'a10', N'РасПотНапПодТрубГВ', N'Расч.потери напора в под.труб.откр.ГВ', N'Расч.потери напора в подающем трубопроводе ГВС', N'"Расчетные потери напора в подающем трубо-воде  открытой системы ГВС"  -  свойство,  определяющее  расчетные  потери напора сетевой воды в подающем трубопроводе сети открытой ГВС теплового пункта.  Начальное значение поля по умолчанию принимается равным 3 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2379, N'Потребитель секционированный', N'PR', N'a11', N'РасПотНапЦиркТрубГВ', N'Расч.потери напора в цирк.труб.отк.ГВС', N'Расчетные потери напора в циркул. трубопроводе ГВС', N'"Расчетные потери напора в циркуляционном трубопроводе открытой системы  ГВС"  - свойство, определяющее расчетные потери напора сетевой воды в циркуляционном трубопроводе сети  открытой ГВС теплового пункта.  Начальное  значение  поля  по  умолчанию  принимается  равным  4 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2380, N'Потребитель секционированный', N'PR', N'a12', N'РасПотНапПриборГВ', N'Расч.напор на вх.водоразб.приборов', N'Расчетный напор на входе водоразборных приборов', N'"Расчетный  напор  на  входе  водоразборных приборов" - свойство,  определяющее  ограничение  напора  сетевой  воды  в  сети открытой  ГВС  на  входе  водоразборных  приборов.   Ограничение регламентируется   СНИП   2.04.01.85   "Внутренний  водопровод". По умолчанию начальное значение принимается равное 25 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2381, N'Потребитель секционированный', N'PR', N'a18', N'КолПодогр1стГВ', N'Кол.вкл.подогрев.1 ст.ГВ', N'Число параллельно включенных подогревателей 1 ступени', N'"Число параллельно включенных подогревателей 1-ой ступени ГВС" - свойство,    определяющее   количество    подогревателей, включенных параллельно в 1-ую ступень нагрева водопроводной воды с  целью  повышения  теплопроизводительности. Начальное значение поля  по умолчанию принимается равным 1, что означает один включенный подогревателей в первой ступени.', NULL, N'штук(и)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2382, N'Потребитель секционированный', N'PR', N'a19', N'КолПодогр2стГВ', N'Кол.вкл.подогрев.2 ст.ГВ', N'Число параллельно включенных подогревателей 2 ступени', N'"Число параллельно включенных подогревателей 2-ой ступени ГВС" - свойство,    определяющее   количество    подогревателей, включенных параллельно в 2-ую ступень нагрева водопроводной воды с  целью  повышения  теплопроизводительности. Начальное значение поля  по умолчанию принимается равным 1, что означает один включенный подогревателей в первой ступени.', NULL, N'штук(и)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2383, N'Потребитель секционированный', N'PR', N'a22', N'РасПотНап1стГВ', N'Расч.потери напора на 1 ст.ГВ', N'Расчетные потери напора на подогревателе 1-ой ступени ГВС', N'"Расчетные потери напора на одном подогревателе 1-ой ступени"  - свойство, определяющее расчетные потери напора на одном  из нескольких параллельно включенных подогревателей 1-ой ступени  в закрытой  ГВС  при  расчетном   расходе.     Начальное  значение  поля по умолчанию принимается равным 4 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2384, N'Потребитель секционированный', N'PR', N'a23', N'РасПотНап2стГВ', N'Расч.потери напора на 2 ст.ГВ', N'Расчетные потери напора на подогревателе 2-ой ступени ГВС', N'"Расчетные потери напора на одном подогревателе 2-ой ступени"  - свойство, определяющее расчетные потери напора на одном  из нескольких параллельно включенных подогревателей 2-ой ступени  в закрытой  ГВС  при  расчетном   расходе.     Начальное  значение  поля по умолчанию принимается равным 4 м.вод.ст.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2385, N'Потребитель секционированный', N'PR', N'Tr_tv_cv', N'РасчТемпНагрВоздВент', N'Расч.темп.нагр.возд.после КУ', N'Расчетная температура нагретого воздуха после КУ', N'Расчетная температура нагретого воздуха  в системе вентиляции или воздушного  отопления', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2386, N'Потребитель секционированный', N'PR', N'Tr_gvs', N'Тгор_расчГВ', N'Расч.темп.горячей воды', N'Расчетная температура горячей воды', N'"Расчетная температура горячей воды " -  числовое поле, значение которого определяет температуру бытовой горячей воды по выходу ее из подогревательных установок, нижнее и верхнее значение которой pегламентиуется тpебованиями СНиП 2.04.01-85: не ниже 60 Гpад.С в ГВС,
пpисоединеных    к   откpытым системам    теплоснабжения;
не ниже  50  Гpад.С , пpисоединенных  к закpытым системам
теплоснабжения и не выше 75 Град.С для всех вышерассмотренных случаев. Для уменьшения циркуляционной воды температуру бытовой воды по выходе ее из подогревательных установок рекомендуется принимать равной в закрытых системах 50+10=60 Град.С, в открытых 60+5= 65 Град.С. Где 5-10 охлаждение циркуляционной воды в водоразборных стояках  многоэтажных зданий по системе в целом.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2387, N'Потребитель секционированный', N'PR', N'gvs_max', N'Кч', N'Коэффициент часовой неравномерности нагрузки горячего водоснабжения', N'Коэфф.часовой неравномерности нагрузки горячего водоснабжения', N'"Коэффициент часовой неравномерности нагрузки горячего водоснабжения" - цифровое поле, значение которого определяет коэффициент часовой неравномерности (kч) расхода тепла за сутки наибольшего водопотребления.  Значение этого поля используется при расчете максимального расхода тепла на горячее водоснабжение жилых зданий, гостиниц, больниц и т.д.: Qгвс_макс=kч*Qгвс_средн.  При определении расхода тепла на горячее  водоснабжение микрорайонов (кварталов) городов kч= 1.7 - 2.2, промышленных предприятий kч= 1. При отсутствии данных о назначении общественных зданий допускается определении коэффициента часовой неравномерности условное количество жителей принимать с коэффициентом 1.2.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2388, N'Потребитель секционированный', N'PR', N'a25', N'УдОбъемВент', N'Удельный  объем  воды  в  системе  вентиляции', N'Удельный объем воды в системе вентиляции', N'"Удельный объем воды в системе вентиляции" - числовое поле, значение которого определяет удельный объем воды в отопительно-вентиляционной системе, оборудованной калориферами, в зависимости от расчетного температурного перепада. Рекомендуется использовать функцию поля.', N'Удельный объем воды', NULL)
