INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2474, N'Потребитель секционированный', N'PR', N'uzel_p', NULL, N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2475, N'Потребитель секционированный', N'PR', N'pr_p', NULL, N'Признак теплопровода узла присоединения', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2476, N'Потребитель секционированный', N'PR', N'otopl_tp', N'Q_тепловыд', N'Расчетные внутренние тепловыделения', N'Расчетные внутренние тепловыделения', N'"Расчетные внутренние тепловыделения" - цифровое  поле, значение которого используется при определении расчетного часового расхода тепла на отопление отдельного здания Q = 1.1(Qн.о + Qв - Qвн), где 1.1 - коэффициент, учитывающий дополнительные потери тепла в местной системе отопления (СНиП II-33), Qн.о - потери тепла через наружные ограждения здания, Qв - тепло, затрачиваемое на вентиляцию  ( на подогре вентиляционного воздуха),  Qвн - тепловые выделения внутри здания. К внутренним  (бытовым ) тепловыделениям относят тепло, выделяемое самими жителями и различного рода бытовыми приборами. Поступление бытового тепла не зависит от наружной температуры и составляет 18 ккал/ч (75.4 кДЖ/ч) на 1 м^2 площади помещений, имеющих нагревательные приборы. При расчете режимов сети значение поля "Расчетные внутренние тепловыделения" уменьшают заданную Расчетную нагрузку на отопление потребителя на веденную величину.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2477, N'Потребитель секционированный', N'PR', N'uf', N'ФактКоэфСмеш', N'Коэффициент  смешения  элеватора', N'Коэффициент  смешения  элеватора', N'"Коэффициент  смешения  элеватора"  -  цифровое  поле,  расчетное значение которого однозначно определяется температурным графиком  сетевой воды,  установленным  для  системы  отопления.   Как   известно, коэффициент  смешения   элеватора  U   определяется  с   помощью следующих выражений:   1.   U=Gп/Gс, где  Gп -  массовый  расход подмешиваемой воды, т/ч; Gс - массовый расход воды, потребляемой из сети на  систему отопления, т/ч;  2.  U=(t1-t3)/(t3-t2),  где t1, t2 - соответственно,  температура сетевой воды в  подающем и обратном  трубопроводах  теплового  пункта;  t3  -   температура смешанной воды,  поступающей в  систему отопления.  Для типового температурного графика  сетевой воды  150-70 Град.С  и графика - подмешанной воды 90-70  Град.С коэффициент смешения  принимается равным  U=2.2.  Это  значение  принимается  в качестве исходного значения  этого  поля  по  умолчанию.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2478, N'Потребитель секционированный', N'PR', N'kodtr', N'КодРасТемп', N'Код расчетных температур', N'Код расчетных температур', N'"Код  расчетных температур"  - символьное  поле, значение которого однозначно определяет группу расчетных температур и температур в точке излома температурного графика теплоносителя, наружного воздуха, нагреваемой водопроводной воды, предназначенных для расчета коэффициентов темплопередачи приборов отопления, вентиляции,  теплообменных аппаратов закрытых систем горячего водоснабжения.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2479, N'Потребитель секционированный', N'PR', N'gvpw', N'СреднНагрПоследГВ', N'Сред.тепл.нагрузка на ГВ, предвключ.сх.', N'Средняя тепловая нагрузка на горячее водоснабжение', N'"Среднечасовая  тепловая   нагрузка   на   ГВ потребителя  в  закрытой  системе   при  предвключенном включении подогревателя  ГВ"   -  цифровое   поле,  значение    которого соответствует среднедельной часовой тепловой нагрузке  на ГВ для указанной схемы включения подогревателей  и назначается пользователем  на основании проектных данных или результатов анализа фактического гидравлического режима.', N'Тепловая мощность', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2480, N'Потребитель секционированный', N'PR', N'Gneob', N'НеобхРасполНапор', N'НеобхРасполНапор', N'Необходимый располагаемый напор', N'"Необходимый располагаемый напор" -  цифровое   поле, значение    которого определяет величину располагаемого напора на входе данного теплового пункта, необходимого для его теплообеспечения.', N'Напор', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2481, N'Потребитель секционированный', N'PR', N'kod_cekz_p', N'КодCекцПотребителя', N'Код секционированного потребителя', N' Краткое содержательное наименование секционированного потребителя', N'Код секционированного потребителя, символьное поле, определяющее краткое содержательное наименование секционированного потребителя. Значение поля поля используется для указания принадлежности зависимых систем отопления данному секционированному потребителю.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2482, N'Потребитель секционированный', N'PR', N'kod_gvs', N'График нагрузки ГВ', N'Код суточного графика нагрузки ГВ', N'Код графика суточного нагрузки ГВ', N'Код графика нагрузки ГВ, символьное поле, определяющее краткое наименование суточного графика нагрузки горячего водоснабжения потребителя. Суточный график нагрузки горячего водоснабжения используется при расчете режима (анализирующего) системы, по результатам которого рассчитываются отклонения фактических (измеренных) значений параметров режима в контрольных точках расчетной схемы системы теплоснабжения. Для открытых систем горячего водоснабжение значение "Балансовая нагрузка" не используется, по умолчанию она будет приравнена средней нагрузке  горячего водоснабжения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2483, N'Потребитель секционированный', N'PR', N'pP_fact', N'ИзмерДавление', N'Измеренное давление на подающем теплопроводе', N'Измеренное давление на подающем теплопроводе', N'Измеренное давление на подающем теплопроводе. Значение поля используется при построении пьезометрического графика, по направлению в состав которого входит и данный узел.', N'Напор', NULL)
