INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2577, N'Расчетная схема', N'PC', N'kod_rs', N'Код РС', N'Код расчетной схемы', N'Код расчетной схемы', N' "Код расчетной схемы" - символьное поле, значение которого формируется пользователем произвольно в виде группы не более трех символов. Важно то, что эти символы однозначно идентифицируют расчетную схему объекта района экплуатации теплоснабжающей системы в целом. Например, в случае, если объектом является Магистраль М1, проходящая через несколько районов эксплуатации, то для объекта  М1 необходимо создавать для каждого района экплуатации свою  расчетную схему, М11, М12 и.т.д. Код расчетной схемы по принадлежности является частью района эксплуатации, ввиду этого значение поля "Наименование района экплуатации" не может быть назначено произвольно, а только выбрано из предлагаемого списка в поле ввода. Значение свойства "Наименование района экплуатации" определяется в объекте "Район эксплуатации".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2578, N'Расчетная схема', N'PC', N'name_fragm', N'Наим.фрагм.района', N'Наименование фрагмента района экплуатации', N'Наименование фрагмента района экплуатации', N'Значение поля в данной версии программного продукта не задействовано.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2579, N'Расчетная схема', N'PC', N'nomer_rn', N'Район эксплуатации', N'Район эксплуатации', N'Наименование района эксплуатации', N'"Наименование района эксплуатации" - символьное поле, значение которого определяет принадлежность расчетной схемы данному району эксплуатации,  ввиду этого значение поля "Наименование района эксплуатации" не может быть назначено произвольно, а только выбрано из предлагаемого списка  в поле ввода. Т.е. одна и та же расчетная схема не может принадлежат двум и более районам одновременнно. Значение свойства "Наименование района эксплуатации" определяется в объекте "Район эксплуатации".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2580, N'Расчетная схема', N'PC', N'kod_ist', N'Код теплогенерирующей установки', N'Код теплогенерирующей установки', N'Код теплогенерирующей установки источника тепла', N' "Код теплогенерирующей установки источника тепла" - символьное поле, значение которого определяет принадлежность расчетной схемы теплогенерирующей установке источника тепла системы теплоснабжения,  ввиду этого значение поля "Код теплогенерирующей установки источника тепла" не может быть назначено произвольно, а только выбрано из предлагаемого списка  в поле ввода. Значение свойства же "Код теплогенерирующей установки источника тепла" определяется в объекте "Источник тепла".', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2581, N'Расчетная схема', N'PC', N'ispoln', NULL, N'Лицо, ответственное за подготовку данных', N'Лицо, ответственное за подготовку данных', N'"Лицо, ответственное за подготовку данных" - символьное поле,  значение  которого носит информационный характер.', NULL, NULL)
