INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2586, N'Расчетная схема', N'PC', N'pc_object', N'Тип объекта', N'Тип объекта', N'Тип объекта системы теплоснабжения', N'"Тип объекта системы теплоснабжения" - символьное поле, значение которого определяет тип объекта системы теплоснабжения,  который представляет расчетная схема в данном районе эксплуатации.   Ввиду того, что набор типов объектов в программном продукте зафиксирован, то рекомендуется тип объекта выбирать из предлагаемого списка  в поле ввода: Магистраль, Распредсеть, НС, Источник тепла, ЦТРП, КРП.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2587, N'Расчетная схема', N'PC', N'name_rs', N'Наименование объекта', N'Наименование объекта', N'Наименование объекта', N'"Наименование объекта" - символьное поле, значение которого определяет имя объекта системы теплоснабжения,  который представляет расчетная схема в данном районе эксплуатации. Значение имен объектов системы теплоснабжения формируется пользователем произвольно и программными средствами не ослеживаются. Значение поля используется при поиске объекта и выделения его цветом на расчетной схеме системы теплоснабжения, по команде Процессор>Выделение>Объекты расчетной схемы.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2588, N'Расчетная схема', N'PC', N'master', N'Начальник участка', N'Начальник участка', N'Начальник магистральной сети', N'"Начальник участка магистральной сети" символьное поле, значение которого определяет имя начальника участка магистральной сети, который представляет расчетная схема в данном районе эксплуатации. Значение поле заполняется с помощью функции поля.', NULL, NULL)
