INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2648, N'Регулирующая арматура', N'ZD2', N'sost', N'Сост', N'Состояние', N'Состояние', N'"Состояние регулирующей арматуры" - символьное поле, значение которого однозначно определяет состояние, в котором находится затвор задвижки. Если в поле присутствует в качестве его значения символы - "Открыто", то это говорит о том, что при расчете "Планового режима", будет произведет поиск гидравлического сопротивления арматуры и % открытия задвижки от KV, т.е. положение  затвора, обеспечивающее заданное падение напора на участке с регулирующей арматурой. При расчете "Фактического режима" будет использоваться сопротивление найденное сопротивление. Если в поле присутствует в качестве его значения символы - "Закрыто", то это говорит о том, что затвор закрыт, а гидравлическое сопротивление задвижки максимально.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2649, N'Регулирующая арматура', N'ZD2', N'kod_p', N'КодРСУзПрис', N'Код расч.сх.узла прис.', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2650, N'Регулирующая арматура', N'ZD2', N'uzel_p', N'НаимУзПрис', N'Наим.узла прис.', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2651, N'Регулирующая арматура', N'ZD2', N'pr_p', N'ПризнТеплУзПрис', N'Признак теплопр.узла прис.', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2652, N'Регулирующая арматура', N'ZD2', N'kod1', N'КодРСНачУз', N'Код расч.сх.нач.узла', N'Код расчетной схемы начального узла', N'«Код расчетной схемы начального узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на входе регулирующей арматуры.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2653, N'Регулирующая арматура', N'ZD2', N'uzel1', N'НаимНачУз', N'Наим.нач.узла', N'Наименование начального узла', N'"Наименование начального узла" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения задвижки на теплопроводах тепловой сети и задания направления потока теплоносителя через задвижку.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2654, N'Регулирующая арматура', N'ZD2', N'pr1', N'ПризнТеплНачУз', N'Признак тепл.кон.узла', N'Признак теплопровода начального узла', N'"Признак теплопровода начального узла" - символьное поле, значение которого значения "Подача" или "Обратка" используются для указания принадлежности узла на входе задвижки только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2655, N'Регулирующая арматура', N'ZD2', N'kod2', N'КодРСКонУз', N'Код расч.сх.коч.узла', N'Код расчетной схемы конечного узла', N'«Код расчетной схемы конечного узла участка» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел на выходе задвижки.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2656, N'Регулирующая арматура', N'ZD2', N'uzel2', N'НаимКонУз', N'Наим.кон.узла', N'Наименование конечного узла участка', N'"Наименование конечного узла" - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения регулирующей арматуры на теплопроводах тепловой сети и задания направления потока теплоносителя через регулирующую арматуру.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2657, N'Регулирующая арматура', N'ZD2', N'pr2', N'ПризнТеплКонУз', N'Признак тепл.кон.узла', N'Признак теплопровода конечного узла', N'"Признак теплопровода конечного узла" - символьное поле, значение которого "Подача" или "Обратка" используются для указания принадлежности узла на выходе регулирующей арматуры только подающему - символы "Подача" или только обратному - символ "Обратка" теплопроводам на расчетной схеме.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2658, N'Регулирующая арматура', N'ZD2', N'diametr', N'ДиаметрУсловн', N'Диаметр условный', N'Диаметр условный', N'"Диаметр условный" - цифровое поле, значение (Dу) которого определяется типом установленной регулирующей арматуры.  В качестве регулирующей арматуры может быть использовна  задвижка, затвор, кран. Значение поля имеет размерность  -  мм. Значение величины используется для расчета гидравлического сопротивления (Sарм) регулирующей арматуры, при разной степени открытия её затвора. Sарм=10/(KV)^2, где KV - пропускная способность установленной регулирующей арматуры.  KV=(5.04*0.785*((Dу)^2/100)* Kп )/(Kси)^0.5, где Kси - коэффициент сопротивления, Kп - поправочный коэффициент входного сечения, Kп=0.95. Kси=f(No), где No - относительное число оборотов приводного маховика регулирующей арматуры, No =N/max, где max, N -  соответственно, максимально возможное и искомое число оборотов маховика, величины определяющее степень открытия затвора регулирующей арматуры. Значение N определяется в % от KV.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2659, N'Регулирующая арматура', N'ZD2', N'otn_kv', N'ОтнПротеч', N'Негерм.затвора, % от KV', N'Относительная протечка в % от KV (негерметичность затвора)', N'"Относительная протечка в % от KV (негерметичность затвора)" - цифровое поле, значение которого определяет величину протечки в % от пропускной способности (KV) через затвор регулирующей арматуры в закрытом состоянии (при минимальной площади прохода). Значение поля численно определяется расходом через регулирующую арматуру при минимальной площади прохода и перепаде давления на нем, равным 1 кгс/см2.  На основе этих данных может быть определено максимальное сопротивление задвижки при полном ее закрытии. Значение поля имеет размерность - %.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2660, N'Регулирующая арматура', N'ZD2', N'proz_kv', N'СтепеньОткрытия', N'Степень открытие арматуры в % от KV', N'Степень открытие арматуры в % от KV', N'"Степень открытие регулирующей арматуры"  -  цифровое поле, значение которого определяет число оборотов приводного маховика регулирующей арматуры  в % от максимально возможного количества оборотов  в полностью  открытом состоянии. Значение поля имеет размерность  -  %. Значение поля определяется  в процессе расчёта "Планового режима", в зависимости от регулируемого перепада давления на участке с арматурой.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2661, N'Регулирующая арматура', N'ZD2', N'sopr', N'ГидрСопр', N'Гидр.сопр.', N'Гидравлическое сопротивление', N'"Гидравлическое сопротивление регулирующей арматуры" - цифровое поле, значение которого  определяться в процессе расчёта "Планового режима", в зависимости от регулируемого перепада давления на участке с арматурой.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2662, N'Регулирующая арматура', N'ZD2', N'name', N'Наимен', N'Наименование', N'Содержательное наименование', N' "Содержательное наименование регулирующей арматуры" - символьное поле, значение которого произвольно и служит для идентификации установленной регулирующей арматуры в процессе имитации переключений потоков в сети.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2663, N'Регулирующая арматура', N'ZD2', N'name_zc', N'Тип арматуры', N'Тип арматуры', N'Тип арматуры', N'"Тип арматуры" - символьное поле, значение которого характеризует тип установленной регулирующей арматуры. Рекомендуется использовать функцию поля для её заполнения.', NULL, NULL)
