INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2665, N'Регулирующая арматура', N'ZD2', N'zemla', N'ПризнУправл', N'Призн.управл.затвор.с земли', N'Признак возможности управления затвором с поверхности земли', N'Признак возможности управления затвором с поверхности земли', NULL, NULL)
