INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2681, N'Регулятор давления', N'RD', N'sost', NULL, N'Состояние', N'Состояние', N'"Состояние регулятора" - символьное поле, значение которого однозначно определяет состояние, в котором находится клапан регулятора. Если в поле присутствует в качестве его значения "Неактивен", то это говорит о том, что клапан открыт, его сопротивление минимально, а регулирующее воздействие отключено. Если в поле отсутствуют какие-либо значения - "Открыт", то клапан в рабочем состоянии (регулятор активен), его сопротивление меняется в зависимости от изменения регулирующего воздействия. Если в поле присутствует символ - "Закрыт", то клапан закрыт,  регулирующее воздействие на него не формируется.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2682, N'Регулятор давления', N'RD', N'kod_p', NULL, N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2683, N'Регулятор давления', N'RD', N'uzel_p', NULL, N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2684, N'Регулятор давления', N'RD', N'pr_p', NULL, N'Признак трубопровода узла присоединения', N'Признак трубопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2685, N'Регулятор давления', N'RD', N'kod1', NULL, N'Код расчетной схемы начального узла', N'Код расчетной схемы узла на входе регулятора', N' "Код расчетной схемы узла на входе регулятора" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит узел на входе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2686, N'Регулятор давления', N'RD', N'uzel1', NULL, N'Наименование начального узла участка', N'Наименование узла на входе регулятора', N' "Наименование узла на входе регулятора " - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения регулирующего клапана регулятора на трубопроводах тепловой сети и задания направления потока теплоносителя через регулирующий клапан регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2687, N'Регулятор давления', N'RD', N'pr1', NULL, N'Признак теплопровода начального узла', N'Признак теплопровода на входе регулятора', N'«Признак  теплопровода»   -  символьное   поле,   значение которого  используется  для   указания принадлежности  начального узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» теплопроводам на расчетной схеме.  В  информационной базы данных значения слов ''''Подача", "Обратка" представлены, соответственно, символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2688, N'Регулятор давления', N'RD', N'kod2', NULL, N'Код расчетной схемы конечного узла', N'Код расчетной схемы узла на выходе регулятора', N' "Код расчетной схемы узла на выходе регулятора" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит узел на выходе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2689, N'Регулятор давления', N'RD', N'uzel2', NULL, N'Наименование конечного узла участка', N'Наименование узла на выходе регулятора', N' "Наименование узла на выходе регулятора " - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения регулирующего клапана регулятора на трубопроводах тепловой сети и задания направления потока теплоносителя через регулирующий клапан регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2690, N'Регулятор давления', N'RD', N'pr2', NULL, N'Признак  теплопровода конечного узла', N'Признак теплопровода на выходе регулятора', N'«Признак  теплопровода»   -  символьное   поле,   значение которого  используется  для   указания принадлежности  конечного узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» теплопроводам на расчетной схеме.  В  информационной базы данных значения слов ''''Подача", "Обратка" представлены, соответственно, символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2691, N'Регулятор давления', N'RD', N'uzu_k', NULL, N'Код расчетной схемы  узла   с  регулируемым   напором', N'Код расчетной схемы  узла   с  регулируемым   напором', N'"Код расчетной схемы узла с регулируемым напором" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит узел с регулируемым напором.', NULL, NULL)
