INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2694, N'Регулятор давления', N'RD', N'h_uzu', NULL, N'Значение  регулируемого  напора', N'Значение  регулируемого  напора', N'"Значение регулируемого напора" - цифровое поле, значение которого определяется требуемой величиной напора в указанном узле.', N'Давление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2695, N'Регулятор давления', N'RD', N'delta', NULL, N'Допустимое  отклонение  напора  от  заданного  значения', N'Допустимое  отклонение  напора  от  заданного  значения', N' "Допустимое отклонение напора от заданного значения" - цифровое поле, значение которого определяет точность поддержания требуемого напора регулятором в узле.', N'Давление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2696, N'Регулятор давления', N'RD', N'kv', NULL, N'Пропускная  способность  регулирующего  клапана', N'Пропускная  способность  регулирующего  клапана', N'"Пропускная способность регулирующего клапана регулятора" цифровое поле, значение которого определяется согласно ГОСТ 14591-69 как номинальная величина пропускной способности регулирующего клапана при максимальной площади прохода, численно равная расходу (т/ч) сетевой воды, пропускаемой регулирующим клапаном при перепаде давления на нем 9.81Е-2 МПА (1кгс/см2).  На основе этих данных может быть определено минимальное сопротивление регулируюшего органа при полном его открытии. Следовательно, если введено значение этого поля, значение минимального сопротивления клапана регулятора задавать не нужно. При наличии наряду с значением пропускной способности и значения гидравлического сопротивления клапана , приоритет отдается последнему .', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2697, N'Регулятор давления', N'RD', N'otn_kv', NULL, N'Относительная   протечка   в   %   от  KV (негерметичность  затвора)', N'Относительная   протечка   в   %   от  KV (негерметичность  затвора)', N' "Относительная протечка в % от KV(негерметичность  затвора)" - цифровое поле, значение которого определяет  величину протечки в % от KV через затвор клапана в закрытом  состоянии (при минимальной площади прохода). Значение поля  численно определяется расходом через клапан регулятора при  минимальной площади прохода и перепада давления на нем равным 1  кгс/см2. На основе этих данных может быть определено  максимальное сопротивление регулирующего органа при полном его  закрытии. При введении значения этого поля можно не задавать  значение гидравлического сопротивления клапана в закрытом  состоянии . При одновременном наличии значений относительной  протечки и гидравлического сопротивления приоритет отдается  сопротивлению.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2698, N'Регулятор давления', N'RD', N'min_sm', NULL, N'Гидравлическое   сопротивление    клапана   в    открытом  состоянии', N'Гидравлическое   сопротивление    клапана   в    открытом  состоянии', N'"Гидравлическое сопротивление клапана в открытом  состоянии"- цифровое поле, значение которого  представляет собой величину гидравлического сопротивления  полностью открытого клапана регулятора, при котором имеет место  наибольшая пропускная способность. Эта величина при имитации  режимов в сетях с теплопроводами большого диаметра может быть  приравнена гидравлическому сопротивлению соответствующего  дроссельного органа или может быть задана условно. При  введении значения этого поля можно не вводить значение  пропускной способности, т.к. приоритет отдается заданному  значению сопротивления клапана.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2699, N'Регулятор давления', N'RD', N'max_sm', NULL, N'Гидравлическое   сопротивление    клапана   в   закрытом  состоянии', N'Гидравлическое   сопротивление    клапана   в   закрытом  состоянии', N' "Гидравлическое сопротивление клапана в закрытом  состоянии" - цифровое поле, значение которого  представляет собой величину гидравлического сопротивления  клапана в закрытом состоянии (при минимальном проходном  сечении). Если значение не задано, но указана негерметичность  затвора, то программная система обеспечит автоматический расчет  гидравлического сопротивления без его записи в поле. Если  сопротивление задано пользователем, то приоритет отдается этому  значению, и по негерметичности затвора расчет его не  производится.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2700, N'Регулятор давления', N'RD', N'typ', NULL, N'Тип стандартного регулятора давления', N'Тип стандартного регулятора давления', N'"Тип стандартного регулятора давления"- символьное поле, значение которого характеризует тип установленного регулятора давления. Рекомендуется использовать функцию поля.', NULL, NULL)
