INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2711, N'Регулятор давления', N'RD', N'g_tep_poteri', NULL, N'Расход на слив', N'Расход на слив', N'"Технически обоснованный расход на слив" - цифровое поле,значение которого используется при расчете Потерь сетевой воды (ПСВ) со сливами из средств автоматического регулирования. Значение принимается согласно паспортным данным. По умолчанию значение равно 0.03 м**3/ч', NULL, N'м^3/ч')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2712, N'Регулятор давления', N'RD', N'pr_raboti', NULL, N'Период работы', N'Период работы', N'"Период работы" - текстовое поле, значение которого используется при расчете Потерь сетевой воды (ПСВ) со сливами из средств автоматического регулирования (САРЗ). Значение поля может принимать значения: "Отопительный", "Летний",  "Круглогодично",  означающие, соответственно, что данное САРЗ работает только в отопительный сезон, только в летний сезон, и в отопительный и в летний сезоны.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2713, N'Регулятор перепада давления', N'RP', N'nomer', NULL, N'№', N'Номер записи', N'Порядковый номер записи', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2714, N'Регулятор перепада давления', N'RP', N'sost', NULL, N'Состояние', N'Состояние', N'"Состояние регулятора" - символьное поле, значение которого однозначно определяет состояние, в котором находится клапан регулятора. Если в поле присутствует в качестве его значения "Неактивен", то это говорит о том, что клапан открыт, его сопротивление минимально, а регулирующее воздействие отключено. Если в поле отсутствуют какие-либо значения - "Открыт", то клапан в рабочем состоянии (регулятор активен), его сопротивление меняется в зависимости от изменения регулирующего воздействия. Если в поле присутствует символ - "Закрыт", то клапан закрыт,  регулирующее воздействие на него не формируется.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2715, N'Регулятор перепада давления', N'RP', N'kod_p', NULL, N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2716, N'Регулятор перепада давления', N'RP', N'uzel_p', NULL, N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2717, N'Регулятор перепада давления', N'RP', N'pr_p', NULL, N'Признак трубопровода узла присоединения', N'Признак трубопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2718, N'Регулятор перепада давления', N'RP', N'kod1', NULL, N'Код расчетной схемы начального узла', N'Код расчетной схемы узла на входе регулятора', N' "Код расчетной схемы узла на входе регулятора" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит узел на входе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2719, N'Регулятор перепада давления', N'RP', N'uzel1', NULL, N'Наименование начального узла участка', N'Наименование узла на входе регулятора', N' "Наименование узла на входе регулятора " - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения регулирующего клапана регулятора на трубопроводах тепловой сети и задания направления потока теплоносителя через регулирующий клапан регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2720, N'Регулятор перепада давления', N'RP', N'pr1', NULL, N'Признак теплопровода начального узла', N'Признак теплопровода на входе регулятора', N'«Признак  теплопровода»   -  символьное   поле,   значение которого  используется  для   указания принадлежности  начального узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» теплопроводам на расчетной схеме.  В  информационной базы данных значения слов ''''Подача", "Обратка" представлены, соответственно, символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2721, N'Регулятор перепада давления', N'RP', N'kod2', NULL, N'Код расчетной схемы конечного узла', N'Код расчетной схемы узла на выходе регулятора', N' "Код расчетной схемы узла на выходе регулятора" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит узел на выходе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2722, N'Регулятор перепада давления', N'RP', N'uzel2', NULL, N'Наименование конечного узла участка', N'Наименование узла на выходе регулятора', N' "Наименование узла на выходе регулятора " - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения регулирующего клапана регулятора на трубопроводах тепловой сети и задания направления потока теплоносителя через регулирующий клапан регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2723, N'Регулятор перепада давления', N'RP', N'pr2', NULL, N'Признак  теплопровода конечного узла', N'Признак теплопровода на выходе регулятора', N'«Признак  теплопровода»   -  символьное   поле,   значение которого  используется  для   указания принадлежности  конечного узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» теплопроводам на расчетной схеме.  В  информационной базы данных значения слов ''''Подача", "Обратка" представлены, соответственно, символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2724, N'Регулятор перепада давления', N'RP', N'kod_impulsa', NULL, N'Код расчетной схемы  узла присоединения импульсной трубки', N'Код расчетной схемы  узла присоединения импульсной трубки', N'"Код расчетной схемы  узла присоединения импульсной трубки" - символьное поле, значение которого однозначно определяет расчетную схему или ее фрагмент, которой принадлежит узел  для присоединения импульсной трубки  установленного регулятора', NULL, NULL)
