INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2727, N'Регулятор перепада давления', N'RP', N'h_regul', NULL, N'Значение  регулируемого перепада давления', N'Значение  регулируемого перепада давления', N'"Значение  регулируемого перепада давления" - числовое поле, определяющее заданное значение  перепада давления из диапазона настройки перепада давления установленного регулятора.', N'Давление', NULL)
