INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2729, N'Регулятор перепада давления', N'RP', N'kv', NULL, N'Условная пропускная  способность  регулирующего  клапана  регулятора', N'Условная пропускная  способность  регулирующего  клапана  регулятора', N'"Условная пропускная  способность  регулирующего  клапана  регулятора" - числовое поле,   определяющее   количество воды при температуре 20 °С , которое способен пропустить регулирующий клапан регулятора при перепаде давления на нем 0,1 МПа (1 кгс/см2,  1бар ) при полностью открытом клапане.', N'Расход', NULL)
