INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2746, N'Регулятор перепада давления', N'RP', N'k_kavit', NULL, N'Коэффициент кавитации', N'Коэффициент кавитации', N'"Коэффициент кавитации" - безразмерное числовое поле, определяющее перепад давления на затворе клапана регулятора, при котором может возникнуть кавитация. Используется при выборе режима работы клапана регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2747, N'Регулятор перепада давления', N'RP', N'g_tep_poteri', NULL, N'Расход на слив', N'Расход на слив', N'"Технически обоснованный расход на слив" - цифровое поле,значение которого используется при расчете Потерь сетевой воды (ПСВ) со сливами из средств автоматического регулирования. Значение принимается согласно паспортным данным. По умолчанию значение равно 0.03 м**3/ч', NULL, N'м^3/ч')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2748, N'Регулятор перепада давления', N'RP', N'pr_raboti', NULL, N'Период работы', N'Период работы', N'"Период работы" - текстовое поле, значение которого используется при расчете Потерь сетевой воды (ПСВ) со сливами из средств автоматического регулирования (САРЗ). Значение поля может принимать значения: "Отопительный", "Летний",  "Круглогодично",  означающие, соответственно, что данное САРЗ работает только в отопительный сезон, только в летний сезон, и в отопительный и в летний сезоны.означает, что САРЗ задействован и в отопительный и влетний сезоны, за исключением  ремонтного периода.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2749, N'Регулятор расхода', N'RR', N'nomer', NULL, N'№', N'Номер записи', N'Порядковый номер записи', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2750, N'Регулятор расхода', N'RR', N'sost', NULL, N'Состояние', N'Состояние', N'"Состояние регулятора" - символьное поле, значение которого однозначно определяет состояние, в котором находится клапан регулятора. Если в поле присутствует в качестве его значения "Неактивен", то это говорит о том, что клапан открыт, его сопротивление минимально, а регулирующее воздействие отключено. Если в поле отсутствуют какие-либо значения - "Открыт", то клапан в рабочем состоянии (регулятор активен), его сопротивление меняется в зависимости от изменения регулирующего воздействия. Если в поле присутствует символ - "Закрыт", то клапан закрыт,  регулирующее воздействие на него не формируется.', NULL, NULL)


