INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2751, N'Регулятор расхода', N'RR', N'kod_p', NULL, N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2752, N'Регулятор расхода', N'RR', N'uzel_p', NULL, N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2753, N'Регулятор расхода', N'RR', N'pr_p', NULL, N'Признак теплопровода узла присоединения', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2754, N'Регулятор расхода', N'RR', N'kod1', NULL, N'Код расчетной схемы начального узла', N'Код расчетной схемы узла на входе регулятора', N' "Код расчетной схемы узла на входе регулятора" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит узел на входе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2755, N'Регулятор расхода', N'RR', N'uzel1', NULL, N'Наименование начального узла', N'Наименование узла на входе регулятора', N' "Наименование узла на входе регулятора " - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения регулирующего клапана регулятора на трубопроводах тепловой сети и задания направления потока теплоносителя через регулирующий клапан регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2756, N'Регулятор расхода', N'RR', N'pr1', NULL, N'Признак теплопровода начального узла', N'Признак теплопровода на входе регулятора', N'«Признак  теплопровода»   -  символьное   поле,   значение которого  используется  для   указания принадлежности  начального узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» теплопроводам на расчетной схеме.  В  информационной базы данных значения слов ''''Подача", "Обратка" представлены, соответственно, символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2757, N'Регулятор расхода', N'RR', N'kod2', NULL, N'Код расчетной схемы конечного узла', N'Код расчетной схемы узла на выходе регулятора', N' "Код расчетной схемы узла на выходе регулятора" - символьное поле, значение которого однозначно определяет расчетную схему, которой принадлежит узел на выходе регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2758, N'Регулятор расхода', N'RR', N'uzel2', NULL, N'Наименование конечного узла', N'Наименование узла на выходе регулятора', N' "Наименование узла на выходе регулятора " - символьное поле, значение которого совместно с кодом расчетной схемы, однозначно определяет узел на расчетной схеме. Это наименование используется для указания местоположения регулирующего клапана регулятора на трубопроводах тепловой сети и задания направления потока теплоносителя через регулирующий клапан регулятора.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2759, N'Регулятор расхода', N'RR', N'pr2', NULL, N'Признак теплопровода конечного узла', N'Признак теплопровода на выходе регулятора', N'«Признак  теплопровода»   -  символьное   поле,   значение которого  используется  для   указания принадлежности  конечного узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» теплопроводам на расчетной схеме.  В  информационной базы данных значения слов ''''Подача", "Обратка" представлены, соответственно, символами "П", "О" и пробел.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2760, N'Регулятор расхода', N'RR', N'q_zad', NULL, N'Значение регулируемого  расхода', N'Значение регулируемого  расхода', N' "Значение регулируемого расхода - цифровое поле, значение которого определяется требуемой величиной расхода в указанном участке.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2761, N'Регулятор расхода', N'RR', N'delta', NULL, N'Допустимое отклонение расхода от заданного значения', N'Допустимое отклонение расхода от заданного значения', N' "Допустимое отклонение расхода от заданного значения" - цифровое поле, значение которого определяет точность поддержания требуемого расхода регулятором на участке.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2762, N'Регулятор расхода', N'RR', N'kv', NULL, N'Пропускная способность регулирующего клапана', N'Пропускная способность регулирующего клапана', N' "Пропускная способность регулирующего клапана регулятора" цифровое поле, значение которого определяется согласно ГОСТ 14591-69 как номинальная величина пропускной способности регулирующего клапана при максимальной площади прохода, численно равная расходу (т/ч) сетевой воды, пропускаемой регулирующим клапаном,при перепаде давления на нем 9.81Е-2 МПА (1кгс/см2).  На основе этих данных может быть определено минимальное сопротивление регулируюшего органа при полном его открытии. Следовательно, если введено значение этого поля, значение минимального сопротивления клапана регулятора задавать не нужно. При наличии наряду с значением пропускной способности и значения гидравлического сопротивления клапана , приоритет отдается последнему.', N'Расход', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2763, N'Регулятор расхода', N'RR', N'otn_kv', NULL, N'Относительная протечка в % от KV(негерметичность  затвора)', N'Относительная протечка в % от KV(негерметичность  затвора)', N' "Относительная протечка в % от KV(негерметичность  затвора)" - цифровое поле, значение которого определяет  величину протечки в % от KV через затвор клапана в закрытом  состоянии (при минимальной площади прохода). Значение поля  численно определяется расходом через клапан регулятора при  минимальной площади прохода и перепада давления на нем равным 1  кгс/см2. На основе этих данных может быть определено  максимальное сопротивление регулирующего органа при полном его  закрытии. При введении значения этого поля можно не задавать  значение гидравлического сопротивления клапана в закрытом  состоянии . При одновременном наличии значений относительной  протечки и гидравлического сопротивления приоритет отдается  сопротивлению.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2764, N'Регулятор расхода', N'RR', N'min_sm', NULL, N'Гидравлическое сопротивление клапана в открытом  состоянии', N'Гидравлическое сопротивление клапана в открытом  состоянии', N' "Гидравлическое сопротивление клапана в открытом  состоянии"- цифровое поле, значение которого  представляет собой величину гидравлического сопротивления  полностью открытого клапана регулятора, при котором имеет место  наибольшая пропускная способность. Эта величина при имитации  режимов в сетях с трубопроводами большого диаметра может быть  приравнена гидравлическому сопротивлению соответствующего  дроссельного органа или может быть задана условно. При  введении значения этого поля можно не вводить значение  пропускной способности, т.к. приоритет отдается заданному  значению сопротивления клапана.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2765, N'Регулятор расхода', N'RR', N'max_sm', NULL, N'Гидравлическое сопротивление клапана в закрытом  состоянии', N'Гидравлическое сопротивление клапана в закрытом  состоянии', N' "Гидравлическое сопротивление клапана в закрытом  состоянии" - цифровое поле, значение которого  представляет собой величину гидравлического сопротивления  клапана в закрытом состоянии (при минимальном проходном  сечении). Если значение не задано, но указана негерметичность  затвора, то программная система обеспечит автоматический расчет  гидравлического сопротивления без его записи в поле. Если  сопротивление задано пользователем, то приоритет отдается этому  значению, и по негерметичности затвора расчет его не  производится.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2766, N'Регулятор расхода', N'RR', N'typ', NULL, N'Тип стандартного регулятора расхода', N'Тип стандартного регулятора расхода', N'"Тип стандартного регулятора давления"- символьное поле, значение которого характеризует тип установленного регулятора расхода. Рекомендуется использовать функцию поля.', NULL, NULL)
