INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2813, N'Система теплоснабжения', N'CT', N'year', N'КалендГод', N'Календарный год начала отопительного сезона', N'Календарный год начала отопительного сезона', N'"Календарный год начала отопительного сезона"- символьное  поле,  значение  которого определяет календарный год начала отопительного сезона работы системы теплоснабжения. Например, 2011. Летний сезон работы системы теплоснабжения будет соответствовать, для данного примера, следующему календарному году, т.е. 2012.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2814, N'Система теплоснабжения', N'CT', N't_or', N'ТрасчОт', N'Расч.темп.наружного возд.для отопления', N'Расчетная температура наружного воздуха для отопления', N'"Расчетная   температура   наружного   воздуха для отопления"  - цифровое  поле,  значение  которого определяет темпеpатуpу наиболее холодной пятидневки отопительного сезона, ноpмиpуемая СНиП 23-01-99*  Строительная климатология. Значения данной величины используется в качестве проектной при определелении теплопотерь зданиями (таблица "Расчетные температуры") и расчетной для отопления при построении графика температур на отопление при центральном качественном регулировании (вкладка График температур окна формы Источник тепла). Внимание! Ввод и редактирование значения данной величины возможно только в поле данного окна "Система теплоснабжения". Для ввода значения рекомендуется использовать функцию поля.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2815, N'Система теплоснабжения', N'CT', N't_vr', N'ТрасчВент', N'Расч.темп.наружного возд.для ветиляции', N'Расчетная температура наружного воздуха для вентиляции', N'"Расчетная температура наружного воздуха для вентиляции" - цифровое  поле,  значение  которого используется в качестве проектного при определелении расчетной тепловой нагрузки на вентиляцию или воздушное отопление здания (таблица "Расчетные температуры") и расчетной для вентиляции или воздушного отопления при построении графика температур сетевой воды при центральном качественном регулировании (вкладка График температур окна формы Источник тепла). Внимание! Ввод и редактирование значения данной величины возможно только в поле данного окна "Система теплоснабжения". Для ввода значения рекомендуется использовать функцию поля.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2816, N'Система теплоснабжения', N'CT', N't_vnew', N'ТначОтопПериода', N'Темп.наружного возд.конца(начала) отоп.сезона', N'Температура наружн. воздуха конца/начала отопит.периода', N' "Температура наружного воздуха конца/начала отопительного периода "-  цифровое  поле,  значение  которого определяет среднесуточную температуру наружного воздуха равная  10 Град.С и ниже, определяющую продолжительность отопительного  периода для каждого климатического района в соответствии со СНиП 23-01-99* Строительная климатология.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2817, N'Система теплоснабжения', N'СТ', N'tx', N'Тхол_зима', N'Расч.темп.холодной воды в отопит.период', N'Расч.температура водопроводной воды в отопит.период', N'"Расчетная температура водопроводной (холодной) воды" - цифровое  поле, значение  которого определяет расчетную температуру холодной (водопроводной) воды в системах горячего водоснабжения в отопительный период функционирования системы теплоснабжения.', NULL, N'Град.С')
