INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2820, N'Система теплоснабжения', N'CT', N'year_audit', N'ГодАудита', N'Отоп.сезон аудита', N'Дата аудита', N'"Дата аудита"- поле типа Дата, значение  которого определяет год технического аудита независимыми специалистами системы теплоснабжения на предмет состояния и технического уровня действующих, и проектируемых СЦТ, а также определения перспективных направлений дальнейшего технического совершенствования, повышения прибыльности и конкурентоспособности, также проверку технической и проектной документации с выражением мнения относительно обоснованности применяемых технических/технологических решений, способов управления производством и соответствия технического состояния сетей, систем и оборудования требованиям нормативных актов. Значение поля носит информационный характер.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2821, N'Система теплоснабжения', N'CT', N'phone_manager', N'Телефон', N'Телефон/факс руководителя', N'Телефон/факс руководителя', N'"Телефон/факс руководителясимвольное" - символьное поле,  значение  которого носит информационный характер.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2822, N'Система теплоснабжения', N'CT', N'begin_year', N'ДатаНачОтопПер', N'Дата начала отоп.периода', N'Дата начала отопительного/летнего периода', N'"Дата начала отопительного/летнего периода" - поле типа Дата, значение  которого определяет календарную дату начала отопительного/летнего периода системы теплоснабжения. Значение  поля используется для определения начала/конца отопительного/летнего  периода при расчете среднемесячных тепловых потерь.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2823, N'Система теплоснабжения', N'CT', N'end_year', N'ДатаОкончОтопПер', N'Дата окончания отоп.периода', N'Дата окончания отопительного/летнего периода', N'"Дата окончания отопительного/летнего периода" - поле типа Дата, значение  которого определяет календарную дату окончания отопительного/летнего периода системы теплоснабжения. Значение  поля используется для определения начала/конца отопительного/летнего  периода при расчете среднемесячных тепловых потерь.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2824, N'Система теплоснабжения', N'СТ', N'tx_leto', N'Тхол_лето', N'Расч.темп.холодной воды в летний период', N'Расчетная температура водопроводной воды в летний период', N'"Расчетная температура водопроводной (холодной) воды" - цифровое  поле, значение  которого определяет расчетную температуру холодной (водопроводной) воды в системах горячего водоснабжения в летний период функционирования системы теплоснабжения.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2825, N'Система теплоснабжения', N'СТ', N'tip_Qgvs', N'Нагрузка ГВС', N'Нагрузка ГВС', N'Задаваемая нагрузка горячего водоснабжения', N'"Задаваемая нагрузка горячего водоснабжения" - текстовое поле, значение  которого определяет вид задаваемого значения нагрузки горячего водоснабжения в системах теплопотребления горячего водоснабжения тепловых пунктах системы теплоснабжения. Значение поля "Средняя" сигнализирует о том, что необходимо задавать среднее значение нагрузок горячего водоснабжения для всех тепловых пунктов (обобщенных, реальных) системы теплоснабжения, "Максимальная"- максимальное значение. Среднее, максимальное, балансовое  значения связываюся между собой через следующие выражения: Qмакс=k*Qcред, где k-коэффициент часовой неравномерности, для района теплоснабжения k=1.7-2.2. Qбаланс=b*Qcред, где b - балансовый коэффициент часового расхода тепла на горячее водоснабжение, при котором обеспечивается суточный баланс теплоты на отопление, несмотря на неравномерность суточного графика горячего водоснабжения. Рекомендуемые значения b смотрите в Справочноq таблице 28_Коэффициенты расчета балансовой нагрузки ГВ.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2826, N'Система теплоснабжения', N'СТ', N'tn_god', N'Среднесезон. температура наружн.возд., отоп.период', N'Среднесезонная температура наружного воздуха, отопит.период', N'Среднесезонная температура наружного воздуха, отопит.период', N'Сренесезонное значение темпратуры наружного воздуха определяется как среднее значение из ожидаемых среднемесячных значений температуры наружного воздуха в отопительный период. Ожидаемые среднемесячные значения температуры наружного воздуха определяются как средние значения из соответствующих статистических климатологических значений за последние 5 лет по данным местной метеорологической станции или по климатологическим справочникам. Значение поле используется при расчете  тепловых потерь.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2827, N'Система теплоснабжения', N'СТ', N'tg_god', N'Среднесезон. температура грунта, отоп.период', N'Среднесезонная температура грунта, отопит.период', N'Среднесезонная  температура грунта, отопит.период', N'Сренесезонное значение темпратуры грунта  определяется как среднее значение из ожидаемых среднемесячных значений температуры грунта на уровне заложения теплопроводов в  отопительный период.  Ожидаемые среднемесячные значения температуры грунта  на уровне заложения теплопроводов определяются как средние значение из соответствующих статистических климатологических значений за последние 5 лет по данным местной метеорологической станции или по климатологическим справочникам. Значение поле используется при расчете  тепловых потерь.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2828, N'Система теплоснабжения', N'СТ', N'a', N'НормаПСВутечкой', N'Нормативная потеря сетевой воды с утечкой', N'Нормативная потеря сетевой воды с утечкой', N'"Нормативная потеря сетевой воды с утечкой" - числовое поле, значение которого определяет нормируемую среднегодовую утечку сетевой воды, м**3/(ч*м**3). Устанавливается не более 0.25% в час от среднегодового объема сетевой воды в тепловой сети и присоединенных к ней системах теплопотребления (0.0025 м**3/(ч*м**3). Для конкретной тепловой сети этот процент устанавливается в размере, не превышающием указанное значения, руководством АО-энерго на основании анализа статистики фактических потерь сетевой воды. Значение поле используется при расчете тепловых потерь с утечкой.', NULL, N'%')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2829, N'Система теплоснабжения', N'СТ', N'tn_god_leto', N'Среднесезон. температура наружн.возд., летн.период', N'Среднесезонная температура наружного воздуха,  летний период', N'Среднесезонная температура наружного воздуха, летний период', N'Сренесезонное значение темпратуры наружного воздуха определяется как среднее значение из ожидаемых среднемесячных значений температуры наружного воздуха в летний период. Ожидаемые среднемесячные значения температуры наружного воздуха определяются как средние значения из соответствующих статистических климатологических значений за последние 5 лет по данным местной метеорологической станции или по климатологическим справочникам. Значение поле используется при расчете  тепловых потерь.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2830, N'Система теплоснабжения', N'СТ', N'tg_god_leto', N'Среднесезон. температура грунта,  летний период', N'Среднесезонная температура грунта,  летний период', N'Среднесезонная температура грунта, летний период', N'Сренегодовое значение темпратуры грунта  определяется как среднее значение из ожидаемых среднемесячных значений температуры грунта на уровне заложения теплопроводов в летний период. Ожидаемые среднемесячные значения температуры грунта  на уровне заложения теплопроводов определяются как средние значение из соответствующих статистических климатологических значений за последние 5 лет по данным местной метеорологической станции или по климатологическим справочникам. Значение поле используется при расчете  тепловых потерь.', NULL, N'Град.С')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2831, N'Система теплоснабжения', N'СТ', N'begin_year', N'ДатаНачОтопСезона', N'Дата начала отоп.сезона', N'Дата начала отопительного сезона', N'"Дата начала отопительного сезона" - поле типа Дата, значение  которого определяет календарную дату начала отопительного периода системы теплоснабжения. Значение  поля используется для определения начала отопительного периода (конца летнего периода) при расчете тепловых потерь.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2832, N'Система теплоснабжения', N'СТ', N'end_year', N'ДатаОкончОтопСезона', N'Дата окончания отоп.сезона', N'Дата окончания отопительного сезона', N'"Дата окончания отопительного сезона" - поле типа Дата, значение  которого определяет календарную дату окончания отопительного периода системы теплоснабжения. Значение  поля используется для определения  конца отопительного периода (начала летнего периода) при расчете тепловых потерь.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2833, N'Спусковое устройство', N'UT', N'kod_p', NULL, N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
