INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2835, N'Спусковое устройство', N'UT', N'pr_p', NULL, N'Признак теплопровода узла присоединения', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел', NULL, NULL)
