INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2941, N'Удельные расходы', N'UR', N'kodur', N'КодУР', N'Код УР', N'Код удельных расходов', N' "Код группы удельных расходов" - символьное поле,  значение которого   определяет   группу   удельных   расходов   по  видам теплопотребления.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2942, N'Удельные расходы', N'UR', N'kod_ist', N'КодИст', N'Код ист.тепла', N'Код источника тепла', N'"Код источника тепла" -  символьное поле,  значение которого определяет принадлежность объекта УР источику тепла.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2943, N'Удельные расходы', N'UR', N'otoplz', N'УР_СОЗав', N'УР потреб.на  отопл., зав.сх.', N'Удельный  расход  потребителя  на  отопление, зависимая схема', N'"Удельный расход потребителя на отопление, зависимая схема" - цифровое поле,  значение которого равно  значению коэффициента пропорциональности между расчетным расходом воды на отопление  и расчетной тепловой нагрузкой(Гкал/ч) отопления при фиксированном расчетном  температурном  перепаде  теплоносителя  (Град.ц) в процессе   теплообмена   в   теплообменных   аппаратах   системы отопления.   Значение  поля  имеет  по умолчанию размерность,  т/Гкал.   т.е. определяет  сколько  тонн  теплоносителя  могут  перенести  одну единицу  количества  тепла(1  Гкал)  при расчетном температурном перепаде теплоносителя в процессе теплообмена.  Удельные расходы сетевой воды на отопление могут принимать следующие значения для типовых температурных графиков: 150-70 Град. С  - 12.5 т/Гкал    130-80 Град. С  - 20   т/Гкал 150-80 Град. С  - 14.3 т/Гкал    105-70 Град. С  - 28.6 т/Гкал 140-70 Град. С  - 14.3 т/Гкал     95-70 Град. С  - 40   т/Гкал 130-70 Град. С  - 16.7 т/Гкал Если потребитель подключен по 4-х трубной схеме, т. е.  нагрузка ГВС реализуется по  отдельным трубам, то  в сети ГВС  появляется дополнительная тепловая  нагрузка на  компенсацию теплопотерь  в трубопроводах  сети  ГВС  и  отопление  ванных  комнат с помощью полотенцесушителей,   обеспечивающая   непрерывную    циркуляцию энергоносителя в  сети ГВС.  Эту дополнительную  нагрузку удобно моделировать  нагрузкой  отопления  по  зависимой  схеме. Обычно величина этой нагрузки может быть  определена по формуле Q от  = 0.3 Q гв  , где Q  гв - средняя  нагрузка горячего водоснабжения потребителя,  Гкал/ч.   Удельный   расход  для  пересчета   этой тепловой нагрузки в циркуляционный расход (т/ч) можно  принимать равным  Куд = 95.   Это  значение  учитывает  как разрегулировки циркуляции, так и регламентируемый СНИП 2.04.01-85 температурный перепад по подающим  трубопроводам и водоразборным  стоякам сети ГВС.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2944, N'Удельные расходы', N'UR', N'otopln', N'УР_СОНез', N'УР потреб.на  отопл., незав.сх.', N'Удельный  расход  потребителя  на  отопление,  независимая схема', N'"Удельный  расход  потребителя  на  отопление,  независимая схема"  -  цифровое  поле,  значение  которого  равно   значению коэффициента пропорциональности между расчетным расходом воды на отопление и расчетной  тепловой нагрузкой(Гкал/ч) отопления  при фиксированном  расчетном  температурном  перепаде  теплоносителя (Град.ц)  в  процессе  теплообмена  в  теплообменных   аппаратах системы  отопления.   Значение  поля  имеет   по умолчанию размерность, т/Гкал. т.е. определяет сколько тонн теплоносителя могут перенести  одну единицу  количества  тепла(1  Гкал)  при расчетном температурном перепаде теплоносителя в процессе теплообмена.  При  независимом присоединении системы отопления расчетную температуру в обратном трубопроводе тепловой сети  после подогревателя принимают  на 10 Град.С   выше    расчетной   температуры    воды    в   обратном трубопроводе, идущем  от системы  отопления, а  поэтому удельные расходы для типовых температурных графиков принимают значения: 150-80 Град. С  - 14.3 т/Гкал     130-80 Град. С  - 20.0 т/Гкал 150-90 Град. С  - 16.7 т/Гкал     130-90 Град. С  - 25.0 т/Гкал 140-80 Град. С  - 16.7 т/Гкал', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2945, N'Удельные расходы', N'UR', N'ventil', N'УР_Вент', N'УР потреб.на  вент.', N'Удельный  расход  потребителя   на вентиляцию', N' "Удельный  расход  потребителя  на  вентиляцию"  - цифровое поле,   значение    которого   равно    значению    коэффициента пропорциональности между расчетным расходом воды на вентиляцию и расчетной  тепловой   нагрузкой  (Гкал/ч)   на  вентиляцию   при фиксированном  расчетном  температурном  перепаде  теплоносителя (Град.С)    в     процессе     теплообмена     в     калориферах приточно-вентиляционных   установок.     Значение   поля   имеет размерность (т/Гкал) ,  т.е.    определяет     сколько      тонн теплоносителя могут перенести  одну единицу количества  тепла (1 Гкал)  при  расчетном  температурном  перепаде  теплоносителя  в процессе теплообмена.  Обычно приточно-вентиляционные  установки проектируются  на  расчетную  температуру  наружного воздуха для отопления, и  поэтому значения  удельных расходов  на вентиляцию для типовых температурных  графиков будут совпадать  с удельными расходами на отопление.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2946, N'Удельные расходы', N'UR', N'kondiz', N'УР_Конд', N'УР потреб.на  конд.', N'Удельный  расход  потребителя   на  кондиционирование', N'"Удельный  расход  потребителя   на  кондиционирование"   - цифровое поле, значение которого определяется расчетным расходом на одну Гкал.  тепла  по данному виду теплопотребления.   Расход же   в   свою   очередь   определяется   графиком   центрального качественного регулирования отпуска тепла.  Значение поля  имеет   по умолчанию  размерность, т/Гкал.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2947, N'Удельные расходы', N'UR', N'txz', N'УР_ТехнЗакр', N'УР потреб.на техн.проц.в закр.ТС', N'Удельный расход потребителя на технологические процессы в закрытой ТС', N'"Удельный расход потребителя на технологические процессы  в закрытой  системе  теплоснабжения"  -  цифровое  поле,  значение которого определяется расчетным расходом на одну Гкал. тепла  по данному  виду  теплопотребления.   Расход  же  в  свою   очередь определяется графиком  центрального качественного  регулирования отпуска тепла.  Значение поля имеет   по умолчанию  размерность, т/Гкал.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2948, N'Удельные расходы', N'UR', N'txo', N'УР_ТехнОткр', N'УР потреб.на техн.проц.в откр.ТС', N'Удельный расход потребителя на технологические процессы в открытой ТС', N'"Удельный расход потребителя на технологические процессы  в открытой системе теплоснабжения  (водоразбор)" - цифровое  поле, значение которого определяется расчетным расходом на одну  Гкал. тепла  по  данному  виду  теплопотребления.  Значение поля имеет   по умолчанию размерность, т/Гкал.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2949, N'Удельные расходы', N'UR', N'gvo', N'УР_ГВ_откр.', N'УР на ГВ при откр.ТС', N'Удельный  расход  на  горячее  водоснабжение при открытой ТС', N'"Удельный  расход  на  горячее  водоснабжение  при открытой системе  теплоснабжения"  -  цифровое  поле,  значение  которого опреляет расход сетевой воды на одну Гкал.  тепла , расходуемого на  горячее  водоснабжение  в  открытой  системе  теплоснабжения (водоразбор  на  ГВ  из  сети).   Величина  удельного расхода на открытое  ГВС  определяется   по  формуле  Куд = 1000/(Тг - Тх), т/Гкал, где Тг, Тх - соответственно, температура горячей воды  в месте водоразбора и температура  водопроводной  воды.  Обычно Тг =60  Град.С, а  Тх  =5  Град.С, тогда Куд = 18.2 т/Гкал.Значение поля имеет   по умолчанию размерность, т/Гкал.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2950, N'Удельные расходы', N'UR', N'rez', N'УР_ГВ_цирк', N'УР на комп.тепл.потерь рецирк.ГВС', N'Удельный рециркуляционный расход на компенсацию тепловых потерь открытой  ГВС', N' "Удельный рециркуляционный расход на  компенсацию тепловых потерь  трубопроводами  открытой  ГВС" - цифровое поле, значение которого определяет расход  сетевой  воды  на  одну  Гкал тепла,  расходуемого на рециркуляцию в открытой системе горячего   водоснабжения. Значение  поля  имеет    по умолчанию размерность,  т/Гкал.  Численное значение удельного  расхода  принимают  равным Куд=1/(dt*с), где dt = ((Тг-Тх)-Тост) - разность температур горячей воды в трубопроводах водоразборных стояков, где Тг - температура горячей воды в системах горячего водоснабжения с непосредственным водоразбором, Тх - температура водопроводной воды.  При   расчетах рециркуляционных сетей  ГВС допустимая температура остывания воды  (Тост) в подающих трубопроводах  обычно  принимают  из  диапазона  30-50  Град.  С., что соответствует величине расчетного расхода теплоты на компенсацию тепловых потерь в системе горячего водоснабжения в размере 10-30% средней нагрузки горячего водоснабжения. Тогда  возможные  значения  удельного  расхода  на   компенсацию тепловых потерь могут быть определены из таблицы, при Тг = 60 Град.С, Тх = 5 Град.С: 
  Допустимое остывание (Тост), Град. С.       30        40       50 
  Удельный расход,   т/Гкал                            40       66.7     200', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2951, N'Удельные расходы', N'UR', N'gvpr', N'УР_ГВ_парал', N'УР на ГВ при парал.ГВС', N'Удельный расход на горячее водоснабжение при параллельной ГВС', N'"Удельный  расход  на  горячее  водоснабжение  в   закрытой системе  теплоснабжения  при  параллельной  схеме  присоединения подогревателей ГВ" - цифровое поле, значение которого определяет расход  сетевой  воды  на  одну  Гкал.   тепла,  расходуемого на горячее   водоснабжение   при   данном   виде  теплопотребления. Значение  поля  имеет  размерность,  т/Гкал.  Численное значение удельного  расхода  принимают  равным  Куд  =  25  т/Гкал,  если тепловой пункт оборудован  регулятором расхода и  температуры, и равен  Куд   =28.8,  если   тепловой  пункт   оборудован  только регулятором температуры или вообще не автоматизирован.   Удельный расход сетевой воды на горячее водоснабжение принимается при максимальной нагрузке на ГВС  и наружной температуре  tн_изл, соответствующей излому температурного графика.  Куд=(Vг_макс/Qгв_макс)=1/((t1_изл - t2_г2_изл)*с), где Vг_макс=b* Vг_средн, b - коэффициент часовой неравномерности (для района теплоснабжения b=1.7-2.2.),  t1_изл -температура сетевой воды в подающей линии сети, работающей по отопительному графику и  имеещей место при наружной температуре  tн_изл, соответствующей излому температурного графика.  t2_г2_изл - температура сетевой воды на выходе из подогревателя ГВС при  tн_изл и максимальной нагрузке на горячее водоснабжение. В проектах  t2_г2_изл обычно принимается равным 20-40 Град.С, при отсутствии проектных данных можно принимать  30 Град.С.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2952, N'Удельные расходы', N'UR', N'gvsm', N'УР_ГВ_смеш', N'УР на ГВ при смеш.ГВС', N'Удельный  расход на горячее водоснабжение при смешанной ГВС', N'"Удельный  расход  на  горячее  водоснабжение  в   закрытой системе  теплоснабжения   при  смешанной   схеме   присоединения подогревателей ГВ" - цифровое поле, значение которого определяет расход  сетевой  воды  на  одну  Гкал   тепла , расходуемого на горячее   водоснабжение   при   данном   виде  теплопотребления. Значение  поля  имеет    по умолчанию размерность,  т/Гкал.  Численное значение удельного расхода  для температурного  графика 130-70  Град.С  и 150-70  Град.С   и  оснащении  теплового   пункта   регуляторами расхода воды и температуры равно Куд = 18.2*b, где b =1.7 -  2.2 -коэффициент часовой неравномерности для района  теплоснабжения. При тех же температурных графиках, но оснащении теплового пункта регулятором температуры,  удельные расходы  равны Куд  =16 и Куд =16.5, соответственно.  Удельный расход сетевой воды на горячее водоснабжение принимается при максимальной нагрузке на ГВС  и наружной температуре  tн_изл, соответствующей излому температурного графика.   Куд=(Vг_макс/Qгв_макс)=gв_макс*(tг - t2см_изл + dt)/(t1_изл - t2см_изл),  где Vг_макс=b* Vг_средн, b - коэффициент часовой неравномерности (для района теплоснабжения b=1.7-2.2.), gв_макс=10^6/(с(tг - tх), удельный расход водопроводной воды на 1 Гкал/ч (1 МВт) максимальной нагрузки горячего водоснабжения.  Температура сетевой воды на выходе из второй ступени подогревателя принимается равной температуре воды на выходе из системы отопления, т.е. t2см_изл=t2_г2_изл=t2_со_изл. dt - принимаемая величина недогрева водопроводной воды до температуры обратной воды, поступающей из системы отопления, в 1 ступень водонагревательной установки. Для автоматизированного теплового пункта dt принимается равной 10 Град.С. При отсутствии на тепловых пунктах регуляторов постоянства расхода на отопление, но при установке регуляторов температуры горячей воды, удельный расход определяется в точке излома температурного графика по балансовой нагрузке горячего водоснабжения, dt при этом принимается равным 5 Град.С.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2953, N'Удельные расходы', N'UR', N'gvps', N'УР_ГВ_посл', N'УР на ГВ при послед.ГВС', N'Удельный  расход на горячее водоснабжение при последовательной ГВС', N'"Удельный  расход  на  горячее  водоснабжение  в   закрытой системе теплоснабжения при последовательной схеме  присоединения подогревателей ГВ" - цифровое поле, значение которого определяет расход  сетевой  воды  на  одну  Гкал.   тепла,  расходуемого на горячее   водоснабжение   при   данном   виде  теплопотребления. Значение  поля  имеет    по умолчанию размерность,  т/Гкал.  Численное значение удельного расхода  для температурных  графиков 130-70  Град. С и 150-70 Град. С  соответственно равно Куд  =18.1 и Куд  =18.7 при оснащении  теплового  пункта  регулятором  расхода и температуры воды. При наличии на тепловых пунктах автоматических регуляторов, поддерживающих постоянный расход сетевой воды и постоянную температуру воды для горячего водоснабжения удельный расход сетевой воды на горячеее водоснабжение определяется в точке излома  температурного графика по балансовой нагрузке горячего водснабжения: при отопительном температурном графике регулирования  Куд=gв_баланс*(tг - t2со_изл + dt)/(t1_изл - t2со_изл), где gв_баланс=1.25*10^6/(с*(tг - tх), удельный расход водопроводной воды на 1 Гкал/ч (1 МВт) балансовой нагрузки горячего водоснабжения, при повышенном температурном графике удельный расход на горячее водоснабжение принимается равным 0.  Величину dt (недогрев водопроводной воды до температуры обратной воды, поступающей из системы отопления, в 1 ступень водонагревательной установки) обычно принимают равной 5 Град.С,  при t1_расч=150 Град.С принимают t2со_изл=41.7, при t1_расч=130 Град.С принимают t2со_изл=44.8.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2954, N'Удельные расходы', N'UR', N'gvpw', N'УР_ГВ_предвкл', N'УР на ГВ при предвкл.ГВС', N'Удельный  расход на горячее водоснабжение при предвключенной ГВС', N'"Удельный  расход  на  горячее  водоснабжение  в   закрытой системе теплоснабжения при предвключенной схеме  присоединения подогревателей ГВ" - цифровое поле, значение которого определяет расход  сетевой  воды  на  одну  Гкал.   тепла,  расходуемого на горячее   водоснабжение   при   данном   виде  теплопотребления. Значение  поля  имеет    по умолчанию размерность,  т/Гкал.  Численное значение удельного расхода  для температурных  графиков 130-70  Град. С и 150-70 Град. С  соответственно равно Куд  =39.68 и Куд  =44.17 при оснащении  теплового  пункта  регулятором  расхода и температуры воды. При наличии на тепловых пунктах автоматических регуляторов, поддерживающих постоянный расход сетевой воды и постоянную температуру воды для горячего водоснабжения удельный расход сетевой воды на горячеее водоснабжение определяется в точке излома  температурного графика по балансовой нагрузке горячего водоснабжения: при отопительном температурном графике регулирования  Куд=gв_баланс*(tг - tx)/(t1_изл - t2со_изл), где gв_баланс=1.25*10^6/(с*(tг - tх)), удельный расход водопроводной воды на 1 Гкал/ч (1 МВт) балансовой нагрузки горячего водоснабжения, при повышенном температурном графике удельный расход на горячее водоснабжение принимается равным 0.  При t1_расч=150 Град.С принимают t2со_изл=41.7, при t1_расч=130 Град.С принимают t2со_изл=44.8.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2955, N'Удельные расходы', N'UR', N'gvz_leto', N'УР_ГВ_закр_лето', N'УР в закрытой  ГВС летний период', N'Удельный  расход  на  ГВ  в закрытой системе в летнем периоде', N'"Удельный  расход  на  горячее  водоснабжение  в   закрытой системе теплоснабжения в летнем периоде" - цифровое поле, значение которого определяет расход  сетевой  воды  на  одну  Гкал тепла,  расходуемого в закрытой системе теплоснабжения на горячее   водоснабжение   в летний период для всех схем подогревателей. Значение  поля  имеет    по умолчанию размерность,  т/Гкал.  Численное значение расчетного расхода сетевой воды для данного вида нагрузки определяется по формуле: Куд=0.8*(tг - txл)*10^3/(tг - tx)/(tпл - tол_средн), где tпл, txл, tол_средн - соответственно, температура воды в подающей линии в летний период, температура воды за подогревателем горячего водоснабжения при средней нагрузке ГВ, температура водопроводной воды в летний период,  tг,tx - соответственно, температура горячей воды в системах горячего водоснабжения, температура водопроводной воды в зимний период. Расход сетевой воды  в закрытой системе теплоснабжения на горячее   водоснабжение   в летний период определяется по формуле (Манюк В.И. и др. Наладка и эксплуатация водяных тепловых сетей):  Gгв_л_средн=Куд* gв_средн. Например, при  tпл=70 Град.С, tол_средн=40 Град.С, tx, txл - соответствено, 5 и 8 Град.С и tг- 55 Град.С, Куд= 25т/Гкал.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2956, N'Удельные расходы', N'UR', N'gvo_leto', N'УР_ГВ_откр_лето', N'УР в открытой  ГВС летний период', N'Удельный  расход  на  ГВ  в открытой системе в летнем периоде', N'"Удельный  расход  на  горячее  водоснабжение  в   открытой системе теплоснабжения в летнем периоде" - цифровое поле, значение которого определяет расход сетевой  воды  на  одну  Гкал тепла при непосредственном водоразборе на горячее водоснабжение  в летнем периоде. Значение  поля  имеет    по умолчанию размерность,  т/Гкал.  Численное значение расчетного расхода сетевой воды для данного вида нагрузки определяется по формуле: Куд=0.8*10^3/(tг - tx), где  tг,tx - соответственно, температура горячей воды в системах горячего водоснабжения, температура водопроводной воды в зимний период. Расход сетевой воды  в открытой системе теплоснабжения на горячее   водоснабжение   в летний период определяется по формуле (Манюк В.И. и др. Наладка и эксплуатация водяных тепловых сетей):  Gгв_л_средн=Куд* gв_средн. Например, при  tx=5 Град.С и tг- 60 Град.С, Куд= 14.54 т/Гкал.', N'Удельный расход воды', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2957, N'Узел', N'US', N'nomer', N'№', N'№', N'Номер записи', N'Порядковый номер записи', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2958, N'Узел', N'US', N'kod_p', NULL, N'Код расчетной схемы узла присоединения', N'Код расчетной схемы узла присоединения', N'«Код расчетной схемы узла присоединения» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2959, N'Узел', N'US', N'uzel_p', NULL, N'Наименование узла присоединения', N'Наименование узла присоединения', N'«Наименование узла присоединения» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  расчетную схему, связанную с узлом присоединения.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (2960, N'Узел', N'US', N'pr_p', NULL, N'Признак теплопровода  узла присоединения', N'Признак теплопровода  узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения, значение «Подающий» означает, что расчетная схема локализована на подающем трубопроводе,  значение «Обратка» - на обратном трубопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным трубопроводами.', NULL, NULL)
