INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3172, N'Участок теплопровода', N'UT', N'pr_p', NULL, N'Признак теплопровода узла присоединения', N'Признак теплопровода узла присоединения', N'«Признак теплопровода узла присоединения»   -  символьное   поле,   значение которого  одназначно определяет локализацию расчетной схемы, связанную с узлом присоединения., значение «Подающий» означает, что расчетная схема локализована на подающем теплопроводе,  значение «Обратка» - на обратном теплопроводе, значение «Общий»,  что расчетная схема локализована между подающим и обратным теплопроводами. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3173, N'Участок теплопровода', N'UT', N'kod1', NULL, N'Код расчетной схемы начального узла', N'Код расчетной схемы начального узла', N'«Код расчетной схемы начального узла участка  теплопровода» -  символьное  поле,  значение  которого  однозначно определяет расчетную схему, которой принадлежит узел участка.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3174, N'Участок теплопровода', N'UT', N'uzel1', NULL, N'Наименование начального узла участка', N'Наименование начального узла участка', N'«Наименование начального узла участка» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  узел   на  расчетной   схеме.    Это   наименование используется для указания исходного направления потока  сетевой воды на участке.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3175, N'Участок теплопровода', N'UT', N'pr1', NULL, N'Признак  теплопровода начального узла', N'Признак  теплопровода начального узла', N'«Признак  теплопровода»   -  символьное   поле,   значение которого  используется  для   указания принадлежности  начального узла только подающему -  значение «Подача» или только обратному  - значение «Обратка» трубопроводам на расчетной схеме. Если  поле имеет значение «Общий», то  это  означает, что узел принадлежит  и подающему и обратному  трубопроводам.   Наличие значения «Общий» в  полях «Признак  теплопровода»  для   начального  и   конечного   узлов свидетельствует  о  том,   что  участок «общий»,  т.е.   его характеристики    одинаковы    для   подающего    и    обратного теплопроводов. В  информационной базы данных значения слов ''''Подача", "Обратка", "Общий" представлены соответственно символами "П", "О" и пробел', NULL, NULL)
