INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3177, N'Участок теплопровода', N'UT', N'uzel2', NULL, N'Наименование конечного узла участка', N'Наименование конечного узла участка', N'«Наименование конечного узла участка» - символьное  поле, значение которого совместно с кодом расчетной схемы, однозначно определяет  узел   на  расчетной   схеме.    Это   наименование используется для указания исходного направления потока  сетевой воды на участке.', NULL, NULL)
