INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3182, N'Участок теплопровода', N'UT', N'tol', NULL, N'Толщина стенки', N'Толщина стенки', N' «Толщина стенки» -  цифровое  поле, значение которого определяет толщину стенки труб,  проложенных  на участке теплопровода.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3183, N'Участок теплопровода', N'UT', N'diametr_usl', NULL, N'Диаметр условный', N'Диаметр условный', N'    «Диаметр условный» -  цифровое  поле, значение которого определяет   условный диаметр  труб,  проложенных  на участке теплопровода.  Рекомендуется   заполнять  значение с помощью функции поля входной формы.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3184, N'Участок теплопровода', N'UT', N'dlina', NULL, N'Длина участка теплопровода', N'Длина участка теплопровода', N'  «Длина участка теплопровода»  -  цифровое  поле, значение  которого  определяется строительной   длиной  участка  трубопровода. При наличии электронной карты рекомендуется   заполнять значение с помощью команды "Установить длину" контекстного меню объекта "Участок", вызываемую нажанием правой клавиши мыши при наведении её на соответствующий участок теплопровода.', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3185, N'Участок теплопровода', N'UT', N'scher', NULL, N'Эквивалентная шероховатость', N'Эквивалентная шероховатость', N'«Эквивалентная  шероховатость  трубы»  -  цифровое   поле, значение которого характеризует  шероховатость ( негладкость  ) внутренних    стенок   труб   по   средней   высоте    выступов. Определяется   в   условиях  эксплуатации   теплоопроводов,   как правило,  по   данным  гидравлических  испытаний тепловых сетей. Рекомендуется   заполнять  значение с помощью функции поля входной формы. По умолчанию  значение принимается равным 0.5 мм.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3186, N'Участок теплопровода', N'UT', N'mestnoe', NULL, N'Сумма коэффициентов местных сопротивлений', N'Сумма коэффициентов местных сопротивлений', N'«Сумма  коэффициентов  местных  сопротивлений»  - цифровое поле,  значение  которого   определяется  суммой   коэффициентов местных  сопротивлений, установленных (имеющих место) на  данном участке  теплопровода.    Рекомендуется    заполнять   значение с помощью  функции поля входной формы.Значение поля  - безразмерная величина. Примечание:   Если   заданы значения полей «Сумма    коэффициентов    местных сопротивлений»    и  «Доля   местных  потерь»,  приоритет   отдается "Сумме".', NULL, NULL)

