INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3187, N'Участок теплопровода', N'UT', N'dolja', NULL, N'Доля местных потерь', N'Доля местных потерь', N'«Доля местных потерь»   - цифровое поле,  значение которого представляет  собой отношение  потерь в местных  сопротивлениях, имеющих   место  на  данном  участке  подающего  или   обратного теплопровода   к  линейным  потерям  напора  на  этих   участках теплопровода   или,   отношение  эквивалентной   длины   местных сопротивлений   к   их  линейной   длине.    Значение  поля    - безразмерная величина.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3188, N'Участок теплопровода', N'UT', N'kodkvp', NULL, N'Код коэфф.вариации параметров по подающей трубе', N'Код коэфф.вариации параметров по подающей трубе', N'«Код группы коэффициентов вариации по подающей трубе» - символьное поле, значение которого однозначно определяют группу коэффициентов вариации значений параметров участка по подающей трубе, определяющих вариант гидравлического режима тепловой сети', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3189, N'Участок теплопровода', N'UT', N'kodkvo', NULL, N'Код коэфф.вариации параметров по обратной трубе', N'Код коэфф.вариации параметров по обратной трубе', N'«Код группы коэффициентов вариации по обратной трубе» - символьное поле, значение которого однозначно определяют группу коэффициентов вариации значений параметров участка по обратной трубе, определяющих  вариант гидравлического режима тепловой сети', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3190, N'Участок теплопровода', N'UT', N'sopr', NULL, N'Гидравлическое сопротивление участка теплопровода', N'Гидравлическое сопротивление участка теплопровода', N'«Гидравлическое сопротивление участка»  - цифровое поле,  значение   которого рассчитывается пользователем или программными средствами на основании геометрических характеристик теплопроводов и шероховатости труб. ВНИМАНИЕ!!!   Если сопротивление известно, например, получено в   результате гидравлических испытаний тепловых сетей и записано пользователем, при этом поля "Признак гидравлического сопротивления потребителя"  входной формы (Вкладка "Основные") имеет значение "Заданное",  то сопротивление программными  средствами  не рассчитывается и, поля, предназначенные для расчета гидравлического сопротивления участка (длина, внутренний диаметр, шероховатость, местные сопротивления, доля) игнорируются, следовательно,  их можно  в этом случае не заполнять.', N'Гидравлическое сопротивление', NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3191, N'Участок теплопровода', N'UT', N'name_calctpr', NULL, N'Метод расчета тепловых потерь', N'Метод расчета тепловых потерь', N'"Метод расчета тепловых потерь" - символьное поле, значение которого используется для выбора метода расчета  тепловых потерь через теплоизоляционные конструкции:
Тепловые нормы - с использованием "Норм плотности теплового потока через изоляционную поверхность";
Изоляция - с использование часовых удельных тепловых потерь через теплоизоляционные конструкции полученных на основании расчета.
Таблицы значений "Нормы плотности теплового потока через изоляционную поверхность" (РД 153-34.0-20.523-98) приведены в пункте меню Сервис->Справочная информация', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3192, N'Участок теплопровода', N'UT', N'name_typ', NULL, N'Тип прокладки', N'Тип прокладки', N'"Тип прокладки" - символьное поле, значение которого может принимать следующие значения: 
        Бесканальная  -  при   подземной  бесканальной   прокладке участков тепловой сети; 
        Канальная - при подземной канальная прокладке участков  тепловой сети; 
        Надземная   -   при надземной  прокладке участков  тепловой сети.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3193, N'Участок теплопровода', N'UT', N'kog_canal', NULL, N'Код канала', N'Код канала', N'Код канала - символьное поле, значение которого определяет канал, местонахождения  участка теплопровода при его подземной канальной прокладке.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3194, N'Участок теплопровода', N'UT', N'kti', NULL, N'Коэффициент тепловых испытаний', N'Коэффициент тепловых испытаний', N'"Коэффициент   тепловых   испытаний"   -   численное  поле, значение которого определяются по результатам тепловых  испытаний системы. Для участков, не подвергнутых испытаниям и имеющим  типы прокладок  и   конструкции  изоляции,   отличные  от   испытанных участков коэффициент тепловых испытаний равен 1.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3195, N'Участок теплопровода', N'UT', N'kolwork', NULL, N'Признак Числа работы в год <5000часов', N'Признак Числа работы в год <5000часов', N'"Признак Числа работы в год <5000 часов" - символьное поле, значение которого используется при расчете тепловых потерь через теплоизоляционные конструкции участка теплопровода с использованием "Норм плотности теплового потока через изоляционную поверхность". Эти "Нормы" используются для расчета тепловых потерь для участков теплопроводов находящихся в эксплуатации с 01.01.1998г. Участок теплопроводов имеет >5000часов работы, в случае, если продолжительность его функционирования в течении года >209 календарных дней.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3196, N'Участок теплопровода', N'UT', N'kod_izol', NULL, N'Материал тепловой изоляции', N'Материал тепловой изоляции', N'"Материал тепловой изоляции" - символьное поле, значение которого определяет материал тепловой изоляции участка теплопровода, теплопроводность которого используется при расчете тепловых потерь участком теплопровода при выборе метода расчета "Изоляция" (расчет часовых удельных тепловых потерь через теплоизоляционные конструкции на основании расчета).  Значение  поля заполняется с помощью функции поля при нахождении курсора мыши в данном поле.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3197, N'Участок теплопровода', N'UT', N'thickizol', NULL, N'Толщина изоляции', N'Толщина изоляции', N'"Толщина изоляции" - численное  поле, значение которого определяет толщину теплоизоляционного слоя участка теплопровода. Используется при расчете тепловых потерь участком теплопровода при выборе метода расчета "Изоляция"(расчет часовых удельных тепловых потерь через теплоизоляционные конструкции на основании расчета). При подземной прокладке рекомендуется использовать функцию поля.', NULL, N'мм')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3198, N'Участок теплопровода', N'UT', N'k_izol', NULL, N'Коэффициент поправки теплопроводности изоляционного материала', N'Коэффициент поправки теплопроводности изоляционного материала', N'"Коэффициент поправки теплопроводности изоляционного материала" - численное  поле, значение которого ввосит поправку в значение коэффициента теплопроводности теплоизоляционного материала участка теплопровода в зависимости от технического состояния изоляции. Значение поля используется при расчете тепловых потерь участком теплопровода при выборе метода расчета "Изоляция" (расчет часовых удельных тепловых потерь через теплоизоляционные конструкции на основании расчета).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3199, N'Участок теплопровода', N'UT', N'izoloutair', NULL, N'Теплоотдача от изоляции трубопровода к окружающему воздуху', N'Теплоотдача от изоляции трубопровода к окружающему воздуху', N'"Теплоотдача от изоляции трубопровода к окружающему воздуху" - численное  поле, значение которого используется при расчете тепловых потерь участком теплопровода надземной прокладке при выборе метода расчета "Изоляция" (расчет часовых удельных тепловых потерь через теплоизоляционные конструкции на основании расчета).  Используемое значение по умолчанию  6 Вт/(м**2*Град.С).', NULL, N'Вт/(м*К)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3200, N'Участок теплопровода', N'UT', N'depth', NULL, N'Глубина заложения до оси теплопровода', N'Глубина заложения до оси теплопровода', N'"Глубина заложения до оси теплопровода" - численное  поле, значение которого используется при расчете тепловых потерь участком теплопровода подземной (канальная, бесканальная) прокладке при выборе метода расчета "Изоляция" (расчет часовых удельных тепловых потерь через теплоизоляционные конструкции на основании расчета).', NULL, N'м')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3201, N'Участок теплопровода', N'UT', N'tpground', NULL, N'Теплопроводность грунта', N'Теплопроводность грунта', N'"Теплопроводность грунта" - численное  поле, значение которого используется при расчете тепловых потерь участком теплопровода подземной (канальная, бесканальная) прокладке при выборе метода расчета "Изоляция"(расчет часовых удельных тепловых потерь через теплоизоляционные конструкции на основании расчета).  Используемое значение по умолчанию 2.56 Вт/(м*Град.С).', NULL, N'Вт/(м*К)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3202, N'Участок теплопровода', N'UT', N'izol_air', NULL, N'Коэфф.теплоотдачи от изоляции трубопровода к воздуху канала', N'Коэфф.теплоотдачи от изоляции трубопровода к воздуху канала', N'"Коэфф.теплоотдачи от изоляции трубопровода к воздуху канала" - численное  поле, значение которого используется при расчете тепловых потерь через теплоизоляционные конструкции участком теплопровода при подземной канальной прокладке, при выборе метода расчета "Изоляция" (расчет часовых удельных тепловых потерь через теплоизоляционные конструкции на основании расчета). Используемое значение по умолчанию 8 Вт/(м**2*Град.С).', NULL, N'Вт/(м*К)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3203, N'Участок теплопровода', N'UT', N'air_ground', NULL, N'Коэфф.теплоотдачи от воздуха канала к грунту', N'Коэфф.теплоотдачи от воздуха канала к грунту', N'"Коэфф.теплоотдачи от воздуха канала к грунту" - численное  поле, значение которого используется при расчете тепловых потерь через теплоизоляционные конструкции участком теплопровода при подземной канальной прокладке, при выборе метода расчета "Изоляция" (расчет часовых удельных тепловых потерь через теплоизоляционные конструкции на основании расчета). Используемое значение по умолчанию 8 Вт/(м**2*Град.С).', NULL, N'Вт/(м*К)')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3204, N'Участок теплопровода', N'UT', N'distance', NULL, N'Расстояние между осями теплопроводов', N'Расстояние между осями теплопроводов', N'Расстояние между осями теплопроводов, для подземной бесканальной прокладки', NULL, N'мм')
