INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3295, N'Участок теплопровода', N'UT', N'truba', NULL, N'Количество труб на участке', N'Количество труб на участке', N'«Количество труб» - цифровое поле, значение которого равно количеству    параллельно   включенных   труб   c    одинаковыми характеристиками  на  данном участке  теплопровода по  подающему (обратному)  теплоопроводу,  соединенных в  начальном и  конечном узлах.  Значение поля имеет размерность, шт. 
      ВНИМАНИЕ!!! Следует иметь ввиду, что если две  параллельно включенные  трубы имеют разные характеристики, то участок  нужно описывать   дважды  с  одинаковыми  наименованиями  начальных  и конечных    узлов.     Программные   средства системы расчета потокораспределения  вычисляют     эквивалентное гидравлическое   сопротивление   для  такого   участка,  и    не рассчитывают  расход в каждой  трубе.  Если у  пользователя есть потребность  в  вычислении расходов  в каждой  трубе на участке, представленном  несколькими параллельно включенными трубами,  то он  должен в каждый участок,кроме одного, ввести фиктивные  узлы, т.е.  представить  их в  виде последовательного  соединения двух участков,  один  из которых  может быть  фиктивным с минимальной длиной,  например  -   1м ,   и   диаметром    равным   диаметру исходной   трубы.    Программные    средства системы  расчета потокораспределения не выполняют  эквивалентирование, а  рассчитывают расходы для каждой трубы участка.', NULL, NULL)
