INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3449, N'Элеватор', N'EL', N'a5', NULL, N'Номер элеватора, установленный', N'Номер элеватора, установленный', N'"Номер элеватора" - свойство, значение которого определяет номер  элеватора,  установленного  на  входе  системы отопления. Начальное  значение  по  умолчанию  принимается  равным "0", что соответствует     элеватору     "нулевого"     номера,    обычно устанавливаемого  для  отопительных  систем  с малыми расчетными нагрузками  (отопительные   системы  частных   домов,  котеджей, вспомогательных помещений  промышленных предприятий).', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (3450, N'Элеватор', N'EL', N'a6', NULL, N'Коэффициент смешения элеватора', N'Коэффициент смешения элеватора', N'  "Фактический коэффициент смешения" -  коэффициент смешения
 элеваторного или насосного смесительного  узла отопительной
 системы, полученный в процессе наладочных работ.           
 Коэффициент смешения,определяется из выражений:            
                                                            
                U=(t1-t3)/(t3-t2),      (1)                 
                                                            
 где  t1,t2,t3 - температура воды при расчетной  температуре
                 наружного воздуха cоответственно в подающем
                 трубопроводе  тепловой   сети,  в  обратном
                 трубопроводе  на  выходе системы отопления,
                 в подающем трубопрроводе системы отопления,
                 Град.С;                                    
                                                            
 или            U=G/Go,                 (2)                 
                                                           
 где     G,Go-  массовый расход воды ,соответственно  через 
                смесительную   перемычку и на входе системы 
                отопления (после узла смешения),т/ч.', NULL, NULL)
