INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (7616, N'RP_Регулятор перепада стандарные', N'RP', N'Py', NULL, NULL, N'Условное давление рабочей среды', N'Размерное числовое поле, представляющее  наибольшее избыточное давление при температуре среды 20 °С, при котором допустима длительная работа арматуры и соединительных деталей трубопроводов, имеющих заданные размеры, обоснованные расчетом на прочность при выбранных материалах и характеристиках их прочности.', NULL, N'Мпа')
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (7617, N'RP_Регулятор перепада стандарные', N'RP', N'Tmax_sreda', NULL, NULL, N'Максимальная температура рабочей среды', N'Размерное числовое поле, представляющее  максимальную температуру рабочей среды, действующую при нормальном ходе технологического процесса без учета случайных кратковременных повышений.', NULL, N'Град.С')
