INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (7715, N'ZC_Задвижки стандартные', N'ZC', N'nomer', N'№', N'№', N'Номер экземпляра', N'Номер экземпляра', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (7716, N'ZC_Задвижки стандартные', N'ZC', N'name', N'Наим', N'Наим', N'Наименование', N'Первые две цифры обозначают тип арматуры: 14  и 15 - клапан, 16 - клапан обратный подъемный, 19 - клапан обратный поворотный, 30 и 31 - задвижка.     Буквы за цифрами обозначают материал, применяемый для изготовления корпуса арматуры: с - сталь, ч - серый чугун, кч - ковкий чугун, Б - бронза, латунь.    Цифры после букв обозначают конструктивные особенности изделия в пределах данного типа и вид привода. Одна или две цифры обозначают номер модели ( ручной привод с маховиком), при наличии трех цифр первая обозначает вид привода: 3 - механический с червячной передачей, 5 - то же с конической передачей, 9 - электрический.   Последние буквы обозначают материал уплотнительных поверхностей: бр - бронза, латунь, нж - коррозийно-стойкая (нержавеющая) сталь, п - пластмассы (кроме винитпласта).    Буквы в конце обозначают исполнение электропривода: Б - взрывозащищенные (взрывобезопастное), Т - тропическое.', NULL, NULL)
INSERT [dbo].[HELP_OLD] ([id], [tab], [stroka], [en], [ru], [nm], [hlp], [helpshiftf1], [velichina], [stand_razmer]) VALUES (7717, N'ZC_Задвижки стандартные', N'ZC', N'name_zc', N'Обозн', N'Обозн', N'Обозначение', N'Первые две цифры обозначают тип арматуры: 14  и 15 - клапан, 16 - клапан обратный подъемный, 19 - клапан обратный поворотный, 30 и 31 - задвижка.     Буквы за цифрами обозначают материал, применяемый для изготовления корпуса арматуры: с - сталь, ч - серый чугун, кч - ковкий чугун, Б - бронза, латунь.    Цифры после букв обозначают конструктивные особенности изделия в пределах данного типа и вид привода. Одна или две цифры обозначают номер модели ( ручной привод с маховиком), при наличии трех цифр первая обозначает вид привода: 3 - механический с червячной передачей, 5 - то же с конической передачей, 9 - электрический.   Последние буквы обозначают материал уплотнительных поверхностей: бр - бронза, латунь, нж - коррозийно-стойкая (нержавеющая) сталь, п - пластмассы (кроме винитпласта).    Буквы в конце обозначают исполнение электропривода: Б - взрывозащищенные (взрывобезопастное), Т - тропическое.', NULL, NULL)
